#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/*
 * 使用栈判断字符串是否为回文串
 * 思路：
 * 1. 将前半部分字符压入栈
 * 2. 如果长度为奇数，跳过中间字符
 * 3. 用后半部分字符依次与栈顶比较
 * 4. 全部匹配则为回文，否则不是回文
 */
bool isPalindromeByStack(char *s) {
    int n = strlen(s);

    // 动态申请一个栈空间，最多存放 n/2 个字符
    char *stack = (char *)malloc((n / 2 + 1) * sizeof(char));
    if (stack == NULL) {
        return false; // 内存申请失败时返回 false
    }

    int top = -1;

    // 1. 前半部分入栈
    for (int i = 0; i < n / 2; i++) {
        stack[++top] = s[i];
    }

    // 2. 确定后半部分起始位置
    int start;
    if (n % 2 == 0) {
        start = n / 2;
    } else {
        start = n / 2 + 1; // 奇数长度时跳过中间字符
    }

    // 3. 后半部分与栈顶逐个比较
    for (int i = start; i < n; i++) {
        if (top < 0 || stack[top] != s[i]) {
            free(stack);
            return false;
        }
        top--;
    }

    free(stack);
    return true;
}

int main() {
    char s[100005];

    // 读入一个数字字符串
    scanf("%s", s);

    if (isPalindromeByStack(s)) {
        printf("true\n");
    } else {
        printf("false\n");
    }

    return 0;
}

