#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    char s[105];

    // 读取输入字符串
    if (scanf("%100s", s) != 1) {
        return 0;
    }

    int n = strlen(s);
    char stack[105];   // 用字符数组模拟栈
    int top = -1;      // 栈顶指针，-1 表示空栈

    for (int i = 0; i < n; i++) {
        char ch = s[i];

        // 如果栈不为空，并且当前字符与栈顶字符是同一个字母的大小写形式
        // 那么它们构成冲突对，需要一起删除（即弹出栈顶）
        if (top >= 0 && abs(stack[top] - ch) == 32) {
            top--;
        } else {
            // 否则将当前字符入栈
            stack[++top] = ch;
        }
    }

    // 栈中剩余字符就是最终答案
    // 注意：如果 top == -1，说明结果为空串，此时直接输出空行即可
    for (int i = 0; i <= top; i++) {
        putchar(stack[i]);
    }
    putchar('\n');

    return 0;
}

