```c
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

#include <stdlib.h>

int* visitOrder(struct TreeNode* root, int* returnSize) {
    // 空树直接返回空数组
    if (root == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 题目保证节点数最多 100，这里开一个足够的空间
    int capacity = 100;
    int *result = (int *)malloc(sizeof(int) * capacity);

    // 用数组模拟栈，存放树节点指针
    struct TreeNode **stack = (struct TreeNode **)malloc(sizeof(struct TreeNode *) * capacity);
    int top = -1;

    // 根节点先入栈
    stack[++top] = root;
    *returnSize = 0;

    while (top >= 0) {
        // 弹出栈顶节点
        struct TreeNode *node = stack[top--];

        // 记录当前节点值
        result[(*returnSize)++] = node->val;

        // 先压右子树，再压左子树
        // 这样出栈时会先处理左子树，符合“根-左-右”顺序
        if (node->right != NULL) {
            stack[++top] = node->right;
        }
        if (node->left != NULL) {
            stack[++top] = node->left;
        }
    }

    free(stack);
    return result;
}
```

