#include <stdio.h>
#include <string.h>

int main() {
    char word[251];
    char ch;

    // 读入字符串和字符
    scanf("%250s %c", word, &ch);

    int n = strlen(word);
    int pos = -1;

    // 查找 ch 第一次出现的位置
    for (int i = 0; i < n; i++) {
        if (word[i] == ch) {
            pos = i;
            break;
        }
    }

    // 如果不存在，直接输出原字符串
    if (pos == -1) {
        printf("%s\n", word);
        return 0;
    }

    // 使用数组模拟栈
    char stack[251];
    int top = -1;

    // 将前缀 [0..pos] 入栈
    for (int i = 0; i <= pos; i++) {
        stack[++top] = word[i];
    }

    char result[251];
    int idx = 0;

    // 出栈，得到倒序后的前缀
    while (top >= 0) {
        result[idx++] = stack[top--];
    }

    // 拼接剩余部分
    for (int i = pos + 1; i < n; i++) {
        result[idx++] = word[i];
    }

    result[idx] = '\0';

    printf("%s\n", result);
    return 0;
}

