#include <stdio.h>
#include <stdlib.h>

// 二叉树节点定义
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

/*
 * 使用栈实现二叉树先序遍历（非递归）
 * 返回动态数组，数组长度通过 returnSize 返回
 */
int* preorderTraversal(struct TreeNode* root, int* returnSize) {
    // 空树直接返回空数组
    if (root == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 题目保证节点数不超过 100，这里开 101 更安全一些
    struct TreeNode* stack[101];
    int top = -1;

    int* result = (int*)malloc(sizeof(int) * 100);
    int count = 0;

    // 根节点先入栈
    stack[++top] = root;

    while (top >= 0) {
        // 弹出栈顶节点
        struct TreeNode* node = stack[top--];

        // 记录当前节点值
        result[count++] = node->val;

        // 注意：先压入右子节点，再压入左子节点
        // 这样出栈时会先处理左子节点，符合先序遍历顺序
        if (node->right != NULL) {
            stack[++top] = node->right;
        }
        if (node->left != NULL) {
            stack[++top] = node->left;
        }
    }

    *returnSize = count;
    return result;
}

