// 释放二叉树内存
void freeTree(struct TreeNode* root) {
    if (root == NULL) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

int main() {
    /*
     * 构造示例二叉树：
     *     1
     *      \
     *       2
     *      /
     *     3
     */
    struct TreeNode* root = createNode(1);
    root->right = createNode(2);
    root->right->left = createNode(3);

    int returnSize = 0;
    int* ans = preorderTraversal(root, &returnSize);

