#include <stdio.h>
#include <string.h>

int main() {
    char s[260];      // 字符串长度最大 250，预留额外空间
    char c;

    // 读入字符串和目标字符
    scanf("%s", s);
    scanf(" %c", &c);

    int len = strlen(s);
    int pos = -1;

    // 找到字符 c 第一次出现的位置
    for (int i = 0; i < len; i++) {
        if (s[i] == c) {
            pos = i;
            break;
        }
    }

    // 如果没有找到，直接输出原字符串
    if (pos == -1) {
        printf("%s\n", s);
        return 0;
    }

    // 用字符数组模拟栈
    char stack[260];
    int top = -1;

    // 将前缀 s[0...pos] 入栈
    for (int i = 0; i <= pos; i++) {
        stack[++top] = s[i];
    }

    // 出栈并写回字符串前缀，实现逆序
    for (int i = 0; i <= pos; i++) {
        s[i] = stack[top--];
    }

    // 输出结果字符串
    printf("%s\n", s);

    return 0;
}

