#define MAXN 205

/*
 * 使用栈模拟字符串的最终输入结果
 * s: 原始按键串
 * out: 处理后的最终字符串
 */
void buildText(char s[], char out[]) {
    char stack[MAXN];   // 用字符数组模拟栈
    int top = -1;       // 栈顶指针，-1 表示空栈

    int len = strlen(s);
    for (int i = 0; i < len; i++) {
        if (s[i] == '@') {
            // 遇到撤销符号，若栈非空则弹出一个字符
            if (top >= 0) {
                top--;
            }
        } else {
            // 普通字符入栈
            stack[++top] = s[i];
        }
