#include <stdio.h>
#include <string.h>

#define MAXN 1005
#define MAXV 10005

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int a[MAXN], b[MAXN];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (int i = 0; i < m; i++) {
        scanf("%d", &b[i]);
    }

    // nextGreater[x] 表示元素 x 在 b 中右侧第一个比它大的值
    // 因为题目保证数值范围在 0~10000，可以直接开数组映射
    int nextGreater[MAXV];
    for (int i = 0; i < MAXV; i++) {
        nextGreater[i] = -1;
    }

    // 单调栈，栈中存放 b 的元素值
    // 维护一个从栈底到栈顶递减的栈
    int stack[MAXN];
    int top = -1;

    // 从左到右扫描 b
    for (int i = 0; i < m; i++) {
        // 当前元素如果比栈顶大，说明它是栈顶元素的“右侧第一个更大值”
        while (top >= 0 && b[i] > stack[top]) {
            nextGreater[stack[top]] = b[i];
            top--;
        }
        // 当前元素入栈
        stack[++top] = b[i];
    }

    // 栈中剩余元素右侧都没有更大值，保持 -1 即可

    // 按照 a 的顺序输出答案
    for (int i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        printf("%d", nextGreater[a[i]]);
    }
    printf("\n");

    return 0;
}

