#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 题意：只用两个队列实现一个栈。
 *
 * 思路：
 * 使用两个队列 q1 和 q2。
 * - push(x):
 *   1. 先把 x 入队到空队列 q2
 *   2. 再把 q1 中的所有元素依次出队，入队到 q2
 *   3. 交换 q1 和 q2
 *   这样 q1 的队首始终就是“栈顶”元素
 *
 * - pop():  直接从 q1 队首出队
 * - top():  直接返回 q1 队首元素
 * - empty(): 判断 q1 是否为空
 *
 * 复杂度：
 * - push: O(n)
 * - pop: O(1)
 * - top: O(1)
 * - empty: O(1)
 */

#define MAXN 105

/* -------------------- 队列定义 -------------------- */
typedef struct {
    int data[MAXN];
    int front;
    int rear;
    int size;
} Queue;

/* 初始化队列 */
void queueInit(Queue* q) {
    q->front = 0;
    q->rear = 0;
    q->size = 0;
}

/* 判空 */
bool queueEmpty(Queue* q) {
    return q->size == 0;
}

/* 获取大小 */
int queueSize(Queue* q) {
    return q->size;
}

/* 入队 */
void enqueue(Queue* q, int x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXN;
    q->size++;
}

/* 出队 */
int dequeue(Queue* q) {
    int val = q->data[q->front];
    q->front = (q->front + 1) % MAXN;
    q->size--;
    return val;
}

/* 读取队首 */
int queueFront(Queue* q) {
    return q->data[q->front];
}

/* -------------------- 栈定义 -------------------- */
typedef struct {
    Queue q1;
    Queue q2;
} MyStack;

/* 创建栈 */
MyStack* myStackCreate() {
    MyStack* obj = (MyStack*)malloc(sizeof(MyStack));
    queueInit(&obj->q1);
    queueInit(&obj->q2);
    return obj;
}

/* 压栈 */
void myStackPush(MyStack* obj, int x) {
    /* 先把新元素放入 q2 */
    enqueue(&obj->q2, x);

    /* 再把 q1 的所有元素搬到 q2 */
    while (!queueEmpty(&obj->q1)) {
        enqueue(&obj->q2, dequeue(&obj->q1));
    }

    /* 交换 q1 和 q2，使 q1 始终保存当前栈数据 */
    Queue temp = obj->q1;
    obj->q1 = obj->q2;
    obj->q2 = temp;
}

/* 弹栈 */
int myStackPop(MyStack* obj) {
    return dequeue(&obj->q1);
}

/* 取栈顶 */
int myStackTop(MyStack* obj) {
    return queueFront(&obj->q1);
}

/* 判空 */
bool myStackEmpty(MyStack* obj) {
    return queueEmpty(&obj->q1);
}

/* 释放栈 */
void myStackFree(MyStack* obj) {
    free(obj);
}

/*
 * 如需本地测试，可取消下面 main 函数注释。
 */
/*
int main() {
    MyStack* st = myStackCreate();

    myStackPush(st, 1);
    myStackPush(st, 2);

    printf("top = %d\n", myStackTop(st));     // 2
    printf("pop = %d\n", myStackPop(st));     // 2
    printf("empty = %s\n", myStackEmpty(st) ? "true" : "false"); // false

    myStackFree(st);
    return 0;
}
*/

