#include <stdio.h>
#include <stdlib.h>

// 二叉树节点定义
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

/*
 * 使用栈实现二叉树的中序遍历
 * 返回动态数组，调用者负责 free
 */
int* inorderTraversal(struct TreeNode* root, int* returnSize) {
    *returnSize = 0;

    // 结果数组初始容量
    int resultCapacity = 16;
    int* result = (int*)malloc(sizeof(int) * resultCapacity);

    // 栈初始容量
    int stackCapacity = 16;
    struct TreeNode** stack = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * stackCapacity);
    int top = -1;

    struct TreeNode* curr = root;

    // 当前节点不为空，或者栈不为空时继续遍历
    while (curr != NULL || top != -1) {
        // 一直向左走，并将沿途节点入栈
        while (curr != NULL) {
            // 如果栈满了，扩容
            if (top + 1 >= stackCapacity) {
                stackCapacity *= 2;
                stack = (struct TreeNode**)realloc(stack, sizeof(struct TreeNode*) * stackCapacity);
            }
            stack[++top] = curr;
            curr = curr->left;
        }

        // 弹出栈顶节点
        curr = stack[top--];

        // 如果结果数组满了，扩容
        if (*returnSize >= resultCapacity) {
            resultCapacity *= 2;
            result = (int*)realloc(result, sizeof(int) * resultCapacity);
        }

        // 记录当前节点值
        result[*returnSize] = curr->val;
        (*returnSize)++;

        // 转向右子树
        curr = curr->right;
    }

    free(stack);
    return result;
}

