#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int workers[105], boxes[105];

    for (int i = 0; i < n; i++) {
        scanf("%d", &workers[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &boxes[i]);
    }

    // 使用数组模拟循环队列
    int queue[1005];
    int front = 0, rear = 0;

    // 初始员工入队
    for (int i = 0; i < n; i++) {
        queue[rear++] = workers[i];
    }

    int top = 0;              // boxes[top] 表示当前栈顶
    int remain = n;           // 当前队列中剩余员工数
    int rotateCount = 0;      // 记录连续有多少人因不匹配被转移到队尾

    // 当还有员工且还有餐盒时继续
    while (remain > 0 && top < n) {
        int cur = queue[front++];   // 取出队首员工

        if (cur == boxes[top]) {
            // 当前员工喜欢栈顶餐盒，取走后离开
            top++;
            remain--;
            rotateCount = 0;  // 只要有人成功取餐，连续轮转次数清零
        } else {
            // 不喜欢，则回到队尾
            queue[rear++] = cur;
            rotateCount++;

            // 如果连续轮转了 remain 次，说明当前所有剩余员工
            // 都不喜欢这个栈顶餐盒，流程结束
