#include <stdlib.h>

/*
 * Definition for a binary tree node.
 */
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

/*
 * 使用栈进行二叉树先序遍历（非递归）
 * 返回结果数组，returnSize 返回数组长度
 */
int* preorderTraversal(struct TreeNode* root, int* returnSize) {
    // 题目保证节点数量不超过 100，这里直接开足够大的空间
    int capacity = 100;
    int *result = (int *)malloc(sizeof(int) * capacity);
    *returnSize = 0;

    // 空树直接返回空数组
    if (root == NULL) {
        return result;
    }

    // 栈中保存树节点指针
    struct TreeNode **stack = (struct TreeNode **)malloc(sizeof(struct TreeNode *) * capacity);
    int top = -1;

    // 根节点入栈
    stack[++top] = root;

    while (top >= 0) {
        // 弹出栈顶节点
        struct TreeNode *node = stack[top--];

        // 记录当前节点值
        result[(*returnSize)++] = node->val;

        /*
         * 先序遍历顺序：根 -> 左 -> 右
         * 栈是后进先出，所以要先压入右孩子，再压入左孩子
         * 这样左孩子会先被弹出并访问
         */
        if (node->right != NULL) {
            stack[++top] = node->right;
        }
        if (node->left != NULL) {
            stack[++top] = node->left;
        }
    }

    free(stack);
    return result;
}

