#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    // 用数组模拟栈，最多会有 n 条有效记录
    int stack[1005];
    int top = -1;      // 栈顶指针，-1 表示空栈
    int sum = 0;       // 实时维护总和，避免最后再遍历栈

    char op[20];

    for (int i = 0; i < n; i++) {
        scanf("%s", op);

        if (strcmp(op, "C") == 0) {
            // 撤销最近一条记录
            sum -= stack[top];
            top--;
        } else if (strcmp(op, "D") == 0) {
            // 最近一条记录的 2 倍入栈
            int val = stack[top] * 2;
            stack[++top] = val;
            sum += val;
        } else if (strcmp(op, "+") == 0) {
            // 最近两条记录之和入栈
            int val = stack[top] + stack[top - 1];
            stack[++top] = val;
            sum += val;
        } else {
            // 普通整数，转为 int 后入栈
            int val = atoi(op);
            stack[++top] = val;
            sum += val;
        }
    }

    printf("%d\n", sum);
    return 0;
}

