#include <stdio.h>
#include <string.h>

#define MAXN 205

/*
 * 使用栈模拟字符串的输入过程：
 * - 普通字符：入栈
 * - '#': 如果栈非空则出栈
 *
 * 处理完成后，栈中保存的就是最终文本。
 */

/* 将原字符串处理后存入 result 中，返回最终长度 */
int buildText(const char *str, char *result) {
    char stack[MAXN];
    int top = -1;

    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] == '#') {
            /* 撤销操作：栈非空时弹出一个字符 */
            if (top >= 0) {
                top--;
            }
        } else {
            /* 普通字符入栈 */
            stack[++top] = str[i];
        }
    }

    /* 将栈中的内容复制到结果字符串中 */
    for (int i = 0; i <= top; i++) {
        result[i] = stack[i];
    }
    result[top + 1] = '\0';

    return top + 1;
}

int main() {
    char s[MAXN], t[MAXN];
    char resS[MAXN], resT[MAXN];

    /* 读入两个字符串 */
    scanf("%s", s);
    scanf("%s", t);

    /* 分别模拟输入过程 */
    buildText(s, resS);
    buildText(t, resT);

    /* 比较最终结果 */
    if (strcmp(resS, resT) == 0) {
        printf("true\n");
    } else {
        printf("false\n");
    }

    return 0;
}

