#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    // 用数组模拟栈，保存所有有效积分记录
    int stack[1005];
    int top = 0;  // top 表示当前栈中元素个数

    char op[25];

    for (int i = 0; i < n; i++) {
        scanf("%s", op);

        if (strcmp(op, "C") == 0) {
            // 撤销最近一次记录，相当于出栈
            top--;
        } else if (strcmp(op, "D") == 0) {
            // 最近一次记录的 2 倍，入栈
            stack[top] = stack[top - 1] * 2;
            top++;
        } else if (strcmp(op, "+") == 0) {
            // 最近两次记录之和，入栈
            stack[top] = stack[top - 1] + stack[top - 2];
            top++;
        } else {
            // 普通整数，转换后直接入栈
            stack[top] = atoi(op);
            top++;
        }
    }

    // 计算所有有效记录的总和
    int sum = 0;
    for (int i = 0; i < top; i++) {
        sum += stack[i];
    }

    printf("%d\n", sum);

    return 0;
}

