#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 用两个队列实现栈
 *
 * 思路：
 * 1. push：直接入主队列 q1
 * 2. pop/top：
 *    - 将 q1 前面的元素依次移动到辅助队列 q2，
 *      直到 q1 只剩最后一个元素
 *    - 这个最后一个元素就是“栈顶”
 *    - pop 直接取出并返回，不再放回
 *    - top 取出后还要放入 q2
 *    - 最后交换 q1 和 q2
 */

#define MAXN 205

/* 队列结构：使用数组模拟循环队列 */
typedef struct {
    int data[MAXN];
    int front;
    int rear;
    int size;
} Queue;

/* 初始化队列 */
void queueInit(Queue* q) {
    q->front = 0;
    q->rear = 0;
    q->size = 0;
}

/* 判空 */
bool queueEmpty(Queue* q) {
    return q->size == 0;
}

/* 获取队列大小 */
int queueSize(Queue* q) {
    return q->size;
}

/* 入队 */
void enqueue(Queue* q, int x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXN;
    q->size++;
}

/* 查看队头元素 */
int queueFront(Queue* q) {
    return q->data[q->front];
}

/* 出队 */
int dequeue(Queue* q) {
    int val = q->data[q->front];
    q->front = (q->front + 1) % MAXN;
    q->size--;
    return val;
}

/* 栈结构：内部维护两个队列 */
typedef struct {
    Queue q1;
    Queue q2;
} MyStack;

/* 创建栈 */
MyStack* myStackCreate() {
    MyStack* obj = (MyStack*)malloc(sizeof(MyStack));
    queueInit(&obj->q1);
    queueInit(&obj->q2);
    return obj;
}

/* 入栈：直接放入主队列 q1 */
void myStackPush(MyStack* obj, int x) {
    enqueue(&obj->q1, x);
}

/* 出栈：把前 n-1 个元素搬到 q2，最后一个就是栈顶 */
int myStackPop(MyStack* obj) {
    while (queueSize(&obj->q1) > 1) {
        enqueue(&obj->q2, dequeue(&obj->q1));
    }

    int ans = dequeue(&obj->q1);

    /* 交换 q1 和 q2，使 q1 继续作为主队列 */
    Queue temp = obj->q1;
    obj->q1 = obj->q2;
    obj->q2 = temp;

    return ans;
}

/* 查看栈顶：与 pop 类似，但最后一个元素还要放回去 */
int myStackTop(MyStack* obj) {
    while (queueSize(&obj->q1) > 1) {
        enqueue(&obj->q2, dequeue(&obj->q1));
    }

    int ans = dequeue(&obj->q1);
    enqueue(&obj->q2, ans);

    /* 交换 q1 和 q2 */
    Queue temp = obj->q1;
    obj->q1 = obj->q2;
    obj->q2 = temp;

    return ans;
}

/* 判断栈是否为空 */
bool myStackEmpty(MyStack* obj) {
    return queueEmpty(&obj->q1);
}

/* 释放空间 */
void myStackFree(MyStack* obj) {
    free(obj);
}

/*
 * 使用说明（OJ 一般不需要你写 main 函数）：
 *
 * MyStack* obj = myStackCreate();
 * myStackPush(obj, 1);
 * myStackPush(obj, 2);
 * int a = myStackTop(obj);    // 2
 * int b = myStackPop(obj);    // 2
 * bool c = myStackEmpty(obj); // false
 * myStackFree(obj);
 */

