bool queueEmpty(Queue* q) {
    return q->size == 0;
}

/* 获取队列大小 */
int queueSize(Queue* q) {
    return q->size;
}

/* 入队 */
void enqueue(Queue* q, int x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXN;
    q->size++;
}

/* 查看队头元素 */
int queueFront(Queue* q) {
    return q->data[q->front];
}

