#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int main() {
    int n;
    scanf("%d", &n);

    int *a = (int *)malloc(sizeof(int) * n);
    if (a == NULL) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // 使用数组模拟栈，最多只需要存前一半元素
    int *stack = (int *)malloc(sizeof(int) * (n / 2 + 1));
    if (stack == NULL) {
        free(a);
        return 0;
    }

    int top = -1;

    // 将前半部分元素入栈
    for (int i = 0; i < n / 2; i++) {
        stack[++top] = a[i];
    }

    // 后半部分开始比较的位置
    int start;
    if (n % 2 == 0) {
        start = n / 2;
    } else {
        start = n / 2 + 1;  // 跳过中间元素
    }

    bool isPalindrome = true;

    // 将后半部分与栈顶元素逐个比较
    for (int i = start; i < n; i++) {
        if (top < 0 || stack[top] != a[i]) {
            isPalindrome = false;
            break;
        }
        top--;
    }

    if (isPalindrome) {
        printf("true\n");
    } else {
        printf("false\n");
    }

    free(a);
    free(stack);
    return 0;
}

