#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main() {
    char s[105];

    // 读取输入字符串
    if (scanf("%100s", s) != 1) {
        return 0;
    }

    char stack[105];
    int top = -1;  // 栈顶指针，-1 表示空栈

    int n = strlen(s);
    for (int i = 0; i < n; i++) {
        if (islower((unsigned char)s[i])) {
            // 遇到字母，入栈表示暂时保留
            stack[++top] = s[i];
        } else if (isdigit((unsigned char)s[i])) {
            // 遇到数字，删除左侧最近保留的一个字母
            // 题目保证一定存在可删除的字母，因此直接弹栈即可
            if (top >= 0) {
                top--;
            }
        }
    }

    // 栈中剩余的字符就是答案
    // 注意栈底到栈顶的顺序正好是最终字符串顺序
    for (int i = 0; i <= top; i++) {
        putchar(stack[i]);
    }
    putchar('\n');

    return 0;
}

