#include <stdlib.h>

/**
 * N叉树节点定义
 */
struct Node {
    int val;
    int numChildren;
    struct Node** children;
};

/**
 * 使用栈实现 N 叉树后序遍历
 *
 * 思路：
 * 1. 使用一个栈进行遍历。
 * 2. 每次弹出一个节点，把它的值加入结果数组。
 * 3. 再把它的所有子节点按从左到右的顺序压栈。
 * 4. 这样得到的顺序其实是“根 -> 从右到左的子树”。
 * 5. 最后把结果数组逆序，即可得到真正的后序遍历。
 *
 * 例如：
 * 原本后序：child1, child2, root
 * 栈处理得到：root, child2, child1
 * 逆序后正好是后序。
 */
int* postorder(struct Node* root, int* returnSize) {
    // 空树直接返回空数组
    if (root == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 题目保证节点总数不超过 10^4，直接开足够大的空间
    int capacity = 10000;

    // 结果数组
    int* result = (int*)malloc(sizeof(int) * capacity);

    // 栈：保存待访问节点
    struct Node** stack = (struct Node**)malloc(sizeof(struct Node*) * capacity);
    int top = -1;

    // 根节点入栈
    stack[++top] = root;
    *returnSize = 0;

    while (top >= 0) {
        // 弹出栈顶节点
        struct Node* cur = stack[top--];

        // 先记录当前节点值
        result[(*returnSize)++] = cur->val;

        // 将当前节点的孩子从左到右压栈
        // 这样出栈时会先处理右边孩子
        for (int i = 0; i < cur->numChildren; i++) {
            if (cur->children[i] != NULL) {
                stack[++top] = cur->children[i];
            }
        }
    }

    // 将结果逆序，得到真正的后序遍历
    for (int i = 0, j = *returnSize - 1; i < j; i++, j--) {
        int temp = result[i];
        result[i] = result[j];
        result[j] = temp;
    }

    // 释放栈空间
    free(stack);

    return result;
}

