#include <stdio.h>
#include <stdlib.h>

// 二叉树结点定义
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

/*
 * 使用两个栈实现二叉树后序遍历（迭代法）
 *
 * 思路：
 * 1. 先将根结点压入栈1。
 * 2. 每次从栈1弹出一个结点，压入栈2。
 * 3. 然后将该结点的左孩子、右孩子依次压入栈1。
 * 4. 当栈1为空时，栈2中弹出的顺序就是后序遍历结果。
 *
 * 原因：
 * 栈1处理顺序相当于“根 -> 右 -> 左”的某种逆过程，
 * 再借助栈2反转后，得到“左 -> 右 -> 根”，即后序遍历。
 */
int* postorderTraversal(struct TreeNode* root, int* returnSize) {
    // 空树直接返回空数组
    if (root == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 题目限制结点数最多为 100，因此开足够大的栈空间即可
    struct TreeNode* stack1[105];
    struct TreeNode* stack2[105];
    int top1 = -1;
    int top2 = -1;

    // 结果数组，最多存 100 个结点值
    int* result = (int*)malloc(sizeof(int) * 105);
    int index = 0;

    // 根结点先入栈1
    stack1[++top1] = root;

    // 先处理栈1，把访问顺序存到栈2中
    while (top1 >= 0) {
        struct TreeNode* node = stack1[top1--];
        stack2[++top2] = node;

        // 注意：这里先压左，再压右
        // 这样栈1弹出时会先处理右子树，最终经过栈2反转后得到正确后序
        if (node->left != NULL) {
            stack1[++top1] = node->left;
        }
        if (node->right != NULL) {
            stack1[++top1] = node->right;
        }
    }

    // 从栈2中弹出，即为后序遍历结果
    while (top2 >= 0) {
        result[index++] = stack2[top2--]->val;
    }

    *returnSize = index;
    return result;
}

