#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 205

/*
 * 用数组模拟队列
 * 支持：
 * 1. 入队 push_back
 * 2. 出队 pop_front
 * 3. 取队首 front
 * 4. 判空 empty
 * 5. 获取大小 size
 */
typedef struct {
    int data[MAXN];
    int front;
    int rear;
} Queue;

// 初始化队列
void initQueue(Queue *q) {
    q->front = 0;
    q->rear = 0;
}

// 判断队列是否为空
bool isQueueEmpty(Queue *q) {
    return q->front == q->rear;
}

// 返回队列大小
int queueSize(Queue *q) {
    return q->rear - q->front;
}

// 入队：从队尾插入
void pushBack(Queue *q, int x) {
    q->data[q->rear++] = x;
}

// 出队：从队首删除并返回
int popFront(Queue *q) {
    return q->data[q->front++];
}

// 获取队首元素
int getFront(Queue *q) {
    return q->data[q->front];
}

/*
 * 用两个队列实现栈
 * 设计思路：
 * - 始终让 q1 保存当前栈的顺序，且“栈顶元素位于 q1 的队首”
 * - push(x) 时：
 *   1. 先把 x 放入空队列 q2
 *   2. 再把 q1 中所有元素依次移到 q2
 *   3. 交换 q1 和 q2
 * 这样就能保证最新压入的元素始终位于 q1 队首
 */
typedef struct {
    Queue q1;
    Queue q2;
} MyStack;

// 初始化栈
void initStack(MyStack *st) {
    initQueue(&st->q1);
    initQueue(&st->q2);
}

// 压栈
void push(MyStack *st, int x) {
    // 新元素先进入空队列 q2
    pushBack(&st->q2, x);

    // 将 q1 中所有元素搬到 q2
    while (!isQueueEmpty(&st->q1)) {
        pushBack(&st->q2, popFront(&st->q1));
    }

    // 交换 q1 和 q2，使 q1 始终作为主队列
    Queue temp = st->q1;
    st->q1 = st->q2;
    st->q2 = temp;
}

// 弹栈并返回栈顶元素
int pop(MyStack *st) {
    return popFront(&st->q1);
}

// 获取栈顶元素
int top(MyStack *st) {
    return getFront(&st->q1);
}

// 判断栈是否为空
bool empty(MyStack *st) {
    return isQueueEmpty(&st->q1);
}

int main() {
    int n;
    scanf("%d", &n);

    MyStack st;
    initStack(&st);

    char op[10];
    for (int i = 0; i < n; i++) {
        scanf("%s", op);

        if (strcmp(op, "push") == 0) {
            int x;
            scanf("%d", &x);
            push(&st, x);
        } else if (strcmp(op, "pop") == 0) {
            printf("%d\n", pop(&st));
        } else if (strcmp(op, "top") == 0) {
            printf("%d\n", top(&st));
        } else if (strcmp(op, "empty") == 0) {
            printf("%s\n", empty(&st) ? "true" : "false");
        }
    }

    return 0;
}

