#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 10005

// 判断括号序列是否合法
bool isValid(char s[]) {
    char stack[MAXN];   // 用数组模拟栈
    int top = -1;       // 栈顶指针，-1 表示空栈

    for (int i = 0; s[i] != '\0'; i++) {
        char ch = s[i];

        // 如果是左括号，直接入栈
        if (ch == '(' || ch == '[' || ch == '{') {
            stack[++top] = ch;
        }
        // 如果是右括号，检查是否能和栈顶匹配
        else {
            // 栈空，说明没有对应的左括号
            if (top == -1) {
                return false;
            }

            // 判断是否匹配
            if ((ch == ')' && stack[top] != '(') ||
                (ch == ']' && stack[top] != '[') ||
                (ch == '}' && stack[top] != '{')) {
                return false;
            }

            // 匹配成功，弹栈
            top--;
        }
    }

    // 最后栈为空，说明全部匹配成功
    return top == -1;
}

int main() {
    char s[MAXN];

    // 读取输入字符串
    scanf("%s", s);

    if (isValid(s)) {
        printf("true\n");
    } else {
        printf("false\n");
    }

    return 0;
}

