#include <stdlib.h>

/*
多叉树节点定义
*/
struct Node {
    int val;
    int numChildren;
    struct Node** children;
};

/*
栈中保存树节点指针
由于节点总数最多为 1e4，这里直接开一个足够大的栈空间
*/
int* postorder(struct Node* root, int* returnSize) {
    *returnSize = 0;

    // 空树直接返回空数组
    if (root == NULL) {
        return NULL;
    }

    // 题目保证节点数不超过 10000
    int capacity = 10000;

    // 用于保存“根-孩子”的遍历结果，最后再逆序得到后序
    int* temp = (int*)malloc(sizeof(int) * capacity);

    // 显式栈
    struct Node** stack = (struct Node**)malloc(sizeof(struct Node*) * capacity);
    int top = -1;

    // 根节点入栈
    stack[++top] = root;

    while (top >= 0) {
        // 弹出栈顶节点
        struct Node* cur = stack[top--];

        // 先记录当前节点值
        temp[(*returnSize)++] = cur->val;

        // 按 children[0] 到 children[numChildren-1] 的顺序入栈
        // 这样出栈时会先处理右边孩子，最后整体逆序后正好得到后序结果
        for (int i = 0; i < cur->numChildren; ++i) {
            if (cur->children[i] != NULL) {
                stack[++top] = cur->children[i];
            }
        }
    }

    // 将 temp 逆序，得到真正的后序遍历结果
    int* ans = (int*)malloc(sizeof(int) * (*returnSize));
    for (int i = 0; i < *returnSize; ++i) {
        ans[i] = temp[*returnSize - 1 - i];
    }

    free(temp);
    free(stack);

    return ans;
}

