#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 用顺序循环队列实现基础队列
 * 由于题目最多操作 100 次，这里开一个足够大的固定数组即可
 */
#define MAXN 1005

typedef struct {
    int data[MAXN];
    int front;
    int rear;
    int size;
} Queue;

/* 队列初始化 */
void queueInit(Queue* q) {
    q->front = 0;
    q->rear = 0;
    q->size = 0;
}

/* 判空 */
bool queueEmpty(Queue* q) {
    return q->size == 0;
}

/* 获取队列大小 */
int queueSize(Queue* q) {
    return q->size;
}

/* 入队：从队尾插入 */
void enqueue(Queue* q, int x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXN;
    q->size++;
}

/* 出队：从队首删除并返回 */
int dequeue(Queue* q) {
    int val = q->data[q->front];
    q->front = (q->front + 1) % MAXN;
    q->size--;
    return val;
}

/* 读取队首元素 */
int queueFront(Queue* q) {
    return q->data[q->front];
}

/*
 * 用两个队列实现栈
 * 思路：
 * 1. push(x) 时，先把 x 放入空队列 q2
 * 2. 再把 q1 中所有元素依次转移到 q2
 * 3. 最后交换 q1 和 q2
 * 这样 q1 的队首始终就是“栈顶”
 */
typedef struct {
    Queue q1;
    Queue q2;
} MyStack;

/* 初始化栈 */
void myStackInit(MyStack* obj) {
    queueInit(&obj->q1);
    queueInit(&obj->q2);
}

/* 压栈 */
void myStackPush(MyStack* obj, int x) {
    /* 先把新元素放入空队列 q2 */
    enqueue(&obj->q2, x);

    /* 再把 q1 中原有元素全部搬到 q2 */
    while (!queueEmpty(&obj->q1)) {
        enqueue(&obj->q2, dequeue(&obj->q1));
    }

    /* 交换 q1 和 q2，使 q1 始终保存当前栈内容 */
    Queue temp = obj->q1;
    obj->q1 = obj->q2;
    obj->q2 = temp;
}

/* 出栈 */
int myStackPop(MyStack* obj) {
    return dequeue(&obj->q1);
}

/* 取栈顶 */
int myStackTop(MyStack* obj) {
    return queueFront(&obj->q1);
}

/* 判空 */
bool myStackEmpty(MyStack* obj) {
    return queueEmpty(&obj->q1);
}

/* 释放资源
 * 本题使用的是静态数组，不需要额外释放堆内存
 */
void myStackFree(MyStack* obj) {
    (void)obj;
}

/*
 * 以下 main 函数仅用于本地测试，提交到部分 OJ 时可按平台要求保留或删除。
 */
int main() {
    MyStack st;
    myStackInit(&st);

    myStackPush(&st, 1);
    myStackPush(&st, 2);

    printf("%d\n", myStackTop(&st));    // 2
    printf("%d\n", myStackPop(&st));    // 2
    printf("%s\n", myStackEmpty(&st) ? "true" : "false"); // false

    myStackFree(&st);
    return 0;
}

