#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXN 1005

typedef struct {
    int data[MAXN];
    int front;
    int rear;
    int size;
} Queue;

/* 队列初始化 */
void queueInit(Queue* q) {
    q->front = 0;
    q->rear = 0;
    q->size = 0;
}

/* 判空 */
bool queueEmpty(Queue* q) {
    return q->size == 0;
}

/* 获取队列大小 */
int queueSize(Queue* q) {
    return q->size;
}

/* 入队：从队尾插入 */
void enqueue(Queue* q, int x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXN;
    q->size++;
}

/* 出队：从队首删除并返回 */
int dequeue(Queue* q) {
    int val = q->data[q->front];
    q->front = (q->front + 1) % MAXN;
    q->size--;
    return val;
}

/* 读取队首元素 */
int queueFront(Queue* q) {
    return q->data[q->front];
}

