#include <stdio.h>

/*
题意：
- workers 表示员工队列中每个人擅长的文件类型
- docs 表示文件栈，docs[0] 是栈顶
- 如果队首员工能处理栈顶文件，则该员工和该文件同时移除
- 否则员工回到队尾
- 若转了一整圈都没人能处理当前栈顶文件，则停止

简单做法：统计 0 和 1 两种员工的人数。
因为文件只有两种类型，所以实际上不需要真的模拟队列旋转。

核心思想：
- 如果当前栈顶文件类型为 0，但已经没有擅长 0 的员工，则剩余员工全部无法处理，直接返回
- 如果当前栈顶文件类型为 1，但已经没有擅长 1 的员工，同理直接返回
- 否则一定能找到一个员工处理掉这份文件，对应计数减 1，继续看下一份文件
*/
int unableToProcess(int* workers, int workersSize, int* docs, int docsSize) {
    int count[2] = {0, 0};
    int i;

    // 统计两类员工人数
    for (i = 0; i < workersSize; i++) {
        count[workers[i]]++;
    }

    // 按文件栈顶到栈底依次处理
    for (i = 0; i < docsSize; i++) {
        int type = docs[i];

        // 没有员工能处理当前栈顶文件，剩余员工都无法完成
        if (count[type] == 0) {
            return docsSize - i;
        }

        // 有员工处理掉该文件
        count[type]--;
    }

    // 所有文件都处理完了，没有员工剩下
    return 0;
}

/*
以下是一个简单的测试主函数。
在实际提交到在线评测系统时，通常只需要保留上面的 unableToProcess 函数。
*/
int main() {
    int workers1[] = {1, 1, 0, 0};
    int docs1[] = {0, 1, 0, 1};
    printf("%d\n", unableToProcess(workers1, 4, docs1, 4));  // 输出 0

    int workers2[] = {1, 1, 1, 0, 0, 1};
    int docs2[] = {1, 0, 0, 0, 1, 1};
    printf("%d\n", unableToProcess(workers2, 6, docs2, 6));  // 输出 3

    return 0;
}

