#include <stdio.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    // 用一个整数模拟栈的大小，也就是当前目录深度
    int depth = 0;
    char log[20];

    for (int i = 0; i < n; i++) {
        scanf("%s", log);

        // 情况1：返回上一级目录
        if (strcmp(log, "../") == 0) {
            // 只有当前不在根目录时，才能回退一层
            if (depth > 0) {
                depth--;
            }
        }
        // 情况2：停留在当前目录，不做任何操作
        else if (strcmp(log, "./") == 0) {
            continue;
        }
        // 情况3：进入子目录，相当于入栈
        else {
            depth++;
        }
    }

    // 最终深度就是回到根目录所需的最少 ../ 次数
    printf("%d\n", depth);

    return 0;
}

