#include <stdlib.h>

/**
 * Definition for a binary tree node.
 */
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

struct TreeNode* increasingBST(struct TreeNode* root) {
    // 题目节点数最多 100，这里开一个足够大的顺序栈
    struct TreeNode* stack[105];
    int top = -1;

    struct TreeNode* curr = root;

    // 虚拟头节点，便于统一处理新链表的拼接
    struct TreeNode dummy;
    dummy.left = NULL;
    dummy.right = NULL;

    // tail 始终指向新树的最后一个节点
    struct TreeNode* tail = &dummy;

    // 迭代中序遍历：左 -> 根 -> 右
    while (curr != NULL || top != -1) {
        // 不断向左走，并将路径上的节点压栈
        while (curr != NULL) {
            stack[++top] = curr;
            curr = curr->left;
        }

        // 栈顶节点即当前应访问的节点
        curr = stack[top--];

        // 访问当前节点时，将其接到新树的右侧
        curr->left = NULL;      // 新树要求所有 left 都为 NULL
        tail->right = curr;     // 拼接到结果链表后面
        tail = curr;            // 更新尾指针

        // 转向右子树继续中序遍历
        curr = curr->right;
    }

    // 结果树的根节点是虚拟头节点的右孩子
    return dummy.right;
}

