#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    char s[105];

    // 读入字符串
    scanf("%s", s);

    int n = strlen(s);
    char stack[105];
    int top = -1;  // 栈顶指针，-1 表示空栈

    // 依次处理每个字符
    for (int i = 0; i < n; i++) {
        char ch = s[i];

        // 如果栈不为空，且当前字符与栈顶字符可以相互消除
        if (top >= 0 && abs(stack[top] - ch) == 32) {
            top--;  // 弹出栈顶，相当于消除这一对字符
        } else {
            stack[++top] = ch;  // 否则当前字符入栈
        }
    }

    // 输出栈中剩余字符，即最终结果字符串
    for (int i = 0; i <= top; i++) {
        putchar(stack[i]);
    }
    putchar('\n');

    return 0;
}

