#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int students[105], materials[105];
    int count[2] = {0, 0};  // count[0] 表示想要 0 的学员数量，count[1] 表示想要 1 的学员数量

    // 读入 students，并统计两种偏好人数
    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i]);
        count[students[i]]++;
    }

    // 读入 materials
    for (int i = 0; i < n; i++) {
        scanf("%d", &materials[i]);
    }

    // 按栈顶到栈底依次处理资料
    for (int i = 0; i < n; i++) {
        int type = materials[i];

        // 如果当前这种资料已经没有学员想要了，说明后面也无法继续发放
        if (count[type] == 0) {
            printf("%d\n", n - i);
            return 0;
        }

        // 否则一定能发出去一份
        count[type]--;
    }

    // 所有资料都成功发放
    printf("0\n");
    return 0;
}

