#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
题意：
给定一个互不相同的整数序列，判断它是否可能是某棵二叉搜索树(BST)的先序遍历结果。

核心思路（栈）：
1. 先序遍历顺序是：根 -> 左子树 -> 右子树。
2. 使用栈维护“当前路径上的祖先节点”。
3. 维护一个 lowerBound，表示当前节点允许的最小值。
   - 一旦我们从某个节点转入它的右子树，后续所有节点都必须大于这个节点值。
4. 遍历序列中的每个值 x：
   - 如果 x < lowerBound，说明违反 BST 性质，直接判定为 NO。
   - 当栈顶元素 < x 时，说明正在不断从左子树回退，进入某些祖先的右子树：
       持续弹栈，并把最后弹出的值更新为 lowerBound。
   - 然后将 x 入栈。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /* 动态申请数组作为栈，n 最大可达 100000 */
    long long *stack = (long long *)malloc(sizeof(long long) * n);
    if (stack == NULL) {
        return 0;
    }

    int top = -1;
    long long lowerBound = LLONG_MIN;
    int valid = 1;

    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);

        /*
        如果当前值比允许的最小下界还小，
        说明它出现在某个右子树之后，却又小于祖先值，不合法。
        */
        if (x < lowerBound) {
            valid = 0;
            /*
            即使已经不合法，也继续把输入读完。
            由于这里是边读边处理，所以只需标记即可。
            */
        }

        /*
        如果当前值大于栈顶，说明左链结束，开始进入右子树。
        不断弹出所有比 x 小的祖先，并更新 lowerBound。
        */
        while (top >= 0 && stack[top] < x) {
            lowerBound = stack[top--];
        }

        /* 当前值入栈，表示继续向下走 */
        stack[++top] = x;
    }

    if (valid) {
        printf("YES\n");
    } else {
        printf("NO\n");
    }

    free(stack);
    return 0;
}

