#include <stdio.h>
#include <string.h>
#include <ctype.h>

/*
题意：
给定一个合法的嵌套整数结构字符串，统计：
1. 所有整数之和
2. 最大嵌套深度

要求体现“栈”思想。

做法：
- 用数组模拟栈，遇到 '[' 就入栈，遇到 ']' 就出栈。
- 栈当前大小就是当前所在列表深度。
- 扫描字符串时，若遇到数字或负号，则解析出一个完整整数并累加到 sum。
- 若整个字符串没有 '['，说明它只是单个整数，最大深度自然为 0。

时间复杂度：O(n)
空间复杂度：O(n)（最坏情况下所有字符都是嵌套括号）
*/

int main() {
    static char s[50005];

    if (scanf("%50000s", s) != 1) {
        return 0;
    }

    int n = (int)strlen(s);

    /* 用数组模拟栈，存放左括号即可，核心是利用栈深度 */
    static char stack[50005];
    int top = -1;

    long long sum = 0;
    int maxDepth = 0;

    for (int i = 0; i < n; i++) {
        if (s[i] == '[') {
            /* 入栈，表示进入一层新的列表 */
            stack[++top] = '[';
            if (top + 1 > maxDepth) {
                maxDepth = top + 1;
            }
        } else if (s[i] == ']') {
            /* 出栈，表示离开当前列表 */
            if (top >= 0) {
                top--;
            }
        } else if (s[i] == '-' || isdigit((unsigned char)s[i])) {
            /* 解析一个完整整数，支持负数 */
            int sign = 1;
            if (s[i] == '-') {
                sign = -1;
                i++;
            }

            long long num = 0;
            while (i < n && isdigit((unsigned char)s[i])) {
                num = num * 10 + (s[i] - '0');
                i++;
            }

            sum += sign * num;

            /*
            上面的 while 结束后，i 已经多走了一步，
            for 循环还会再 i++，所以这里回退一次。
            */
            i--;
        }
        /* 遇到逗号直接跳过 */
    }

    printf("%lld %d\n", sum, maxDepth);
    return 0;
}

