#include <stdio.h>
#include <stdlib.h>

/*
 * 单链表结点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 将链表重排为：首、尾、次首、次尾……
 *
 * 思路（栈）：
 * 1. 先遍历链表，统计长度 n，并把所有结点指针依次压入“栈”。
 *    由于数组尾部天然可作为栈顶，因此这里用动态数组模拟栈。
 * 2. 从链表头开始，用 cur 指向当前前半部分结点。
 * 3. 每次从栈顶弹出一个尾部结点 back，把它插到 cur 后面。
 * 4. 然后 cur 移动到原来的下一个前部结点，继续操作。
 * 5. 当处理到中间位置时停止，并把最后一个结点的 next 置为 NULL，避免成环。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(n)
 */
struct ListNode* rearrangeByEnds(struct ListNode* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    /* 第一步：统计链表长度 */
    int n = 0;
    struct ListNode *p = head;
    while (p != NULL) {
        n++;
        p = p->next;
    }

    /* 使用数组模拟栈，存储所有结点指针 */
    struct ListNode **stack = (struct ListNode **)malloc(sizeof(struct ListNode*) * n);
    if (stack == NULL) {
        /* 内存分配失败时，直接返回原链表 */
        return head;
    }

    p = head;
    for (int i = 0; i < n; i++) {
        stack[i] = p;
        p = p->next;
    }

    int top = n - 1;
    struct ListNode *cur = head;

    /*
     * 只需要处理前半部分：
     * 例如 n=5，处理 2 次插入：1->5, 2->4，最后剩下 3
     * 例如 n=4，处理 2 次插入：1->4, 2->3
     */
    for (int i = 0; i < n / 2; i++) {
        struct ListNode *nextFront = cur->next;  // 保存当前前部结点的下一个
        struct ListNode *back = stack[top--];    // 弹出当前尾部结点

        /*
         * 将尾部结点插入到 cur 后面：
         * cur -> back -> nextFront
         */
        cur->next = back;
        back->next = nextFront;

        /* cur 前进到下一轮的前部结点 */
        cur = nextFront;
    }

    /*
     * 断开尾部，防止形成环
     * - n 为奇数时，cur 最终在中间结点，应该令 cur->next = NULL
     * - n 为偶数时，cur 最终在后半段起点，也同样要断开
     */
    if (cur != NULL) {
        cur->next = NULL;
    }

    free(stack);
    return head;
}

/****************************
 * 以下为本地测试辅助代码
 ****************************/

/* 创建新结点 */
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

/* 根据数组创建链表 */
struct ListNode* createList(int* arr, int size) {
    if (size == 0) return NULL;
    struct ListNode* head = createNode(arr[0]);
    struct ListNode* tail = head;
    for (int i = 1; i < size; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }
    return head;
}

/* 打印链表 */
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        if (head->next != NULL) printf(",");
        head = head->next;
    }
    printf("]\n");
}

/* 释放链表 */
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr1[] = {1, 2, 3, 4};
    struct ListNode* head1 = createList(arr1, 4);
    head1 = rearrangeByEnds(head1);
    printList(head1);   // 期望输出：[1,4,2,3]
    freeList(head1);

    int arr2[] = {1, 2, 3, 4, 5};
    struct ListNode* head2 = createList(arr2, 5);
    head2 = rearrangeByEnds(head2);
    printList(head2);   // 期望输出：[1,5,2,4,3]
    freeList(head2);

    int arr3[] = {7};
    struct ListNode* head3 = createList(arr3, 1);
    head3 = rearrangeByEnds(head3);
    printList(head3);   // 期望输出：[7]
    freeList(head3);

    return 0;
}

