#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定字符串 s，包含小写字母和 #。
每遇到一个 #，必须删除它左侧尚未删除字符中字典序最小的那个字符。
若最小字符有多个，可任选其一。
要求得到字典序最小的最终字符串。

关键结论：
当某次需要删除最小字符 c 时，如果 c 出现多次，应该删除“最靠右”的那个 c。
这样能尽可能保留更靠左的位置，从而让最终字符串字典序更小。

做法：
1. 扫描字符串。
2. 对 26 个字母分别维护一个“位置栈”，栈中存该字母尚未被删除的位置。
3. 遇到普通字母，压入对应栈。
4. 遇到 #：
   - 从 'a' 到 'z' 找第一个非空栈，说明它是当前最小可删字符；
   - 弹出该栈栈顶位置（即该字符最靠右的那个未删除位置）；
   - 标记该字符位置和当前 # 位置都被删除。
5. 最后按原顺序收集所有未删除且不是 # 的字符。

复杂度：
- 每个字符最多入栈、出栈一次
- 每个 # 最多扫描 26 个字母
- 总复杂度 O(26n) = O(n)
*/

int main() {
    char *s = (char *)malloc(200005 * sizeof(char));
    if (s == NULL) return 0;

    if (scanf("%200000s", s) != 1) {
        free(s);
        return 0;
    }

    int n = (int)strlen(s);

    /* deleted[i] = 1 表示该位置字符已被删除 */
    char *deleted = (char *)calloc(n, sizeof(char));
    if (deleted == NULL) {
        free(s);
        return 0;
    }

    /*
    26 个栈，每个栈存储对应字母出现的位置。
    pos[ch][k] 表示字母 ch 的第 k 个入栈位置。
    top[ch] 为栈顶下标，初始为 -1。
    */
    int **pos = (int **)malloc(26 * sizeof(int *));
    int top[26];
    if (pos == NULL) {
        free(s);
        free(deleted);
        return 0;
    }

    for (int i = 0; i < 26; i++) {
        pos[i] = (int *)malloc(n * sizeof(int));
        top[i] = -1;
        if (pos[i] == NULL) {
            for (int j = 0; j < i; j++) free(pos[j]);
            free(pos);
            free(s);
            free(deleted);
            return 0;
        }
    }

    /* 扫描处理 */
    for (int i = 0; i < n; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            int c = s[i] - 'a';
            pos[c][++top[c]] = i;
        } else if (s[i] == '#') {
            deleted[i] = 1;  // 当前 # 一定会被删除

            /* 找当前左侧尚未删除字符中字典序最小的字母 */
            for (int c = 0; c < 26; c++) {
                if (top[c] >= 0) {
                    int idx = pos[c][top[c]--];  // 删除最靠右的那个最小字符
                    deleted[idx] = 1;
                    break;
                }
            }
        }
    }

    /* 构造答案 */
    char *ans = (char *)malloc((n + 1) * sizeof(char));
    if (ans == NULL) {
        for (int i = 0; i < 26; i++) free(pos[i]);
        free(pos);
        free(s);
        free(deleted);
        return 0;
    }

    int len = 0;
    for (int i = 0; i < n; i++) {
        if (!deleted[i] && s[i] != '#') {
            ans[len++] = s[i];
        }
    }
    ans[len] = '\0';

    printf("%s\n", ans);

    /* 释放内存 */
    for (int i = 0; i < 26; i++) free(pos[i]);
    free(pos);
    free(s);
    free(deleted);
    free(ans);

    return 0;
}

