#include <stdio.h>
#include <stdlib.h>

/**
 * Definition for singly-linked list.
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 题意：
 * 给定一个长度为偶数的单链表，结点 i 与结点 n-1-i 配对，
 * 返回所有配对中的最大和值。
 *
 * 栈解法思路：
 * 1. 先遍历链表求出长度 n。
 * 2. 再遍历前一半结点，把它们的值依次压入栈中。
 * 3. 继续遍历后一半结点，每次弹出一个栈顶元素，
 *    它正好对应当前结点的镜像结点值。
 * 4. 计算两者和，维护最大值。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(n)
 */
int maxMirrorSum(struct ListNode* head) {
    // 第一步：统计链表长度
    int n = 0;
    struct ListNode* cur = head;
    while (cur != NULL) {
        n++;
        cur = cur->next;
    }

    // 题目保证 n 为偶数，且 n >= 2
    int half = n / 2;

    // 使用动态数组模拟栈
    int* stack = (int*)malloc(sizeof(int) * half);
    int top = 0;  // top 表示当前栈中元素个数，也指向下一个入栈位置

    // 第二步：将前 half 个结点的值压栈
    cur = head;
    for (int i = 0; i < half; i++) {
        stack[top++] = cur->val;
        cur = cur->next;
    }

    // 第三步：遍历后半段，与栈顶元素配对求和
    int ans = 0;
    while (cur != NULL) {
        int leftVal = stack[--top];  // 弹出与当前结点对应的镜像值
        int sum = leftVal + cur->val;
        if (sum > ans) {
            ans = sum;
        }
        cur = cur->next;
    }

    free(stack);
    return ans;
}

