#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意简化：
- 'L'：向左移动
- 'R'：向右移动
- 'P'：静止

碰撞规则：
1. R 与 L 相撞：答案 +2，二者都变成静止
2. 移动车撞上静止车：答案 +1，移动车变成静止

解法：使用栈模拟“当前已经处理过的左侧货箱状态”。

核心思路：
- 遇到 'R'：先压栈，因为它可能和右边来的货箱发生碰撞
- 遇到 'P'：
    所有栈顶连续的 'R' 最终都会撞到这个静止货箱上，
    每个贡献 1 次停滞事件，因此不断弹出 'R' 并累加答案。
    最后把 'P' 压栈，表示当前位置（或碰撞点）现在是静止状态。
- 遇到 'L'：
    1) 若栈顶是 'R'，则先与最近的一个 'R' 对撞，答案 +2；
       此时当前货箱也变成静止状态。
       接着，栈中更靠左的连续 'R' 还会继续撞到这个新形成的静止点，
       每个再贡献 1。
       最后压入 'P'。
    2) 若栈顶是 'P'，当前 'L' 会撞上静止货箱，答案 +1，
       当前货箱也停下，压入 'P'。
    3) 否则（栈空或栈顶是 'L'），它不会和左边货箱发生碰撞，直接压入 'L'。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    char state[100005];
    if (scanf("%100000s", state) != 1) {
        return 0;
    }

    int n = (int)strlen(state);

    // 用数组手写栈
    char *stack = (char *)malloc((n + 5) * sizeof(char));
    int top = -1;

    long long ans = 0;

    for (int i = 0; i < n; i++) {
        char c = state[i];

        if (c == 'R') {
            // 先入栈，等待后续可能的碰撞
            stack[++top] = 'R';
        }
        else if (c == 'P') {
            // 所有向右移动的货箱都会撞到这个静止货箱
            while (top >= 0 && stack[top] == 'R') {
                ans += 1;
                top--;
            }
            // 当前点形成静止状态
            stack[++top] = 'P';
        }
        else if (c == 'L') {
            if (top >= 0 && stack[top] == 'R') {
                // 最近的一个 R 和当前 L 对撞
                ans += 2;
                top--;

                // 更左边若还有连续的 R，会继续撞上新形成的静止点
                while (top >= 0 && stack[top] == 'R') {
                    ans += 1;
                    top--;
                }

                // 碰撞后该位置变成静止
                stack[++top] = 'P';
            }
            else if (top >= 0 && stack[top] == 'P') {
                // 当前 L 撞上左边静止货箱
                ans += 1;
                stack[++top] = 'P';
            }
            else {
                // 不会发生碰撞，继续向左滑走
                stack[++top] = 'L';
            }
        }
    }

    printf("%lld\n", ans);

    free(stack);
    return 0;
}

