#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    // 题目保证 n 为偶数，这里不额外做复杂校验
    int *arr = (int *)malloc(sizeof(int) * n);
    if (arr == NULL) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // 使用数组模拟栈，存储前半部分元素
    int half = n / 2;
    int *stack = (int *)malloc(sizeof(int) * half);
    if (stack == NULL) {
        free(arr);
        return 0;
    }

    int top = -1;

    // 将前半部分依次入栈
    for (int i = 0; i < half; i++) {
        stack[++top] = arr[i];
    }

    int maxSum = INT_MIN;

    // 遍历后半部分，每次弹出栈顶与当前元素配对
    // 这样就能得到 arr[half-1] 对 arr[half]，arr[half-2] 对 arr[half+1] ...
    // 等价于原题中的镜像配对关系
    for (int i = half; i < n; i++) {
        int left = stack[top--];
        int sum = left + arr[i];
        if (sum > maxSum) {
            maxSum = sum;
        }
    }

    printf("%d\n", maxSum);

    free(arr);
    free(stack);
    return 0;
}

