#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);

    // 动态分配数组，避免栈空间不足
    ll *a = (ll *)malloc((n + 1) * sizeof(ll));
    ll *prefix = (ll *)malloc((n + 1) * sizeof(ll));
    int *left = (int *)malloc((n + 1) * sizeof(int));
    int *right = (int *)malloc((n + 1) * sizeof(int));
    int *stack = (int *)malloc((n + 1) * sizeof(int));

    // 读入数组，使用 1-based 下标，方便处理区间和边界
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
    }

    // 前缀和：prefix[i] 表示 a[1..i] 的元素和
    prefix[0] = 0;
    for (int i = 1; i <= n; i++) {
        prefix[i] = prefix[i - 1] + a[i];
    }

    // ------------------------------------------------------------
    // 计算 left[i]
    // left[i] 表示：在 i 左边最近的、严格小于 a[i] 的元素位置
    // 如果不存在，则为 0
    //
    // 这里使用单调递增栈：栈中下标对应的值严格递增
    // 为了处理重复值，弹栈条件使用 >=
    // 这样能保证每个元素作为“区间最小值”时，区间不会被重复计算
    // ------------------------------------------------------------
    int top = 0;
    for (int i = 1; i <= n; i++) {
        while (top > 0 && a[stack[top - 1]] >= a[i]) {
            top--;
        }
        left[i] = (top == 0) ? 0 : stack[top - 1];
        stack[top++] = i;
    }

    // ------------------------------------------------------------
    // 计算 right[i]
    // right[i] 表示：在 i 右边最近的、严格小于 a[i] 的元素位置
    // 如果不存在，则为 n + 1
    //
    // 同样用单调递增栈，从右往左扫描
    // 为了和左边界配合去重，这里弹栈条件使用 >
    // ------------------------------------------------------------
    top = 0;
    for (int i = n; i >= 1; i--) {
        while (top > 0 && a[stack[top - 1]] > a[i]) {
            top--;
        }
        right[i] = (top == 0) ? (n + 1) : stack[top - 1];
        stack[top++] = i;
    }

    // ------------------------------------------------------------
    // 枚举每个位置 i，假设 a[i] 是某个最优区间的最小值
    // 它能扩展到的最大区间为：
    // [left[i] + 1, right[i] - 1]
    //
    // 区间和可以由前缀和 O(1) 得出：
    // sum = prefix[right[i] - 1] - prefix[left[i]]
    // 稳定度 = a[i] * sum
    // ------------------------------------------------------------
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        int L = left[i] + 1;
        int R = right[i] - 1;
        ll sum = prefix[R] - prefix[L - 1];
        ll value = a[i] * sum;
        if (value > ans) {
            ans = value;
        }
    }

    printf("%lld\n", ans % MOD);

    free(a);
    free(prefix);
    free(left);
    free(right);
    free(stack);

    return 0;
}

