#include <stdlib.h>

/*
题意：
删除数组中所有“右侧存在严格更大元素”的数，返回剩余元素，顺序保持不变。

思路（单调栈）：
从左到右遍历数组，用一个栈保存“当前可能被保留”的元素。

当遍历到 nums[i] 时：
- 如果栈顶元素比 nums[i] 小，说明这个栈顶元素右侧已经出现了更大的值 nums[i]，
  因此它不可能保留，需要弹出。
- 持续弹出所有比 nums[i] 小的元素。
- 然后将 nums[i] 入栈。

最终栈中剩下的元素，就是答案，并且顺序已经正确。

例如：
nums = [5,2,13,3,8]
- 5 入栈         -> [5]
- 2 入栈         -> [5,2]
- 13 来了，弹出 2、5 -> [13]
- 3 入栈         -> [13,3]
- 8 来了，弹出 3 -> [13,8]

时间复杂度：O(n)
每个元素最多入栈一次、出栈一次。

空间复杂度：O(n)
栈在最坏情况下需要保存所有元素。
*/
int* clearWeakerElements(int* nums, int numsSize, int* returnSize) {
    // 特殊情况处理
    if (numsSize <= 0) {
        *returnSize = 0;
        return NULL;
    }

    // 用数组模拟栈
    int* stack = (int*)malloc(sizeof(int) * numsSize);
    int top = -1;

    for (int i = 0; i < numsSize; ++i) {
        // 当前元素比栈顶大，则栈顶元素右侧已经出现更大值，应删除
        while (top >= 0 && stack[top] < nums[i]) {
            top--;
        }

        // 当前元素入栈
        stack[++top] = nums[i];
    }

    // 栈中元素个数就是答案长度
    *returnSize = top + 1;

    // 为了返回紧凑数组，重新申请恰好大小的结果空间
    int* ans = (int*)malloc(sizeof(int) * (*returnSize));
    for (int i = 0; i < *returnSize; ++i) {
        ans[i] = stack[i];
    }

    free(stack);
    return ans;
}

