#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);

    ll *a = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    // left[i]: 在区间 [0..i] 中，若要求以 i 结尾形成“非递减”轮廓，
    //          且 h[i] 取到 a[i] 时，能够得到的最大高度和。
    ll *left = (ll *)malloc(sizeof(ll) * n);

    // right[i]: 在区间 [i..n-1] 中，若要求以 i 开始形成“非递增”轮廓，
    //           且 h[i] 取到 a[i] 时，能够得到的最大高度和。
    ll *right = (ll *)malloc(sizeof(ll) * n);

    // 单调栈中存下标，维护对应高度严格递增
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    // 计算 left
    // 对于每个 i，找到左边最近的一个位置 p，使得 a[p] < a[i]
    // 那么区间 (p, i] 都可以被 a[i] 作为上界“压平”成不超过 a[i] 的非递减末尾。
    for (int i = 0; i < n; i++) {
        while (top >= 0 && a[stack[top]] >= a[i]) {
            top--;
        }

        if (top == -1) {
            // 左边没有更小值，则 [0..i] 全部最多取 a[i]
            left[i] = a[i] * (i + 1LL);
        } else {
            int p = stack[top];
            // [p+1..i] 这一段都可以取到 a[i]
            // 再加上 left[p]
            left[i] = left[p] + a[i] * (i - p);
        }

        stack[++top] = i;
    }

    // 清空栈，计算 right
    top = -1;
    // 对称地，从右向左处理
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && a[stack[top]] >= a[i]) {
            top--;
        }

        if (top == -1) {
            // 右边没有更小值，则 [i..n-1] 全部最多取 a[i]
            right[i] = a[i] * (n - i);
        } else {
            int p = stack[top];
            // [i..p-1] 这一段都可以取到 a[i]
            // 再加上 right[p]
            right[i] = right[p] + a[i] * (p - i);
        }

        stack[++top] = i;
    }

    // 枚举山顶位置 i
    // left[i] + right[i] - a[i]
    // 因为 a[i] 在左右两部分中各算了一次，所以减去一次
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        ll total = left[i] + right[i] - a[i];
        if (total > ans) {
            ans = total;
        }
    }

    printf("%lld\n", ans);

    free(a);
    free(left);
    free(right);
    free(stack);

    return 0;
}

