#include <stdio.h>
#include <string.h>

/*
题意：
按照栈规约规则处理字符串：
- 读到 'a'：压栈一个新片段（状态 'a'）
- 读到 'b'：栈顶必须是 'a'，然后将其更新为 'b'
- 读到 'c'：栈顶必须是 'b'，然后弹栈

如果当前字符无法直接处理，可以在它前面插入若干字符进行修复。
问最少插入多少个字符，使整个处理结束后栈为空。

思路（栈模拟 + 贪心）：
1. 用数组模拟栈，栈中元素只会是 'a' 或 'b'：
   - 'a' 表示该片段已经有了 a，还缺 b、c
   - 'b' 表示该片段已经有了 a、b，还缺 c
2. 从左到右扫描每个字符：
   - 如果是 'a'：
       当前如果栈顶还有未完成片段，说明在新开一个片段前，
       旧片段必须先补齐：
         top='a' -> 还缺 b、c，补 2 个
         top='b' -> 还缺 c，补 1 个
       补齐后弹栈，再把新的 'a' 压栈。
   - 如果是 'b'：
       若栈顶是 'a'，可直接把它更新成 'b'；
       否则说明缺少前导 'a'，需要先插入 1 个 'a'，
       然后这个 'b' 才能接上，因此压入/更新为 'b'。
   - 如果是 'c'：
       若栈顶是 'b'，可直接弹栈；
       若栈顶是 'a'，说明缺一个 'b'，先补 1 个 'b'，再弹栈；
       若栈空，说明缺 'a' 和 'b'，先补 2 个字符，再完成该 'c'。
3. 扫描结束后，栈中如果还有未完成片段：
   - 'a' 需要再补 2 个
   - 'b' 需要再补 1 个

复杂度：
- 时间复杂度 O(n)
- 空间复杂度 O(n)
*/

int minInsertionsToValid(const char *word) {
    int n = (int)strlen(word);
    char stack[105];   // n <= 50，留足空间
    int top = -1;
    int ans = 0;

    for (int i = 0; i < n; i++) {
        char ch = word[i];

        if (ch == 'a') {
            /*
            新的 'a' 代表开启一个新片段。
            如果栈顶还有未完成片段，则必须先补齐它，
            因为合法串只能由若干个完整的 "abc" 顺序拼接而成。
            */
            if (top >= 0) {
                if (stack[top] == 'a') {
                    ans += 2;   // 补 'b' 和 'c'
                } else if (stack[top] == 'b') {
                    ans += 1;   // 补 'c'
                }
                top--;          // 该未完成片段补齐后出栈
            }
            stack[++top] = 'a';
        }
        else if (ch == 'b') {
            if (top >= 0 && stack[top] == 'a') {
                // 正常从 a 进入 b 状态
                stack[top] = 'b';
            } else {
                // 缺少前面的 'a'，插入一个 'a'
                ans += 1;
                stack[++top] = 'b';
            }
        }
        else if (ch == 'c') {
            if (top >= 0 && stack[top] == 'b') {
                // 完整匹配 abc，弹栈
                top--;
            } else if (top >= 0 && stack[top] == 'a') {
                // 只有 a，缺一个 b
                ans += 1;
                top--;
            } else {
                // 连 a、b 都没有，需要补 "ab"
                ans += 2;
            }
        }
    }

    // 扫描结束后，补齐栈中剩余未完成片段
    while (top >= 0) {
        if (stack[top] == 'a') {
            ans += 2;
        } else { // 'b'
            ans += 1;
        }
        top--;
    }

    return ans;
}

int main() {
    char word[105];

    if (scanf("%s", word) != 1) {
        return 0;
    }

    printf("%d\n", minInsertionsToValid(word));
    return 0;
}

