#include <stdio.h>
#include <stdlib.h>

/*
题目思路：
1. 我们希望找到最大的 j - i，使得 i < j 且 power[i] <= power[j]。
2. 先从左到右构造一个“单调递减栈”（栈里存下标）：
   - 如果当前下标对应的值比栈顶下标对应的值更小，才入栈。
   - 这样栈中保存的都是“可能成为最优左端点”的位置。
3. 再从右到左扫描每个 j：
   - 只要栈顶下标 i 满足 power[i] <= power[j]，
     就可以更新答案 ans = max(ans, j - i)，并弹栈。
   - 因为当前 j 已经是这个 i 能匹配到的最靠右位置，再往左扫描不可能得到更大跨度。
4. 时间复杂度 O(n)，空间复杂度 O(n)。
*/

int maxSignalSpan(int *power, int n) {
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;
    int ans = 0;

    /*
    第一步：构造单调递减栈（按 power 值递减）
    栈中保存的是下标，且 power[stack[0]] > power[stack[1]] > ...
    */
    for (int i = 0; i < n; i++) {
        if (top == -1 || power[i] < power[stack[top]]) {
            stack[++top] = i;
        }
    }

    /*
    第二步：从右往左扫描，尝试匹配尽可能远的左端点
    */
    for (int j = n - 1; j >= 0; j--) {
        while (top >= 0 && power[stack[top]] <= power[j]) {
            int width = j - stack[top];
            if (width > ans) {
                ans = width;
            }
            top--;
        }
    }

    free(stack);
    return ans;
}

int main() {
    int n;
    scanf("%d", &n);

    int *power = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &power[i]);
    }

    printf("%d\n", maxSignalSpan(power, n));

    free(power);
    return 0;
}

