#include <stdio.h>
#include <string.h>

/*
题意：
给定一个合法括号序列 seq，将每个括号分给 A 或 B（输出 0/1 表示），
要求 A、B 都是合法括号序列，并且 max(depth(A), depth(B)) 最小。

核心结论：
把不同“嵌套层”的括号按层数奇偶分配即可达到最优。

实现方法：
- 用 depth 表示当前扫描位置之前，未匹配的左括号数量。
- 遇到 '(' 时：
    该括号所在的新层数是 depth + 1。
    先分配：ans = depth % 2，然后 depth++。
  等价地，它会和对应的 ')' 被分到同一组。
- 遇到 ')' 时：
    它对应的是当前最内层未匹配左括号。
    先 depth--，再按 depth % 2 分配。

这样可以保证：
1. 每一对匹配括号进入同一组；
2. 每组仍是合法括号序列；
3. 最大深度尽可能平均分摊到两组中，达到最优。

输入：一行字符串 seq
输出：长度为 n 的 0/1 数组，空格分隔
*/

int main() {
    char seq[10005];
    if (scanf("%10000s", seq) != 1) {
        return 0;
    }

    int n = (int)strlen(seq);
    int depth = 0;
    int ans[10005];

    for (int i = 0; i < n; i++) {
        if (seq[i] == '(') {
            /*
            当前 '(' 进入更深一层。
            用进入前的 depth 奇偶性分组。
            */
            ans[i] = depth % 2;
            depth++;
        } else {
            /*
            当前 ')' 对应当前最内层的 '('。
            先退回该层，再用退回后的 depth 奇偶性分组。
            这样能保证一对匹配括号分到同一组。
            */
            depth--;
            ans[i] = depth % 2;
        }
    }

    for (int i = 0; i < n; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    return 0;
}

