#include <stdio.h>
#include <stdlib.h>

/*
思路说明：

一个区间 [l..r] 是“天幕区间”，当且仅当：
1) r - l + 1 >= 3
2) min(h[l], h[r]) > 中间所有元素

由于数组元素互不相同，所以两端一定有一个更小、一个更大。

设较小的端点是 i：
- 如果较小端点在左边，即 h[i] < h[r]
  那么区间要成立，就要求 i 和 r 之间的所有元素都 < h[i]。
  因此，r 必须正好是 i 右侧第一个比 h[i] 大的位置（next greater）。

- 如果较小端点在右边，即 h[l] > h[i]
  同理，l 必须正好是 i 左侧第一个比 h[i] 大的位置（previous greater）。

所以每个天幕区间都可以唯一对应到：
- 某个位置 i 与它的左侧第一个更大元素组成区间；或
- 某个位置 i 与它的右侧第一个更大元素组成区间。

再加上区间长度至少为 3，也就是两个端点下标差至少为 2。

因此答案就是：
- 统计所有满足 i - prevGreater[i] >= 2 的位置 i
- 统计所有满足 nextGreater[i] - i >= 2 的位置 i

利用单调栈可以在线性时间 O(n) 内求出每个位置左/右第一个更大元素。
*/

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *h = (int *)malloc(sizeof(int) * n);
    int *prevGreater = (int *)malloc(sizeof(int) * n);
    int *nextGreater = (int *)malloc(sizeof(int) * n);
    int *stack = (int *)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    /*
    计算每个位置左侧第一个更大元素的位置 prevGreater[i]
    栈内维护一个“高度单调递减”的下标栈
    */
    int top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && h[stack[top]] < h[i]) {
            top--;
        }
        if (top >= 0) {
            prevGreater[i] = stack[top];
        } else {
            prevGreater[i] = -1;
        }
        stack[++top] = i;
    }

    /*
    计算每个位置右侧第一个更大元素的位置 nextGreater[i]
    同样维护单调递减栈，不过从右往左扫描
    */
    top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && h[stack[top]] < h[i]) {
            top--;
        }
        if (top >= 0) {
            nextGreater[i] = stack[top];
        } else {
            nextGreater[i] = -1;
        }
        stack[++top] = i;
    }

    long long ans = 0;

    for (int i = 0; i < n; i++) {
        /*
        以 i 作为较小的右端点：
        区间左端是 prevGreater[i]
        长度至少为 3 => i - prevGreater[i] >= 2
        */
        if (prevGreater[i] != -1 && i - prevGreater[i] >= 2) {
            ans++;
        }

        /*
        以 i 作为较小的左端点：
        区间右端是 nextGreater[i]
        长度至少为 3 => nextGreater[i] - i >= 2
        */
        if (nextGreater[i] != -1 && nextGreater[i] - i >= 2) {
            ans++;
        }
    }

    printf("%lld\n", ans);

    free(h);
    free(prevGreater);
    free(nextGreater);
    free(stack);

    return 0;
}

