#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    long long *a = (long long *)malloc(sizeof(long long) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    /*
     * 单调栈思路：
     * 从右往左找“后缀严格最大值”位置。
     * 若 a[i] > i 右侧所有值，那么它在最优路径中一定会被经过。
     * 
     * 证明要点：
     * 1. 如果某次从 l 直接跳到 r，而中间存在 i (l < i < r) 且 a[i] > a[r]，
     *    那么改成 l -> i -> r 会更优：
     *    (i-l)*a[i] + (r-i)*a[r] > (r-l)*a[r]
     * 2. 所以，任何“比右边最终落点更大”的点，都值得插入路径。
     * 3. 于是最优路径恰好由所有“后缀严格最大值”构成，再加上终点 n-1。
     *
     * 我们用栈保存这些关键下标：
     * - 先把 n-1 入栈
     * - 从右向左扫描 [1, n-2]
     * - 若 a[i] > 当前栈顶下标对应的值，则 i 也是关键点，入栈
     *
     * 最后从栈顶到栈底依次弹出，就是从左到右的最优落点顺序。
     */

    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    /* 终点一定在路径中 */
    stack[++top] = n - 1;

    /* 找所有后缀严格最大值位置（不包括起点 0） */
    for (int i = n - 2; i >= 1; i--) {
        if (a[i] > a[stack[top]]) {
            stack[++top] = i;
        }
    }

    long long ans = 0;
    int prev = 0;

    /*
     * 依次经过这些关键点。
     * 栈顶是最靠左的关键点，持续弹出即可得到从左到右的路径。
     */
