#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定一列机器人，正数向右，负数向左，绝对值表示能量。
当右移机器人与左移机器人相遇时：
1. 小的爆炸
2. 一样大则同时爆炸
3. 幸存者继续前进并可能继续碰撞

做法：使用栈模拟当前存活的机器人。
- 若当前机器人向右，直接入栈；
- 若当前机器人向左，则可能与栈顶连续发生碰撞（前提是栈顶向右）。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *robots = (int *)malloc(sizeof(int) * n);
    int *stack = (int *)malloc(sizeof(int) * n);
    if (robots == NULL || stack == NULL) {
        free(robots);
        free(stack);
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &robots[i]);
    }

    int top = -1;  // 栈顶指针，-1 表示空栈

    for (int i = 0; i < n; i++) {
        int cur = robots[i];
        int alive = 1;  // 当前机器人是否还能存活并入栈

        /*
        只有在以下情况下才会发生碰撞：
        - 栈顶机器人向右（>0）
        - 当前机器人向左（<0）
        */
        while (alive && top >= 0 && stack[top] > 0 && cur < 0) {
            int topEnergy = stack[top];
            int curEnergy = -cur;

            if (topEnergy < curEnergy) {
                // 栈顶更小，栈顶爆炸，当前机器人继续尝试和新的栈顶碰撞
                top--;
            } else if (topEnergy == curEnergy) {
                // 同归于尽
                top--;
                alive = 0;
            } else {
                // 当前机器人更小，当前机器人爆炸
                alive = 0;
            }
        }

        if (alive) {
            stack[++top] = cur;
        }
    }

    // 输出结果
    for (int i = 0; i <= top; i++) {
        if (i > 0) printf(" ");
        printf("%d", stack[i]);
    }
    printf("\n");

    free(robots);
    free(stack);
    return 0;
}

