#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定数组 nums，求所有非空连续区间的 (最大值 - 最小值) 之和。

核心思路：贡献法 + 单调栈
1. 计算每个元素作为“区间最大值”时的贡献次数。
2. 计算每个元素作为“区间最小值”时的贡献次数。
3. 答案 = 所有最大值贡献之和 - 所有最小值贡献之和。

对于某个位置 i：
- 若它作为区间最大值：
  设 leftGreater[i]  是左侧离它最近的“严格大于 nums[i]”的位置
  设 rightGreaterEq[i] 是右侧离它最近的“大于等于 nums[i]”的位置
  则以 nums[i] 作为最大值的区间个数为：
      (i - leftGreater[i]) * (rightGreaterEq[i] - i)

- 若它作为区间最小值：
  设 leftLess[i]  是左侧离它最近的“严格小于 nums[i]”的位置
  设 rightLessEq[i] 是右侧离它最近的“小于等于 nums[i]”的位置
  则以 nums[i] 作为最小值的区间个数为：
      (i - leftLess[i]) * (rightLessEq[i] - i)

为什么一边严格、一边非严格？
- 为了处理重复元素，避免重复统计或漏统计。
- 最大值统计采用：左边严格大于，右边大于等于。
- 最小值统计采用：左边严格小于，右边小于等于。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n;
    scanf("%d", &n);

    long long *nums = (long long *)malloc(sizeof(long long) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &nums[i]);
    }

    // 四组边界数组
    int *leftGreater = (int *)malloc(sizeof(int) * n);
    int *rightGreaterEq = (int *)malloc(sizeof(int) * n);
    int *leftLess = (int *)malloc(sizeof(int) * n);
    int *rightLessEq = (int *)malloc(sizeof(int) * n);

    // 单调栈，存下标
    int *stack = (int *)malloc(sizeof(int) * n);
    int top;

    /*
    1) 求 leftGreater：左侧最近的严格大于 nums[i] 的位置
       维护一个“严格递减”的栈（栈内对应值从栈底到栈顶递减）
       当栈顶 <= nums[i] 时弹出，最后栈顶就是最近的 > nums[i]
    */
    top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && nums[stack[top]] <= nums[i]) {
            top--;
        }
        leftGreater[i] = (top >= 0) ? stack[top] : -1;
        stack[++top] = i;
    }

    /*
    2) 求 rightGreaterEq：右侧最近的大于等于 nums[i] 的位置
       从右往左，维护一个“严格递减”的栈
       当栈顶 < nums[i] 时弹出，最后栈顶就是最近的 >= nums[i]
    */
    top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && nums[stack[top]] < nums[i]) {
            top--;
        }
        rightGreaterEq[i] = (top >= 0) ? stack[top] : n;
        stack[++top] = i;
    }

    /*
    3) 求 leftLess：左侧最近的严格小于 nums[i] 的位置
       维护一个“严格递增”的栈
       当栈顶 >= nums[i] 时弹出，最后栈顶就是最近的 < nums[i]
    */
    top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && nums[stack[top]] >= nums[i]) {
            top--;
        }
        leftLess[i] = (top >= 0) ? stack[top] : -1;
        stack[++top] = i;
    }

    /*
    4) 求 rightLessEq：右侧最近的小于等于 nums[i] 的位置
       从右往左，维护一个“严格递增”的栈
       当栈顶 > nums[i] 时弹出，最后栈顶就是最近的 <= nums[i]
    */
    top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && nums[stack[top]] > nums[i]) {
            top--;
        }
        rightLessEq[i] = (top >= 0) ? stack[top] : n;
        stack[++top] = i;
    }

    // 汇总答案：总最大值贡献 - 总最小值贡献
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        long long maxCount = (long long)(i - leftGreater[i]) * (rightGreaterEq[i] - i);
        long long minCount = (long long)(i - leftLess[i]) * (rightLessEq[i] - i);

        ans += nums[i] * maxCount;
        ans -= nums[i] * minCount;
    }

    printf("%lld\n", ans);

    free(nums);
    free(leftGreater);
    free(rightGreaterEq);
    free(leftLess);
    free(rightLessEq);
    free(stack);

    return 0;
}

