#include <stdio.h>
#include <stdlib.h>

/*
 * MinCountStack
 *
 * 设计思路：
 * 对于栈中的每一个位置，除了保存当前入栈的值 val，
 * 还额外保存：
 * 1. 到当前位置为止的最小值 currentMin
 * 2. 该最小值出现的次数 minCount
 *
 * 这样：
 * - push 时，可以根据前一个栈顶的信息 O(1) 得到新状态
 * - pop 时，只需栈顶下标减一
 * - top / getMin / getMinCount 时直接读取栈顶信息
 *
 * 所有操作均为 O(1)。
 */

typedef struct {
    int val;        // 当前元素值
    int currentMin; // 压入当前元素后，栈内最小值
    int minCount;   // 当前最小值在栈内出现次数
} Node;

typedef struct {
    Node *data;     // 动态数组模拟栈
    int topIndex;   // 栈顶下标，-1 表示空栈
    int capacity;   // 当前容量
} MinCountStack;

/* 初始化栈 */
MinCountStack* minCountStackCreate() {
    MinCountStack *obj = (MinCountStack*)malloc(sizeof(MinCountStack));
    obj->capacity = 16;
    obj->topIndex = -1;
    obj->data = (Node*)malloc(sizeof(Node) * obj->capacity);
    return obj;
}

/* 扩容函数 */
void ensureCapacity(MinCountStack *obj) {
    if (obj->topIndex + 1 < obj->capacity) {
        return;
    }
    obj->capacity *= 2;
    obj->data = (Node*)realloc(obj->data, sizeof(Node) * obj->capacity);
}

/* 入栈 */
void minCountStackPush(MinCountStack* obj, int val) {
    ensureCapacity(obj);

    obj->topIndex++;

    if (obj->topIndex == 0) {
        // 第一个元素
        obj->data[obj->topIndex].val = val;
        obj->data[obj->topIndex].currentMin = val;
        obj->data[obj->topIndex].minCount = 1;
        return;
    }

    Node prev = obj->data[obj->topIndex - 1];
    obj->data[obj->topIndex].val = val;

    if (val < prev.currentMin) {
        // 出现更小的值，最小值更新，计数重置为 1
        obj->data[obj->topIndex].currentMin = val;
        obj->data[obj->topIndex].minCount = 1;
    } else if (val == prev.currentMin) {
        // 当前值等于最小值，计数 +1
        obj->data[obj->topIndex].currentMin = prev.currentMin;
        obj->data[obj->topIndex].minCount = prev.minCount + 1;
    } else {
        // 当前值更大，继承之前的最小值和计数
        obj->data[obj->topIndex].currentMin = prev.currentMin;
        obj->data[obj->topIndex].minCount = prev.minCount;
    }
}

/* 出栈 */
void minCountStackPop(MinCountStack* obj) {
    if (obj->topIndex >= 0) {
        obj->topIndex--;
    }
}

/* 获取栈顶元素 */
int minCountStackTop(MinCountStack* obj) {
    return obj->data[obj->topIndex].val;
}

/* 获取当前最小值 */
int minCountStackGetMin(MinCountStack* obj) {
    return obj->data[obj->topIndex].currentMin;
}

/* 获取当前最小值出现次数 */
int minCountStackGetMinCount(MinCountStack* obj) {
    return obj->data[obj->topIndex].minCount;
}

/* 释放栈 */
void minCountStackFree(MinCountStack* obj) {
    if (obj == NULL) return;
    free(obj->data);
    free(obj);
}

