#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 1. 按输入顺序构造 BST
 * 2. 使用“显式栈”的中序遍历，将 BST 原地转换为有序双向链表
 * 3. 输出正向和反向遍历结果
 *
 * 说明：
 * - left 指针作为双向链表的 prev
 * - right 指针作为双向链表的 next
 * - 不允许递归转换，因此使用栈模拟中序遍历
 */

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

/* 创建新节点 */
TreeNode* create_node(int val) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

/*
 * 迭代方式插入 BST
 * 题目保证所有值互不相同
 */
TreeNode* insert_bst(TreeNode* root, int val) {
    TreeNode* node = create_node(val);
    if (root == NULL) {
        return node;
    }

    TreeNode* cur = root;
    TreeNode* parent = NULL;

    while (cur != NULL) {
        parent = cur;
        if (val < cur->val) {
            cur = cur->left;
        } else {
            cur = cur->right;
        }
    }

    if (val < parent->val) {
        parent->left = node;
    } else {
        parent->right = node;
    }

    return root;
}

/*
 * 使用栈进行中序遍历，将 BST 原地改造成有序双向链表
 * 返回头结点，并通过 tail_out 返回尾结点
 */
TreeNode* bst_to_doubly_list(TreeNode* root, TreeNode** tail_out, int n) {
    if (root == NULL) {
        *tail_out = NULL;
        return NULL;
    }

    /*
     * 栈最大深度不会超过节点总数 n
     * 这里直接申请 n 个指针空间，足够使用
     */
    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * (n > 0 ? n : 1));
    int top = -1;

    TreeNode* cur = root;
    TreeNode* prev = NULL;   /* 双向链表中当前节点的前驱 */
    TreeNode* head = NULL;   /* 链表头 */
    TreeNode* tail = NULL;   /* 链表尾 */

    while (cur != NULL || top >= 0) {
        /* 一路向左入栈 */
        while (cur != NULL) {
            stack[++top] = cur;
            cur = cur->left;
        }

        /* 访问栈顶节点 */
        cur = stack[top--];

        /* 将当前节点接到双向链表尾部 */
        if (head == NULL) {
            head = cur;
        }
        cur->left = prev;
        if (prev != NULL) {
            prev->right = cur;
        }

        prev = cur;
        tail = cur;

        /* 转向原来的右子树 */
        cur = cur->right;
    }

    /* 补齐首尾边界 */
    if (head != NULL) {
        head->left = NULL;
    }
    if (tail != NULL) {
        tail->right = NULL;
    }

    free(stack);
    *tail_out = tail;
    return head;
}

/* 正向输出链表 */
void print_forward(TreeNode* head) {
    TreeNode* cur = head;
    int first = 1;
    while (cur != NULL) {
        if (!first) printf(" ");
        printf("%d", cur->val);
        first = 0;
        cur = cur->right;
    }
    printf("\n");
}

/* 反向输出链表 */
void print_backward(TreeNode* tail) {
    TreeNode* cur = tail;
    int first = 1;
    while (cur != NULL) {
        if (!first) printf(" ");
        printf("%d", cur->val);
        first = 0;
        cur = cur->left;
    }
    printf("\n");
}

/* 释放链表内存 */
void free_list(TreeNode* head) {
    TreeNode* cur = head;
    while (cur != NULL) {
        TreeNode* next = cur->right;
        free(cur);
        cur = next;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    if (n == 0) {
        printf("EMPTY\n");
        return 0;
    }

    TreeNode* root = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        root = insert_bst(root, x);
    }

    TreeNode* tail = NULL;
    TreeNode* head = bst_to_doubly_list(root, &tail, n);

    print_forward(head);
    print_backward(tail);

    free_list(head);
    return 0;
}

