#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 100005

int main() {
    static char s[MAXN];

    // 读取一整行输入
    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }

    // 去掉末尾换行符
    int n = strlen(s);
    if (n > 0 && s[n - 1] == '\n') {
        s[--n] = '\0';
    }

    // del[i] = 1 表示该位置字符需要被删除
    int *del = (int *)calloc(n, sizeof(int));
    // 栈中存放尚未匹配的 '(' 的下标
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    // 第一次扫描：删除无法匹配的 ')'
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') {
            // 左括号下标入栈，等待后续匹配
            stack[++top] = i;
        } else if (s[i] == ')') {
            if (top >= 0) {
                // 存在可匹配的 '('，完成一次匹配
                top--;
            } else {
                // 没有可匹配的 '('，该 ')' 无效，标记删除
                del[i] = 1;
            }
        }
        // 字母和数字无需处理，直接保留
    }

    // 扫描结束后，栈中剩余的 '(' 都是无效的，需要删除
    while (top >= 0) {
        del[stack[top--]] = 1;
    }

    // 输出结果：跳过所有被标记删除的位置
    for (int i = 0; i < n; i++) {
        if (!del[i]) {
            putchar(s[i]);
        }
    }
    putchar('\n');

    free(del);
    free(stack);
    return 0;
}

