#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int value;   // 当前组的数值
    int count;   // 该数值在栈顶连续“有效候选”中出现了多少次
} Node;

int main() {
    int n;
    scanf("%d", &n);

    int *nums = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    // 单调不增栈：栈中 value 从底到顶非严格递减
    Node *stack = (Node *)malloc(sizeof(Node) * n);
    int top = -1;

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        int x = nums[i];

        // 每个单独元素自身一定构成一个长度为 1 的合法区间
        ans++;

        // 栈中所有比 x 小的值都不可能再与未来位置组成合法区间：
        // 因为当前出现了更大的 x，它会“挡住”这些更小值。
        while (top >= 0 && stack[top].value < x) {
            top--;
        }

        if (top >= 0 && stack[top].value == x) {
            // 当前 x 可以与栈顶这一组中的所有相同值分别配对，
            // 形成若干个“左右端点相等且为区间最大值”的新区间。
            ans += stack[top].count;

            // 当前 x 也加入这组，供后面的元素继续配对
            stack[top].count++;
        } else {
            // 栈为空，或栈顶值 > x：
            // 当前 x 不能和前面任何值直接形成新区间，只能作为新候选入栈
            top++;
            stack[top].value = x;
            stack[top].count = 1;
        }
    }

    printf("%lld\n", ans);

    free(nums);
    free(stack);
    return 0;
}

