#include <stdio.h>
#include <stdlib.h>

/*
 * 题意本质：
 * 对每个运输器 i，求它第一次与前方某个目标（单个运输器或已形成的运输队）合并的时间。
 *
 * 核心思路（单调栈）：
 * 从右向左处理每个运输器。
 * 栈中维护“对当前及更左侧运输器仍然可能成为有效碰撞目标”的下标。
 *
 * 设当前运输器为 i，栈顶候选目标为 j。
 * 1) 若 v[i] <= v[j]，则 i 永远追不上 j，j 不可能成为答案，弹出。
 * 2) 否则可计算理论追上时间 t = (x[j] - x[i]) / (v[i] - v[j])。
 *    但如果 j 会在 ans[j] 时刻先与前方合并，且 t > ans[j]，
 *    则说明 i 还没来得及追上 j，j 已经变成别的运输队了，
 *    因而 j 也不是 i 的有效目标，需要弹出继续判断。
 * 3) 否则，j 就是 i 的第一次合并对象，ans[i] = t。
 *
 * 每个元素最多进栈出栈一次，总复杂度 O(n)。
 */

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *x = (int *)malloc(sizeof(int) * n);
    int *v = (int *)malloc(sizeof(int) * n);
    double *ans = (double *)malloc(sizeof(double) * n);
    int *stack = (int *)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        scanf("%d %d", &x[i], &v[i]);
        ans[i] = -1.0;
    }

    int top = -1;  // 单调栈，存下标

    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0) {
            int j = stack[top];

            // 当前速度不比候选目标快，不可能追上
            if (v[i] <= v[j]) {
                top--;
                continue;
            }

            // 理论碰撞时间
            double t = (double)(x[j] - x[i]) / (double)(v[i] - v[j]);

            // 如果 j 会先在 ans[j] 时刻与别人合并，且 i 追上 j 的时间更晚，
            // 那么 i 实际上追到的不会是“原来的 j”，j 不再是有效候选。
            if (ans[j] > 0.0 && t > ans[j]) {
                top--;
                continue;
            }

            // 找到有效碰撞目标
            break;
        }

        if (top >= 0) {
            int j = stack[top];
            ans[i] = (double)(x[j] - x[i]) / (double)(v[i] - v[j]);
        }

        stack[++top] = i;
    }

    for (int i = 0; i < n; i++) {
        if (i) printf(" ");
        if (ans[i] < 0) printf("-1.00000");
        else printf("%.5f", ans[i]);
    }
    printf("\n");

    free(x);
    free(v);
    free(ans);
    free(stack);

    return 0;
}

