#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定 n 件藏品，每件有 value 和 type。
从中选出恰好 k 件（保持原相对顺序的子序列），
最大化：sum(value) + distinct_type^2。

核心结论：
虽然题目要求“子序列”，但只要确定选中了哪些元素，
按原顺序取出它们自然就是一个合法子序列。
因此问题等价于：从所有元素里选恰好 k 个，最大化上述表达式。

经典做法：
1. 先按 value 从大到小排序。
2. 先取前 k 个，保证初始总价值尽可能大。
3. 若某个元素的 type 已出现过，则它是“重复类别元素”。
   这些元素中的某些可以被后面“尚未出现的新类别元素”替换。
4. 由于排序后 value 非增，
   在前 k 个中，后加入的“重复类别元素”价值一定不大于先加入的，
   因此可以用“栈”维护这些可替换元素的 value：
   栈顶始终是当前最适合被替换（价值最小）的重复元素。
5. 枚举后续元素，如果它带来一个新类别，且栈非空，
   就用它替换掉一个栈顶重复元素，并更新答案。

时间复杂度：O(n log n)
空间复杂度：O(n)
*/

typedef long long ll;

typedef struct {
    int value;
    int type;
} Item;

/* 按 value 降序排序 */
int cmpItem(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->value < y->value) return 1;
    if (x->value > y->value) return -1;
    return 0;
}

static inline ll maxll(ll a, ll b) {
    return a > b ? a : b;
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }

    Item *items = (Item *)malloc(sizeof(Item) * n);
    for (int i = 0; i < n; ++i) {
        scanf("%d %d", &items[i].value, &items[i].type);
    }

    /* 按价值从大到小排序 */
    qsort(items, n, sizeof(Item), cmpItem);

    /*
    cnt[type] 表示当前已选集合中该类别出现次数。
    题目保证 1 <= type <= n，可直接开 n+1。
    */
    int *cnt = (int *)calloc(n + 1, sizeof(int));

    /*
    用数组模拟栈：存放“前 k 个已选元素中，那些类别重复的元素的 value”。
    因为按价值降序扫描，后压入栈的重复元素价值更小（或相等），
    所以替换时直接弹栈顶即可，相当于移除当前最小的可替换重复元素。
    */
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = 0; /* 栈大小 */

    ll sum = 0;           /* 当前选中 k 个元素的总价值 */
    ll distinct = 0;      /* 当前不同类别数 */

    /* 先取前 k 个价值最大的元素 */
    for (int i = 0; i < k; ++i) {
        sum += items[i].value;
        if (cnt[items[i].type] == 0) {
            distinct++;
        } else {
            /* 该元素类别重复，可作为未来替换对象，压入栈 */
            stack[top++] = items[i].value;
        }
        cnt[items[i].type]++;
    }

    ll ans = sum + distinct * distinct;

    /*
    枚举后面的元素：
    若发现一个“新类别”元素，并且当前有可替换的重复元素，
    就用它替换掉栈顶（即价值最小的重复元素），尝试提升答案。
    */
    for (int i = k; i < n; ++i) {
        int v = items[i].value;
        int t = items[i].type;

        /* 只有新类别才有必要考虑，因为重复类别不会增加 distinct */
        if (cnt[t] == 0 && top > 0) {
            int removed = stack[--top];  /* 移除一个最小重复元素 */
            sum = sum - removed + v;
            distinct++;
            cnt[t] = 1;

            ans = maxll(ans, sum + distinct * distinct);
        }
    }

    printf("%lld\n", ans);

    free(items);
    free(cnt);
    free(stack);
    return 0;
}

