#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

/*
 * 每个子表达式都维护两类信息：
 * t = 该子表达式求值为 true 的方案数
 * f = 该子表达式求值为 false 的方案数
 */
typedef struct {
    ll t;
    ll f;
} Node;

static ll mod_add(ll a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

static ll mod_sub(ll a, ll b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

static ll mod_mul(ll a, ll b) {
    return (a * b) % MOD;
}

int main() {
    char *expression = (char *)malloc(400005);
    if (expression == NULL) return 0;

    if (scanf("%400000s", expression) != 1) {
        free(expression);
        return 0;
    }

    int n = (int)strlen(expression);

    /*
     * 操作符栈：保存 &, |, !
     */
    char *opStack = (char *)malloc((n + 5) * sizeof(char));

    /*
     * 值栈：保存已经归约好的子表达式 (t, f)
     */
    Node *valStack = (Node *)malloc((n + 5) * sizeof(Node));

    /*
     * 标记栈：遇到 '(' 时，在值栈上记录当前边界位置，
     * 扫描到 ')' 时，就能知道这一层子表达式的参数范围。
     */
    int *markStack = (int *)malloc((n + 5) * sizeof(int));

    if (opStack == NULL || valStack == NULL || markStack == NULL) {
        free(expression);
        free(opStack);
        free(valStack);
        free(markStack);
        return 0;
    }

    int opTop = -1;
    int valTop = -1;
    int markTop = -1;

    for (int i = 0; i < n; ++i) {
        char c = expression[i];

        if (c == '&' || c == '|' || c == '!') {
            /* 压入操作符栈 */
            opStack[++opTop] = c;
        } else if (c == '(') {
            /*
             * 记录当前值栈顶部，表示此层参数起点之前的位置。
             * 之后直到对应 ')' 之间新压入的值，都是该操作符的参数。
             */
            markStack[++markTop] = valTop;
        } else if (c == 't') {
            valStack[++valTop].t = 1;
            valStack[valTop].f = 0;
        } else if (c == 'f') {
            valStack[++valTop].t = 0;
            valStack[valTop].f = 1;
        } else if (c == '?') {
            /* '?' 可以独立替换为 t 或 f */
            valStack[++valTop].t = 1;
            valStack[valTop].f = 1;
        } else if (c == ',') {
            /* 分隔符，直接跳过 */
            continue;
        } else if (c == ')') {
            /*
             * 归约一个完整的子表达式。
             * 参数范围为 valStack[(lastMark+1) ... valTop]
             */
            int lastMark = markStack[markTop--];
            char op = opStack[opTop--];

            int l = lastMark + 1;
            int r = valTop;

            Node res;

            if (op == '!') {
                /* 合法表达式保证 ! 只有一个参数 */
                Node a = valStack[r];
                res.t = a.f;
                res.f = a.t;
            } else if (op == '&') {
                /*
                 * AND:
                 * true 方案数 = 所有参数 true 方案数之积
                 * total 方案数 = 所有参数 (t+f) 方案数之积
                 * false = total - true
                 */
                ll trueWays = 1;
                ll totalWays = 1;
                for (int j = l; j <= r; ++j) {
                    trueWays = mod_mul(trueWays, valStack[j].t);
                    totalWays = mod_mul(totalWays, mod_add(valStack[j].t, valStack[j].f));
                }
                res.t = trueWays;
                res.f = mod_sub(totalWays, trueWays);
            } else {
                /* op == '|' */
                /*
                 * OR:
                 * false 方案数 = 所有参数 false 方案数之积
                 * total 方案数 = 所有参数 (t+f) 方案数之积
                 * true = total - false
                 */
                ll falseWays = 1;
                ll totalWays = 1;
                for (int j = l; j <= r; ++j) {
                    falseWays = mod_mul(falseWays, valStack[j].f);
                    totalWays = mod_mul(totalWays, mod_add(valStack[j].t, valStack[j].f));
                }
                res.f = falseWays;
                res.t = mod_sub(totalWays, falseWays);
            }

            /*
             * 弹出这一层的所有参数，只保留归约后的结果。
             * 由于 lastMark 是进入 '(' 前的 valTop，
             * 所以归约完成后直接把 valTop 回退到 lastMark，
             * 再压入 res 即可。
             */
            valTop = lastMark;
            valStack[++valTop] = res;
        }
    }

    /* 最终整个表达式应当只剩一个结果 */
    printf("%lld\n", valStack[valTop].t % MOD);

    free(expression);
    free(opStack);
    free(valStack);
    free(markStack);
    return 0;
}

