#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
核心思路：
1. 巡航器碰撞是否发生，只与它们在“位置排序后”的相对关系有关。
2. 只有“前面向右(R)”和“后面向左(L)”的巡航器才可能相撞。
3. 因此按位置升序排序后：
   - 遇到 R，压栈
   - 遇到 L，就不断与栈顶的 R 进行碰撞模拟
4. 用栈维护“当前仍然可能与未来 L 碰撞的、向右移动的巡航器”。
5. 最后按原始输入顺序输出仍存活者的最终稳定值。

时间复杂度：O(n log n)（排序）
栈模拟总碰撞次数为 O(n)，因此总复杂度为 O(n log n)
*/

typedef struct {
    int pos;      // 初始位置
    int health;   // 当前稳定值（会变化）
    char dir;     // 方向
    int idx;      // 原始下标
    int alive;    // 是否存活
} Robot;

int cmpRobot(const void *a, const void *b) {
    const Robot *ra = (const Robot *)a;
    const Robot *rb = (const Robot *)b;
    if (ra->pos < rb->pos) return -1;
    if (ra->pos > rb->pos) return 1;
    return 0;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *positions = (int *)malloc(sizeof(int) * n);
    int *healths = (int *)malloc(sizeof(int) * n);
    char *directions = (char *)malloc(sizeof(char) * (n + 5));
    Robot *robots = (Robot *)malloc(sizeof(Robot) * n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &positions[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &healths[i]);
    }
    scanf("%s", directions);

    for (int i = 0; i < n; i++) {
        robots[i].pos = positions[i];
        robots[i].health = healths[i];
        robots[i].dir = directions[i];
        robots[i].idx = i;
        robots[i].alive = 1;
    }

    // 按位置排序，便于从左到右处理碰撞关系
    qsort(robots, n, sizeof(Robot), cmpRobot);

    // 栈中存放“按位置排序后的下标”，且这些机器人方向都是 R，并且当前存活
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    for (int i = 0; i < n; i++) {
        if (robots[i].dir == 'R') {
            // 向右的机器人可能与未来某个向左机器人碰撞，入栈
            stack[++top] = i;
        } else {
            // 当前是向左的机器人，尝试与栈顶向右机器人连续碰撞
            while (top >= 0 && robots[i].alive) {
                int j = stack[top];

                // 理论上栈内都应为存活的 R，下面开始模拟碰撞
                if (!robots[j].alive) {
                    top--;
                    continue;
                }

                if (robots[j].health < robots[i].health) {
                    // 栈顶 R 被撞毁，当前 L 存活且 health - 1，继续找下一个 R
                    robots[j].alive = 0;
                    top--;
                    robots[i].health -= 1;
                } else if (robots[j].health > robots[i].health) {
                    // 当前 L 被撞毁，栈顶 R 存活且 health - 1
                    robots[i].alive = 0;
                    robots[j].health -= 1;
                } else {
                    // 二者同归于尽
                    robots[i].alive = 0;
                    robots[j].alive = 0;
                    top--;
                }
            }
        }
    }

    // 按原始输入顺序收集答案
    int *ans = (int *)malloc(sizeof(int) * n);
    int cnt = 0;

    // 由于 robots 已按位置排序，需要根据 idx 还原到原始顺序
    int *finalHealth = (int *)malloc(sizeof(int) * n);
    int *survive = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        finalHealth[i] = 0;
        survive[i] = 0;
    }

    for (int i = 0; i < n; i++) {
        if (robots[i].alive) {
            survive[robots[i].idx] = 1;
            finalHealth[robots[i].idx] = robots[i].health;
        }
    }

    for (int i = 0; i < n; i++) {
        if (survive[i]) {
            ans[cnt++] = finalHealth[i];
        }
    }

    // 输出结果
    printf("%d\n", cnt);
    for (int i = 0; i < cnt; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(positions);
    free(healths);
    free(directions);
    free(robots);
    free(stack);
    free(ans);
    free(finalHealth);
    free(survive);

    return 0;
}

