#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

/*
 * 题意：
 * 对所有连续非空子数组，计算 min(subarray) * sum(subarray) 的总和。
 *
 * 核心做法：
 * 1. 用单调栈求每个位置 i 作为“区间最小值代表”时，左边第一个严格小于它的位置 left[i]，
 *    右边第一个小于等于它的位置 right[i]。
 *    这样可避免重复统计相等元素。
 *
 * 2. 对于固定位置 i，所有以 ore[i] 作为最小值代表的子数组，左端点 l 范围为 (left[i], i]，
 *    右端点 r 范围为 [i, right[i])。
 *
 * 3. 我们需要求所有这些子数组的 sum(ore[l..r]) 之和，再乘 ore[i]。
 *    这可以通过“前缀和的前缀和”在 O(1) 内计算。
 *
 * 公式说明：
 * 设 pre[x] = ore[0] + ... + ore[x-1]   (长度 n+1, pre[0]=0)
 * 再设 ppre[x] = pre[0] + pre[1] + ... + pre[x-1]   (长度 n+2, ppre[0]=0)
 *
 * 对固定 i：
 *   L = left[i], R = right[i]
 *   左端点个数 leftCount = i - L
 *   右端点个数 rightCount = R - i
 *
 * 子数组和总贡献可化为：
 *   (sum_{r=i}^{R-1} pre[r+1]) * leftCount - (sum_{l=L+1}^{i} pre[l-1]) * rightCount
 *
 * 用 ppre 可快速取区间和：
 *   sum_{k=a}^{b} pre[k] = ppre[b+1] - ppre[a]
 *
 * 最终答案累加： ore[i] * (positivePart - negativePart)
 */

static ll mod_norm(ll x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return x;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    ll *ore = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; ++i) {
        scanf("%lld", &ore[i]);
        ore[i] %= MOD;
    }

    /* 前缀和 pre，长度 n+1 */
    ll *pre = (ll *)malloc(sizeof(ll) * (n + 1));
    pre[0] = 0;
    for (int i = 0; i < n; ++i) {
        pre[i + 1] = (pre[i] + ore[i]) % MOD;
    }

    /* 前缀和的前缀和 ppre，长度 n+2
       ppre[k+1] = pre[0] + ... + pre[k] */
    ll *ppre = (ll *)malloc(sizeof(ll) * (n + 2));
    ppre[0] = 0;
    for (int i = 0; i <= n; ++i) {
        ppre[i + 1] = (ppre[i] + pre[i]) % MOD;
    }

    int *left = (int *)malloc(sizeof(int) * n);
    int *right = (int *)malloc(sizeof(int) * n);
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    /*
     * 求 left[i]: 左侧第一个严格小于 ore[i] 的位置
     * 维护单调递增栈，遇到 >= 当前值的都弹出
     */
    for (int i = 0; i < n; ++i) {
        while (top >= 0 && ore[stack[top]] >= ore[i]) {
            --top;
        }
        left[i] = (top >= 0) ? stack[top] : -1;
        stack[++top] = i;
    }

    /*
     * 求 right[i]: 右侧第一个小于等于 ore[i] 的位置
     * 从右往左，维护单调递增栈，遇到 > 当前值的弹出
     */
    top = -1;
    for (int i = n - 1; i >= 0; --i) {
        while (top >= 0 && ore[stack[top]] > ore[i]) {
            --top;
        }
        right[i] = (top >= 0) ? stack[top] : n;
        stack[++top] = i;
    }

    ll ans = 0;

    for (int i = 0; i < n; ++i) {
        int L = left[i];
        int R = right[i];

        ll leftCount = i - L;     /* 左端点可选数量 */
        ll rightCount = R - i;    /* 右端点可选数量 */

        /*
         * sumRight = pre[i+1] + pre[i+2] + ... + pre[R]
         * 对应 ppre[R+1] - ppre[i+1]
         */
        ll sumRight = mod_norm(ppre[R + 1] - ppre[i + 1]);

        /*
         * sumLeft = pre[L+1? 不对] 实际需要的是 pre[l]，其中 l 属于 [L+1, i]
         * 即 pre[L+1] + pre[L+2] + ... + pre[i]
         * 对应 ppre[i+1] - ppre[L+1]
         */
        ll sumLeft = mod_norm(ppre[i + 1] - ppre[L + 1]);

        ll totalSubarraySums = mod_norm(sumRight * (leftCount % MOD) - sumLeft * (rightCount % MOD));
        ll contribution = ore[i] * totalSubarraySums % MOD;
        ans += contribution;
        ans %= MOD;
    }

    printf("%lld\n", ans % MOD);

    free(ore);
    free(pre);
    free(ppre);
    free(left);
    free(right);
    free(stack);

    return 0;
}

