#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int students[205];   // 开大一些，便于循环队列操作
    int snacks[105];

    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i]);
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &snacks[i]);
    }

    // 使用数组模拟循环队列
    int front = 0;   // 队首下标
    int rear = n;    // 队尾的下一位置
    int size = n;    // 当前队列中的人数
    int snackIndex = 0; // 当前处理到的点心下标

    // failCount 表示连续多少个学员都没有拿走当前点心
    int failCount = 0;

    while (size > 0 && failCount < size) {
        int current = students[front];
        front++;

        // 如果队首学员喜欢当前点心，则领取并离开
        if (current == snacks[snackIndex]) {
            size--;
            snackIndex++;
            failCount = 0; // 有人成功领取，重新计数
        } else {
            // 否则回到队尾
            students[rear] = current;
            rear++;
            failCount++;
        }
    }

    // 剩余队列人数就是无法领到点心的人数
    printf("%d\n", size);

    return 0;
}

