#include <stdio.h>

// 定义队列中的结点：记录顾客剩余需要领取的餐品数，以及其初始编号
typedef struct {
    int remain;
    int id;
} Node;

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int need[105];
    for (int i = 0; i < n; i++) {
        scanf("%d", &need[i]);
    }

    // 由于题目数据范围较小，这里使用数组模拟一个简单队列
    Node queue[10005];
    int front = 0, rear = 0;

    // 初始时，所有顾客按顺序入队
    for (int i = 0; i < n; i++) {
        queue[rear].remain = need[i];
        queue[rear].id = i;
        rear++;
    }

    int time = 0;

    // 不断模拟队首顾客领取餐品
    while (front < rear) {
        Node cur = queue[front++];  // 出队

        // 当前顾客领取 1 份餐品，耗时 1 秒
        cur.remain--;
        time++;

        // 如果当前正好是目标顾客，并且已经领取完所有餐品，直接输出答案
        if (cur.id == k && cur.remain == 0) {
            printf("%d\n", time);
            return 0;
        }

        // 如果还没领完，则回到队尾继续排队
        if (cur.remain > 0) {
            queue[rear++] = cur;
        }
    }

    return 0;
}

