#include <stdio.h>

// 使用数组模拟队列中的每个人
// remain[i]：当前这个人还需要多少张餐券
// idx[i]：这个人最初的编号，用来判断是否是目标同学

typedef struct {
    int id;      // 原始编号
    int remain;  // 剩余需要领取的张数
} Person;

int main() {
    int n;
    scanf("%d", &n);

    Person q[10005];
    int front = 0, rear = 0;

    // 读入每个人需要的餐券数，并加入队列
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        q[rear].id = i;
        q[rear].remain = x;
        rear++;
    }

    int k;
    scanf("%d", &k);

    int time = 0;

    // 不断模拟队首同学领取餐券
    while (front < rear) {
        // 取出队首
        Person cur = q[front++];

        // 领取一张餐券，耗时1秒
        cur.remain--;
        time++;

        // 如果当前人已经领完
        if (cur.remain == 0) {
            // 若正好是目标同学，输出答案并结束
            if (cur.id == k) {
                printf("%d\n", time);
                return 0;
            }
            // 否则此人离队，不再入队
        } else {
            // 还没领完，回到队尾
            q[rear++] = cur;
        }
    }

    return 0;
}

