#include <stdio.h>

/*
题意：
- students 表示学生队列中每个人喜欢的饮料类型（0 或 1）
- drinks 表示饮料发放顺序，drinks[0] 是当前要发的饮料
- 如果队首学生喜欢当前饮料，就领取并离开
- 否则回到队尾
- 当队列中没有人喜欢当前饮料时，过程结束
- 返回无法领到饮料的学生人数

思路（简单做法）：
由于饮料只有 0 和 1 两种类型，实际上不必真的模拟队列旋转。
只需要统计：
- 喜欢 0 的学生数量 count0
- 喜欢 1 的学生数量 count1

然后按 drinks 的顺序依次检查：
- 如果当前饮料是 0，但 count0 == 0，说明没人喜欢它，剩余学生都无法领取，直接返回剩余人数
- 如果当前饮料是 1，但 count1 == 0，同理返回剩余人数
- 否则，将对应喜欢该饮料的学生数量减 1

最终如果所有饮料都能发完，则返回 0。
*/
int countUnableToDrink(int* students, int studentsSize, int* drinks, int drinksSize) {
    int count0 = 0, count1 = 0;
    int i;

    /* 统计两种偏好的学生数量 */
    for (i = 0; i < studentsSize; i++) {
        if (students[i] == 0) {
            count0++;
        } else {
            count1++;
        }
    }

    /* 按饮料发放顺序处理 */
    for (i = 0; i < drinksSize; i++) {
        if (drinks[i] == 0) {
            /* 没有人喜欢 0，当前以及后面的饮料都无法继续发放 */
            if (count0 == 0) {
                return drinksSize - i;
            }
            count0--;
        } else {
            /* 没有人喜欢 1，当前以及后面的饮料都无法继续发放 */
            if (count1 == 0) {
                return drinksSize - i;
            }
            count1--;
        }
    }

    return 0;
}

/* 以下为简单测试代码，可根据需要删除 */
int main() {
    int students1[] = {1, 1, 0, 0};
    int drinks1[] = {0, 1, 0, 1};
    printf("%d\n", countUnableToDrink(students1, 4, drinks1, 4));  // 输出 0

    int students2[] = {1, 1, 1, 0, 0, 1};
    int drinks2[] = {1, 0, 0, 0, 1, 1};
    printf("%d\n", countUnableToDrink(students2, 6, drinks2, 6));  // 输出 3

    return 0;
}

