#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int workers[105], meals[105];

    for (int i = 0; i < n; i++) {
        scanf("%d", &workers[i]);
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &meals[i]);
    }

    // 使用循环队列模拟员工排队
    int queue[205];
    int front = 0, rear = 0;

    // 初始入队
    for (int i = 0; i < n; i++) {
        queue[rear++] = workers[i];
    }

    int mealIndex = 0;      // 当前处理到的餐点位置
    int remain = n;         // 当前队列中剩余员工数
    int failCount = 0;      // 连续多少人不接受当前餐点

    while (remain > 0 && mealIndex < n) {
        // 取出队首员工
        int current = queue[front++];

        if (current == meals[mealIndex]) {
            // 员工领取餐点并离开
            mealIndex++;
            remain--;
            failCount = 0;  // 只要有人成功领取，重新计数
        } else {
            // 不喜欢当前餐点，回到队尾
            queue[rear++] = current;
            failCount++;

            // 如果连续 remain 个员工都不接受当前餐点，说明无法继续
            if (failCount == remain) {
                break;
            }
        }
    }

    // remain 即为无法领取餐点的员工人数
    printf("%d\n", remain);

    return 0;
}

