#include <stdio.h>
#include <string.h>

#define MAXN 100005

int main() {
    char s[MAXN];

    // 读取字符串
    if (scanf("%s", s) != 1) {
        return 0;
    }

    int n = strlen(s);

    // cnt[c] 记录字符 c 出现的次数
    int cnt[26] = {0};

    // 用数组模拟队列，队列中存放字符下标
    int queue[MAXN];
    int front = 0, rear = 0;

    // 按顺序处理每个字符
    for (int i = 0; i < n; i++) {
        int ch = s[i] - 'a';
        cnt[ch]++;

        // 当前下标进入候选队列
        queue[rear++] = i;

        // 如果队首对应字符已经重复，就移出队列
        while (front < rear && cnt[s[queue[front]] - 'a'] > 1) {
            front++;
        }
    }

    // 队列非空，则队首就是第一个只出现一次字符的下标
    if (front < rear) {
        printf("%d\n", queue[front]);
    } else {
        printf("-1\n");
    }

    return 0;
}

