#include <stdio.h>
#include <stdbool.h>

// 题目中最多调用 100 次操作，这里开一个足够大的数组模拟栈
#define MAXN 1000

// 定义栈结构
typedef struct {
    int data[MAXN];
    int top; // top 指向当前栈顶元素下标，-1 表示空栈
} Stack;

// 初始化栈
void initStack(Stack *s) {
    s->top = -1;
}

// 判断栈是否为空
bool stackEmpty(Stack *s) {
    return s->top == -1;
}

// 入栈
void stackPush(Stack *s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int stackPop(Stack *s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int stackTop(Stack *s) {
    return s->data[s->top];
}

// 用两个栈实现队列
// inStack：负责接收新加入的元素
// outStack：负责弹出和读取队头元素
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// 初始化队列
void myQueueInit(MyQueue *obj) {
    initStack(&obj->inStack);
    initStack(&obj->outStack);
}

// 将元素加入队尾
void myQueuePush(MyQueue *obj, int x) {
    stackPush(&obj->inStack, x);
}

// 如果 outStack 为空，就把 inStack 的所有元素转移过去
// 转移后，最早进入队列的元素会来到 outStack 的栈顶
void moveIfNeeded(MyQueue *obj) {
    if (stackEmpty(&obj->outStack)) {
        while (!stackEmpty(&obj->inStack)) {
            int x = stackPop(&obj->inStack);
            stackPush(&obj->outStack, x);
        }
    }
}

// 删除并返回队头元素
int myQueuePop(MyQueue *obj) {
    moveIfNeeded(obj);
    return stackPop(&obj->outStack);
}

// 返回队头元素
int myQueuePeek(MyQueue *obj) {
    moveIfNeeded(obj);
    return stackTop(&obj->outStack);
}

// 判断队列是否为空
bool myQueueEmpty(MyQueue *obj) {
    return stackEmpty(&obj->inStack) && stackEmpty(&obj->outStack);
}

// 以下为示例测试代码
int main() {
    MyQueue q;
    myQueueInit(&q);

    myQueuePush(&q, 1);
    myQueuePush(&q, 2);

    printf("%d\n", myQueuePeek(&q));   // 1
    printf("%d\n", myQueuePop(&q));    // 1
    printf("%s\n", myQueueEmpty(&q) ? "true" : "false"); // false

    return 0;
}

