#include <stdio.h>

// 定义队列中的结点：
// id 表示这个人最初的位置编号
// cnt 表示这个人还需要打多少份饭
typedef struct {
    int id;
    int cnt;
} Node;

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    // 由于数据范围很小，这里开一个足够大的数组来模拟队列
    // 最多每个人会反复进队 many 次，但我们采用循环数组即可
    Node queue[1005];

    int front = 0, rear = 0;

    // 读入每个人需要的份数，并按初始顺序入队
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        queue[rear].id = i;
        queue[rear].cnt = x;
        rear++;
    }

    int time = 0;

    // 当队列非空时不断模拟
    while (front < rear) {
        // 取出队首同学
        Node cur = queue[front++];

        // 打一份饭，耗时 1 秒
        cur.cnt--;
        time++;

        // 如果当前是目标同学，并且已经全部打完，直接输出答案
        if (cur.id == k && cur.cnt == 0) {
            printf("%d\n", time);
            return 0;
        }

        // 如果还没有打完，则重新排到队尾
        if (cur.cnt > 0) {
            queue[rear++] = cur;
        }
    }

    return 0;
}

