#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    // 用数组模拟队列，最多存 n 个时间戳
    int *queue = (int *)malloc(sizeof(int) * n);
    int front = 0, rear = 0; // 队列区间为 [front, rear)

    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);

        // 当前时间入队
        queue[rear++] = t;

        // 移除所有不在 [t-3000, t] 范围内的旧时间
        while (front < rear && queue[front] < t - 3000) {
            front++;
        }

        // 当前队列长度就是最近 3000 毫秒内的消息数
        int ans = rear - front;

        // 按要求输出，数字之间用空格分隔
        if (i > 0) {
            printf(" ");
        }
        printf("%d", ans);
    }

    printf("\n");
    free(queue);
    return 0;
}

