#include <stdio.h>

// 定义队列中的元素：记录还需要打几份饭，以及该同学的原始编号
typedef struct {
    int remain;
    int id;
} Node;

int main() {
    int n;
    scanf("%d", &n);

    int meals[105];
    for (int i = 0; i < n; i++) {
        scanf("%d", &meals[i]);
    }

    int k;
    scanf("%d", &k);

    // 由于每个人最多会重复入队多次，这里开大一点即可
    Node queue[10005];
    int front = 0, rear = 0;

    // 初始入队
    for (int i = 0; i < n; i++) {
        queue[rear].remain = meals[i];
        queue[rear].id = i;
        rear++;
    }

    int time = 0;

    // 按照题意模拟队列过程
    while (front < rear) {
        Node cur = queue[front++];  // 队首出队

        // 当前同学打一份饭，耗时 1 秒
        cur.remain--;
        time++;

        // 如果这个人正好是目标同学，并且已经完成，直接输出答案
        if (cur.id == k && cur.remain == 0) {
            printf("%d\n", time);
            return 0;
        }

        // 如果还没完成，则重新排到队尾
        if (cur.remain > 0) {
            queue[rear++] = cur;
        }
    }

    return 0;
}

