#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int students[105];
    int meals[105];

    // 读入学生偏好队列
    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i]);
    }

    // 读入主食盒顺序
    for (int i = 0; i < n; i++) {
        scanf("%d", &meals[i]);
    }

    // 用数组模拟循环队列
    int front = 0;      // 队首下标
    int rear = n;       // 队尾的下一个位置
    int size = n;       // 当前队列人数
    int mealIndex = 0;  // 当前最前面的主食盒下标

    // rotateCount 表示连续多少个学生没有取走当前主食盒
    // 如果它等于当前队列人数，说明没人愿意吃这份主食盒，过程结束
    int rotateCount = 0;

    while (size > 0 && rotateCount < size) {
        int currentStudent = students[front];
        front = (front + 1) % 105;  // 出队

        if (currentStudent == meals[mealIndex]) {
            // 当前学生取走主食盒并离开
            size--;
            mealIndex++;
            rotateCount = 0;  // 成功取餐后重新计数
        } else {
            // 当前学生不接受，重新回到队尾
            students[rear % 105] = currentStudent;
            rear = (rear + 1) % 105;
            rotateCount++;
        }
    }

    // 剩余人数就是无法取到餐的学生人数
    printf("%d\n", size);

    return 0;
}

