#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 用两个栈实现队列
 *
 * 思路：
 * 1. inStack：专门负责入队
 * 2. outStack：专门负责出队 / 取队头
 * 3. 当 outStack 为空，而需要 pop / peek 时，
 *    将 inStack 中所有元素依次弹出并压入 outStack。
 *    这样最早进入队列的元素就会来到 outStack 的栈顶。
 */

#define MAX_SIZE 1000

/* -------------------- 栈的定义与操作 -------------------- */
typedef struct {
    int data[MAX_SIZE];
    int top;
} Stack;

// 初始化栈
void stackInit(Stack* s) {
    s->top = -1;
}

// 判断栈是否为空
bool stackEmpty(Stack* s) {
    return s->top == -1;
}

// 入栈
void stackPush(Stack* s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int stackPop(Stack* s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int stackTop(Stack* s) {
    return s->data[s->top];
}

/* -------------------- 队列的定义与操作 -------------------- */
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// 创建队列
MyQueue* myQueueCreate() {
    MyQueue* obj = (MyQueue*)malloc(sizeof(MyQueue));
    stackInit(&obj->inStack);
    stackInit(&obj->outStack);
    return obj;
}

// 将 inStack 中的元素转移到 outStack
void moveIfNeeded(MyQueue* obj) {
    if (stackEmpty(&obj->outStack)) {
        while (!stackEmpty(&obj->inStack)) {
            int x = stackPop(&obj->inStack);
            stackPush(&obj->outStack, x);
        }
    }
}

// 入队：直接压入 inStack
void myQueuePush(MyQueue* obj, int x) {
    stackPush(&obj->inStack, x);
}

// 出队：必要时先转移，再弹出 outStack 栈顶
int myQueuePop(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackPop(&obj->outStack);
}

// 取队头：必要时先转移，再查看 outStack 栈顶
int myQueuePeek(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackTop(&obj->outStack);
}

// 判空：两个栈都为空时，队列才为空
bool myQueueEmpty(MyQueue* obj) {
    return stackEmpty(&obj->inStack) && stackEmpty(&obj->outStack);
}

// 释放队列
void myQueueFree(MyQueue* obj) {
    free(obj);
}

/*
// 以下是简单测试代码，可按需取消注释
int main() {
    MyQueue* q = myQueueCreate();

    myQueuePush(q, 1);
    myQueuePush(q, 2);

    printf("%d\n", myQueuePeek(q));   // 1
    printf("%d\n", myQueuePop(q));    // 1
    printf("%s\n", myQueueEmpty(q) ? "true" : "false"); // false

    myQueueFree(q);
    return 0;
}
*/

