#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    // 使用数组模拟队列
    int *queue = (int *)malloc(sizeof(int) * (n + 5));
    if (queue == NULL) {
        return 0;
    }

    int front = 0, rear = 0; // 队列区间为 [front, rear)

    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);

        // 新事件入队
        queue[rear++] = t;

        // 移除所有不在区间 [t - 3000, t] 内的事件
        while (front < rear && queue[front] < t - 3000) {
            front++;
        }

        // 当前队列中的元素个数就是答案
        printf("%d\n", rear - front);
    }

    free(queue);
    return 0;
}

