#include <stdio.h>
#include <string.h>

#define MAXN 100005

int main() {
    char s[MAXN];

    // 读入字符串
    if (scanf("%s", s) != 1) {
        return 0;
    }

    int n = strlen(s);

    // count[i] 表示字符 'a' + i 出现的次数
    int count[26] = {0};

    // 使用数组模拟队列，队列中存储字符在字符串中的下标
    int queue[MAXN];
    int front = 0, rear = 0;

    // 逐个处理字符
    for (int i = 0; i < n; i++) {
        int idx = s[i] - 'a';
        count[idx]++;

        // 每个字符第一次进入时，把它的下标放入队尾
        queue[rear++] = i;

        // 如果队首对应字符已经重复出现，就不断出队
        while (front < rear && count[s[queue[front]] - 'a'] > 1) {
            front++;
        }
    }

    // 处理结束后，队首就是最靠前的只出现一次字符的下标
    if (front < rear) {
        printf("%d\n", queue[front]);
    } else {
        printf("-1\n");
    }

    return 0;
}

