    if (scanf("%100000s", s) != 1) {
        return 0;
    }

    int n = strlen(s);

    // count[c] 记录字符 c 出现的次数
    int count[26] = {0};

    // 用数组模拟队列，队列中存的是“字符下标”
    int queue[MAXN];
    int front = 0, rear = 0;

    // 从左到右扫描字符串
    for (int i = 0; i < n; i++) {
        int idx = s[i] - 'a';
        count[idx]++;

        // 当前下标进入队列，作为候选位置
        queue[rear++] = i;

        // 如果队头对应的字符已经重复出现，就不断出队
        while (front < rear && count[s[queue[front]] - 'a'] > 1) {
            front++;
        }
    }

    // 扫描结束后，若队列非空，队头就是第一个只出现一次的字符下标
    if (front < rear) {
        printf("%d\n", queue[front]);
    } else {
        printf("-1\n");
    }

    return 0;
}

