#include <stdio.h>
#include <stdbool.h>

// 为了满足题目中最多 100 次操作，这里开一个足够大的容量
#define MAXSIZE 200

// 用数组模拟栈
typedef struct {
    int data[MAXSIZE];
    int top;
} Stack;

// 初始化栈
void stackInit(Stack* s) {
    s->top = -1;
}

// 判断栈是否为空
bool stackEmpty(Stack* s) {
    return s->top == -1;
}

// 入栈
void stackPush(Stack* s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int stackPop(Stack* s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int stackTop(Stack* s) {
    return s->data[s->top];
}

// 队列结构：使用两个栈实现
// inStack：负责入队
// outStack：负责出队/取队头
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// 初始化队列
void myQueueInit(MyQueue* obj) {
    stackInit(&obj->inStack);
    stackInit(&obj->outStack);
}

// 将元素加入队尾
void myQueuePush(MyQueue* obj, int x) {
    stackPush(&obj->inStack, x);
}

// 当 outStack 为空时，把 inStack 中元素全部倒过去
// 这样最早进入的元素就会来到 outStack 的栈顶
void moveIfNeeded(MyQueue* obj) {
    if (stackEmpty(&obj->outStack)) {
        while (!stackEmpty(&obj->inStack)) {
            stackPush(&obj->outStack, stackPop(&obj->inStack));
        }
    }
}

// 删除并返回队头元素
int myQueuePop(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackPop(&obj->outStack);
}

// 返回队头元素
int myQueuePeek(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackTop(&obj->outStack);
}

// 判断队列是否为空
bool myQueueEmpty(MyQueue* obj) {
    return stackEmpty(&obj->inStack) && stackEmpty(&obj->outStack);
}

// 释放资源
// 由于这里使用的是静态数组，不需要额外释放
void myQueueFree(MyQueue* obj) {
    (void)obj; // 防止未使用参数警告
}

/*
下面是一个简单测试用例，提交到 OJ 时通常不需要 main 函数。
如平台要求自行补充，可参考如下写法。
*/
int main() {
    MyQueue q;
    myQueueInit(&q);

    myQueuePush(&q, 1);
    myQueuePush(&q, 2);

    printf("%d\n", myQueuePeek(&q));   // 1
    printf("%d\n", myQueuePop(&q));    // 1
    printf("%s\n", myQueueEmpty(&q) ? "true" : "false"); // false

    myQueueFree(&q);
    return 0;
}

