#include <stdio.h>
#include <stdlib.h>

// 为了简单起见，根据题目约束设置一个足够大的容量
#define MAX_SIZE 1000

// 栈结构
typedef struct {
    int data[MAX_SIZE];
    int top;
} Stack;

// 队列结构：使用两个栈模拟
// inStack 负责入队
// outStack 负责出队/取队头
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// ---------------- 栈的基本操作 ----------------

// 初始化栈
void initStack(Stack* s) {
    s->top = -1;
}

// 判断栈是否为空
int isStackEmpty(Stack* s) {
    return s->top == -1;
}

// 入栈
void stackPush(Stack* s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int stackPop(Stack* s) {
    return s->data[(s->top)--];
}

// 读取栈顶元素
int stackTop(Stack* s) {
    return s->data[s->top];
}

// ---------------- 队列的实现 ----------------

// 创建队列
MyQueue* myQueueCreate() {
    MyQueue* obj = (MyQueue*)malloc(sizeof(MyQueue));
    initStack(&obj->inStack);
    initStack(&obj->outStack);
    return obj;
}

// 将 inStack 中的元素转移到 outStack
// 只有当 outStack 为空时才需要转移
void moveIfNeeded(MyQueue* obj) {
    if (isStackEmpty(&obj->outStack)) {
        while (!isStackEmpty(&obj->inStack)) {
            stackPush(&obj->outStack, stackPop(&obj->inStack));
        }
    }
}

// 入队：直接压入 inStack
void myQueuePush(MyQueue* obj, int x) {
    stackPush(&obj->inStack, x);
}

// 出队：如果 outStack 为空，先转移，再弹出 outStack 栈顶
int myQueuePop(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackPop(&obj->outStack);
}

// 取队头：如果 outStack 为空，先转移，再查看 outStack 栈顶
int myQueuePeek(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackTop(&obj->outStack);
}

// 判断队列是否为空：两个栈都为空才为空
int myQueueEmpty(MyQueue* obj) {
    return isStackEmpty(&obj->inStack) && isStackEmpty(&obj->outStack);
}

// 释放队列
void myQueueFree(MyQueue* obj) {
    free(obj);
}

/*
下面给出一个简单测试示例。
实际提交到在线评测时，通常只需要保留上面的实现部分。
*/
int main() {
    MyQueue* q = myQueueCreate();

    myQueuePush(q, 3);
    myQueuePush(q, 5);

    printf("%d\n", myQueuePeek(q));   // 3
    printf("%d\n", myQueuePop(q));    // 3
    printf("%d\n", myQueueEmpty(q));  // 0

    myQueueFree(q);
    return 0;
}

