#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    // 由于最多只有 n 条消息，开一个大小为 n 的数组模拟队列即可
    int *queue = (int *)malloc(sizeof(int) * n);
    if (queue == NULL) {
        return 0;
    }

    int front = 0;  // 队头下标
    int rear = 0;   // 队尾下一个位置下标

    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);

        // 当前消息入队
        queue[rear++] = t;

        // 移除所有不在区间 [t - 3000, t] 内的旧消息
        while (front < rear && queue[front] < t - 3000) {
            front++;
        }

        // 当前队列中的元素个数就是最近 3000 毫秒内的消息数
        int count = rear - front;

        // 按要求输出，数字之间用空格分隔
        if (i > 0) {
            printf(" ");
        }
        printf("%d", count);
    }

    printf("\n");
    free(queue);
    return 0;
}

