#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// 题目中最多 100 次操作，这里开大一点更安全
#define MAXN 1005

// =========================
// 栈的定义与基本操作
// =========================
typedef struct {
    int data[MAXN];
    int top; // 栈顶下标，-1 表示空栈
} Stack;

// 初始化栈
void initStack(Stack *s) {
    s->top = -1;
}

// 判断栈是否为空
bool isEmptyStack(Stack *s) {
    return s->top == -1;
}

// 入栈
void pushStack(Stack *s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int popStack(Stack *s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int peekStack(Stack *s) {
    return s->data[s->top];
}

// =========================
// 用两个栈实现队列
// inStack: 负责接收新加入的元素
// outStack: 负责弹出/查看队头元素
// =========================
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// 初始化队列
void initQueue(MyQueue *q) {
    initStack(&q->inStack);
    initStack(&q->outStack);
}

// 将 inStack 中所有元素转移到 outStack
// 这样最早进入的元素会来到 outStack 的栈顶
void moveIfNeeded(MyQueue *q) {
    if (isEmptyStack(&q->outStack)) {
        while (!isEmptyStack(&q->inStack)) {
            pushStack(&q->outStack, popStack(&q->inStack));
        }
    }
}

// 入队
void queuePush(MyQueue *q, int x) {
    pushStack(&q->inStack, x);
}

// 出队
int queuePop(MyQueue *q) {
    moveIfNeeded(q);
    return popStack(&q->outStack);
}

// 查看队头
int queuePeek(MyQueue *q) {
    moveIfNeeded(q);
    return peekStack(&q->outStack);
}

// 判断队列是否为空
bool queueEmpty(MyQueue *q) {
    return isEmptyStack(&q->inStack) && isEmptyStack(&q->outStack);
}

int main() {
    int n;
    scanf("%d", &n);

    MyQueue q;
    initQueue(&q);

    char op[20];
    int x;

    for (int i = 0; i < n; i++) {
        scanf("%s", op);

        if (strcmp(op, "push") == 0) {
            scanf("%d", &x);
            queuePush(&q, x);
        } else if (strcmp(op, "pop") == 0) {
            printf("%d\n", queuePop(&q));
        } else if (strcmp(op, "peek") == 0) {
            printf("%d\n", queuePeek(&q));
        } else if (strcmp(op, "empty") == 0) {
            printf("%s\n", queueEmpty(&q) ? "true" : "false");
        }
    }

    return 0;
}

