#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 1005

/*
 * 使用顺序栈实现一个简单栈
 */
typedef struct {
    int data[MAXN];
    int top;
} Stack;

// 初始化栈
void initStack(Stack *s) {
    s->top = -1;
}

// 判断栈是否为空
bool isEmptyStack(Stack *s) {
    return s->top == -1;
}

// 入栈
void pushStack(Stack *s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int popStack(Stack *s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int topStack(Stack *s) {
    return s->data[s->top];
}

/*
 * 用两个栈实现队列
 * inStack: 负责入队
 * outStack: 负责出队/取队头
 */
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

// 初始化队列
void initQueue(MyQueue *q) {
    initStack(&q->inStack);
    initStack(&q->outStack);
}

// 将 inStack 中的元素转移到 outStack 中
void moveStack(MyQueue *q) {
    while (!isEmptyStack(&q->inStack)) {
        pushStack(&q->outStack, popStack(&q->inStack));
    }
}

// 入队
void queuePush(MyQueue *q, int x) {
    pushStack(&q->inStack, x);
}

// 出队
int queuePop(MyQueue *q) {
    if (isEmptyStack(&q->outStack)) {
        moveStack(q);
    }
    return popStack(&q->outStack);
}

// 取队头元素
int queueFront(MyQueue *q) {
    if (isEmptyStack(&q->outStack)) {
        moveStack(q);
    }
    return topStack(&q->outStack);
}

// 判断队列是否为空
bool queueEmpty(MyQueue *q) {
    return isEmptyStack(&q->inStack) && isEmptyStack(&q->outStack);
}

int main() {
    int n;
    scanf("%d", &n);

    MyQueue q;
    initQueue(&q);

    char op[20];
    int x;

    for (int i = 0; i < n; i++) {
        scanf("%s", op);

        if (strcmp(op, "push") == 0) {
            scanf("%d", &x);
            queuePush(&q, x);
