        } else if (strcmp(op, "front") == 0) {
            printf("%d\n", queueFront(&q));
        } else if (strcmp(op, "empty") == 0) {
            printf("%s\n", queueEmpty(&q) ? "true" : "false");
        }
    }

    return 0;
}

