#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int meals[105];
    for (int i = 0; i < n; i++) {
        scanf("%d", &meals[i]);
    }

    int k;
    scanf("%d", &k);

    /*
     * 用数组模拟一个简单队列，队列中存放的是同学编号。
     * 因为每个人可能会多次回到队尾，所以这里开大一些空间。
     * 最大时间不会超过 100 * 100 = 10000，因此队列空间足够即可。
     */
    int queue[20005];
    int front = 0, rear = 0;

    // 初始时所有同学按顺序入队
    for (int i = 0; i < n; i++) {
        queue[rear++] = i;
    }

    int time = 0;

    while (front < rear) {
        // 取出队首同学编号
        int id = queue[front++];

        // 该同学领取 1 份餐品，耗时 1 秒
        meals[id]--;
        time++;

        // 如果该同学已经全部领取完成
        if (meals[id] == 0) {
            // 如果正好是目标同学，输出当前时间并结束
            if (id == k) {
                printf("%d\n", time);
                return 0;
            }
        } else {
            // 还没领取完，重新回到队尾
            queue[rear++] = id;
        }
    }

    return 0;
}

