#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>

/*
 * 用两个栈实现队列
 *
 * 思路：
 * 1. inStack 负责入队：push(x) 时直接压入 inStack
 * 2. outStack 负责出队/取队头：
 *    - 如果 outStack 非空，直接从 outStack 顶部操作
 *    - 如果 outStack 为空，就把 inStack 中所有元素逐个弹出并压入 outStack
 *      这样顺序就反转了，最早进入队列的元素会来到 outStack 栈顶
 */

#define MAX_SIZE 1000

/* ==================== 栈的定义与基本操作 ==================== */
typedef struct {
    int data[MAX_SIZE];
    int top;  // 栈顶下标，-1 表示空栈
} Stack;

// 初始化栈
void stackInit(Stack* s) {
    s->top = -1;
}

// 判断栈是否为空
bool stackEmpty(Stack* s) {
    return s->top == -1;
}

// 入栈
void stackPush(Stack* s, int x) {
    s->data[++(s->top)] = x;
}

// 出栈
int stackPop(Stack* s) {
    return s->data[(s->top)--];
}

// 取栈顶元素
int stackTop(Stack* s) {
    return s->data[s->top];
}

/* ==================== 队列的定义 ==================== */
typedef struct {
    Stack inStack;
    Stack outStack;
} MyQueue;

/*
 * 当 outStack 为空时，把 inStack 中所有元素转移到 outStack
 * 转移后，最早入队的元素会位于 outStack 的栈顶
 */
void moveIfNeeded(MyQueue* obj) {
    if (stackEmpty(&(obj->outStack))) {
        while (!stackEmpty(&(obj->inStack))) {
            int x = stackPop(&(obj->inStack));
            stackPush(&(obj->outStack), x);
        }
    }
}

/*
 * 创建队列
 */
MyQueue* myQueueCreate() {
    MyQueue* obj = (MyQueue*)malloc(sizeof(MyQueue));
    stackInit(&(obj->inStack));
    stackInit(&(obj->outStack));
    return obj;
}

/*
 * 入队：直接压入 inStack
 */
void myQueuePush(MyQueue* obj, int x) {
    stackPush(&(obj->inStack), x);
}

/*
 * 出队：优先从 outStack 弹出
 * 如果 outStack 为空，则先转移元素
 */
int myQueuePop(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackPop(&(obj->outStack));
}

/*
 * 取队头：优先查看 outStack 栈顶
 * 如果 outStack 为空，则先转移元素
 */
int myQueuePeek(MyQueue* obj) {
    moveIfNeeded(obj);
    return stackTop(&(obj->outStack));
}

/*
 * 判断队列是否为空：两个栈都为空才算空
 */
bool myQueueEmpty(MyQueue* obj) {
    return stackEmpty(&(obj->inStack)) && stackEmpty(&(obj->outStack));
}

/*
 * 释放队列空间
 */
void myQueueFree(MyQueue* obj) {
    free(obj);
}

/* ==================== 测试示例 ==================== */
int main() {
    MyQueue* q = myQueueCreate();

    myQueuePush(q, 1);
    myQueuePush(q, 2);

    printf("peek = %d\n", myQueuePeek(q));    // 1
    printf("pop = %d\n", myQueuePop(q));      // 1
    printf("empty = %s\n", myQueueEmpty(q) ? "true" : "false"); // false

    myQueueFree(q);
    return 0;
}

