#include <stdio.h>
#include <string.h>

#define MAXN 100005

int main() {
    char s[MAXN];

    // 读入字符串
    scanf("%s", s);
    int n = strlen(s);

    // count[c] 记录字符 c 出现的次数
    int count[26] = {0};

    // 使用数组模拟队列，队列中存储字符下标
    int queue[MAXN];
    int front = 0, rear = 0;

    // 从左到右扫描字符串
    for (int i = 0; i < n; i++) {
        int idx = s[i] - 'a';
        count[idx]++;

        // 当前字符第一次出现时，先加入队列
        if (count[idx] == 1) {
            queue[rear++] = i;
        }

        // 把队首中已经重复的字符下标移除
        while (front < rear && count[s[queue[front]] - 'a'] > 1) {
            front++;
        }
    }

    // 扫描结束后，队首就是最早只出现一次的字符下标
    if (front < rear) {
        printf("%d\n", queue[front]);
    } else {
        printf("-1\n");
    }

    return 0;
}

