#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int robots[105], batteries[105];
    int cnt[2] = {0, 0};

    // 读入机器人需求，并统计 0 和 1 各有多少个
    for (int i = 0; i < n; i++) {
        scanf("%d", &robots[i]);
        cnt[robots[i]]++;
    }

    // 读入电池发放顺序
    for (int i = 0; i < n; i++) {
        scanf("%d", &batteries[i]);
    }

    // 按电池顺序依次处理
    // 如果当前电池类型已经没有机器人需要，则剩余机器人都无法领取
    for (int i = 0; i < n; i++) {
        if (cnt[batteries[i]] == 0) {
            // 从当前电池开始，后面所有机器人都无法领取
            printf("%d\n", n - i);
            return 0;
        }
        // 有机器人能领取该类型电池，数量减 1
        cnt[batteries[i]]--;
    }

    // 所有电池都成功被领取
    printf("0\n");
    return 0;
}

