#include <stdio.h>

#define MAXN 105

/*
 * 题意：
 * 使用队列模拟学生领取贴纸的过程。
 *
 * 做法：
 * 1. 用数组模拟循环队列。
 * 2. stickers[idx] 表示当前最前面的贴纸。
 * 3. 如果队首学生喜欢当前贴纸，则出队并消耗一张贴纸。
 * 4. 否则将该学生移到队尾。
 * 5. 用 failCount 记录“连续多少次没人拿走当前贴纸”。
 *    - 一旦有人拿走贴纸，failCount 置 0；
 *    - 如果 failCount == 当前队列人数，说明队里没人喜欢这张贴纸，结束。
 */

int main() {
    int n;
    int students[MAXN], stickers[MAXN];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &stickers[i]);
    }

    /* 用循环队列存学生偏好 */
    int q[MAXN * 2];
    int front = 0, rear = 0;

    for (int i = 0; i < n; i++) {
        q[rear++] = students[i];
    }

    int stickerIndex = 0;   // 当前处理到哪张贴纸
    int remain = n;         // 当前队列中剩余学生人数
    int failCount = 0;      // 连续无法领取当前贴纸的人数

    while (remain > 0 && stickerIndex < n) {
        int cur = q[front++];   // 取队首学生

        if (cur == stickers[stickerIndex]) {
            // 学生领走贴纸并离开队伍
            stickerIndex++;
            remain--;
            failCount = 0;      // 当前贴纸已被领取，重新统计
        } else {
            // 不匹配，回到队尾
            q[rear++] = cur;
            failCount++;

            // 当前队伍里所有人都试过了，仍没人拿这张贴纸
            if (failCount == remain) {
                break;
            }
        }
    }

    printf("%d\n", remain);
    return 0;
}

