#include <stdio.h>

#define MAXN 105

int main() {
    int n;
    int students[MAXN], boxes[MAXN];

    // 读入学生人数
    scanf("%d", &n);

    // 读入学生队列
    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i]);
    }

    // 读入餐盒序列
    for (int i = 0; i < n; i++) {
        scanf("%d", &boxes[i]);
    }

    // 使用数组模拟循环队列
    int q[MAXN * 2];
    int front = 0, rear = 0;

    // 初始化队列
    for (int i = 0; i < n; i++) {
        q[rear++] = students[i];
    }

    int boxIndex = 0;       // 当前处理到的餐盒位置
    int remain = n;         // 当前队列中剩余学生数
    int failCount = 0;      // 连续不愿领取当前餐盒的学生数

    // 当还有学生且还有餐盒时继续模拟
    while (remain > 0 && boxIndex < n) {
        int cur = q[front++];   // 取出队首学生

        if (cur == boxes[boxIndex]) {
            // 当前学生领取餐盒，离开队列
            boxIndex++;
            remain--;
            failCount = 0; // 有人成功领取，重新计数
        } else {
            // 当前学生不喜欢该餐盒，回到队尾
            q[rear++] = cur;
            failCount++;

            // 如果连续 remain 个学生都不接受当前餐盒
            // 说明再也无法继续发放
            if (failCount == remain) {
                break;
            }
        }
    }

    // 剩余学生数就是无法领取餐盒的人数
    printf("%d\n", remain);

    return 0;
}

