#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 给定一组互不相同的整数，需要构造一个初始队列，使得按如下规则操作时，
 * 取出的数字序列恰好是升序：
 * 1) 取出队首
 * 2) 若队列非空，则将新的队首移到队尾
 *
 * 核心思路：
 * 不是直接模拟数字，而是模拟“位置”。
 *
 * 假设最终答案数组为 ans[0..n-1]，其中 ans[0] 是初始队首。
 * 如果我们知道这些位置被“取出”的顺序，那么只需把排好序的数字按这个顺序填进去即可。
 *
 * 位置顺序如何得到？
 * 初始时队列中放入下标 0,1,2,...,n-1。
 * 每次：
 *   - 弹出一个下标 idx，表示这个位置会在当前轮被取出
 *   - 将当前最小的还未使用数字放到 ans[idx]
 *   - 若队列不空，再把队首下标弹出并压回队尾，模拟“跳过一个位置”
 *
 * 这样即可在线性模拟中完成构造。
 */

/* qsort 比较函数：升序 */
int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return x - y;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *a = (int *)malloc(sizeof(int) * n);
    int *ans = (int *)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 先将所有数字升序排序 */
    qsort(a, n, sizeof(int), cmp_int);

    /*
     * 用循环队列维护“还未填值的位置下标”。
     * 由于最多只需要容纳 n 个元素，开 n+5 足够。
     */
    int *queue = (int *)malloc(sizeof(int) * (n + 5));
    int front = 0, rear = 0;

    /* 初始把所有位置下标入队 */
    for (int i = 0; i < n; i++) {
        queue[rear++] = i;
    }

    /* 依次把最小、次小、... 的数字放到应被取出的那些位置上 */
    for (int i = 0; i < n; i++) {
        /* 当前位置是当前会被取出的下标 */
        int idx = queue[front++];
        ans[idx] = a[i];

        /*
         * 模拟“取出后，把新的队首移到队尾”
         * 若队列仍非空，则执行一次头元素到尾部的移动
         */
        if (front < rear) {
            int move_idx = queue[front++];
            queue[rear++] = move_idx;
        }
    }

    /* 输出答案 */
    for (int i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(a);
    free(ans);
    free(queue);
    return 0;
}

