#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);

    int *nums = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    /*
     * 使用两个单调队列：
     * 1. maxDeque：维护当前窗口内可能成为最大值的下标，队列对应值单调递减
     * 2. minDeque：维护当前窗口内可能成为最小值的下标，队列对应值单调递增
     *
     * 用滑动窗口 [left, right]：
     * - 每次扩展 right 后，把 nums[right] 插入两个单调队列
     * - 若当前窗口 max - min > 2，则不断右移 left 缩小窗口
     * - 对于每个 right，以 right 结尾的合法子数组个数为 right - left + 1
     */

    int *maxDeque = (int *)malloc(sizeof(int) * n);
    int *minDeque = (int *)malloc(sizeof(int) * n);
    int maxHead = 0, maxTail = 0;
    int minHead = 0, minTail = 0;

    int left = 0;
    ll ans = 0;

    for (int right = 0; right < n; right++) {
        /* 维护单调递减队列（最大值队列） */
        while (maxHead < maxTail && nums[maxDeque[maxTail - 1]] < nums[right]) {
            maxTail--;
        }
        maxDeque[maxTail++] = right;

        /* 维护单调递增队列（最小值队列） */
        while (minHead < minTail && nums[minDeque[minTail - 1]] > nums[right]) {
            minTail--;
        }
        minDeque[minTail++] = right;

        /* 若窗口不合法，则移动 left 直到合法 */
        while (maxHead < maxTail && minHead < minTail &&
               (ll)nums[maxDeque[maxHead]] - (ll)nums[minDeque[minHead]] > 2) {
            if (maxDeque[maxHead] == left) {
                maxHead++;
            }
            if (minDeque[minHead] == left) {
                minHead++;
            }
            left++;
        }

        /* 以 right 结尾的所有合法子数组个数 */
        ans += (ll)(right - left + 1);
    }

    printf("%lld\n", ans);

    free(nums);
    free(maxDeque);
    free(minDeque);
    return 0;
}

