#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
思路说明：
1. 用一个数组模拟队列，保存所有进入过队列的号码，顺序即入队顺序。
2. 用 freq[x] 记录号码 x 出现的次数。
3. 对于 CHECK 操作：
   - 从队头开始，如果当前队头号码的出现次数 > 1，说明它不可能成为答案，
     就将队头指针向后移动（懒删除思想）。
   - 重复这个过程，直到队头号码出现次数为 1，或者队列为空。
   - 若队列非空，则队头就是当前“最靠前且只出现一次”的号码；否则输出 -1。

为什么这样是对的？
- 队列中元素只会追加，不会真正删除；
- 一旦某个元素出现次数大于 1，它将永远不可能再成为“唯一号码”；
- 因此在 CHECK 时可以安全地把这些不可能成为答案的队头元素跳过。

时间复杂度：
- 每个元素最多入队一次、被队头跳过一次，总复杂度 O(n + q)
- 每次操作均摊 O(1)
*/

#define MAXV 1000000

int main() {
    int n;
    scanf("%d", &n);

    /*
    总共最多会有 n + q 次 ENQUEUE，
    由于 q 还没读到，先读 n 后再读 q 之前无法精确分配。
    因此先把初始数据临时存起来，读到 q 后再统一开足够空间。
    */
    int *init = NULL;
    if (n > 0) {
        init = (int *)malloc(sizeof(int) * n);
        for (int i = 0; i < n; i++) {
            scanf("%d", &init[i]);
        }
    }

    int q;
    scanf("%d", &q);

    /*
    队列最大长度不超过 n + q：
    因为每个操作至多新增一个元素。
    */
    int maxSize = n + q + 5;
    int *queue = (int *)malloc(sizeof(int) * maxSize);

    /* 频次数组，题目保证 1 <= x <= 1e6 */
    int *freq = (int *)calloc(MAXV + 1, sizeof(int));

    int front = 0, rear = 0;

    /* 初始化队列 */
    for (int i = 0; i < n; i++) {
        int x = init[i];
        queue[rear++] = x;
        freq[x]++;
    }

    free(init);

    char op[20];
    for (int i = 0; i < q; i++) {
        scanf("%s", op);

        if (strcmp(op, "ENQUEUE") == 0) {
            int x;
            scanf("%d", &x);
            queue[rear++] = x;
            freq[x]++;
        } else if (strcmp(op, "CHECK") == 0) {
            /*
            懒删除：跳过所有出现次数大于 1 的队头元素
            */
            while (front < rear && freq[queue[front]] > 1) {
                front++;
            }

            if (front < rear) {
                printf("%d\n", queue[front]);
            } else {
                printf("-1\n");
            }
        }
    }

    free(queue);
    free(freq);
    return 0;
}

