#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
核心思路：
1. 所有加入的数据按顺序进入一个队列。
2. 用哈希表统计每个数字出现的次数。
3. 每次查询时，不断检查队首：
   - 如果队首数字出现次数 > 1，说明它已经不可能是答案，弹出；
   - 否则它就是当前“首个唯一编号”。
4. 如果队列被清空，则答案为 -1。

由于题目中的数字范围很大（可到 ±1e9），不能直接开数组计数，
因此这里手写一个哈希表（拉链法）来维护频次。
*/

#define MAXN 400005          /* n + q 的最大可能数量级，队列容量够用 */
#define HASH_SIZE 524287     /* 一个较大的质数，减少冲突 */

typedef long long ll;

/* ==================== 队列部分 ==================== */
typedef struct {
    ll data[MAXN];
    int front;
    int rear;
} Queue;

void initQueue(Queue *q) {
    q->front = 0;
    q->rear = 0;
}

void pushQueue(Queue *q, ll x) {
    q->data[q->rear++] = x;
}

ll frontQueue(Queue *q) {
    return q->data[q->front];
}

void popQueue(Queue *q) {
    if (q->front < q->rear) q->front++;
}

int emptyQueue(Queue *q) {
    return q->front == q->rear;
}

/* ==================== 哈希表部分（统计频次） ==================== */
typedef struct Node {
    ll key;               /* 编号值 */
    int cnt;              /* 出现次数 */
    struct Node *next;
} Node;

Node *hashTable[HASH_SIZE];

/*
将 long long 映射到哈希桶。
这里做一个简单混合，尽量降低负数和大数带来的影响。
*/
unsigned int hashFunc(ll x) {
    unsigned long long v = (unsigned long long)x;
    v ^= v >> 33;
    v *= 0xff51afd7ed558ccdULL;
    v ^= v >> 33;
    v *= 0xc4ceb9fe1a85ec53ULL;
    v ^= v >> 33;
    return (unsigned int)(v % HASH_SIZE);
}

/* 查找 key 对应的结点，不存在则返回 NULL */
Node* findNode(ll key) {
    unsigned int idx = hashFunc(key);
    Node *cur = hashTable[idx];
    while (cur) {
        if (cur->key == key) return cur;
        cur = cur->next;
    }
    return NULL;
}

/* 让 key 的频次 +1 */
void addCount(ll key) {
    unsigned int idx = hashFunc(key);
    Node *cur = hashTable[idx];
    while (cur) {
        if (cur->key == key) {
            cur->cnt++;
            return;
        }
        cur = cur->next;
    }

    /* 不存在则新建结点 */
    Node *node = (Node *)malloc(sizeof(Node));
    node->key = key;
    node->cnt = 1;
    node->next = hashTable[idx];
    hashTable[idx] = node;
}

/* 获取 key 的频次，不存在则返回 0 */
int getCount(ll key) {
    Node *node = findNode(key);
    return node ? node->cnt : 0;
}

/* ==================== 主逻辑 ==================== */
int main() {
    int n, q;
    Queue que;
    initQueue(&que);
    memset(hashTable, 0, sizeof(hashTable));

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        ll x;
        scanf("%lld", &x);
        pushQueue(&que, x);
        addCount(x);
    }

    scanf("%d", &q);
    while (q--) {
        int op;
        scanf("%d", &op);

        if (op == 1) {
            ll x;
            scanf("%lld", &x);
            pushQueue(&que, x);
            addCount(x);
        } else if (op == 2) {
            /*
            把所有已经重复的队首元素移除。
            这些元素即使保留在前面，也永远不可能再成为答案。
            */
            while (!emptyQueue(&que) && getCount(frontQueue(&que)) > 1) {
                popQueue(&que);
            }

            if (emptyQueue(&que)) {
                printf("-1\n");
            } else {
                printf("%lld\n", frontQueue(&que));
            }
        }
    }

    return 0;
}

