#include <stdbool.h>
#include <stdlib.h>

/*
 * 题意：
 * 维护数据流最近的 k 个元素，判断其中等于 value 的元素个数是否至少为 t。
 *
 * 思路：
 * 1. 使用循环队列保存最近的 k 个元素。
 * 2. 用一个计数器 matchCount 记录当前窗口中等于 value 的元素个数。
 * 3. 每次 push(num)：
 *    - 如果队列已满，先弹出最早进入窗口的元素；
 *      如果该元素等于 value，则 matchCount--。
 *    - 再将 num 入队；
 *      如果 num 等于 value，则 matchCount++。
 *    - 若当前窗口大小不足 k，返回 false；
 *      否则判断 matchCount >= t。
 *
 * 每次操作时间复杂度 O(1)，空间复杂度 O(k)。
 */

typedef struct {
    int value;          // 目标值
    int k;              // 窗口大小
    int t;              // 至少需要出现的次数
    int *queue;         // 循环队列数组
    int front;          // 队头下标
    int rear;           // 队尾下一个位置下标
    int size;           // 当前队列中元素个数
    int matchCount;     // 当前窗口中等于 value 的元素个数
} StreamWindow;

/* 创建对象 */
StreamWindow* streamWindowCreate(int value, int k, int t) {
    StreamWindow* obj = (StreamWindow*)malloc(sizeof(StreamWindow));
    obj->value = value;
    obj->k = k;
    obj->t = t;
    obj->queue = (int*)malloc(sizeof(int) * k);
    obj->front = 0;
    obj->rear = 0;
    obj->size = 0;
    obj->matchCount = 0;
    return obj;
}

/*
 * 向数据流中加入一个数，并判断最近 k 个元素中 value 的出现次数是否至少为 t
 */
bool streamWindowPush(StreamWindow* obj, int num) {
    // 如果窗口已满，先移除最早的元素
    if (obj->size == obj->k) {
        int removed = obj->queue[obj->front];
        obj->front = (obj->front + 1) % obj->k;
        obj->size--;

        if (removed == obj->value) {
            obj->matchCount--;
        }
    }

    // 新元素入队
    obj->queue[obj->rear] = num;
    obj->rear = (obj->rear + 1) % obj->k;
    obj->size++;

    if (num == obj->value) {
        obj->matchCount++;
    }

    // 如果当前元素不足 k 个，不满足条件
    if (obj->size < obj->k) {
        return false;
    }

    // 判断最近 k 个元素中，value 的出现次数是否至少为 t
    return obj->matchCount >= obj->t;
}

/* 释放对象 */
void streamWindowFree(StreamWindow* obj) {
    if (obj != NULL) {
        free(obj->queue);
        free(obj);
    }
}

/*
 * 如果在某些评测平台需要使用如下接口风格，可直接对应：
 *
 * StreamWindow* obj = streamWindowCreate(value, k, t);
 * bool param_1 = streamWindowPush(obj, num);
 * streamWindowFree(obj);
 */

