#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

int main() {
    int n;
    ll k;
    if (scanf("%d %lld", &n, &k) != 2) {
        return 0;
    }

    // 1-based 存储，便于状态转移
    ll *nums = (ll *)malloc((n + 1) * sizeof(ll));
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &nums[i]);
    }

    // dp[i]：前 i 个元素的合法切分方案数
    // pre[i]：dp[0] + dp[1] + ... + dp[i] 的前缀和
    ll *dp = (ll *)malloc((n + 1) * sizeof(ll));
    ll *pre = (ll *)malloc((n + 1) * sizeof(ll));

    // 两个单调队列：
    // maxQ 维护区间最大值（下标对应的值单调递减）
    // minQ 维护区间最小值（下标对应的值单调递增）
    int *maxQ = (int *)malloc((n + 1) * sizeof(int));
    int *minQ = (int *)malloc((n + 1) * sizeof(int));
    int maxHead = 0, maxTail = 0;
    int minHead = 0, minTail = 0;

    dp[0] = 1;      // 空前缀有 1 种“切分完成”的方式
    pre[0] = 1;

    int left = 1;   // 当前合法窗口的最左端

    for (int right = 1; right <= n; right++) {
        // 把 nums[right] 加入维护最大值的单调队列
        while (maxHead < maxTail && nums[maxQ[maxTail - 1]] <= nums[right]) {
            maxTail--;
        }
        maxQ[maxTail++] = right;

        // 把 nums[right] 加入维护最小值的单调队列
        while (minHead < minTail && nums[minQ[minTail - 1]] >= nums[right]) {
            minTail--;
        }
        minQ[minTail++] = right;

        // 若当前窗口最大值 - 最小值 > k，则不断右移 left
        while (maxHead < maxTail && minHead < minTail &&
               nums[maxQ[maxHead]] - nums[minQ[minHead]] > k) {
            if (maxQ[maxHead] == left) {
                maxHead++;
            }
            if (minQ[minHead] == left) {
                minHead++;
            }
            left++;
        }

        // 现在所有以 right 结尾的合法段，其起点可以是 left..right
        // 设最后一段为 [start..right]
        // 那么前 start-1 个元素的方案数是 dp[start-1]
        // 所以：
        // dp[right] = sum(dp[start-1])，其中 start in [left..right]
        //          = sum(dp[t])，其中 t in [left-1..right-1]
        // 利用前缀和快速计算
        ll total = pre[right - 1];
        if (left >= 2) {
            total = (total - pre[left - 2] + MOD) % MOD;
        }

        dp[right] = total;
        pre[right] = (pre[right - 1] + dp[right]) % MOD;
    }

    printf("%lld\n", dp[n] % MOD);

    free(nums);
    free(dp);
    free(pre);
    free(maxQ);
    free(minQ);
    return 0;
}

