#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 有 n 个窗口，每个窗口有一个顺序队列。
 * 按“轮转”方式取数：每次从当前活跃窗口的队首取 1 个元素，
 * 若该窗口还有剩余元素，则重新加入活跃队列尾部。
 * 输出所有元素的服务顺序。
 *
 * 核心做法：
 * - 用一个数组保存每个窗口的所有元素；
 * - 用 pos[i] 表示窗口 i 当前已经取到了第几个元素；
 * - 再用一个“窗口编号队列”保存当前仍然非空的窗口；
 * - 每次弹出一个窗口编号 idx，输出该窗口当前元素，pos[idx]++；
 * - 如果该窗口还有剩余元素，则再把 idx 放回队尾。
 *
 * 这正是队列在“交错迭代 / 轮转调度”中的经典应用。
 */

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /*
     * windows[i]     : 指向第 i 个窗口的客户编号数组
     * len[i]         : 第 i 个窗口的总人数
     * pos[i]         : 第 i 个窗口当前已经服务到的位置
     */
    int **windows = (int **)malloc(n * sizeof(int *));
    int *len = (int *)malloc(n * sizeof(int));
    int *pos = (int *)calloc(n, sizeof(int));

    if (!windows || !len || !pos) {
        return 0;
    }

    int total = 0;  // 所有客户总数

    for (int i = 0; i < n; i++) {
        scanf("%d", &len[i]);
        total += len[i];

        if (len[i] > 0) {
            windows[i] = (int *)malloc(len[i] * sizeof(int));
            if (!windows[i]) {
                return 0;
            }
            for (int j = 0; j < len[i]; j++) {
                scanf("%d", &windows[i][j]);
            }
        } else {
            windows[i] = NULL;
        }
    }

    /*
     * 活跃窗口编号队列。
     * 最多会进行 total 次入队，因此开到 total + n 足够安全。
     */
    int queueSize = total + n + 5;
    int *queue = (int *)malloc(queueSize * sizeof(int));
    if (!queue) {
        return 0;
    }

    int head = 0, tail = 0;

    /* 初始时，把所有非空窗口加入队列 */
    for (int i = 0; i < n; i++) {
        if (len[i] > 0) {
            queue[tail++] = i;
        }
    }

    /*
     * 为了方便控制输出空格，记录是否是第一个输出的数。
     */
    int first = 1;

    while (head < tail) {
        int idx = queue[head++];  // 取出当前要服务的窗口编号

        /* 输出该窗口当前队首（逻辑上的队首，由 pos[idx] 指向） */
        int value = windows[idx][pos[idx]];
        pos[idx]++;

        if (!first) {
            printf(" ");
        }
        printf("%d", value);
        first = 0;

        /* 如果该窗口还有剩余客户，则重新加入队尾 */
        if (pos[idx] < len[idx]) {
            queue[tail++] = idx;
        }
    }

    printf("\n");

    /* 释放内存 */
    for (int i = 0; i < n; i++) {
        free(windows[i]);
    }
    free(windows);
    free(len);
