#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题目核心：
维护“当前最早出现且只出现一次的编号”。

高效做法：
1. 用 count[value] 记录每个编号出现次数。
2. 用队列保存所有加入过的编号（按时间顺序）。
3. 查询时，不断检查队首：
   - 如果 count[queue_front] > 1，说明它已经不是唯一编号，弹出。
   - 否则它就是当前答案。

这样每个元素最多进队一次、出队一次，总体复杂度 O(n + q)。
*/

#define MAXV 100000
#define MAXN 200005

typedef struct {
    int *data;      // 队列数组
    int front;      // 队头下标
    int rear;       // 队尾下一个位置
    int capacity;   // 容量
    int count[MAXV + 1]; // 统计每个编号出现次数
} UniqueQueue;

/* 初始化数据结构 */
void initUniqueQueue(UniqueQueue *uq, int totalCapacity) {
    uq->data = (int *)malloc(sizeof(int) * totalCapacity);
    uq->front = 0;
    uq->rear = 0;
    uq->capacity = totalCapacity;
    memset(uq->count, 0, sizeof(uq->count));
}

/* 释放内存 */
void freeUniqueQueue(UniqueQueue *uq) {
    free(uq->data);
}

/* 入队 */
void enqueue(UniqueQueue *uq, int value) {
    uq->data[uq->rear++] = value;
}

/* 清理队头中已不唯一的元素 */
void normalizeFront(UniqueQueue *uq) {
    while (uq->front < uq->rear && uq->count[uq->data[uq->front]] > 1) {
        uq->front++;
    }
}

/* 添加一个新编号 */
void add(UniqueQueue *uq, int value) {
    uq->count[value]++;
    enqueue(uq, value);
    normalizeFront(uq);
}

/* 返回当前最早的唯一编号，不存在则返回 -1 */
int showFirstUnique(UniqueQueue *uq) {
    normalizeFront(uq);
    if (uq->front < uq->rear) {
        return uq->data[uq->front];
    }
    return -1;
}

int main() {
    int n, q;
    scanf("%d", &n);

    /*
    最大可能元素数 = 初始 n + 后续 add 次数
    题目保证总量不超过 100000，这里开大一些更安全
    */
    UniqueQueue uq;
    initUniqueQueue(&uq, MAXN);

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        add(&uq, x);
    }

    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        char op[10];
        scanf("%s", op);

        if (strcmp(op, "show") == 0) {
            printf("%d\n", showFirstUnique(&uq));
        } else if (strcmp(op, "add") == 0) {
            int x;
            scanf("%d", &x);
            add(&uq, x);
        }
    }

    freeUniqueQueue(&uq);
    return 0;
}

