#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 题意：
 * 设计一个数据结构 TrendStream，支持不断向数据流中加入整数，
 * 并判断最近 k 个整数是否构成非递减序列。
 *
 * 关键观察：
 * 对于一个长度为 k 的窗口 [a1, a2, ..., ak]，
 * 它是非递减序列，当且仅当窗口内不存在 ai > ai+1。
 *
 * 因此，我们只需维护：
 * 1. 最近 k 个元素（用循环队列保存）
 * 2. 当前窗口中“下降对”的数量 badPairs
 *    即满足前一个元素 > 后一个元素的相邻对个数。
 *
 * 若当前窗口长度为 k 且 badPairs == 0，则最近 k 个数为非递减序列。
 *
 * 每次 append(num) 时：
 * - 若队列非空，新增一个相邻对 (旧尾, num)，若旧尾 > num，则 badPairs++。
 * - 若队列已满，需要弹出队头 old：
 *      这会移除原先的相邻对 (old, newHead)
 *      若 old > newHead，则 badPairs--。
 * - 再把 num 放入队尾。
 *
 * 如此每次操作都只需 O(1) 时间。
 */

typedef struct {
    int *data;      // 循环队列数组
    int k;          // 窗口大小
    int size;       // 当前队列长度
    int front;      // 队头下标
    int rear;       // 队尾下一个位置下标
    int badPairs;   // 当前窗口内“下降相邻对”的数量
} TrendStream;

/* 创建对象 */
TrendStream* trendStreamCreate(int k) {
    TrendStream *obj = (TrendStream *)malloc(sizeof(TrendStream));
    obj->data = (int *)malloc(sizeof(int) * k);
    obj->k = k;
    obj->size = 0;
    obj->front = 0;
    obj->rear = 0;
    obj->badPairs = 0;
    return obj;
}

/*
 * 向数据流加入一个数，并判断最近 k 个数是否非递减
 * 返回 true / false
 */
bool trendStreamAppend(TrendStream* obj, int num) {
    /*
     * 第一步：如果队列非空，新增相邻关系 (尾元素, num)
     * 先取出当前尾元素位置：rear 的前一个位置
     */
    if (obj->size > 0) {
        int tailIndex = (obj->rear - 1 + obj->k) % obj->k;
        int tailValue = obj->data[tailIndex];
        if (tailValue > num) {
            obj->badPairs++;
        }
    }

    /*
     * 第二步：如果窗口已满，需要先移除队头元素
     * 移除队头 old 时，会删除相邻对 (old, next)
     */
    if (obj->size == obj->k) {
        int oldFront = obj->front;
        int nextFront = (obj->front + 1) % obj->k;

        /*
         * 当 size == k >= 2 时，(oldFront, nextFront) 是一个有效相邻对。
         * 如果 old > next，则此前这个下降对被统计过，现在应删去。
         *
         * 若 k == 1，则窗口内没有相邻对，不需要处理。
         */
        if (obj->k >= 2 && obj->data[oldFront] > obj->data[nextFront]) {
            obj->badPairs--;
        }

        obj->front = nextFront;
        obj->size--;
    }

    /* 第三步：把新元素加入队尾 */
    obj->data[obj->rear] = num;
    obj->rear = (obj->rear + 1) % obj->k;
    obj->size++;

    /* 第四步：判断答案 */
    return (obj->size == obj->k && obj->badPairs == 0);
}

/* 释放对象 */
void trendStreamFree(TrendStream* obj) {
    free(obj->data);
    free(obj);
}

/*
 * 下面给出一个简单的本地测试样例。
 * 在线评测时通常不需要 main，保留仅供参考。
 */
int main() {
    TrendStream *ts = trendStreamCreate(3);

    printf("%s\n", trendStreamAppend(ts, 1) ? "true" : "false"); // false
    printf("%s\n", trendStreamAppend(ts, 2) ? "true" : "false"); // false
    printf("%s\n", trendStreamAppend(ts, 2) ? "true" : "false"); // true
    printf("%s\n", trendStreamAppend(ts, 1) ? "true" : "false"); // false
    printf("%s\n", trendStreamAppend(ts, 3) ? "true" : "false"); // false

    trendStreamFree(ts);
    return 0;
}

