#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

int main() {
    int n;
    ll k;
    scanf("%d %lld", &n, &k);

    ll *nums = (ll *)malloc((n + 1) * sizeof(ll));
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &nums[i]);
    }

    /*
     * dp[i]：将前 i 个元素划分为若干个稳定片段的方案数
     * prefix[i]：dp[0] + dp[1] + ... + dp[i] 的前缀和
     *
     * 若某个位置 i 的合法片段左端点最早可以从 left 开始，
     * 则最后一段可以是 [j..i]（left <= j <= i），
     * 因此：dp[i] = dp[j-1] 的总和 = prefix[i-1] - prefix[left-2]
     */
    ll *dp = (ll *)malloc((n + 1) * sizeof(ll));
    ll *prefix = (ll *)malloc((n + 1) * sizeof(ll));

    /*
     * 使用两个单调队列维护当前窗口 [left..right] 内的：
     * 1) 最大值（递减队列）
     * 2) 最小值（递增队列）
     *
     * 队列中存储的是下标。
     */
    int *maxQ = (int *)malloc((n + 1) * sizeof(int));
    int *minQ = (int *)malloc((n + 1) * sizeof(int));
    int maxHead = 0, maxTail = 0;
    int minHead = 0, minTail = 0;

    dp[0] = 1;       // 空前缀有 1 种划分方式
    prefix[0] = 1;

    int left = 1;

    for (int right = 1; right <= n; right++) {
        /* 维护最大值单调队列：队尾比当前值小的都弹出 */
        while (maxHead < maxTail && nums[maxQ[maxTail - 1]] <= nums[right]) {
            maxTail--;
        }
        maxQ[maxTail++] = right;

        /* 维护最小值单调队列：队尾比当前值大的都弹出 */
        while (minHead < minTail && nums[minQ[minTail - 1]] >= nums[right]) {
            minTail--;
        }
        minQ[minTail++] = right;

        /*
         * 若当前窗口最大值 - 最小值 > k，说明窗口不合法，
         * 需要不断右移 left，直到重新合法。
         */
        while (maxHead < maxTail && minHead < minTail &&
               nums[maxQ[maxHead]] - nums[minQ[minHead]] > k) {
            if (maxQ[maxHead] == left) maxHead++;
            if (minQ[minHead] == left) minHead++;
            left++;
        }

        /*
         * 现在 [left..right] 是以 right 结尾的最早合法窗口。
         * 所有 [j..right]（left <= j <= right）都是合法的最后一段。
         *
         * dp[right] = dp[left-1] + dp[left] + ... + dp[right-1]
         *           = prefix[right-1] - prefix[left-2]
         */
        ll total = prefix[right - 1];
        ll remove = (left >= 2 ? prefix[left - 2] : 0);
        dp[right] = (total - remove + MOD) % MOD;

        prefix[right] = (prefix[right - 1] + dp[right]) % MOD;
    }

    printf("%lld\n", dp[n]);

    free(nums);
    free(dp);
    free(prefix);
    free(maxQ);
    free(minQ);

    return 0;
}

