#include <stdio.h>
#include <string.h>

#define MAXN 10005

/*
 * 使用顺序队列模拟：
 * 1. 分别记录 A 队和 B 队当前仍有效调度员的下标。
 * 2. 每次取两个队列的队首比较：
 *    - 下标小的先行动，冻结对方当前队首对应的人。
 *    - 该先行动的人仍然存活，会在下一轮继续参与，
 *      所以将其下标加上 n 后重新入队。
 * 3. 直到某一方队列为空，另一方胜利。
 */

int main() {
    char order[MAXN];
    int qa[MAXN * 2], qb[MAXN * 2];
    int ha = 0, ta = 0;   // A 队队列头尾指针，区间为 [ha, ta)
    int hb = 0, tb = 0;   // B 队队列头尾指针，区间为 [hb, tb)

    if (scanf("%s", order) != 1) {
        return 0;
    }

    int n = (int)strlen(order);

    // 初始时，将两队成员的位置分别入队
    for (int i = 0; i < n; i++) {
        if (order[i] == 'A') {
            qa[ta++] = i;
        } else {
            qb[tb++] = i;
        }
    }

    // 模拟过程
    while (ha < ta && hb < tb) {
        int pa = qa[ha++];
        int pb = qb[hb++];

        if (pa < pb) {
            // A 队成员先行动，冻结这个 B 队成员
            // A 队成员进入下一轮
            qa[ta++] = pa + n;
        } else {
            // B 队成员先行动，冻结这个 A 队成员
            // B 队成员进入下一轮
            qb[tb++] = pb + n;
        }
    }

    if (ha < ta) {
        printf("Alpha\n");
    } else {
        printf("Beta\n");
    }

    return 0;
}

