#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
题意分析：
设用户按 1 ~ n 编号（便于推导），cost[i-1] 是第 i 位用户付费办理的代价。

如果为第 i 位用户付费：
- 第 i 位用户被办理；
- 后面最多再有 i 位用户可以免费办理；
- 因此，这次操作最多可以把区间 [i, 2i] 全部覆盖。

但注意：在 [i+1, 2i] 中的某个用户，即使本可免费办理，仍然可以选择“付费办理”来触发更远的奖励。

定义 dp[i]：从第 i 位用户开始，到第 n 位用户全部办理完成的最小花费。
则有：
  dp[i] = cost[i-1] + min(dp[j])，其中 j 属于 [i+1, 2i+1]
含义：
- 付费办理第 i 位用户后，前面最多能把 [i, 2i] 这段覆盖掉；
- 下一位“还需要继续考虑的起点”可以是 i+1 到 2i+1 之间的任意位置；
- 如果 j = n+1，表示已经全部办理完成，dp[n+1] = 0。

边界：dp[n+1] = 0

为了快速求区间最小值 min(dp[i+1..2i+1])，
我们从后往前计算 dp，并用一个单调队列（双端队列）维护候选下标，
使队列中的 dp 值单调递增，从而 O(1) 获得当前区间最小值。

时间复杂度：O(n)
空间复杂度：O(n)
*/

long long minimumTokens(int* cost, int n) {
    // dp 下标范围：1 ~ n+1
    long long* dp = (long long*)malloc((n + 2) * sizeof(long long));
    if (dp == NULL) return -1;

    // 手写双端队列，存储的是下标 idx
    int* deque = (int*)malloc((n + 2) * sizeof(int));
    if (deque == NULL) {
        free(dp);
        return -1;
    }

    int head = 0, tail = -1;

    // 边界：dp[n+1] = 0
    dp[n + 1] = 0;
    deque[++tail] = n + 1;

    // 从后往前递推
    for (int i = n; i >= 1; --i) {
        // 当前需要的合法区间为 [i+1, 2i+1]
        // 队首若超过右边界 2i+1，则弹出
        while (head <= tail && deque[head] > 2 * i + 1) {
            head++;
        }

        // 此时队首即为区间 [i+1, 2i+1] 内 dp 最小的下标
        dp[i] = (long long)cost[i - 1] + dp[deque[head]];

        // 将 i 入队前，维持 dp 值单调递增
        while (head <= tail && dp[deque[tail]] >= dp[i]) {
            tail--;
        }
        deque[++tail] = i;
    }

    long long ans = dp[1];
    free(dp);
    free(deque);
    return ans;
}

int main() {
    int n;
    scanf("%d", &n);

    int* cost = (int*)malloc(n * sizeof(int));
    if (cost == NULL) return 0;

    for (int i = 0; i < n; ++i) {
        scanf("%d", &cost[i]);
    }

    printf("%lld\n", minimumTokens(cost, n));

    free(cost);
    return 0;
}

