 *
 * 核心思路：
 * 1. 使用“循环队列”维护最近的 k 个元素。
 * 2. 再维护一个 invalidCount，表示当前窗口中“不稳定读数”的个数。
 * 3. 每次加入新元素：
 *    - 如果队列已满，先弹出最旧元素；若该元素不稳定，则 invalidCount--。
 *    - 再把新元素加入队列；若新元素不稳定，则 invalidCount++。
 * 4. 当窗口大小不足 k 时，一定返回 false。
 * 5. 当窗口大小恰好为 k 且 invalidCount == 0 时，返回 true。
 *
 * 这样每次 stable() 操作的时间复杂度为 O(1)。
 */

typedef struct {
    long long target;      // 目标值
    long long tolerance;   // 允许误差
    int k;                 // 窗口大小

    int *queue;            // 循环队列数组，容量为 k
    int head;              // 队头下标
    int size;              // 当前队列中元素个数

    int invalidCount;      // 当前窗口中不在合法范围内的元素个数
} SignalStream;

/* 判断一个数是否为稳定读数 */
static bool isValid(SignalStream *obj, int num) {
    long long x = num;
    return (x >= obj->target - obj->tolerance) && (x <= obj->target + obj->tolerance);
}

/* 初始化对象 */
SignalStream* signalStreamCreate(int target, int tolerance, int k) {
    SignalStream *obj = (SignalStream *)malloc(sizeof(SignalStream));
    obj->target = target;
    obj->tolerance = tolerance;
    obj->k = k;

    obj->queue = (int *)malloc(sizeof(int) * k);
    obj->head = 0;
    obj->size = 0;
    obj->invalidCount = 0;

    return obj;
}

/*
 * 加入一个新读数，并判断最近 k 个读数是否都稳定
 */
bool signalStreamStable(SignalStream* obj, int num) {
    /* 如果队列已满，先移除最旧元素 */
    if (obj->size == obj->k) {
        int oldNum = obj->queue[obj->head];
        if (!isValid(obj, oldNum)) {
            obj->invalidCount--;
        }
        obj->head = (obj->head + 1) % obj->k;
        obj->size--;
    }

    /* 计算新元素插入位置：队尾 = (head + size) % k */
    int tail = (obj->head + obj->size) % obj->k;
    obj->queue[tail] = num;
    obj->size++;

    if (!isValid(obj, num)) {
        obj->invalidCount++;
    }

    /* 元素不足 k 个，条件不成立 */
    if (obj->size < obj->k) {
        return false;
    }

    /* 最近 k 个元素全部稳定，invalidCount 必须为 0 */
    return obj->invalidCount == 0;
}

/* 释放对象 */
void signalStreamFree(SignalStream* obj) {
    free(obj->queue);
    free(obj);
}

/*
 * 以下是一个简单的测试示例。
 * 提交到在线评测系统时，通常只保留上面的结构体与函数实现即可。
 */
int main() {
    SignalStream *stream = signalStreamCreate(10, 2, 3);

    printf("%s\n", signalStreamStable(stream, 9) ? "true" : "false");   // false
    printf("%s\n", signalStreamStable(stream, 12) ? "true" : "false");  // false
    printf("%s\n", signalStreamStable(stream, 8) ? "true" : "false");   // true
    printf("%s\n", signalStreamStable(stream, 10) ? "true" : "false");  // true
    printf("%s\n", signalStreamStable(stream, 13) ? "true" : "false");  // false

    signalStreamFree(stream);
    return 0;
}

