#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 巡检机械蛇 - C语言参考实现
 *
 * 核心思路：
 * 1. 用一个“循环队列”维护蛇身体的顺序：队头是尾巴，队尾是头。
 * 2. 用 occupied[r][c] 标记某个格子当前是否被蛇身体占据，用于 O(1) 判重。
 * 3. 每次移动时：
 *    - 先算出新的头部位置
 *    - 判断是否越界
 *    - 判断是否吃到当前补给点
 *    - 若本次不吃补给，则尾巴会移动：
 *         在做碰撞检测前，可以把“旧尾巴位置”临时视为可进入
 *      这样就正确处理了“头可以移动到旧尾巴位置”的特殊规则
 *
 * 时间复杂度：O(M)
 * 空间复杂度：O(H*W + M + F)
 */

typedef struct {
    int r;
    int c;
} Node;

typedef struct {
    Node *data;
    int front;      // 指向队头（尾巴）
    int rear;       // 指向下一个可插入位置
    int size;
    int capacity;
} Queue;

/* 初始化循环队列 */
void initQueue(Queue *q, int capacity) {
    q->data = (Node *)malloc(sizeof(Node) * capacity);
    q->front = 0;
    q->rear = 0;
    q->size = 0;
    q->capacity = capacity;
}

/* 入队：在队尾加入新的头部 */
void pushBack(Queue *q, Node x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % q->capacity;
    q->size++;
}

/* 出队：弹出队头，也就是旧尾巴 */
Node popFront(Queue *q) {
    Node x = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->size--;
    return x;
}

/* 查看队头（尾巴） */
Node getFront(Queue *q) {
    return q->data[q->front];
}

int main() {
    int H, W;
    scanf("%d %d", &H, &W);

    int F;
    scanf("%d", &F);

    int *foodR = NULL;
    int *foodC = NULL;
    if (F > 0) {
        foodR = (int *)malloc(sizeof(int) * F);
        foodC = (int *)malloc(sizeof(int) * F);
        for (int i = 0; i < F; i++) {
            scanf("%d %d", &foodR[i], &foodC[i]);
        }
    }

    int M;
    scanf("%d", &M);

    char *ops = (char *)malloc(sizeof(char) * (M + 5));
    scanf("%s", ops);

    /*
     * 队列最多会存下：初始长度1 + 最多吃到F个补给
     * 由于移动过程中长度不会超过 1+F，开大一些更安全：M+F+5
     */
    Queue q;
    initQueue(&q, M + F + 5);

    /* 用一维数组模拟二维占用表：occupied[r * W + c] */
    int *occupied = (int *)calloc(H * W, sizeof(int));

    /* 初始状态：蛇在 (0, 0) */
    Node start;
    start.r = 0;
    start.c = 0;
    pushBack(&q, start);
    occupied[0] = 1;

    int headR = 0, headC = 0;
    int score = 0;
    int foodIndex = 0;

    for (int step = 1; step <= M; step++) {
        char ch = ops[step - 1];
        int nr = headR;
        int nc = headC;

        /* 根据命令计算新头部位置 */
        if (ch == 'U') nr--;
        else if (ch == 'D') nr++;
        else if (ch == 'L') nc--;
        else if (ch == 'R') nc++;

        /* 1. 判断是否撞墙 */
        if (nr < 0 || nr >= H || nc < 0 || nc >= W) {
            printf("GAME OVER %d %d\n", step, score);
            free(foodR);
            free(foodC);
            free(ops);
            free(q.data);
            free(occupied);
            return 0;
        }

        /* 2. 判断本次是否吃到当前补给点 */
        int grow = 0;
        if (foodIndex < F && nr == foodR[foodIndex] && nc == foodC[foodIndex]) {
            grow = 1;
        }

        /*
         * 3. 自碰撞判断
         * 如果本次不生长，尾巴会移动，所以“旧尾巴位置”应先临时腾空，
         * 这样就允许头部移动到旧尾巴格子。
         */
        Node tail;
        int hasTempRemovedTail = 0;
        if (!grow) {
            tail = getFront(&q);
            occupied[tail.r * W + tail.c] = 0;
            hasTempRemovedTail = 1;
        }

        if (occupied[nr * W + nc]) {
            /* 如果之前临时移除了尾巴，这里无需恢复，程序直接结束即可 */
            printf("GAME OVER %d %d\n", step, score);
            free(foodR);
            free(foodC);
            free(ops);
            free(q.data);
            free(occupied);
            return 0;
        }

        /*
         * 4. 执行移动
         *    - 如果没生长，需要真正把旧尾巴从队列中删除
         *    - 新头部入队
         */
        if (!grow) {
            popFront(&q);
        }

        Node newHead;
        newHead.r = nr;
        newHead.c = nc;
        pushBack(&q, newHead);
        occupied[nr * W + nc] = 1;

        headR = nr;
        headC = nc;

        /* 5. 更新得分和补给指针 */
        if (grow) {
            score++;
            foodIndex++;
        }
    }

    /* 所有操作顺利执行完成 */
    printf("OK %d %d %d\n", score, headR, headC);

    free(foodR);
    free(foodC);
    free(ops);
    free(q.data);
    free(occupied);
    return 0;
}

