typedef struct {
    int r;
    int c;
} Node;

typedef struct {
    Node *data;
    int front;
    int rear;
    int size;
    int capacity;
} Queue;

/* 初始化循环队列 */
void initQueue(Queue *q, int capacity) {
    q->data = (Node *)malloc(sizeof(Node) * capacity);
    q->front = 0;
    q->rear = 0;
    q->size = 0;
    q->capacity = capacity;
}

/* 入队：在队尾加入新的头部 */
void pushBack(Queue *q, Node x) {
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % q->capacity;
    q->size++;
}

/* 出队：弹出队头，也就是旧尾巴 */
Node popFront(Queue *q) {
    Node x = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->size--;
    return x;
}

/* 查看队头（尾巴） */
Node getFront(Queue *q) {
    return q->data[q->front];
}

