#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 设计思路：
 * 1. 使用循环队列保存“当前可用”的通行码编号。
 * 2. 使用布尔数组 available[] 记录每个编号当前是否可用。
 *
 * 初始化时：
 *   所有编号 0 ~ maxCodes-1 都可用，依次入队。
 *
 * get():
 *   - 若队列为空，返回 -1
 *   - 否则队头出队，标记为不可用，返回该编号
 *
 * check(code):
 *   - 若 code 越界，返回 false
 *   - 否则返回 available[code]
 *
 * release(code):
 *   - 仅当 code 合法且当前处于“不可用”状态时，才回收
 *   - 将其重新入队，并标记为可用
 */

typedef struct {
    int maxCodes;      // 编号总数
    int *queue;        // 循环队列，保存当前可用的编号
    bool *available;   // available[i] == true 表示编号 i 当前可用
    int front;         // 队头下标
    int rear;          // 队尾下一个位置
    int size;          // 当前队列中的元素个数
} CodeManager;

/* 创建管理器 */
CodeManager* codeManagerCreate(int maxCodes) {
    CodeManager *obj = (CodeManager *)malloc(sizeof(CodeManager));
    if (obj == NULL) {
        return NULL;
    }

    obj->maxCodes = maxCodes;
    obj->queue = (int *)malloc(sizeof(int) * maxCodes);
    obj->available = (bool *)malloc(sizeof(bool) * maxCodes);

    if (obj->queue == NULL || obj->available == NULL) {
        free(obj->queue);
        free(obj->available);
        free(obj);
        return NULL;
    }

    obj->front = 0;
    obj->rear = 0;
    obj->size = 0;

    /* 初始化：所有编号都可用，全部入队 */
    for (int i = 0; i < maxCodes; ++i) {
        obj->queue[obj->rear] = i;
        obj->rear = (obj->rear + 1) % maxCodes;
        obj->size++;
        obj->available[i] = true;
    }

    return obj;
}

/* 分配一个可用编号 */
int codeManagerGet(CodeManager* obj) {
    if (obj == NULL || obj->size == 0) {
        return -1;
    }

    int code = obj->queue[obj->front];
    obj->front = (obj->front + 1) % obj->maxCodes;
    obj->size--;

    obj->available[code] = false;
    return code;
}

/* 检查某编号当前是否可用 */
bool codeManagerCheck(CodeManager* obj, int code) {
    if (obj == NULL || code < 0 || code >= obj->maxCodes) {
        return false;
    }
    return obj->available[code];
}

/* 回收某编号 */
void codeManagerRelease(CodeManager* obj, int code) {
    if (obj == NULL || code < 0 || code >= obj->maxCodes) {
        return;
    }

    /* 只有当前“不可用”的编号才能被回收 */
    if (obj->available[code] == false) {
        obj->queue[obj->rear] = code;
        obj->rear = (obj->rear + 1) % obj->maxCodes;
        obj->size++;
        obj->available[code] = true;
    }
}

/* 释放管理器 */
void codeManagerFree(CodeManager* obj) {
    if (obj == NULL) {
        return;
    }
    free(obj->queue);
    free(obj->available);
    free(obj);
}

/*
 * 说明：
 * 上述代码是题目要求的标准接口实现。
 * 在线评测系统通常会自动调用这些函数，因此不需要自己编写 main 函数。
 *
 * 若你希望本地测试，可参考下面的示例：
 *
 * int main() {
 *     CodeManager* obj = codeManagerCreate(3);
 *     printf("%d\n", codeManagerGet(obj));      // 0
 *     printf("%d\n", codeManagerGet(obj));      // 1
 *     printf("%d\n", codeManagerCheck(obj, 2)); // 1 (true)
 *     printf("%d\n", codeManagerGet(obj));      // 2
 *     printf("%d\n", codeManagerCheck(obj, 2)); // 0 (false)
 *     codeManagerRelease(obj, 1);
 *     printf("%d\n", codeManagerCheck(obj, 1)); // 1 (true)
 *     printf("%d\n", codeManagerGet(obj));      // 1
 *     codeManagerFree(obj);
 *     return 0;
 * }
 */

