#include <stdio.h>
#include <stdlib.h>

#define MAXN 505

/*
 * 使用顺序队列模拟环形传花过程。
 * 思路：
 * 1. 初始时把 1~n 依次入队。
 * 2. 每一轮先把前 k-1 个元素依次“出队后再入队”，表示继续顺时针传递。
 * 3. 此时队首元素就是第 k 个同学，将其出队并记录为淘汰者。
 * 4. 重复直到队列中只剩 1 个元素。
 */

typedef struct {
    int data[MAXN * MAXN]; // 为简单起见开大一些，足够本题使用
    int front;
    int rear;
} Queue;

// 初始化队列
void initQueue(Queue *q) {
    q->front = 0;
    q->rear = 0;
}

// 判断队列是否为空
int isEmpty(Queue *q) {
    return q->front == q->rear;
}

// 当前队列元素个数
int size(Queue *q) {
    return q->rear - q->front;
}

// 入队
void push(Queue *q, int x) {
    q->data[q->rear++] = x;
}

// 出队
int pop(Queue *q) {
    return q->data[q->front++];
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    Queue q;
    initQueue(&q);

    // 初始 1~n 入队
    for (int i = 1; i <= n; i++) {
        push(&q, i);
    }

    int eliminated[MAXN];
    int cnt = 0;

    // 当队列中多于 1 人时，继续淘汰
    while (size(&q) > 1) {
        // 前 k-1 人传花：队首出队后再入队
        for (int i = 1; i <= k - 1; i++) {
            int x = pop(&q);
            push(&q, x);
        }

        // 第 k 人淘汰
        eliminated[cnt++] = pop(&q);
    }

    // 输出淘汰顺序
    for (int i = 0; i < cnt; i++) {
        if (i > 0) printf(" ");
        printf("%d", eliminated[i]);
    }
    printf("\n");

    // 输出获胜者
    printf("%d\n", pop(&q));

    return 0;
}

