#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 设计思路：
 *
 * 1. 用循环队列维护“当前可用的编号”。
 *    - 初始化时，0 ~ maxSlots - 1 全部入队。
 *    - get() 时，从队头取出一个编号。
 *    - release(number) 时，如果该编号当前处于已分配状态，则重新入队。
 *
 * 2. 用布尔数组 available[number] 记录该编号当前是否可用。
 *    - true  : 当前可分配（在可用池中）
 *    - false : 当前已被分配
 *
 * 3. 为了让循环队列不会溢出，这里分配 2 * maxSlots + 5 的容量。
 *    原因：
 *    - 初始化时会入队 maxSlots 个元素。
 *    - 之后只有“已分配的编号”才能被 release 并重新入队。
 *    - 任意时刻队列中的元素数量不会超过 maxSlots。
 *    因此开到 maxSlots + 5 就足够；这里留更宽松一些也没问题。
 */

typedef struct {
    int *queue;          // 循环队列，存储当前可用编号
    bool *available;     // available[i] == true 表示编号 i 当前可用
    int front;           // 队头下标
    int rear;            // 队尾的下一个位置
    int size;            // 当前队列元素个数
    int capacity;        // 队列容量
    int maxSlots;        // 编号总数
} SlotDirectory;

/* 创建分配器 */
SlotDirectory* slotDirectoryCreate(int maxSlots) {
    SlotDirectory* obj = (SlotDirectory*)malloc(sizeof(SlotDirectory));
    if (obj == NULL) return NULL;

    obj->maxSlots = maxSlots;
    obj->capacity = maxSlots + 5;
    obj->queue = (int*)malloc(sizeof(int) * obj->capacity);
    obj->available = (bool*)malloc(sizeof(bool) * maxSlots);

    if (obj->queue == NULL || obj->available == NULL) {
        free(obj->queue);
        free(obj->available);
        free(obj);
        return NULL;
    }

    obj->front = 0;
    obj->rear = 0;
    obj->size = 0;

    // 初始时所有编号都可用，按 0 ~ maxSlots-1 的顺序入队
    for (int i = 0; i < maxSlots; ++i) {
        obj->queue[obj->rear] = i;
        obj->rear = (obj->rear + 1) % obj->capacity;
        obj->size++;
        obj->available[i] = true;
    }

    return obj;
}

/* 分配一个可用编号，若没有则返回 -1 */
int slotDirectoryGet(SlotDirectory* obj) {
    if (obj == NULL || obj->size == 0) {
        return -1;
    }

    int number = obj->queue[obj->front];
    obj->front = (obj->front + 1) % obj->capacity;
    obj->size--;

    // 被取走后，编号变为“已分配”状态
    obj->available[number] = false;
    return number;
}

/* 检查某个编号当前是否可用 */
bool slotDirectoryCheck(SlotDirectory* obj, int number) {
    if (obj == NULL || number < 0 || number >= obj->maxSlots) {
        return false;
    }
    return obj->available[number];
}

/* 回收一个已分配的编号；若本来就可用，则忽略 */
void slotDirectoryRelease(SlotDirectory* obj, int number) {
    if (obj == NULL || number < 0 || number >= obj->maxSlots) {
        return;
    }

    // 只有当前“已分配”的编号才能回收，防止重复入队
    if (obj->available[number] == false) {
        obj->queue[obj->rear] = number;
        obj->rear = (obj->rear + 1) % obj->capacity;
        obj->size++;
        obj->available[number] = true;
    }
}

/* 释放内存 */
void slotDirectoryFree(SlotDirectory* obj) {
    if (obj == NULL) return;
    free(obj->queue);
    free(obj->available);
    free(obj);
}

/*
 * 说明：
 * 如果在本地测试，可参考如下 main 函数。
 * 在线评测系统通常不需要提交 main，只提交上面的实现即可。
 */
/*
int main() {
    SlotDirectory* dir = slotDirectoryCreate(3);

    printf("%d\n", slotDirectoryGet(dir));      // 0
    printf("%d\n", slotDirectoryGet(dir));      // 1
    printf("%s\n", slotDirectoryCheck(dir, 2) ? "true" : "false"); // true
    printf("%d\n", slotDirectoryGet(dir));      // 2
    printf("%s\n", slotDirectoryCheck(dir, 2) ? "true" : "false"); // false
    slotDirectoryRelease(dir, 2);
    printf("%s\n", slotDirectoryCheck(dir, 2) ? "true" : "false"); // true
    printf("%d\n", slotDirectoryGet(dir));      // 2

    slotDirectoryFree(dir);
    return 0;
}
*/

