#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * 题意：
 * 设计一个工牌分配系统，支持：
 * 1. get()    : 取出当前最早可用的编号
 * 2. check(x) : 判断编号 x 是否可用
 * 3. release(x): 归还已分配的编号，归还后进入队尾
 *
 * 核心数据结构：
 * - 循环队列：维护“当前可用”的编号，保证 FIFO 分配
 * - 布尔数组 available[]：记录每个编号当前是否可用
 *
 * 关键点：
 * - 初始化时，0 ~ maxTag-1 全部入队
 * - get() 从队头取出一个编号，并标记为不可用
 * - release(x) 只有在 x 当前不可用时才入队并标记为可用
 *   这样可以避免重复归还导致同一编号多次进入队列
 */

typedef struct TagSystem {
    int *queue;         // 循环队列，存放当前可用编号
    bool *available;    // available[i] == true 表示编号 i 当前可用
    int capacity;       // 最大编号总数
    int front;          // 队头下标
    int rear;           // 队尾的下一个位置
    int size;           // 当前队列中元素个数
} TagSystem;

/* 创建系统 */
TagSystem* tagSystemCreate(int maxTag) {
    TagSystem *obj = (TagSystem *)malloc(sizeof(TagSystem));
    if (obj == NULL) {
        return NULL;
    }

    obj->queue = (int *)malloc(sizeof(int) * maxTag);
    obj->available = (bool *)malloc(sizeof(bool) * maxTag);
    if (obj->queue == NULL || obj->available == NULL) {
        free(obj->queue);
        free(obj->available);
        free(obj);
        return NULL;
    }

    obj->capacity = maxTag;
    obj->front = 0;
    obj->rear = 0;
    obj->size = 0;

    // 初始时所有编号都可用，按 0 ~ maxTag-1 的顺序入队
    for (int i = 0; i < maxTag; ++i) {
        obj->queue[obj->rear] = i;
        obj->rear = (obj->rear + 1) % obj->capacity;
        obj->size++;
        obj->available[i] = true;
    }

    return obj;
}

/* 分配最早可用的编号 */
int tagSystemGet(TagSystem* obj) {
    if (obj == NULL || obj->size == 0) {
        return -1;
    }

    int tag = obj->queue[obj->front];
    obj->front = (obj->front + 1) % obj->capacity;
    obj->size--;

    // 被分配后，标记为不可用
    obj->available[tag] = false;
    return tag;
}

/* 检查某个编号是否可用 */
bool tagSystemCheck(TagSystem* obj, int tag) {
    if (obj == NULL || tag < 0 || tag >= obj->capacity) {
        return false;
    }
    return obj->available[tag];
}

/* 归还一个编号：只有当前已分配的编号才能归还成功 */
void tagSystemRelease(TagSystem* obj, int tag) {
    if (obj == NULL || tag < 0 || tag >= obj->capacity) {
        return;
    }

    // 如果该编号已经可用，说明重复归还，直接忽略
    if (obj->available[tag]) {
        return;
    }

    // 放入队尾，重新变为可用
    obj->queue[obj->rear] = tag;
    obj->rear = (obj->rear + 1) % obj->capacity;
    obj->size++;
    obj->available[tag] = true;
}

/* 释放内存 */
void tagSystemFree(TagSystem* obj) {
    if (obj == NULL) {
        return;
    }
    free(obj->queue);
    free(obj->available);
    free(obj);
}

/*
 * 时间复杂度：
 * - tagSystemCreate: O(maxTag)
 * - tagSystemGet   : O(1)
 * - tagSystemCheck : O(1)
 * - tagSystemRelease: O(1)
 *
 * 空间复杂度：O(maxTag)
 */

