#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定每个位置已有的信标数量 beacons[i]，每个信标可覆盖距离 <= d 的位置。
还能新增 k 个信标，问所有位置中的最小防护值最大能达到多少。

核心做法：
1. 先用滑动窗口预处理每个位置的“初始防护值” base[i]。
2. 二分答案 x：判断是否能让每个位置防护值都 >= x。
3. 判定时从左到右贪心：
   - 若当前位置不足 x，则必须立刻补信标；
   - 为了让新增信标影响尽可能远，应该放在当前位置右侧最远还能覆盖当前位置的位置：pos = min(n-1, i+d)
   - 这批新增信标会一直影响到 expire = min(n-1, pos+d) = min(n-1, i+2*d)
4. 用“队列”维护所有仍然生效的新增批次：
   - 队首是最早失效的批次；
   - 扫描到新位置时，把已经失效的批次弹出；
   - activeAdd 表示当前所有仍生效新增信标对当前位置的总贡献。

时间复杂度：
- 预处理 O(n)
- 每次可行性检查 O(n)
- 二分约 O(log(sum+k))
总复杂度 O(n log(sum+k))
*/

// 判定是否可以让所有位置的防护值都至少达到 target
static int canReach(long long* base, int n, int d, long long k, long long target) {
    // 队列中存储：每一批新增信标的失效位置 expire，以及该批数量 amount
    int* expireQ = (int*)malloc(sizeof(int) * n);
    long long* amountQ = (long long*)malloc(sizeof(long long) * n);
    if (expireQ == NULL || amountQ == NULL) {
        free(expireQ);
        free(amountQ);
        return 0;
    }

    int head = 0, tail = 0;
    long long activeAdd = 0;   // 当前仍在生效的新增信标总贡献
    long long used = 0;        // 已使用新增信标数量

    for (int i = 0; i < n; ++i) {
        // 移除已经失效的新增批次
        while (head < tail && expireQ[head] < i) {
            activeAdd -= amountQ[head];
            head++;
        }

        long long current = base[i] + activeAdd;

        // 如果当前位置防护值不足 target，必须补足
        if (current < target) {
            long long need = target - current;
            used += need;
            if (used > k) {
                free(expireQ);
                free(amountQ);
                return 0;
            }

            // 贪心：把这批新增信标放在最右边仍能覆盖 i 的位置
            int pos = i + d;
            if (pos >= n) pos = n - 1;

            // 这批新增信标最远能影响到的位置
            int expire = pos + d;
            if (expire >= n) expire = n - 1;

            // 入队
            expireQ[tail] = expire;
            amountQ[tail] = need;
            tail++;

            activeAdd += need;
        }
    }

    free(expireQ);
    free(amountQ);
    return 1;
}

long long maximizeMinimumDefense(int* beacons, int n, int d, long long k) {
    long long* base = (long long*)malloc(sizeof(long long) * n);
    if (base == NULL) return -1;

    // 预处理每个位置的初始防护值：滑动窗口统计 [i-d, i+d] 内 beacons 之和
    long long windowSum = 0;
    int left = 0, right = -1;
    long long totalBeacons = 0;

    for (int i = 0; i < n; ++i) totalBeacons += beacons[i];

    for (int i = 0; i < n; ++i) {
        int L = i - d;
        if (L < 0) L = 0;
        int R = i + d;
        if (R >= n) R = n - 1;

        // 扩展右边界
        while (right < R) {
            right++;
            windowSum += beacons[right];
        }

        // 收缩左边界
        while (left < L) {
            windowSum -= beacons[left];
            left++;
        }

        base[i] = windowSum;
    }

    // 二分答案
    // 任一位置的防护值不可能超过 totalBeacons + k
    long long lo = 0, hi = totalBeacons + k;
    long long ans = 0;

    while (lo <= hi) {
        long long mid = lo + ((hi - lo) >> 1);
        if (canReach(base, n, d, k, mid)) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    free(base);
    return ans;
}

