#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定长度为 n 的 01 串，每次可以翻转连续 k 个位置，求把所有位变成 1 的最少操作数，无法完成则输出 -1。

核心思路（贪心 + 队列）：
1. 从左到右扫描每个位置 i。
2. 一个在位置 start 发起的翻转，会影响区间 [start, start + k - 1]。
   因此，当扫描到 i 时，凡是 start + k <= i 的翻转都已失效，可以从队列中弹出。
3. 队列中剩余翻转的个数若为奇数，说明当前位置已被翻转奇数次；
   若为偶数，说明当前位置保持原值。
4. 计算当前位置的“实际值”：actual = original ^ (activeFlipCount % 2)
   - 如果 actual == 1，说明当前位置已经满足要求，不必操作。
   - 如果 actual == 0，想把它变成 1，唯一选择就是“立刻在 i 位置发起一次翻转”。
     因为后面开始的翻转再也无法覆盖到 i。
5. 若 i + k > n，则已经无法在 i 发起长度为 k 的翻转，返回 -1。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }

    char *s = (char *)malloc((n + 5) * sizeof(char));
    if (s == NULL) return 0;

    scanf("%s", s);

    /*
    用数组模拟队列，存储每次翻转的起点。
    队列中保存的是“当前仍然对当前位置有影响”的翻转。
    */
    int *queue = (int *)malloc(n * sizeof(int));
    if (queue == NULL) {
        free(s);
        return 0;
    }

    int front = 0, rear = 0;
    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        /* 移除所有已经失效的翻转：start + k <= i */
        while (front < rear && queue[front] + k <= i) {
            front++;
        }

        /* 当前仍生效的翻转次数 */
        int active = rear - front;

        /* 原始位 */
        int bit = s[i] - '0';

        /* 实际位 = 原始位 ^ (是否被翻转奇数次) */
        int actual = bit ^ (active & 1);

        /*
        若当前位置实际为 0，为了最终全为 1，必须立即在 i 发起翻转。
        这是贪心的关键：当前位置错过之后，再无机会修复。
        */
        if (actual == 0) {
            if (i + k > n) {
                printf("-1\n");
                free(s);
                free(queue);
                return 0;
            }

            queue[rear++] = i;
            ans++;
        }
    }

    printf("%lld\n", ans);

    free(s);
    free(queue);
    return 0;
}

