#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
 * 最大接力能量
 *
 * 核心思路：
 * 设 dp[i] 表示“必须以第 i 个节点结尾”时能获得的最大总能量。
 * 则有：
 *   dp[i] = a[i] + max(0, max(dp[j]))，其中 i-k <= j < i
 *
 * 也就是说，我们只需要知道最近 k 个位置中的 dp 最大值。
 * 使用单调队列（双端队列）维护候选下标，使得：
 *   1. 队头始终在窗口 [i-k, i-1] 内
 *   2. 队列中对应的 dp 值单调递减，队头即当前窗口最大 dp
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(n)
 */

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }

    long long *a = (long long *)malloc((n + 1) * sizeof(long long));
    long long *dp = (long long *)malloc((n + 1) * sizeof(long long));
    int *deque = (int *)malloc((n + 1) * sizeof(int));

    if (!a || !dp || !deque) {
        free(a);
        free(dp);
        free(deque);
        return 0;
    }

    for (int i = 1; i <= n; ++i) {
        scanf("%lld", &a[i]);
    }

    int head = 0, tail = 0;  // deque[head..tail-1] 有效
    long long ans = LLONG_MIN;

    for (int i = 1; i <= n; ++i) {
        /*
         * 1. 弹出窗口外的下标
         *    允许转移的 j 满足 j >= i-k
         */
        while (head < tail && deque[head] < i - k) {
            head++;
        }

        /*
         * 2. 取窗口内最大 dp 值（若为负则不如重新开始）
         */
        long long best = 0;
        if (head < tail && dp[deque[head]] > 0) {
            best = dp[deque[head]];
        }

        dp[i] = a[i] + best;
        if (dp[i] > ans) {
            ans = dp[i];
        }

        /*
         * 3. 将当前 i 插入单调队列
         *    维护 dp 值从大到小，队头最大
         */
        while (head < tail && dp[deque[tail - 1]] <= dp[i]) {
            tail--;
        }
        deque[tail++] = i;
    }

    printf("%lld\n", ans);

    free(a);
    free(dp);
    free(deque);
    return 0;
}

