#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 题解思路：
 *
 * 这是一个“最近 m 个元素”的滑动窗口问题，核心点有两个：
 * 1. 需要一个队列/循环数组，支持窗口满时弹出最早元素；
 * 2. 需要快速求：
 *    - 最小的 k 个数之和
 *    - 最大的 k 个数之和
 *
 * 因为 num 的范围是 [1, 1e5]，可以使用两个树状数组（Fenwick Tree）：
 * - bitCnt: 维护每个值出现次数
 * - bitSum: 维护每个值的数值总和
 *
 * 这样可以支持：
 * - 插入一个值: O(logV)
 * - 删除一个值: O(logV)
 * - 查询前 k 小元素之和: O(logV)
 *
 * 对于“前 k 小元素之和”：
 *   先二分/树状数组跳跃找到最小的值 x，使得 prefixCount(x) >= k。
 *   设：
 *     cntLess = 前缀中严格小于 x 的元素个数
 *     sumLess = 前缀中严格小于 x 的元素和
 *   那么：
 *     sumFirstK = sumLess + (k - cntLess) * x
 *
 * 最大的 k 个数之和可以转化为：
 *   sumLargestK = totalSum - sumFirst(totalCount - k)
 *
 * 当窗口大小固定为 m 时：
 *   middleSum = totalSum - sumSmallestK - sumLargestK
 *   answer = middleSum / (m - 2k)
 *
 * 下面给出符合 LeetCode 风格的 C 语言实现。
 */

#define MAXV 100000

typedef long long ll;

typedef struct {
    int n;
    ll *tree;
} Fenwick;

static Fenwick* fenwickCreate(int n) {
    Fenwick *fw = (Fenwick*)malloc(sizeof(Fenwick));
    fw->n = n;
    fw->tree = (ll*)calloc(n + 1, sizeof(ll));
    return fw;
}

static void fenwickAdd(Fenwick *fw, int idx, ll delta) {
    while (idx <= fw->n) {
        fw->tree[idx] += delta;
        idx += idx & -idx;
    }
}

static ll fenwickSumPrefix(Fenwick *fw, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += fw->tree[idx];
        idx -= idx & -idx;
    }
    return res;
}

static void fenwickFree(Fenwick *fw) {
    free(fw->tree);
    free(fw);
}

/*
 * 在 bitCnt 中找到最小的 idx，使得 prefixCount(idx) >= k
 * 要求 k >= 1
 */
static int fenwickKth(Fenwick *bitCnt, ll k) {
    int idx = 0;
    int bitMask = 1;
    while ((bitMask << 1) <= bitCnt->n) bitMask <<= 1;

    for (int step = bitMask; step > 0; step >>= 1) {
        int next = idx + step;
        if (next <= bitCnt->n && bitCnt->tree[next] < k) {
            idx = next;
            k -= bitCnt->tree[next];
        }
    }
    return idx + 1;
}

typedef struct {
    int m;
    int k;

    /* 循环队列，保存最近 m 个元素 */
    int *q;
    int head;
    int size;

    Fenwick *bitCnt;
    Fenwick *bitSum;

    ll totalSum;
} RobustMean;

/* 计算当前窗口中前 t 小元素的和 */
static ll getFirstTSum(RobustMean *obj, int t) {
    if (t <= 0) return 0;

    int x = fenwickKth(obj->bitCnt, t);           // 第 t 小元素的值
    ll cntLess = fenwickSumPrefix(obj->bitCnt, x - 1);
    ll sumLess = fenwickSumPrefix(obj->bitSum, x - 1);

    return sumLess + (ll)(t - cntLess) * x;
}

/*
 * 最大的 t 个元素之和
 * = totalSum - 前 (size - t) 小元素之和
 */
static ll getLastTSum(RobustMean *obj, int t) {
    if (t <= 0) return 0;
    return obj->totalSum - getFirstTSum(obj, obj->size - t);
}

RobustMean* robustMeanCreate(int m, int k) {
    RobustMean *obj = (RobustMean*)malloc(sizeof(RobustMean));
    obj->m = m;
    obj->k = k;
    obj->q = (int*)malloc(sizeof(int) * m);
    obj->head = 0;
    obj->size = 0;
    obj->bitCnt = fenwickCreate(MAXV);
    obj->bitSum = fenwickCreate(MAXV);
    obj->totalSum = 0;
    return obj;
}

void robustMeanPush(RobustMean* obj, int num) {
    /* 如果窗口已满，先删除最早元素 */
    if (obj->size == obj->m) {
        int old = obj->q[obj->head];
        obj->head = (obj->head + 1) % obj->m;
        obj->size--;

        fenwickAdd(obj->bitCnt, old, -1);
        fenwickAdd(obj->bitSum, old, -old);
        obj->totalSum -= old;
    }

    /* 插入新元素到循环队列尾部 */
    int tail = (obj->head + obj->size) % obj->m;
    obj->q[tail] = num;
    obj->size++;

    fenwickAdd(obj->bitCnt, num, 1);
    fenwickAdd(obj->bitSum, num, num);
    obj->totalSum += num;
}

int robustMeanQuery(RobustMean* obj) {
    if (obj->size < obj->m) return -1;

    ll lowSum = getFirstTSum(obj, obj->k);
    ll highSum = getLastTSum(obj, obj->k);
    ll middleSum = obj->totalSum - lowSum - highSum;
    int middleCnt = obj->m - 2 * obj->k;

    return (int)(middleSum / middleCnt);
}

void robustMeanFree(RobustMean* obj) {
    if (!obj) return;
    free(obj->q);
    fenwickFree(obj->bitCnt);
    fenwickFree(obj->bitSum);
    free(obj);
}

/*
 * 使用说明（伪代码风格）：
 *
 * RobustMean* obj = robustMeanCreate(m, k);
 * robustMeanPush(obj, num);
 * int ans = robustMeanQuery(obj);
 * robustMeanFree(obj);
 *
 *
