 *     printf("%d\n", robustMeanQuery(obj)); // -1
 *     robustMeanPush(obj, 10);
 *     printf("%d\n", robustMeanQuery(obj)); // 3
 *     robustMeanPush(obj, 5);
 *     robustMeanPush(obj, 5);
 *     robustMeanPush(obj, 5);
 *     printf("%d\n", robustMeanQuery(obj)); // 5
 *     robustMeanFree(obj);
 *     return 0;
 * }
 */

