#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

/*
题意精炼：
给定按顺序排队的 boxes，每次必须从队头取一段连续区间 [j+1 .. i]，
满足：
1) 区间长度 <= maxBoxes
2) 区间总重量 <= maxWeight

若这一段作为一次运输，其代价为：
2 + 该区间内相邻箱子港口不同的次数

设：
- wpre[i] = 前 i 个箱子的重量前缀和
- neg[i] = 前 i 个箱子中，相邻港口变化次数的前缀和
  这里定义：
    neg[0] = 0
    neg[i] = neg[i-1] + (port[i-1] != port[i] ? 1 : 0)   (i >= 2, 1-based理解)
  更直接地，在代码中使用 1-based 数组：
    diff[i] = (i >= 2 && port[i] != port[i-1]) ? 1 : 0
    neg[i] = neg[i-1] + diff[i]

那么一段 [j+1 .. i] 的运输代价：
cost(j+1, i) = 2 + (neg[i] - neg[j+1])
因为区间内部相邻变化统计的是 (j+2..i) 这些位置上的 diff。

状态转移：
dp[i] = 运输完前 i 个箱子的最小代价
dp[0] = 0

对于最后一趟取 [j+1 .. i]：
dp[i] = dp[j] + 2 + neg[i] - neg[j+1]
      = (dp[j] - neg[j+1]) + neg[i] + 2

因此对每个 i，只要找到所有合法 j 中最小的 (dp[j] - neg[j+1]) 即可。
合法 j 需要满足：
- i - j <= maxBoxes
- wpre[i] - wpre[j] <= maxWeight

随着 i 递增，合法 j 形成一个滑动窗口。
我们使用一个单调队列维护候选 j，按值：
value(j) = dp[j] - neg[j+1]
递增维护。

注意边界：
当 j = 0 时，需要用 neg[1]。而 diff[1] = 0，所以 neg[1] = 0，成立。

复杂度：
- 时间 O(n)
- 空间 O(n)
*/

int minVoyages(int** boxes, int boxesSize, int* boxesColSize,
               int portsCount, int maxBoxes, int maxWeight) {
    (void)boxesColSize; // 避免未使用警告
    (void)portsCount;   // 本题中港口总数不参与计算，仅用于保证数据合法

    int n = boxesSize;

    // 使用 1-based 数组，便于前缀处理
    int* port = (int*)malloc((n + 1) * sizeof(int));
    int* weight = (int*)malloc((n + 1) * sizeof(int));
    long long* wpre = (long long*)malloc((n + 1) * sizeof(long long));
    int* neg = (int*)malloc((n + 1) * sizeof(int));
    int* dp = (int*)malloc((n + 1) * sizeof(int));

    // 单调队列中存储候选下标 j
    int* deque = (int*)malloc((n + 1) * sizeof(int));
    int head = 0, tail = 0; // [head, tail)

    if (!port || !weight || !wpre || !neg || !dp || !deque) {
        free(port);
        free(weight);
        free(wpre);
        free(neg);
        free(dp);
        free(deque);
        return -1;
    }

    for (int i = 1; i <= n; ++i) {
        port[i] = boxes[i - 1][0];
        weight[i] = boxes[i - 1][1];
    }

    wpre[0] = 0;
    neg[0] = 0;
    for (int i = 1; i <= n; ++i) {
        wpre[i] = wpre[i - 1] + weight[i];
        neg[i] = neg[i - 1];
        if (i >= 2 && port[i] != port[i - 1]) {
            neg[i]++;
        }
    }

    dp[0] = 0;

    // 初始候选 j = 0
    deque[tail++] = 0;

    for (int i = 1; i <= n; ++i) {
        // 1) 弹出所有对当前 i 不合法的 j
        // 条件：
        // - 箱子数超过 maxBoxes  => i - j > maxBoxes
        // - 总重量超过 maxWeight => wpre[i] - wpre[j] > maxWeight
        while (head < tail) {
            int j = deque[head];
            if (i - j > maxBoxes || wpre[i] - wpre[j] > maxWeight) {
                head++;
            } else {
                break;
            }
        }

        // 题目保证每个箱子单独运输可行，因此这里一定存在合法 j
        int best = deque[head];
        dp[i] = dp[best] + 2 + (neg[i] - neg[best + 1]);

        // 2) 将当前 i 作为未来状态的候选 j 插入单调队列
        // 维护 value(j) = dp[j] - neg[j+1] 递增
        // 未来转移时：dp[t] = value(j) + neg[t] + 2
        int curValue = dp[i] - (i + 1 <= n ? neg[i + 1] : neg[i]);
        // 当 i == n 时，j = n 不会再被使用（没有更大的 t），
        // 但统一写法下仍可安全处理，令 neg[n+1] 视作 neg[n] 即可。

        while (head < tail) {
            int last = deque[tail - 1];
            int lastValue = dp[last] - (last + 1 <= n ? neg[last + 1] : neg[last]);
            if (lastValue >= curValue) {
                tail--;
            } else {
                break;
            }
        }
        deque[tail++] = i;
    }

    int ans = dp[n];

    free(port);
    free(weight);
    free(wpre);
    free(neg);
    free(dp);
    free(deque);

    return ans;
}

