#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定初始二进制数组 source 和目标数组 target。
每次可选择一个长度为 k 的连续区间，将其中每一位取反。
求最少操作次数使 source 变为 target，不可能则输出 -1。

核心思路（贪心 + 队列）：
1. 从左到右扫描每个位置 i。
2. 用一个队列保存“已经发起、且仍然影响当前位置”的翻转操作起点。
3. 若某个起点 start 满足 start + k <= i，则它已经失效，需要从队头弹出。
4. 队列当前元素个数的奇偶性，表示位置 i 被翻转了多少次（只关心奇偶）。
5. source[i] 在当前位置的实际值 = source[i] ^ (队列大小 % 2)
6. 如果实际值 != target[i]，那么按照贪心策略，必须在 i 发起一次新的长度 k 翻转。
   - 若 i + k > n，说明越界，无解，返回 -1。
   - 否则把 i 入队，答案加 1。

为什么贪心正确：
- 扫描到 i 时，只有起点 <= i 的操作能影响它。
- 如果当前值不等于目标值，而你不在 i 发起翻转，之后任何起点 > i 的操作都无法再影响 i。
- 所以此时“翻”是唯一选择。

时间复杂度：O(n)
空间复杂度：O(n)（队列）
*/

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }

    int *source = (int *)malloc(sizeof(int) * n);
    int *target = (int *)malloc(sizeof(int) * n);
    if (source == NULL || target == NULL) {
        free(source);
        free(target);
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &source[i]);
    }
    for (int i = 0; i < n; ++i) {
        scanf("%d", &target[i]);
    }

    /*
    使用数组模拟队列，存储每次翻转的起点。
    由于每个位置最多发起一次翻转，所以最多 n 次入队。
    */
    int *queue = (int *)malloc(sizeof(int) * n);
    if (queue == NULL) {
        free(source);
        free(target);
        return 0;
    }

    int front = 0, rear = 0;   // 队列区间 [front, rear)
    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        /*
        把已经不再影响位置 i 的翻转操作移出队列。
        若某翻转起点为 s，则它影响区间 [s, s+k-1]。
        当 s+k <= i 时，说明它对 i 已经失效。
        */
        while (front < rear && queue[front] + k <= i) {
            front++;
        }

        /* 当前仍生效翻转次数的奇偶性 */
        int parity = (rear - front) & 1;

        /* 当前位置在所有历史翻转作用后的实际值 */
        int current = source[i] ^ parity;

        /*
        若当前值和目标值不同，则必须从 i 开始翻转一个长度为 k 的区间。
        */
        if (current != target[i]) {
            if (i + k > n) {
                printf("-1\n");
                free(source);
                free(target);
                free(queue);
                return 0;
            }
            queue[rear++] = i;
            ans++;
        }
    }

    printf("%lld\n", ans);

    free(source);
    free(target);
    free(queue);
    return 0;
}

