    int n, s;
    scanf("%d %d", &n, &s);

    int a[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int count = 0;

    // 从下标 s 开始，顺时针走一整圈，共访问 n 间房屋
    for (int i = 0; i < n; i++) {
        // 环形数组下标：走到末尾后回到开头
        int index = (s + i) % n;

        // 如果当前房屋门灯亮着，则计数加一
        if (a[index] == 1) {
            count++;
        }
    }

    // 输出亮灯房屋总数
    printf("%d\n", count);

    return 0;
}

