#include <stdio.h>

// 统计数组中既不是最小值、也不是最大值的元素个数
int countMiddleElements(int* nums, int numsSize) {
    int minVal = nums[0];
    int maxVal = nums[0];
    int i;

    // 第一步：找出数组中的最小值和最大值
    for (i = 1; i < numsSize; i++) {
        if (nums[i] < minVal) {
            minVal = nums[i];
        }
        if (nums[i] > maxVal) {
            maxVal = nums[i];
        }
    }

    // 第二步：统计严格大于最小值且严格小于最大值的元素个数
    int count = 0;
    for (i = 0; i < numsSize; i++) {
        if (nums[i] > minVal && nums[i] < maxVal) {
            count++;
        }
    }

    return count;
}

// 以下是简单测试代码
int main() {
    int nums1[] = {11, 7, 2, 15};
    int size1 = sizeof(nums1) / sizeof(nums1[0]);
    printf("%d\n", countMiddleElements(nums1, size1));  // 输出 2

    int nums2[] = {-3, 3, 3, 90};
    int size2 = sizeof(nums2) / sizeof(nums2[0]);
    printf("%d\n", countMiddleElements(nums2, size2));  // 输出 2

    return 0;
}

