#include <stdio.h>
#include <stdlib.h>

// qsort 比较函数：从小到大排序
int cmp(const void *a, const void *b) {
    long long x = *(const int *)a;
    long long y = *(const int *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int n;
    scanf("%d", &n);

    int *nums = (int *)malloc(sizeof(int) * n);
    if (nums == NULL) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    // 先排序，便于统计相同元素出现次数
    qsort(nums, n, sizeof(int), cmp);

    int ans = 0;
    int i = 0;

    while (i < n) {
        // 统计当前值 nums[i] 出现了多少次
        int currentValue = nums[i];
        int count1 = 0;
        while (i < n && nums[i] == currentValue) {
            count1++;
            i++;
        }

        // 看下一个不同的值是否恰好等于 currentValue + 1
        if (i < n && nums[i] == currentValue + 1) {
            int nextValue = nums[i];
            int count2 = 0;
            int j = i;
            while (j < n && nums[j] == nextValue) {
                count2++;
                j++;
            }

            // 两个值相差 1，可以组成合法子序列
            if (count1 + count2 > ans) {
                ans = count1 + count2;
            }
        }
    }

    printf("%d\n", ans);

    free(nums);
    return 0;
}

