#include <stdio.h>

/*
 * 函数功能：
 * 返回所有配送方案中最早的完成时刻。
 *
 * 参数说明：
 * plans      : 二维数组，每一行包含两个整数 [开始时刻, 耗时]
 * plansSize  : 方案数量
 *
 * 返回值：
 * 最早完成的时刻
 */
int earliestFinish(int plans[][2], int plansSize) {
    // 先用第一个方案的完成时刻初始化最小值
    int minTime = plans[0][0] + plans[0][1];

    // 遍历其余方案，更新最小完成时刻
    for (int i = 1; i < plansSize; i++) {
        int finishTime = plans[i][0] + plans[i][1];
        if (finishTime < minTime) {
            minTime = finishTime;
        }
    }

    return minTime;
}

/*
 * 下面是测试代码，可根据需要修改。
 */
int main() {
    int plans1[][2] = {{1, 6}, {2, 3}};
    int size1 = sizeof(plans1) / sizeof(plans1[0]);
    printf("%d\n", earliestFinish(plans1, size1));  // 输出 5

    int plans2[][2] = {{4, 2}, {8, 1}, {3, 5}};
    int size2 = sizeof(plans2) / sizeof(plans2[0]);
    printf("%d\n", earliestFinish(plans2, size2));  // 输出 6

    return 0;
}

