#include <stdio.h>

/*
 * 函数功能：
 * 统计数组中满足 0 <= i < j < numsSize 且 nums[i] != nums[j] 的二元组数量
 *
 * 参数说明：
 * nums     - 输入数组
 * numsSize - 数组长度
 *
 * 返回值：
 * 满足条件的二元组总数
 */
int countUnequalPairs(int* nums, int numsSize) {
    int count = 0;

    // 枚举所有 i < j 的二元组
    for (int i = 0; i < numsSize; i++) {
        for (int j = i + 1; j < numsSize; j++) {
            // 如果两个位置上的值不同，则计数加 1
            if (nums[i] != nums[j]) {
                count++;
            }
        }
    }

    return count;
}

/*
 * 以下 main 函数仅用于本地测试，提交到题目平台时
 * 如果平台已经提供主函数，可删除 main。
 */
int main() {
    int nums1[] = {4, 4, 2, 4, 3};
    int size1 = sizeof(nums1) / sizeof(nums1[0]);
    printf("%d\n", countUnequalPairs(nums1, size1));  // 输出 7

    int nums2[] = {1, 1, 1, 1};
    int size2 = sizeof(nums2) / sizeof(nums2[0]);
    printf("%d\n", countUnequalPairs(nums2, size2));  // 输出 0

    return 0;
}

