#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int nums[105];
    int maxVal = 0;
    int sum = 0;

    // 读入数组，同时求最大值和数组元素之和
    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
        if (nums[i] > maxVal) {
            maxVal = nums[i];
        }
        sum += nums[i];
    }

    // 所有元素补到最大值 maxVal
    // 最少操作次数 = maxVal * n - sum
    int moves = maxVal * n - sum;

    printf("%d\n", moves);

    return 0;
}

