#include <stdio.h>
#include <stdlib.h>

/*
 * 函数功能：找出数组中重复出现的数字和缺失的数字
 * 返回值：长度为 2 的动态数组
 *   ans[0] = 重复的数字
 *   ans[1] = 缺失的数字
 * 注意：返回的数组需要由调用者 free
 */
int* findErrorNums(int* nums, int numsSize, int* returnSize) {
    // 结果数组长度固定为 2
    *returnSize = 2;
    int* ans = (int*)malloc(sizeof(int) * 2);

    // 计数数组，count[i] 表示数字 i 出现的次数
    int* count = (int*)calloc(numsSize + 1, sizeof(int));

    // 统计每个数字出现的次数
    for (int i = 0; i < numsSize; i++) {
        count[nums[i]]++;
    }

    // 查找重复值和缺失值
    for (int i = 1; i <= numsSize; i++) {
        if (count[i] == 2) {
            ans[0] = i;  // 重复的数字
        } else if (count[i] == 0) {
            ans[1] = i;  // 缺失的数字
        }
    }

    free(count);
    return ans;
}

/*
 * 下面是一个简单的测试主函数。
 * 在在线评测系统中通常不需要提交 main 函数，
 * 只提交 findErrorNums 函数即可。
 */
int main() {
    int nums[] = {1, 2, 2, 4};
    int numsSize = sizeof(nums) / sizeof(nums[0]);
    int returnSize;

    int* ans = findErrorNums(nums, numsSize, &returnSize);

    printf("[%d,%d]\n", ans[0], ans[1]);

