#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int nums[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    // 先找到数组中的最小值和最大值
    int minVal = nums[0];
    int maxVal = nums[0];
    for (int i = 1; i < n; i++) {
        if (nums[i] < minVal) {
            minVal = nums[i];
        }
        if (nums[i] > maxVal) {
            maxVal = nums[i];
        }
    }

    // 统计严格大于最小值且严格小于最大值的元素个数
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (nums[i] > minVal && nums[i] < maxVal) {
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}

