#include <stdbool.h>

/*
 * 判断最后一个字符是否为单格指令
 *
 * 思路：
 * 从左到右扫描数组：
 * 1. 如果当前位置是 0，说明它是单格指令，指针前进 1 步。
 * 2. 如果当前位置是 1，说明它必须和下一位组成双格指令，指针前进 2 步。
 *
 * 如果最终指针正好停在最后一个位置，说明最后一个 0 是单独解析的单格指令。
 * 如果最终越过了最后一个位置，说明最后一个 0 被前面的 1 带走，属于双格指令。
 */
bool isLastSingle(int* codes, int codesSize) {
    int i = 0;

    /*
     * 只需要处理到倒数第二个位置之前。
     * 因为我们关心的是最后一个位置是否被单独留下。
     */
    while (i < codesSize - 1) {
        if (codes[i] == 0) {
            // 单格指令，占 1 位
            i += 1;
        } else {
            // 双格指令，占 2 位
            i += 2;
        }
    }

    // 如果最后停在最后一个位置，说明它是单格指令
    return i == codesSize - 1;
}

