#include <stdio.h>
#include <stdlib.h>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    // 动态申请数组空间
    int *a = (int *)malloc(sizeof(int) * n);
    int *b = (int *)malloc(sizeof(int) * m);

    // 读入数组 a
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // 读入数组 b
    for (int i = 0; i < m; i++) {
        scanf("%d", &b[i]);
    }

    // 双指针分别指向两个数组的开头
    int i = 0, j = 0;

    while (i < n && j < m) {
        // 如果找到相同元素，因为数组有序，当前相同元素一定是最小的相同元素
        if (a[i] == b[j]) {
            printf("%d\n", a[i]);
            free(a);
            free(b);
            return 0;
        }
        // 较小的那个指针向后移动
        else if (a[i] < b[j]) {
            i++;
        } else {
            j++;
        }
    }

    // 如果遍历结束仍未找到相同元素
    printf("-1\n");

    free(a);
    free(b);
    return 0;
}

