#include <stdio.h>

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    int query[1000], arr[1000];

    // 读入 query 数组
    for (int i = 0; i < m; i++) {
        scanf("%d", &query[i]);
    }

    // 读入 arr 数组
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // 对 query 中的每个元素分别处理
    for (int i = 0; i < m; i++) {
        int x = query[i];
        int pos = -1;      // x 在 arr 中的位置
        int answer = -1;   // 默认找不到更大的数时输出 -1

        // 先找到 x 在 arr 中的位置
        for (int j = 0; j < n; j++) {
            if (arr[j] == x) {
                pos = j;
                break;
            }
        }

        // 从 pos 的右边开始，寻找第一个比 x 大的数
        for (int j = pos + 1; j < n; j++) {
            if (arr[j] > x) {
                answer = arr[j];
                break;
            }
        }

        // 按要求输出，数字之间用空格分隔
        if (i > 0) {
            printf(" ");
        }
        printf("%d", answer);
    }

    printf("\n");
    return 0;
}

