#include <stdio.h>

// 计算一个正整数的十进制位数
int countDigits(int num) {
    int digits = 0;
    while (num > 0) {
        digits++;
        num /= 10;
    }
    return digits;
}

int main() {
    int n;
    scanf("%d", &n);

    int count = 0;  // 记录位数为奇数的元素个数

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        int digits = countDigits(x);

        // 如果位数是奇数，则计数加一
        if (digits % 2 == 1) {
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}

