#include <stdio.h>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int x;
    int minVal, maxVal;

    // 读入第一个元素，初始化最小值和最大值
    scanf("%d", &x);
    minVal = maxVal = x;

    // 继续读入其余元素，并更新最小值和最大值
    for (int i = 1; i < n; i++) {
        scanf("%d", &x);
        if (x < minVal) minVal = x;
        if (x > maxVal) maxVal = x;
    }

    // 原始波动值
    int diff = maxVal - minVal;

    // 每个数最多调整 k，因此最大值和最小值之间最多可缩小 2k
    int ans = diff - 2 * k;
    if (ans < 0) ans = 0;

    printf("%d\n", ans);

    return 0;
}

