#include <stdio.h>

#define MAXN 105

int main() {
    int n, m;
    int indoorStart[MAXN], indoorTime[MAXN];
    int outdoorStart[MAXN], outdoorTime[MAXN];

    // 读入室内训练数量
    scanf("%d", &n);

    // 读入室内训练最早开始时间
    for (int i = 0; i < n; i++) {
        scanf("%d", &indoorStart[i]);
    }

    // 读入室内训练持续时间
    for (int i = 0; i < n; i++) {
        scanf("%d", &indoorTime[i]);
    }

    // 读入室外训练数量
    scanf("%d", &m);

    // 读入室外训练最早开始时间
    for (int j = 0; j < m; j++) {
        scanf("%d", &outdoorStart[j]);
    }

    // 读入室外训练持续时间
    for (int j = 0; j < m; j++) {
        scanf("%d", &outdoorTime[j]);
    }

    // 用一个较大的初值保存答案
    int ans = 1e9;

    // 枚举每一个室内训练和室外训练的组合
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            // 情况1：先做室内训练，再做室外训练
            int finishIndoor = indoorStart[i] + indoorTime[i];
            int startOutdoor = finishIndoor > outdoorStart[j] ? finishIndoor : outdoorStart[j];
            int finishBoth1 = startOutdoor + outdoorTime[j];

            // 情况2：先做室外训练，再做室内训练
            int finishOutdoor = outdoorStart[j] + outdoorTime[j];
            int startIndoor = finishOutdoor > indoorStart[i] ? finishOutdoor : indoorStart[i];
            int finishBoth2 = startIndoor + indoorTime[i];

            // 更新最小答案
            if (finishBoth1 < ans) ans = finishBoth1;
            if (finishBoth2 < ans) ans = finishBoth2;
        }
    }

    // 输出最早完成时间
    printf("%d\n", ans);

    return 0;
}

