#include <stdio.h>

// 交换两个整数的值
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int w[1005];
    for (int i = 0; i < n; i++) {
        scanf("%d", &w[i]);
    }

    // 冒泡排序：将果子重量从小到大排序
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (w[j] > w[j + 1]) {
                swap(&w[j], &w[j + 1]);
            }
        }
    }

    int sum = 0;      // 当前已装入果子的总重量
    int count = 0;    // 已装入果子的数量

    // 从最轻的果子开始尝试装入
    for (int i = 0; i < n; i++) {
        if (sum + w[i] <= m) {
            sum += w[i];
            count++;
        } else {
            // 如果当前果子装不下，后面的更重，也一定装不下
            break;
        }
    }

    printf("%d\n", count);

    return 0;
}

