#include <stdio.h>
#include <string.h>

#define MAXN 105
#define MAXL 25

int main() {
    int n;
    char phone[MAXN][MAXL];

    // 读入号码个数
    scanf("%d", &n);

    // 读入所有号码
    for (int i = 0; i < n; i++) {
        scanf("%s", phone[i]);
    }

    // 枚举每一对号码，检查是否存在前缀关系
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int len1 = strlen(phone[i]);
            int len2 = strlen(phone[j]);

            // 判断 phone[i] 是否为 phone[j] 的前缀
            if (len1 < len2 && strncmp(phone[i], phone[j], len1) == 0) {
                printf("BAD\n");
                return 0;
            }

            // 判断 phone[j] 是否为 phone[i] 的前缀
            if (len2 < len1 && strncmp(phone[j], phone[i], len2) == 0) {
                printf("BAD\n");
                return 0;
            }
        }
    }

    // 没有找到任何前缀关系
    printf("SAFE\n");
    return 0;
}

