#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
 * 函数功能：
 * 在环形数组 nums 中，从 startIndex 出发，找到到 target 的最短步数。
 * 如果 target 不存在，返回 -1。
 */
int nearestTargetDistance(int* nums, int numsSize, int target, int startIndex) {
    int ans = INT_MAX;
    int found = 0;

    for (int i = 0; i < numsSize; i++) {
        if (nums[i] == target) {
            found = 1;

            // 线性距离
            int diff = abs(i - startIndex);

            // 环形数组中的最短距离：顺着走 or 反着绕一圈走
            int dist = diff < (numsSize - diff) ? diff : (numsSize - diff);

            if (dist < ans) {
                ans = dist;
            }
        }
    }

    return found ? ans : -1;
}

/*
// 如需本地测试，可使用下面的 main 函数：
int main() {
    int nums1[] = {4, 7, 2, 9, 4};
    printf("%d\n", nearestTargetDistance(nums1, 5, 4, 2)); // 2

    int nums2[] = {5, 1, 8};
    printf("%d\n", nearestTargetDistance(nums2, 3, 8, 0)); // 1

    int nums3[] = {3, 6, 1, 2};
    printf("%d\n", nearestTargetDistance(nums3, 4, 7, 1)); // -1

    return 0;
}
