#include <stdio.h>
#include <stdlib.h>

/*
 * 函数功能：找出数组中重复出现的两个编号
 * 参数说明：
 *   nums       - 输入数组
 *   numsSize   - 数组长度，满足 numsSize = n + 2
 *   returnSize - 返回结果数组长度，设为 2
 * 返回值：
 *   动态分配的整型数组，长度为 2，存放两个重复元素
 */
int* findTwoRepeated(int* nums, int numsSize, int* returnSize) {
    // 由题意可知：numsSize = n + 2，所以 n = numsSize - 2
    int n = numsSize - 2;

    // 申请计数数组，记录每个编号出现的次数
    int* count = (int*)calloc(n, sizeof(int));

    // 申请结果数组
    int* result = (int*)malloc(2 * sizeof(int));
    int idx = 0;

    // 遍历 nums，统计出现次数
    for (int i = 0; i < numsSize; i++) {
        count[nums[i]]++;

        // 当某个数第 2 次出现时，说明它是重复编号
        if (count[nums[i]] == 2) {
            result[idx++] = nums[i];
        }
    }

    *returnSize = 2;

    // 释放辅助空间
    free(count);

    return result;
}

/*
 * 下面是简单的测试代码，提交到在线评测系统时通常不需要保留 main 函数。
 */
int main() {
    int nums[] = {0, 3, 2, 1, 3, 2};
    int numsSize = sizeof(nums) / sizeof(nums[0]);
    int returnSize;

    int* ans = findTwoRepeated(nums, numsSize, &returnSize);

    printf("[");
    for (int i = 0; i < returnSize; i++) {
        printf("%d", ans[i]);
        if (i < returnSize - 1) {
            printf(",");
        }
    }
    printf("]\n");

    free(ans);
    return 0;
}

