#include <stdio.h>
#include <stdlib.h>

/*
 * 对温度网格进行平滑处理
 * 返回一个新的二维数组，数组中的每个位置都是其周围 3x3 区域内
 * 所有有效位置元素的平均值（向下取整）
 */
int** smoothGrid(int** grid, int gridSize, int* gridColSize, int* returnSize, int** returnColumnSizes) {
    int m = gridSize;
    int n = gridColSize[0];

    // 设置返回数组的行数
    *returnSize = m;

    // 为每一行的列数分配空间
    *returnColumnSizes = (int*)malloc(sizeof(int) * m);
    for (int i = 0; i < m; i++) {
        (*returnColumnSizes)[i] = n;
    }

    // 为结果二维数组分配空间
    int** result = (int**)malloc(sizeof(int*) * m);
    for (int i = 0; i < m; i++) {
        result[i] = (int*)malloc(sizeof(int) * n);
    }

    // 枚举每个位置，计算其周围 3x3 区域的平均值
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int sum = 0;
            int count = 0;

            // 遍历当前位置周围的 3x3 区域
            for (int x = i - 1; x <= i + 1; x++) {
                for (int y = j - 1; y <= j + 1; y++) {
                    // 判断是否在网格范围内
                    if (x >= 0 && x < m && y >= 0 && y < n) {
                        sum += grid[x][y];
                        count++;
                    }
                }
            }

            // 向下取整平均值（整数除法本身就是向下取整）
            result[i][j] = sum / count;
        }
    }

    return result;
}

/*
 * 下面是一个简单的本地测试示例。
 * 提交到在线评测系统时，通常只需要保留上面的函数即可。
 */
int main() {
    int m = 3, n = 3;

    // 分配原始二维数组
    int** grid = (int**)malloc(sizeof(int*) * m);
    for (int i = 0; i < m; i++) {
        grid[i] = (int*)malloc(sizeof(int) * n);
    }

    // 示例数据
    int data[3][3] = {
        {100, 200, 100},
        {200, 50, 200},
        {100, 200, 100}
    };

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            grid[i][j] = data[i][j];
        }
    }

    int gridColSize[3] = {3, 3, 3};
    int returnSize;
    int* returnColumnSizes;

    int** ans = smoothGrid(grid, m, gridColSize, &returnSize, &returnColumnSizes);

    // 输出结果
    printf("平滑后的网格：\n");
    for (int i = 0; i < returnSize; i++) {
        for (int j = 0; j < returnColumnSizes[i]; j++) {
            printf("%d ", ans[i][j]);
        }
        printf("\n");
    }

    // 释放内存
    for (int i = 0; i < m; i++) {
        free(grid[i]);
    }
    free(grid);

    for (int i = 0; i < returnSize; i++) {
        free(ans[i]);
    }
    free(ans);
    free(returnColumnSizes);

    return 0;
}

