#include <stdio.h>

/*
 * 计算一个非负整数的各位数字之和
 */
int digitSum(int x) {
    int sum = 0;

    // 特殊处理 0，因为 0 的各位数字之和就是 0
    if (x == 0) {
        return 0;
    }

    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }

    return sum;
}

/*
 * 返回最小的下标 i，使得 nums[i] 的各位数字之和等于 i
 * 如果不存在这样的下标，返回 -1
 */
int firstMatchingIndex(int* nums, int numsSize) {
    for (int i = 0; i < numsSize; i++) {
        if (digitSum(nums[i]) == i) {
            return i;  // 找到第一个满足条件的位置，直接返回
        }
    }

    return -1;  // 没有找到
}

/*
 * 以下 main 函数仅用于本地测试，可根据实际评测平台要求保留或删除
 */
int main() {
    int nums1[] = {4, 7, 2};
    int nums2[] = {5, 10, 11, 30};
    int nums3[] = {8, 3, 5};

    printf("%d\n", firstMatchingIndex(nums1, 3)); // 2
    printf("%d\n", firstMatchingIndex(nums2, 4)); // 1
    printf("%d\n", firstMatchingIndex(nums3, 3)); // -1

    return 0;
}

