#include <stdio.h>
#include <stdbool.h>

/*
 * 判断数组 a 是否同时是数组 b 的前缀和后缀
 * a: 较短数组
 * lenA: a 的长度
 * b: 较长数组
 * lenB: b 的长度
 */
bool isHeadTail(int* a, int lenA, int* b, int lenB) {
    // 如果 a 比 b 长，直接不可能
    if (lenA > lenB) {
        return false;
    }

    // 检查是否为前缀
    for (int i = 0; i < lenA; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }

    // 检查是否为后缀
    for (int i = 0; i < lenA; i++) {
        if (a[i] != b[lenB - lenA + i]) {
            return false;
        }
    }

    return true;
}

/*
 * 统计满足 i < j 且 groups[i] 同时是 groups[j] 的前缀和后缀的下标对数量
 */
int countHeadTailPairs(int** groups, int groupsSize, int* groupsColSize) {
    int ans = 0;

    // 枚举所有下标对 (i, j)
    for (int i = 0; i < groupsSize; i++) {
        for (int j = i + 1; j < groupsSize; j++) {
            if (isHeadTail(groups[i], groupsColSize[i], groups[j], groupsColSize[j])) {
                ans++;
            }
        }
    }

    return ans;
}

/*
 * 以下是一个简单的测试样例，可根据需要修改
 */
