    int a0[] = {1};
    int a1[] = {1, 2, 1};
    int a2[] = {1, 2, 1, 1, 2, 1};
    int a3[] = {1, 1};

    int* groups[] = {a0, a1, a2, a3};
    int groupsColSize[] = {1, 3, 6, 2};
    int groupsSize = 4;

    int result = countHeadTailPairs(groups, groupsSize, groupsColSize);
    printf("%d\n", result);  // 预期输出 4

    return 0;
}

