#include <stdbool.h>

/*
 * 函数功能：
 * 判断数组中任意两个相邻的 1 之间是否至少间隔 gap 个位置。
 *
 * 参数：
 * arr      - 输入的二进制数组
 * arrSize  - 数组长度
 * gap      - 最小间隔要求
 *
 * 返回：
 * true  - 满足条件
 * false - 不满足条件
 */
bool checkGap(int* arr, int arrSize, int gap) {
    // last 用来记录上一个 1 出现的位置
    // 初始设为 -1，表示还没有遇到过 1
    int last = -1;

    for (int i = 0; i < arrSize; i++) {
        if (arr[i] == 1) {
            // 如果之前已经出现过 1，则检查当前 1 与上一个 1 的间隔
            if (last != -1) {
                // 两个 1 之间空位置的数量为 i - last - 1
                if (i - last - 1 < gap) {
                    return false;
                }
            }
            // 更新最近一次出现 1 的位置
            last = i;
        }
    }

    // 遍历结束都没有发现不合法情况，返回 true
    return true;
}

