#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int x;
    int negativeCount = 0;  // 统计负数个数

    for (int i = 0; i < n; i++) {
        scanf("%d", &x);

        // 只要出现 0，乘积一定为 0，可以直接输出并结束程序
        if (x == 0) {
            printf("0\n");
            return 0;
        }

        // 统计负数个数
        if (x < 0) {
            negativeCount++;
        }
    }

    // 若负数个数为偶数，乘积为正；否则为负
    if (negativeCount % 2 == 0) {
        printf("1\n");
    } else {
        printf("-1\n");
    }

    return 0;
}

