#include <stdio.h>

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    int bestRow = 0;     // 当前1最多的行下标
    int maxOnes = -1;    // 当前最多的1的个数，初始设为-1便于第一行更新

    // 逐行读取并统计
    for (int i = 0; i < m; i++) {
        int count = 0;   // 当前行中1的数量

        for (int j = 0; j < n; j++) {
            int x;
            scanf("%d", &x);
            if (x == 1) {
                count++;
            }
        }

        // 如果当前行的1更多，则更新答案
        // 若数量相同，不更新，这样自然保留下标更小的那一行
        if (count > maxOnes) {
            maxOnes = count;
            bestRow = i;
        }
    }

    // 输出结果：行下标 和 该行1的个数
    printf("%d %d\n", bestRow, maxOnes);

    return 0;
}

