#include <stdio.h>
#include <stdlib.h>

#define MAXN 105

// 返回整数的绝对值
int myAbs(int x) {
    return x < 0 ? -x : x;
}

int main() {
    int n;
    int points[MAXN][2];

    // 读入点的数量
    scanf("%d", &n);

    // 读入所有坐标点
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &points[i][0], &points[i][1]);
    }

    int totalTime = 0;

    // 依次计算相邻两个点之间的最少时间
    for (int i = 1; i < n; i++) {
        int dx = myAbs(points[i][0] - points[i - 1][0]);
        int dy = myAbs(points[i][1] - points[i - 1][1]);

        // 可以斜着走，所以最少时间是 dx 和 dy 中的较大值
        totalTime += (dx > dy) ? dx : dy;
    }

    // 输出总耗时
    printf("%d\n", totalTime);

    return 0;
}

