#include <stdbool.h>

/*
题意：
- 数组中每个数都是 1~99 的正整数
- 你只能选择“所有一位数”或“所有两位数”
- 如果你选择的那一组元素和 严格大于 其余元素和，则返回 true
- 否则返回 false

思路：
1. 统计整个数组的总和 total
2. 统计所有一位数的和 singleSum
3. 两位数的和 doubleSum = total - singleSum
4. 判断：
   - 选择一位数是否获胜：singleSum > total - singleSum
   - 选择两位数是否获胜：doubleSum > total - doubleSum
5. 任意一种成立就返回 true

时间复杂度：O(n)
空间复杂度：O(1)
*/
bool canWinByDigitGroup(int* nums, int numsSize) {
    int total = 0;      // 数组总和
    int singleSum = 0;  // 所有一位数的和

    for (int i = 0; i < numsSize; i++) {
        total += nums[i];

        // 一位数范围是 1~9
        if (nums[i] >= 1 && nums[i] <= 9) {
            singleSum += nums[i];
        }
    }

    // 两位数的和 = 总和 - 一位数的和
    int doubleSum = total - singleSum;

    // 判断选择一位数或两位数是否能赢
    if (singleSum > total - singleSum) {
        return true;
    }

    if (doubleSum > total - doubleSum) {
        return true;
    }

    return false;
}

