#include <stdio.h>
#include <stdlib.h>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int *nums = (int *)malloc(sizeof(int) * n);
    if (nums == NULL) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    // 使用 long long 保存区间和，防止数据范围较大时整型溢出
    long long windowSum = 0;

    // 先计算第一个长度为 k 的窗口和
    for (int i = 0; i < k; i++) {
        windowSum += nums[i];
    }

    long long maxSum = windowSum;

    // 滑动窗口：每次移除最左元素，加入新元素
    for (int i = k; i < n; i++) {
        windowSum += nums[i];       // 加入新进入窗口的元素
        windowSum -= nums[i - k];   // 移除离开窗口的元素

        if (windowSum > maxSum) {
            maxSum = windowSum;
        }
    }

    // 最大平均值 = 最大区间和 / k
    double answer = (double)maxSum / k;

    // 按题意输出，保留 5 位小数即可
    printf("%.5f\n", answer);

    free(nums);
    return 0;
}

