#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    scanf("%d", &n);

    // 动态申请数组空间
    int *record = (int *)malloc(sizeof(int) * n);
    if (record == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &record[i]);
    }

    int k;
    long long lower, upper;
    scanf("%d %lld %lld", &k, &lower, &upper);

    long long sum = 0;
    int score = 0;

    // 先计算第一个长度为 k 的窗口和
    for (int i = 0; i < k; i++) {
        sum += record[i];
    }

    // 判断第一个窗口的得分
    if (sum < lower) {
        score--;
    } else if (sum > upper) {
        score++;
    }

    // 使用滑动窗口依次处理后续区间
    for (int i = k; i < n; i++) {
        // 加入新元素，移除窗口最左侧元素
        sum += record[i];
        sum -= record[i - k];

        if (sum < lower) {
            score--;
        } else if (sum > upper) {
            score++;
        }
    }

    printf("%d\n", score);

    free(record);
    return 0;
}

