#include <stdbool.h>
#include <string.h>

/*
 * 函数功能：
 * 判断 target 是否可以由 parts 数组的前若干个字符串按顺序拼接得到。
 *
 * 思路：
 * 1. 用变量 pos 记录当前匹配到 target 的位置。
 * 2. 依次遍历 parts 中的每个字符串。
 * 3. 对当前字符串的每个字符进行比较：
 *    - 如果 target 已经结束，说明前面的拼接已经刚好构成 target，返回 true。
 *    - 如果字符不同，说明无法继续匹配，返回 false。
 *    - 如果字符相同，继续向后匹配。
 * 4. 遍历结束后，判断是否刚好匹配完整个 target。
 */
bool isPrefixConcatenation(char * target, char ** parts, int partsSize) {
    int pos = 0;                   // target 当前匹配位置
    int targetLen = strlen(target);

    for (int i = 0; i < partsSize; i++) {
        for (int j = 0; parts[i][j] != '\0'; j++) {
            // 如果 target 已经匹配完，说明前面的若干项已经构成 target
            if (pos == targetLen) {
                return true;
            }

            // 当前字符不一致，无法由前缀拼接得到
            if (target[pos] != parts[i][j]) {
                return false;
            }

            pos++;
        }

        // 每处理完一个字符串后，如果刚好匹配完整个 target，返回 true
        if (pos == targetLen) {
            return true;
        }
    }

    // 所有字符串都处理完后，只有完全匹配 target 才返回 true
    return pos == targetLen;
}

