#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 题意：
 * 从字符串数组中选出两个没有公共字母的字符串，
 * 使它们长度的乘积最大，返回这个最大值。
 *
 * 核心思路：位掩码（bitmask）
 * - 由于字符串只包含 26 个小写字母，
 *   可以用一个 32 位整数的低 26 位表示某个字符串中出现过哪些字母。
 * - 如果两个字符串的掩码 mask[i] 和 mask[j] 满足：
 *      (mask[i] & mask[j]) == 0
 *   就说明它们没有公共字母。
 * - 然后枚举所有字符串对，计算长度乘积的最大值即可。
 *
 * 时间复杂度：O(n^2 + 总字符数)
 * 空间复杂度：O(n)
 */
int maxCodeValue(char** codes, int codesSize) {
    int* masks = (int*)malloc(sizeof(int) * codesSize);
    int* lens  = (int*)malloc(sizeof(int) * codesSize);
    if (masks == NULL || lens == NULL) {
        free(masks);
        free(lens);
        return 0;
    }

    // 预处理每个字符串的长度和字母掩码
    for (int i = 0; i < codesSize; ++i) {
        int mask = 0;
        int len = (int)strlen(codes[i]);
        for (int j = 0; j < len; ++j) {
            int bit = codes[i][j] - 'a';
            mask |= (1 << bit);
        }
        masks[i] = mask;
        lens[i] = len;
    }

    int ans = 0;

    // 枚举所有字符串对
    for (int i = 0; i < codesSize; ++i) {
        for (int j = i + 1; j < codesSize; ++j) {
            // 没有公共字母
            if ((masks[i] & masks[j]) == 0) {
                int value = lens[i] * lens[j];
                if (value > ans) {
                    ans = value;
                }
            }
        }
    }

    free(masks);
    free(lens);
    return ans;
}

/*
 * 以下 main 函数仅用于本地测试，提交到题目平台时可按需删除。
 */
int main() {
    char* codes1[] = {"abcw", "baz", "foo", "bar", "xtfn", "abcdef"};
    printf("%d\n", maxCodeValue(codes1, 6)); // 16

    char* codes2[] = {"a", "ab", "abc", "d", "cd", "bcd", "abcd"};
    printf("%d\n", maxCodeValue(codes2, 7)); // 4

    char* codes3[] = {"a", "aa", "aaa", "aaaa"};
    printf("%d\n", maxCodeValue(codes3, 4)); // 0

    return 0;
}

