#include <stdio.h>
#include <stdlib.h>

// 计算当分组基数为 base 时，所有任务拆分后的总组数
// 使用 long long 防止累加过程中溢出
long long calcGroups(int loads[], int n, int base, int limit) {
    long long total = 0;
    for (int i = 0; i < n; i++) {
        // 向上取整：ceil(loads[i] / base) = (loads[i] + base - 1) / base
        total += (loads[i] + base - 1) / base;

        // 剪枝：一旦已经超过 limit，就没必要继续累加
        if (total > limit) {
            return total;
        }
    }
    return total;
}

int main() {
    int n, limit;
    scanf("%d %d", &n, &limit);

    int *loads = (int *)malloc(sizeof(int) * n);
    if (loads == NULL) {
        return 0;
    }

    int maxVal = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &loads[i]);
        if (loads[i] > maxVal) {
            maxVal = loads[i];
        }
    }

    // 二分查找最小可行 base
    // 最小一定是 1，最大不超过数组中的最大值
    int left = 1, right = maxVal;
    int answer = maxVal;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        long long groups = calcGroups(loads, n, mid, limit);

        // 如果总组数不超过 limit，说明当前 mid 可行
        // 尝试继续缩小 base，寻找更小的可行解
        if (groups <= limit) {
            answer = mid;
            right = mid - 1;
        } else {
            // 否则说明 base 太小，需要增大
            left = mid + 1;
        }
    }

    printf("%d\n", answer);

    free(loads);
    return 0;
}

