#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    // 动态分配数组，适应较大的 n
    long long *a = (long long *)malloc(sizeof(long long) * n);
    long long *leftMax = (long long *)malloc(sizeof(long long) * n);
    long long *rightMin = (long long *)malloc(sizeof(long long) * n);

    if (a == NULL || leftMax == NULL || rightMin == NULL) {
        // 内存分配失败，直接结束
        free(a);
        free(leftMax);
        free(rightMin);
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    // leftMax[i] 表示下标 i 左侧（不含 i）的最大值
    // 若 i 左侧没有元素，则设为负无穷
    leftMax[0] = LLONG_MIN;
    for (int i = 1; i < n; i++) {
        leftMax[i] = leftMax[i - 1] > a[i - 1] ? leftMax[i - 1] : a[i - 1];
    }

    // rightMin[i] 表示下标 i 右侧（不含 i）的最小值
    // 若 i 右侧没有元素，则设为正无穷
    rightMin[n - 1] = LLONG_MAX;
    for (int i = n - 2; i >= 0; i--) {
        rightMin[i] = rightMin[i + 1] < a[i + 1] ? rightMin[i + 1] : a[i + 1];
    }

    int count = 0;

    // 若 a[i] 严格大于左侧最大值，且严格小于右侧最小值
    // 则它是一个稳定定位点
    for (int i = 0; i < n; i++) {
        if (a[i] > leftMax[i] && a[i] < rightMin[i]) {
            count++;
        }
    }

    printf("%d\n", count);

    free(a);
    free(leftMax);
    free(rightMin);
    return 0;
}

