#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/*
题意：
给定 n 名学生的偏好 ranking，以及最终配对 partners。
如果学生 x 当前和 y 配对，但存在另一个学生 u，满足：
1. x 更喜欢 u 胜过 y
2. u 更喜欢 x 胜过自己的搭档 v
则 x 不满意。

思路：
1. 用 partner[x] 记录 x 当前的搭档是谁。
2. 用 order[x][u] 记录 u 在 x 的偏好列表中的排名，值越小表示越喜欢。
3. 对每个学生 x：
   - 找到其当前搭档 y
   - 在 ranking[x] 中，只需要检查排在 y 前面的那些学生 u
   - 若存在某个 u，使得 u 更喜欢 x 胜过其当前搭档，则 x 不满意
4. 统计不满意人数。

时间复杂度：O(n^2)
空间复杂度：O(n^2)
*/

int countUnsatisfiedStudents(int n, int** ranking, int rankingSize, int* rankingColSize,
                             int** partners, int partnersSize, int* partnersColSize) {
    int i, j;

    // partner[x] 表示学生 x 当前的搭档
    int* partner = (int*)malloc(sizeof(int) * n);
    if (partner == NULL) return 0;

    // order[x][u] 表示学生 u 在 x 的偏好排名（越小越优先）
    int** order = (int**)malloc(sizeof(int*) * n);
    if (order == NULL) {
        free(partner);
        return 0;
    }

    for (i = 0; i < n; i++) {
        order[i] = (int*)malloc(sizeof(int) * n);
        if (order[i] == NULL) {
            while (--i >= 0) free(order[i]);
            free(order);
            free(partner);
            return 0;
        }
    }

    // 建立搭档映射
    for (i = 0; i < partnersSize; i++) {
        int a = partners[i][0];
        int b = partners[i][1];
        partner[a] = b;
        partner[b] = a;
    }

    // 预处理排名表
    for (i = 0; i < n; i++) {
        for (j = 0; j < n - 1; j++) {
            int student = ranking[i][j];
            order[i][student] = j;
        }
    }

    int unhappyCount = 0;

    // 检查每个学生是否不满意
    for (int x = 0; x < n; x++) {
        int y = partner[x];

        // y 在 x 的偏好列表中的位置
        int yRank = order[x][y];
        bool unhappy = false;

        // 只需查看 x 比 y 更喜欢的那些学生 u
        for (j = 0; j < yRank; j++) {
            int u = ranking[x][j];
            int v = partner[u];

            // 如果 u 更喜欢 x 胜过当前搭档 v，则 x 不满意
            if (order[u][x] < order[u][v]) {
                unhappy = true;
                break;
            }
        }

        if (unhappy) {
            unhappyCount++;
        }
    }

    // 释放内存
    for (i = 0; i < n; i++) {
        free(order[i]);
    }
    free(order);
    free(partner);

    return unhappyCount;
}

/*
如果你想本地测试，可使用下面的 main 函数。
在线评测时通常只提交上面的函数即可。
*/
int main() {
    int n = 4;

    // ranking = [[1,2,3],[3,2,0],[3,1,0],[1,2,0]]
    int rankingData[4][3] = {
        {1, 2, 3},
        {3, 2, 0},
        {3, 1, 0},
        {1, 2, 0}
    };

    int* ranking[4];
    int rankingColSize[4] = {3, 3, 3, 3};
    for (int i = 0; i < 4; i++) {
        ranking[i] = rankingData[i];
    }

    // partners = [[0,1],[2,3]]
    int partnersData[2][2] = {
        {0, 1},
        {2, 3}
    };

    int* partners[2];
    int partnersColSize[2] = {2, 2};
    for (int i = 0; i < 2; i++) {
        partners[i] = partnersData[i];
    }

    int ans = countUnsatisfiedStudents(n,
                                       ranking, 4, rankingColSize,
                                       partners, 2, partnersColSize);

    printf("%d\n", ans);  // 预期输出 2
    return 0;
}

