#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 对于每个 devices[i]，统计有多少个 cells[j] 满足：
 * devices[i] * cells[j] >= target
 *
 * 做法：
 * 1. 先对 cells 排序。
 * 2. 对每个 devices[i]，二分查找第一个满足：
 *    devices[i] * cells[pos] >= target 的位置 pos。
 * 3. 则答案为 m - pos。
 *
 * 时间复杂度：O(m log m + n log m)
 * 空间复杂度：O(1)（不计输出数组）
 */

/* qsort 比较函数：升序 */
int cmpInt(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

/*
 * 在已排序数组 arr 中，寻找第一个满足：
 * base * arr[mid] >= target 的下标
 * 若不存在，返回 len
 */
int lowerBoundSuccess(int *arr, int len, int base, long long target) {
    int left = 0, right = len;

    while (left < right) {
        int mid = left + (right - left) / 2;
        long long product = 1LL * base * arr[mid];

        if (product >= target) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int *devices = (int *)malloc(sizeof(int) * n);
    int *cells = (int *)malloc(sizeof(int) * m);
    int *ans = (int *)malloc(sizeof(int) * n);
    long long target;

    for (int i = 0; i < n; i++) {
        scanf("%d", &devices[i]);
    }

    for (int i = 0; i < m; i++) {
        scanf("%d", &cells[i]);
    }

    scanf("%lld", &target);

    /* 对 cells 排序，便于二分查找 */
    qsort(cells, m, sizeof(int), cmpInt);

    /* 逐个设备计算答案 */
    for (int i = 0; i < n; i++) {
        int pos = lowerBoundSuccess(cells, m, devices[i], target);
        ans[i] = m - pos;
    }

    /* 输出结果 */
    for (int i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(devices);
    free(cells);
    free(ans);

    return 0;
}

