#include <stdio.h>

/*
题意简化：
每块正方形板材由 [y, len] 给出。
它在纵向覆盖区间 [y, y + len]，宽度恒为 len。

若切割线在高度 k：
- 该板材在线下的面积 = len * clamp(k - y, 0, len)
- 该板材总面积 = len * len

我们要求最小的 k，使得所有板材线下面积之和 == 总面积的一半。

由于“线下面积和”关于 k 单调不减，因此可以二分答案。
约束下总面积 <= 1e12，使用 long double 更稳妥。
*/

double balanceCutLine(int** panels, int panelsSize, int* panelsColSize) {
    long double totalArea = 0.0L;
    long double left = 1e18L;
    long double right = -1.0L;

    // 统计总面积，并确定二分范围 [最小底边, 最大顶边]
    for (int i = 0; i < panelsSize; ++i) {
        long double y = (long double)panels[i][0];
        long double len = (long double)panels[i][1];

        totalArea += len * len;
        if (y < left) left = y;
        if (y + len > right) right = y + len;
    }

    long double target = totalArea / 2.0L;

    // 二分查找最小 k，使得 below(k) >= target
    // 做足够多轮即可达到 1e-5 精度要求
    for (int step = 0; step < 100; ++step) {
        long double mid = (left + right) / 2.0L;
        long double below = 0.0L;

        for (int i = 0; i < panelsSize; ++i) {
            long double y = (long double)panels[i][0];
            long double len = (long double)panels[i][1];
            long double h = mid - y;  // 切割线高于底边的高度

            if (h <= 0.0L) {
                // 该板材完全在线上，贡献 0
                continue;
            } else if (h >= len) {
                // 该板材完全在线下，贡献整个面积
                below += len * len;
            } else {
                // 部分在线下，面积 = 宽 len * 高 h
                below += len * h;
            }
        }

        if (below >= target) {
            right = mid;
        } else {
            left = mid;
        }
    }

    return (double)right;
}

/*
如果你想本地测试，可使用下面的 main。
在线评测时通常只提交上面的函数即可。
*/
/*
int main() {
    int a0[] = {0, 1};
    int a1[] = {2, 1};
    int* panels1[] = {a0, a1};
    int cols1[] = {2, 2};
    printf("%.5f\n", balanceCutLine(panels1, 2, cols1)); // 1.00000

    int b0[] = {0, 2};
    int b1[] = {1, 1};
    int* panels2[] = {b0, b1};
    int cols2[] = {2, 2};
    printf("%.5f\n", balanceCutLine(panels2, 2, cols2)); // 1.16667

    return 0;
}
*/

