#include <stdlib.h>

/*
 * 比较函数：用于 qsort 从小到大排序
 */
static int cmpInt(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

/*
 * 题意分析：
 * 设最终选中了 k 个人。
 *
 * 若某人被选中，则必须满足 limit[i] < k。
 * 若某人未被选中，则必须满足 limit[i] > k。
 *
 * 这意味着：
 * 1. 所有 limit[i] < k 的人，必须全部被选中；
 * 2. 所有 limit[i] > k 的人，必须全部不选；
 * 3. 如果存在 limit[i] == k，则无论选还是不选都无法满意，因此这种 k 不可行。
 *
 * 因此，一个 k 合法，当且仅当：
 * - 恰好有 k 个数严格小于 k；
 * - 数组中不存在等于 k 的数。
 *
 * 排序后，我们检查每一个“分割点”：
 * - 选前 k 个（它们都必须 < k）
 * - 后面的都必须 > k
 *
 * 具体地：
 * - k = 0 时，需要最小值 > 0
 * - 1 <= k <= n-1 时，需要 a[k-1] < k < a[k]
 * - k = n 时，需要最大值 < n（由于 limit[i] < n 恒成立，因此总是可检查为真）
 *
 * 时间复杂度：O(n log n)
 * 空间复杂度：O(1)（不计排序栈空间）
 */
int countBalancedGroups(int* limit, int limitSize) {
    int n = limitSize;
    int ans = 0;

    qsort(limit, n, sizeof(int), cmpInt);

    /*
     * 情况 1：k = 0
     * 没有人被选中，则所有人都必须满足 0 < limit[i]
     * 排序后只需检查最小值是否 > 0
     */
    if (limit[0] > 0) {
        ans++;
    }

    /*
     * 情况 2：1 <= k <= n-1
     * 如果前 k 个数都 < k，且后面的数都 > k，
     * 排序后等价于：limit[k-1] < k < limit[k]
     */
    for (int k = 1; k < n; k++) {
        if (limit[k - 1] < k && k < limit[k]) {
            ans++;
        }
    }

    /*
     * 情况 3：k = n
     * 所有人都被选中，需要所有人满足 limit[i] < n
     * 题目保证 0 <= limit[i] < n，因此这一种总是成立。
     * 也可以写成 if (limit[n - 1] < n) ans++;
     */
    ans++;

    return ans;
}

