#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
解题思路：
1. 原图中每个 1x1 方格不好直接判断区域连通性，因为斜线会把一个格子切成两部分。
2. 可以把每个格子放大成 3x3 的小网格：
   - 若字符为 '/'，则将 (0,2), (1,1), (2,0) 标记为障碍
   - 若字符为 '\\'，则将 (0,0), (1,1), (2,2) 标记为障碍
   - 若字符为空格，则不标记
3. 这样原来的斜线就转化成了“墙”，然后统计放大后网格中 0 连通块的数量即可。
4. 使用 DFS 或 BFS 统计连通块数。

复杂度分析：
- 设原网格大小为 n x n
- 放大后网格大小为 (3n) x (3n)
- 时间复杂度：O((3n)^2) = O(n^2)
- 空间复杂度：O((3n)^2) = O(n^2)
*/

#define MAXN 100

static void dfs(int **grid, int size, int x, int y) {
    if (x < 0 || x >= size || y < 0 || y >= size || grid[x][y] != 0) {
        return;
    }

    // 标记为已访问
    grid[x][y] = 2;

    dfs(grid, size, x + 1, y);
    dfs(grid, size, x - 1, y);
    dfs(grid, size, x, y + 1);
    dfs(grid, size, x, y - 1);
}

int regionsByLines(char **board, int boardSize) {
    int size = boardSize * 3;
    int i, j;

    // 动态分配放大后的网格
    int **grid = (int **)malloc(sizeof(int *) * size);
    for (i = 0; i < size; i++) {
        grid[i] = (int *)calloc(size, sizeof(int));
    }

    // 将斜线映射到 3x3 网格中
    for (i = 0; i < boardSize; i++) {
        for (j = 0; j < boardSize; j++) {
            char c = board[i][j];
            int r = i * 3;
            int col = j * 3;

            if (c == '/') {
                grid[r][col + 2] = 1;
                grid[r + 1][col + 1] = 1;
                grid[r + 2][col] = 1;
            } else if (c == '\\') {
                grid[r][col] = 1;
                grid[r + 1][col + 1] = 1;
                grid[r + 2][col + 2] = 1;
            }
        }
    }

    // 统计连通块数量
    int regions = 0;
    for (i = 0; i < size; i++) {
        for (j = 0; j < size; j++) {
            if (grid[i][j] == 0) {
                regions++;
                dfs(grid, size, i, j);
            }
        }
    }

    // 释放内存
    for (i = 0; i < size; i++) {
        free(grid[i]);
    }
    free(grid);

    return regions;
}

