#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定一个 n x m 的 0/1 矩阵，求值为 1 的最长连续线段长度。
连续线段允许出现在 4 个方向：
1. 水平（左 -> 右）
2. 垂直（上 -> 下）
3. 主对角线（左上 -> 右下）
4. 副对角线（右上 -> 左下）

思路：动态规划
设：
- hori[i][j]  表示以 (i,j) 为结尾的水平方向连续 1 的长度
- vert[i][j]  表示以 (i,j) 为结尾的垂直方向连续 1 的长度
- diag[i][j]  表示以 (i,j) 为结尾的主对角线方向连续 1 的长度
- anti[i][j]  表示以 (i,j) 为结尾的副对角线方向连续 1 的长度

转移：
若 grid[i][j] == 1，则
hori[i][j] = (j > 0)     ? hori[i][j-1] + 1 : 1
vert[i][j] = (i > 0)     ? vert[i-1][j] + 1 : 1
diag[i][j] = (i > 0 && j > 0)         ? diag[i-1][j-1] + 1 : 1
anti[i][j] = (i > 0 && j + 1 < m)     ? anti[i-1][j+1] + 1 : 1

答案为所有状态中的最大值。

时间复杂度：O(n * m)
空间复杂度：O(n * m)

在 n,m <= 1000 时，4 个 int 型 DP 数组是可接受的。
*/

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    // 为了便于动态分配，使用一维数组模拟二维数组
    int *grid = (int *)malloc(sizeof(int) * n * m);
    int *hori = (int *)calloc(n * m, sizeof(int));
    int *vert = (int *)calloc(n * m, sizeof(int));
    int *diag = (int *)calloc(n * m, sizeof(int));
    int *anti = (int *)calloc(n * m, sizeof(int));

    if (grid == NULL || hori == NULL || vert == NULL || diag == NULL || anti == NULL) {
        // 内存分配失败，直接结束
        free(grid);
        free(hori);
        free(vert);
        free(diag);
        free(anti);
        return 0;
    }

    // 读入矩阵
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%d", &grid[i * m + j]);
        }
    }

    int ans = 0;

    // 动态规划计算
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int idx = i * m + j;

            if (grid[idx] == 1) {
                // 水平：来自左边
                hori[idx] = (j > 0) ? (hori[i * m + (j - 1)] + 1) : 1;

                // 垂直：来自上边
                vert[idx] = (i > 0) ? (vert[(i - 1) * m + j] + 1) : 1;

                // 主对角线：来自左上
                diag[idx] = (i > 0 && j > 0) ? (diag[(i - 1) * m + (j - 1)] + 1) : 1;

                // 副对角线：来自右上
                anti[idx] = (i > 0 && j + 1 < m) ? (anti[(i - 1) * m + (j + 1)] + 1) : 1;

                // 更新答案
                if (hori[idx] > ans) ans = hori[idx];
                if (vert[idx] > ans) ans = vert[idx];
                if (diag[idx] > ans) ans = diag[idx];
                if (anti[idx] > ans) ans = anti[idx];
            }
        }
    }

    printf("%d\n", ans);

    // 释放内存
    free(grid);
    free(hori);
    free(vert);
    free(diag);
    free(anti);

    return 0;
}

