#include <stdio.h>
#include <string.h>

#define MAXN 1005
#define NEG_INF -1000000000

int main() {
    int n, target;
    int nums[MAXN];

    scanf("%d %d", &n, &target);
    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    // dp[s] 表示：从前若干个元素中选取子序列，
    // 当和恰好为 s 时，所能得到的最长长度。
    // 不可达时记为一个极小值。
    int dp[1005];
    for (int i = 0; i <= target; i++) {
        dp[i] = NEG_INF;
    }

    // 和为 0 时，选空子序列，长度为 0
    dp[0] = 0;

    // 01 背包式转移：每个元素最多使用一次
    for (int i = 0; i < n; i++) {
        int x = nums[i];

        // 逆序枚举，防止同一个元素被重复使用
        for (int s = target; s >= x; s--) {
            if (dp[s - x] != NEG_INF) {
                if (dp[s] < dp[s - x] + 1) {
                    dp[s] = dp[s - x] + 1;
                }
            }
        }
    }

    if (dp[target] < 0) {
        printf("-1\n");
    } else {
        printf("%d\n", dp[target]);
    }

    return 0;
}

