#include <stdio.h>
#include <stdlib.h>

/*
题目核心：
如果选择起始编号 x，那么它能清理的编号必须形如 x + k * step (k >= 0)。
这意味着：
1. 能被同一次清理覆盖的编号，它们对 step 取模后的余数必须相同；
2. 在同一个余数组内，如果想清理到该组的所有元素，应选择该组中最小的编号作为起点。

因此问题转化为：
- 按 nums[i] % step 分组；
- 找到元素个数最多的组；
- 若有多个组个数相同，返回这些组中最小编号最小的那个。

实现方式：
由于 C 语言里手写哈希较繁琐，这里采用排序：
- 为每个元素记录 (remainder, value)
- 按 remainder 升序、value 升序排序
- 线性扫描每个余数组，统计数量，并记录该组最小值

时间复杂度：O(n log n)
空间复杂度：O(n)
*/

typedef struct {
    int rem;   // nums[i] % step
    int val;   // nums[i]
} Node;

/* 比较函数：先按 rem 升序，再按 val 升序 */
int cmp(const void *a, const void *b) {
    Node *x = (Node *)a;
    Node *y = (Node *)b;

    if (x->rem != y->rem) {
        return (x->rem < y->rem) ? -1 : 1;
    }
    if (x->val != y->val) {
        return (x->val < y->val) ? -1 : 1;
    }
    return 0;
}

/*
函数说明：
nums     - 输入数组
numsSize - 数组长度
step     - 固定步长
返回值   - 最优起始编号
*/
int bestStartNumber(int* nums, int numsSize, int step) {
    Node *arr = (Node *)malloc(sizeof(Node) * numsSize);
    if (arr == NULL) {
        return -1; // 简单防御，正常题目环境下一般不会发生
    }

    // 构造 (余数, 原值) 对
    for (int i = 0; i < numsSize; i++) {
        arr[i].rem = nums[i] % step;
        arr[i].val = nums[i];
    }

    // 排序后，相同余数的元素会连续出现
    qsort(arr, numsSize, sizeof(Node), cmp);

    int bestCount = 0;   // 当前最大组大小
    int answer = 0;      // 对应最小起始编号

    int i = 0;
    while (i < numsSize) {
        int j = i;
        int currentRem = arr[i].rem;

        // 由于同余数组内又按 value 升序排，因此第一个就是该组最小值
        int groupMin = arr[i].val;

        // 统计当前余数组大小
        while (j < numsSize && arr[j].rem == currentRem) {
            j++;
        }

        int groupCount = j - i;

        // 更新答案：优先更大的组，若数量相同取更小的起始编号
        if (groupCount > bestCount) {
            bestCount = groupCount;
            answer = groupMin;
        } else if (groupCount == bestCount && groupMin < answer) {
            answer = groupMin;
        }

        i = j;
    }

    free(arr);
    return answer;
}

/* =========================
   以下为示例测试代码
   提交到 OJ 时可按需删除 main
   ========================= */
int main() {
    int nums1[] = {3, 7, 8, 1, 1, 5};
    int step1 = 2;
    printf("%d\n", bestStartNumber(nums1, 6, step1)); // 1

    int nums2[] = {1, 3, 5, 2, 4, 6};
    int step2 = 2;
    printf("%d\n", bestStartNumber(nums2, 6, step2)); // 1

    int nums3[] = {6, 2, 5};
    int step3 = 100;
    printf("%d\n", bestStartNumber(nums3, 3, step3)); // 2

    return 0;
}

