#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定若干数据块的处理时间 nums[i]，每个批次总时间不能超过 limit。
每个数据块必须完整放入某个批次，且可以任意调整处理顺序。
求完成所有数据块所需的最少批次数。

思路：状态压缩 DP
--------------------------------------------------
因为 n <= 14，所以可以用一个二进制 mask 表示哪些数据块已经处理完。

定义：
  dp[mask] 表示处理完 mask 对应的数据块后，当前状态下：
    1) 使用的批次数最少；
    2) 在批次数最少的前提下，当前最后一个批次已经使用的时间尽量小。

为了同时保存这两个信息，这里定义结构体：
  sessions: 已使用的批次数
  used: 当前最后一个批次已经占用的时间

初始状态：
  dp[0] = {1, 0}
表示虽然还没有处理任何数据块，但我们“准备”使用第 1 个批次，已用时间为 0。
最终答案就是 dp[(1<<n)-1].sessions。

状态转移：
从 mask 转移到 mask | (1<<i)，表示加入第 i 个数据块。
- 如果当前最后一个批次还能放下 nums[i]，那么：
    sessions 不变，used += nums[i]
- 否则需要新开一个批次：
    sessions + 1，used = nums[i]

比较两个候选状态的优劣：
- 批次数少的更优
- 若批次数相同，则最后一个批次已用时间更小的更优

时间复杂度：O(n * 2^n)
空间复杂度：O(2^n)
*/

typedef struct {
    int sessions; // 已使用的批次数
    int used;     // 当前最后一个批次已使用的时间
} State;

// 判断状态 a 是否优于状态 b
int better(State a, State b) {
    if (a.sessions != b.sessions) {
        return a.sessions < b.sessions;
    }
    return a.used < b.used;
}

int minBatches(int* nums, int n, int limit) {
    int totalStates = 1 << n;
    State* dp = (State*)malloc(sizeof(State) * totalStates);
    if (dp == NULL) {
        return -1;
    }

    // 初始化为“很差”的状态
    for (int i = 0; i < totalStates; i++) {
        dp[i].sessions = 1000000;
        dp[i].used = 1000000;
    }

    // 初始状态：还没选任何数据块，当前准备使用第一个批次
    dp[0].sessions = 1;
    dp[0].used = 0;

    for (int mask = 0; mask < totalStates; mask++) {
        // 如果当前状态不可达，跳过
        if (dp[mask].sessions == 1000000) {
            continue;
        }

        // 尝试加入一个尚未处理的数据块 i
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                int nextMask = mask | (1 << i);
                State candidate;

                // 当前批次还能放下 nums[i]
                if (dp[mask].used + nums[i] <= limit) {
                    candidate.sessions = dp[mask].sessions;
                    candidate.used = dp[mask].used + nums[i];
                } else {
                    // 需要新开一个批次
                    candidate.sessions = dp[mask].sessions + 1;
                    candidate.used = nums[i];
                }

                if (better(candidate, dp[nextMask])) {
                    dp[nextMask] = candidate;
                }
            }
        }
    }

    int answer = dp[totalStates - 1].sessions;
    free(dp);
    return answer;
}

int main() {
    int n;
    scanf("%d", &n);

    int* nums = (int*)malloc(sizeof(int) * n);
    if (nums == NULL) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    int limit;
    scanf("%d", &limit);

    int result = minBatches(nums, n, limit);
    printf("%d\n", result);

    free(nums);
    return 0;
}

