#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 给定加分事件数组、扣分事件数组，以及每位选手的事件记录。
 * - 加分事件 +3
 * - 扣分事件 -1
 * - 其他事件 0
 * 最后按：
 * 1. 积分降序
 * 2. 编号升序
 * 返回前 k 名选手编号。
 *
 * 解法：
 * 1. 先对 bonus_event 和 penalty_event 排序。
 * 2. 对每位选手的每个事件，使用二分查找判断其类型，累加得分。
 * 3. 将每位选手的 (id, score) 存入结构体数组。
 * 4. 对结构体数组排序：分数高的在前；若分数相同，id 小的在前。
 * 5. 取前 k 个 id 返回。
 */

typedef struct {
    int id;
    int score;
} Player;

/* 比较两个 int，用于 qsort 升序排序 */
int cmpInt(const void* a, const void* b) {
    long long x = *(const int*)a;
    long long y = *(const int*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/* 比较两个 Player：先按 score 降序，再按 id 升序 */
int cmpPlayer(const void* a, const void* b) {
    Player* p1 = (Player*)a;
    Player* p2 = (Player*)b;

    if (p1->score != p2->score) {
        return p2->score - p1->score;  // 分数高的在前
    }
    if (p1->id < p2->id) return -1;   // id 小的在前
    if (p1->id > p2->id) return 1;
    return 0;
}

/* 二分查找：判断 target 是否存在于已排序数组 arr 中 */
int existsInSorted(int* arr, int size, int target) {
    int left = 0, right = size - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            return 1;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return 0;
}

int* topKPlayers(
    int* bonus_event, int bonusSize,
    int* penalty_event, int penaltySize,
    int** events, int eventsSize, int* eventColSize,
    int* player_id, int playerIdSize,
    int k, int* returnSize
) {
    int i, j;

    /* 按题意，eventsSize 与 playerIdSize 相等 */
    (void)playerIdSize;

    /* 先排序加分事件和扣分事件，便于后续二分查找 */
    qsort(bonus_event, bonusSize, sizeof(int), cmpInt);
    qsort(penalty_event, penaltySize, sizeof(int), cmpInt);

    /* 保存每位选手的编号和积分 */
    Player* players = (Player*)malloc(sizeof(Player) * eventsSize);
    if (players == NULL) {
        *returnSize = 0;
        return NULL;
    }

    /* 统计每位选手得分 */
    for (i = 0; i < eventsSize; i++) {
        int score = 0;
        for (j = 0; j < eventColSize[i]; j++) {
            int code = events[i][j];
            if (existsInSorted(bonus_event, bonusSize, code)) {
                score += 3;
            } else if (existsInSorted(penalty_event, penaltySize, code)) {
                score -= 1;
            }
        }
        players[i].id = player_id[i];
        players[i].score = score;
    }

    /* 按规则排序 */
    qsort(players, eventsSize, sizeof(Player), cmpPlayer);

    /* 构造返回结果 */
    int* ans = (int*)malloc(sizeof(int) * k);
    if (ans == NULL) {
        free(players);
        *returnSize = 0;
        return NULL;
    }

    for (i = 0; i < k; i++) {
        ans[i] = players[i].id;
    }

    free(players);
    *returnSize = k;
    return ans;
}

