#include <stdio.h>
#include <stdlib.h>

/*
思路说明：
1. 原矩阵顺时针旋转 90 度后，原来每一行中的“向右移动”效果，
   等价于旋转后的“向下掉落”效果。
2. 因此可以先对原矩阵的每一行进行处理：
   - 把每个被 '*' 分隔开的区间内的 '#' 尽量移动到最右边。
3. 然后再将处理后的矩阵顺时针旋转 90 度，得到最终答案。

时间复杂度：O(m * n)
空间复杂度：O(m * n)
*/

char*** transformRack(char** rack, int rackSize, int* rackColSize, int* returnSize, int** returnColumnSizes) {
    int m = rackSize;
    int n = rackColSize[0];

    // 先原地处理每一行，让石头在隔板范围内尽量靠右
    for (int i = 0; i < m; i++) {
        int write = n - 1;  // 当前石头应该落到的位置

        for (int j = n - 1; j >= 0; j--) {
            if (rack[i][j] == '*') {
                // 遇到障碍，障碍左边的石头只能落在障碍左侧
                write = j - 1;
            } else if (rack[i][j] == '#') {
                // 把当前石头移动到 write 位置
                rack[i][j] = '.';
                rack[i][write] = '#';
                write--;
            }
            // 如果是 '.' 则跳过即可
        }
    }

    // 分配返回结果：旋转后大小为 n x m
    char*** result = (char***)malloc(sizeof(char**) * n);
    *returnSize = n;
    *returnColumnSizes = (int*)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        (*returnColumnSizes)[i] = m;
        result[i] = (char**)malloc(sizeof(char*) * m);
        for (int j = 0; j < m; j++) {
            result[i][j] = (char*)malloc(sizeof(char));
        }
    }

    // 顺时针旋转 90 度
    // 原坐标 (i, j) -> 新坐标 (j, m - 1 - i)
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            *(result[j][m - 1 - i]) = rack[i][j];
        }
    }

    return result;
}

