#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定长度为 n 的数组位置，从 0 出发到 n-1。
每次可以：
1. i -> i+1，成功率 step1[i]
2. i -> i+2，成功率 step2[i]
blocked[i] = 1 表示该位置不能落脚。
求到达终点的最大成功率（路径上各步概率乘积最大）。

思路：
设 dp[i] 表示到达位置 i 的最大成功率。
那么：
1. 如果 i-1 可达，并且 i 未被封锁，则
   dp[i] = max(dp[i], dp[i-1] * step1[i-1])
2. 如果 i-2 可达，并且 i 未被封锁，则
   dp[i] = max(dp[i], dp[i-2] * step2[i-2])

初始：dp[0] = 1.0（起点本身成功率视为 1）
若最终 dp[n-1] 仍为 0，则表示无法到达。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *blocked = (int *)malloc(sizeof(int) * n);
    double *step1 = (double *)malloc(sizeof(double) * n);
    double *step2 = (double *)malloc(sizeof(double) * n);
    double *dp = (double *)malloc(sizeof(double) * n);

    if (!blocked || !step1 || !step2 || !dp) {
        free(blocked);
        free(step1);
        free(step2);
        free(dp);
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &blocked[i]);
    }

    for (int i = 0; i < n; i++) {
        scanf("%lf", &step1[i]);
    }

    for (int i = 0; i < n; i++) {
        scanf("%lf", &step2[i]);
    }

    // 初始化 dp 数组
    for (int i = 0; i < n; i++) {
        dp[i] = 0.0;
    }

    // 起点可达，成功率为 1
    dp[0] = 1.0;

    for (int i = 1; i < n; i++) {
        // 如果当前位置被封锁，则无法停留
        if (blocked[i] == 1) {
            dp[i] = 0.0;
            continue;
        }

        // 从 i-1 跳到 i
        if (i - 1 >= 0 && dp[i - 1] > 0.0) {
            double candidate = dp[i - 1] * step1[i - 1];
            if (candidate > dp[i]) {
                dp[i] = candidate;
            }
        }

        // 从 i-2 跳到 i
        if (i - 2 >= 0 && dp[i - 2] > 0.0) {
            double candidate = dp[i - 2] * step2[i - 2];
            if (candidate > dp[i]) {
                dp[i] = candidate;
            }
        }
    }

    printf("%.6f\n", dp[n - 1]);

    free(blocked);
    free(step1);
    free(step2);
    free(dp);

    return 0;
}

