#include <stdlib.h>

/*
核心结论：
1. 每一轮都会删除“当前还存在的每个数字”的一个最靠前的出现位置。
2. 如果某个数字 x 一共出现 freq[x] 次，那么它会在第 freq[x] 轮被彻底删光。
3. 因此，最后一轮之前还存在的数字，必须满足：它的总出现次数等于全局最大频次 maxFreq。
4. 对于这些数字，最后一轮之前只会各剩下 1 个，且这个剩下的元素正是它们的“最后一次出现”。
5. 所以答案就是：
   - 找出所有出现次数等于 maxFreq 的数字；
   - 按原数组顺序，取这些数字的最后一次出现，组成结果。

时间复杂度：O(n + m)
空间复杂度：O(m)
*/

int* lastArrayBeforeEmpty(int* nums, int numsSize, int m, int* returnSize) {
    // 统计每个数字的出现次数
    int* freq = (int*)calloc(m + 1, sizeof(int));
    int i;
    int maxFreq = 0;

    for (i = 0; i < numsSize; ++i) {
        freq[nums[i]]++;
        if (freq[nums[i]] > maxFreq) {
            maxFreq = freq[nums[i]];
        }
    }

    /*
    remain[x] 表示在从左到右扫描时，当前位置及其后面还剩多少个 x。
    当某个位置 i 满足：
    - nums[i] 的总频次等于 maxFreq
    - 并且它是该数字的最后一次出现（即 remain[nums[i]] 变成 0）
    那么 nums[i] 就应当出现在答案中。
    */
    int* remain = (int*)malloc((m + 1) * sizeof(int));
    for (i = 0; i <= m; ++i) {
        remain[i] = freq[i];
    }

    // 答案长度不会超过 m，也不会超过 numsSize，直接按 numsSize 分配最安全
    int* ans = (int*)malloc(numsSize * sizeof(int));
    int ansSize = 0;

    for (i = 0; i < numsSize; ++i) {
        int x = nums[i];
        remain[x]--;

        // 如果 x 的总出现次数是最大值，且当前位置是它最后一次出现，则加入答案
        if (freq[x] == maxFreq && remain[x] == 0) {
            ans[ansSize++] = x;
        }
    }

    free(freq);
    free(remain);

    *returnSize = ansSize;
    return ans;
}

