#include <stdio.h>
#include <string.h>

#define MAXM 55
#define MAXN 55
#define INF 0x3f3f3f3f
#define MAXQ (MAXM * MAXN * 2)

typedef struct {
    int x;
    int y;
} Node;

int grid[MAXM][MAXN];
int dist[MAXM][MAXN];
Node dequeArr[MAXQ];

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &grid[i][j]);
        }
    }

    // dist[i][j] 表示从起点走到 (i, j) 时，
    // 路径上经过的危险格子数量最小值（包含起点和终点本身）。
    memset(dist, 0x3f, sizeof(dist));

    // 0-1 BFS 双端队列初始化
    int head = MAXQ / 2;
    int tail = MAXQ / 2;

    dist[0][0] = grid[0][0];
    dequeArr[tail++] = (Node){0, 0};

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (head < tail) {
        Node cur = dequeArr[head++];
        int x = cur.x;
        int y = cur.y;

        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (nx < 0 || nx >= m || ny < 0 || ny >= n) {
                continue;
            }

            // 走到相邻格子的代价就是该格子是否危险：
            // 安全格代价 0，危险格代价 1
            int w = grid[nx][ny];
            if (dist[x][y] + w < dist[nx][ny]) {
                dist[nx][ny] = dist[x][y] + w;

                // 0-1 BFS：
                // 权值为 0 的边放队头，权值为 1 的边放队尾
                if (w == 0) {
                    dequeArr[--head] = (Node){nx, ny};
                } else {
                    dequeArr[tail++] = (Node){nx, ny};
                }
            }
        }
    }

    // 若最优路径经过 k 个危险格，则最少初始体力需要 k + 1，
    // 因为体力必须始终保持大于 0。
    int answer = dist[m - 1][n - 1] + 1;
    printf("%d\n", answer);

    return 0;
}

