#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定一棵由 parent 数组表示的树，以及若干被锁定的节点 locked。
从节点 0 出发，不能访问 locked 中的节点，也不能通过它们继续向下访问。
求最终能够访问到的节点数量。

思路：
1. 用 parent 数组构建“孩子列表”。
2. 用一个布尔数组 isLocked 标记哪些节点被锁定。
3. 从 0 开始做迭代 DFS（也可以 BFS），遇到锁定节点就跳过。
4. 统计访问到的节点个数。

由于 n 可达 1e5，不能使用递归 DFS，避免栈溢出。
时间复杂度：O(n)
空间复杂度：O(n)
*/

int reachableEmployees(int n, int* parent, int* locked, int lockedSize) {
    int i;

    /* 记录哪些员工被锁定 */
    char* isLocked = (char*)calloc(n, sizeof(char));
    for (i = 0; i < lockedSize; ++i) {
        isLocked[locked[i]] = 1;
    }

    /*
    统计每个节点有多少个孩子，便于构建紧凑的孩子数组
    childCount[x] = x 的孩子数量
    */
    int* childCount = (int*)calloc(n, sizeof(int));
    for (i = 1; i < n; ++i) {
        childCount[parent[i]]++;
    }

    /*
    start[x] 表示节点 x 的孩子在 children 数组中的起始位置
    采用前缀和方式存储所有孩子
    */
    int* start = (int*)malloc(sizeof(int) * (n + 1));
    start[0] = 0;
    for (i = 0; i < n; ++i) {
        start[i + 1] = start[i] + childCount[i];
    }

    /* children 数组中存放所有节点的孩子 */
    int* children = (int*)malloc(sizeof(int) * (n - 1));

    /*
    cur[x] 用于记录当前给节点 x 填充孩子的位置
    初始值就是 start[x]
    */
    int* cur = (int*)malloc(sizeof(int) * n);
    for (i = 0; i < n; ++i) {
        cur[i] = start[i];
    }

    for (i = 1; i < n; ++i) {
        int p = parent[i];
        children[cur[p]++] = i;
    }

    /* 迭代 DFS 栈 */
    int* stack = (int*)malloc(sizeof(int) * n);
    int top = 0;
    int ans = 0;

    /* 题目保证 0 不会被锁定 */
    stack[top++] = 0;

    while (top > 0) {
        int u = stack[--top];

        /* 如果该节点被锁定，则不能访问 */
        if (isLocked[u]) {
            continue;
        }

        ans++;

        /* 遍历 u 的所有孩子 */
        for (i = start[u]; i < start[u + 1]; ++i) {
            int v = children[i];
            if (!isLocked[v]) {
                stack[top++] = v;
            }
        }
    }

    free(isLocked);
    free(childCount);
    free(start);
    free(children);
    free(cur);
    free(stack);

    return ans;
}

/*
以下是一个简单测试示例。
在线评测时通常只提交 reachableEmployees 函数即可。
*/
int main() {
    {
        int n = 7;
        int parent[] = {-1, 0, 1, 1, 0, 0, 5};
        int locked[] = {4, 5};
        int result = reachableEmployees(n, parent, locked, 2);
        printf("%d\n", result);  // 输出 4
    }

    {
        int n = 7;
        int parent[] = {-1, 0, 0, 2, 0, 0, 5};
        int locked[] = {4, 2, 1};
        int result = reachableEmployees(n, parent, locked, 3);
        printf("%d\n", result);  // 输出 3
    }

    return 0;
}

