#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
题意：
给定数组 arr 和整数 gap，求满足 |i - j| >= gap 的一对元素，
使得 |arr[i] - arr[j]| 最小，输出这个最小值。

解法：二分答案 + 按值排序 + 滑动窗口 + 单调队列维护窗口中的最小/最大下标

核心思想：
1. 设答案为 D，判断是否存在一对元素：
   - 它们的值差 <= D
   - 且下标差 >= gap
2. 将元素按“值”排序后，若固定右端 right，所有满足：
      nodes[right].value - nodes[left].value <= D
   的元素构成一个窗口。
   在这个窗口中，如果存在两个原始下标之差至少为 gap，说明 D 可行。
3. 对于窗口内元素，只需要知道：
   - 最小原始下标
   - 最大原始下标
   因为最大下标 - 最小下标 >= gap 就说明存在合法二元组。
4. 窗口左右端移动时，使用两个单调队列分别维护窗口内原始下标的最小值和最大值。
5. 对 D 二分查找即可。

时间复杂度：
- 排序 O(n log n)
- 每次 check O(n)
- 二分约 O(log 1e9)
总复杂度 O(n log n + n log V)
*/

typedef long long ll;

typedef struct {
    int value;
    int index;
} Node;

int cmpNode(const void *a, const void *b) {
    Node *x = (Node *)a;
    Node *y = (Node *)b;
    if (x->value < y->value) return -1;
    if (x->value > y->value) return 1;
    return x->index - y->index;
}

/*
检查是否存在一对元素：
- 值差 <= limit
- 下标差 >= gap
*/
int check(Node *nodes, int n, int gap, int limit) {
    /*
    minDeque: 维护窗口内 index 的递增队列，队首为最小下标
    maxDeque: 维护窗口内 index 的递减队列，队首为最大下标

    队列中存的是排序后数组中的位置 pos，而不是原始下标本身。
    这样方便在 left 右移时判断队首是否过期。
    */
    int *minDeque = (int *)malloc(sizeof(int) * n);
    int *maxDeque = (int *)malloc(sizeof(int) * n);
    int minHead = 0, minTail = 0;
    int maxHead = 0, maxTail = 0;

    int left = 0;

    for (int right = 0; right < n; right++) {
        /* 扩展窗口：加入 nodes[right] */
        while (minHead < minTail && nodes[minDeque[minTail - 1]].index >= nodes[right].index) {
            minTail--;
        }
        minDeque[minTail++] = right;

        while (maxHead < maxTail && nodes[maxDeque[maxTail - 1]].index <= nodes[right].index) {
            maxTail--;
        }
        maxDeque[maxTail++] = right;

        /* 收缩窗口，保证值差 <= limit */
        while (left <= right && nodes[right].value - nodes[left].value > limit) {
            if (minHead < minTail && minDeque[minHead] == left) minHead++;
            if (maxHead < maxTail && maxDeque[maxHead] == left) maxHead++;
            left++;
        }

        /* 当前窗口 [left, right] 中，若最大下标 - 最小下标 >= gap，则可行 */
        if (left <= right && minHead < minTail && maxHead < maxTail) {
            int minIndex = nodes[minDeque[minHead]].index;
            int maxIndex = nodes[maxDeque[maxHead]].index;
            if (maxIndex - minIndex >= gap) {
                free(minDeque);
                free(maxDeque);
                return 1;
            }
        }
    }

    free(minDeque);
    free(maxDeque);
    return 0;
}

int main() {
    int n, gap;
    scanf("%d %d", &n, &gap);

    int *arr = (int *)malloc(sizeof(int) * n);
    Node *nodes = (Node *)malloc(sizeof(Node) * n);

    int minVal = INT_MAX;
    int maxVal = INT_MIN;

    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
        nodes[i].value = arr[i];
        nodes[i].index = i;
        if (arr[i] < minVal) minVal = arr[i];
        if (arr[i] > maxVal) maxVal = arr[i];
    }

    /* 按值排序 */
    qsort(nodes, n, sizeof(Node), cmpNode);

    /*
    特判：gap == 0 时，同一个位置也满足 |i-j|>=0 吗？
    一般题意默认选两个下标，可相同与否往往不明确。
    参考原题语义为两个元素，通常取两个位置；
    但即使要求不同下标，只要 n>=1，二分逻辑也能正常工作。
    这里不额外特判，统一走通用逻辑。
    */

    int left = 0, right = maxVal - minVal;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (check(nodes, n, gap, mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    printf("%d\n", left);

    free(arr);
    free(nodes);
    return 0;
}

