#include <stdio.h>
#include <stdlib.h>

/*
    题意：
    对每个连续子数组，计算 max(值 * 该值在子数组中的出现次数)，
    求所有子数组该值的总和。

    思路：
    1. n <= 2000，可以使用 O(n^2) 枚举所有子数组。
    2. 固定左端点 l，从右端点 r = l 向右扩展：
       - 动态维护每个数在当前子数组中的出现次数。
       - 每加入一个元素，只需要更新这个元素对应的出现次数，
         并尝试刷新当前子数组的最大主导得分。
    3. 由于 a[i] 可达 1e9，不适合直接开频次数组，先做坐标压缩。

    时间复杂度：O(n^2)
    空间复杂度：O(n)
*/

#define MAXN 2005

typedef long long ll;

typedef struct {
    ll value;   // 原始值
    int index;  // 原位置
} Node;

// qsort 比较函数：按 value 升序排序
int cmp_node(const void *a, const void *b) {
    ll va = ((const Node *)a)->value;
    ll vb = ((const Node *)b)->value;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

int main() {
    int n;
    ll a[MAXN];

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
    }

    /*
        坐标压缩：
        id[i] 表示 a[i] 压缩后的编号（从 0 开始）
        realVal[id] 表示该编号对应的原始数值
    */
    Node arr[MAXN];
    for (int i = 1; i <= n; i++) {
        arr[i - 1].value = a[i];
        arr[i - 1].index = i;
    }

    qsort(arr, n, sizeof(Node), cmp_node);

    int id[MAXN];
    ll realVal[MAXN];
    int m = 0; // 不同数值的个数

    for (int i = 0; i < n; i++) {
        if (i == 0 || arr[i].value != arr[i - 1].value) {
            realVal[m] = arr[i].value;
            m++;
        }
        id[arr[i].index] = m - 1;
    }

    ll answer = 0;
    int freq[MAXN];

    // 枚举左端点
    for (int l = 1; l <= n; l++) {
        // 每次固定新的左端点，都要清空频次数组
        for (int i = 0; i < m; i++) {
            freq[i] = 0;
        }

        ll currentMax = 0;

        // 枚举右端点，不断扩展子数组 [l..r]
        for (int r = l; r <= n; r++) {
            int cid = id[r];
            freq[cid]++;

            // 新加入的这个值，其主导得分可能变成当前最大值
            ll candidate = realVal[cid] * (ll)freq[cid];
            if (candidate > currentMax) {
                currentMax = candidate;
            }

            // 当前子数组的片段主导值加入答案
            answer += currentMax;
        }
    }

    printf("%lld\n", answer);
    return 0;
}

