#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

/*
  题意：
  给定 boosters 数组，每个位置的增强器能覆盖 [i-r, i+r]。
  可以再增加 k 个增强器，问所有房间的最小信号强度最大能是多少。

  核心思路：
  1. 先计算每个位置当前的信号强度 power[i]。
     这个值等于 boosters 在区间 [i-r, i+r] 上的和。
     可通过前缀和 O(n) 得到。

  2. 二分答案 x：判断是否能让所有位置的最终信号强度都 >= x。

  3. 可行性检查（贪心 + 差分）：
     从左到右扫描每个房间 i。
     - 维护当前位置受到的“新增增强器”带来的累计贡献 addEffect。
     - 当前总强度 = power[i] + addEffect。
     - 若不足 x，需要补 need = x - 当前总强度。
     - 为了尽可能让这次新增影响更靠后的更多位置，贪心地把这 need 个增强器放在最右侧可放位置：pos = min(n-1, i+r)。
       这样它会覆盖从 max(0, pos-r) 到 min(n-1, pos+r)。
       对当前从左往右扫描来说，这样能让新增贡献尽量延续到后面。
     - 使用差分数组记录这些新增增强器在后续区间中的影响终止位置。

  复杂度：
  - 预处理 power：O(n)
  - 每次 check：O(n)
  - 二分次数：O(log Answer)
  总复杂度：O(n log Answer)
*/

// 计算较小值
static inline int min_int(int a, int b) {
    return a < b ? a : b;
}

// 计算较大值
static inline int max_int(int a, int b) {
    return a > b ? a : b;
}

/*
  检查是否能让所有房间最终强度都 >= target
  power[]: 原始每个房间的信号强度
  n, r, k: 题目参数
*/
int canReach(ll *power, int n, int r, ll k, ll target) {
    // diff 用于维护“新增增强器”对扫描过程中的区间贡献
    // 为了安全，开到 n + 1
    ll *diff = (ll *)calloc((size_t)(n + 1), sizeof(ll));
    if (diff == NULL) return 0;

    ll used = 0;        // 已经新增的增强器总数
    ll addEffect = 0;   // 当前下标 i 受到的新增增强器累计贡献

    for (int i = 0; i < n; i++) {
        // 移除在当前位置失效的贡献
        addEffect += diff[i];

