            }

            // 贪心：把 need 个增强器尽量放到右边，覆盖当前 i 同时尽量帮助后面
            int pos = min_int(n - 1, i + r);

            // 这些增强器会对区间 [pos-r, pos+r] 产生贡献
            int left = max_int(0, pos - r);
            int right = min_int(n - 1, pos + r);

            // 由于我们是从左往右扫描，并且此时一定有 left <= i <= right
            // 所以当前立即增加 addEffect
            addEffect += need;

            // 到 right+1 时，这批贡献失效
            if (right + 1 < n) {
                diff[right + 1] -= need;
            }
        }
    }

    free(diff);
    return 1;
}

int main() {
    int n, r;
    ll k;
    if (scanf("%d %d %lld", &n, &r, &k) != 3) {
        return 0;
    }

    ll *boosters = (ll *)malloc((size_t)n * sizeof(ll));
    ll *prefix = (ll *)malloc((size_t)(n + 1) * sizeof(ll));
    ll *power = (ll *)malloc((size_t)n * sizeof(ll));

    if (boosters == NULL || prefix == NULL || power == NULL) {
        free(boosters);
        free(prefix);
        free(power);
        return 0;
    }

    for (int i = 0; i < n; i++) {
