      上界可以取 maxPower + k，足够保守。
      实际上某个房间最多也就多获得 k 的新增覆盖，因此这个上界是安全的。
    */
    ll left = minPower;
    ll right = maxPower + k;
    ll ans = minPower;

    while (left <= right) {
        ll mid = left + (right - left) / 2;
        if (canReach(power, n, r, k, mid)) {
            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%lld\n", ans);

    free(boosters);
    free(prefix);
    free(power);
    return 0;
}

