#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

/*
 * 判断是否可以让 k 个槽位同时运行 time 分钟。
 * 核心结论：
 * 对于目标时间 time，每个电源模块最多只能贡献 min(packs[i], time) 的总有效时长。
 * 如果所有模块的贡献总和 >= k * time，则可行；否则不可行。
 */
static int canRun(ll *packs, int m, int k, ll time) {
    ll need = (ll)k * time;
    ll sum = 0;

    for (int i = 0; i < m; ++i) {
        sum += (packs[i] < time) ? packs[i] : time;
        /*
         * 提前剪枝：一旦累计贡献已达到需求，就无需继续累加，
         * 还能避免极端情况下不必要的运算。
         */
        if (sum >= need) {
            return 1;
        }
    }
    return sum >= need;
}

int main() {
    int k, m;
    if (scanf("%d %d", &k, &m) != 2) {
        return 0;
    }

    ll *packs = (ll *)malloc(sizeof(ll) * m);
    if (packs == NULL) {
        return 0;
    }

    ll total = 0;
    for (int i = 0; i < m; ++i) {
        scanf("%lld", &packs[i]);
        total += packs[i];
    }

    /*
     * 最大答案不会超过 total / k：
     * 因为总共只有 total 分钟的电量，而每分钟需要 k 份并行供电。
     */
    ll left = 0, right = total / k;

    /*
     * 二分答案：寻找最大的可行时间。
     * 使用上取中位数，避免死循环。
     */
    while (left < right) {
        ll mid = left + (right - left + 1) / 2;
        if (canRun(packs, m, k, mid)) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }

    printf("%lld\n", left);

    free(packs);
    return 0;
}

