#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

/*
 * 题解思路：
 *
 * 我们想最大化“某个大小为 m 的子集”的按位与结果。
 *
 * 若最终答案为 mask，那么意味着：
 * 至少存在 m 个数，可以分别通过若干次 +1 操作变成某些值 y，且每个 y 都满足：
 *     (y & mask) == mask
 *
 * 也就是说，mask 中为 1 的每一位，选中的这 m 个数最终都必须有这一位。
 *
 * 因此问题转化为：
 * 给定一个候选 mask，计算每个 power[i] 变成某个满足 (y & mask) == mask 且 y >= power[i] 的最小代价，
 * 取其中最小的 m 个代价，若其和 <= k，则说明这个 mask 可行。
 *
 * 然后可以从高位到低位贪心地构造答案：
 * 尝试把当前位设为 1，如果仍可行，就保留，否则放弃。
 *
 * ------------------------------------------------------------
 *
 * 关键函数：min_cost_to_cover(x, mask)
 *
 * 求最小的 y >= x，使得 (y & mask) == mask。
 *
 * 贪心构造 y：
 * 从高位到低位扫描。
 * 若 mask 的第 b 位要求为 1，但当前 y 的第 b 位是 0，
 * 那么必须把 y 提升到“第 b 位变成 1，且低于 b 的位全部清零”的最小值：
 *
 *     y = ((y >> b) + 1) << b
 *
 * 这样是最小的、且能保证第 b 位变成 1 的不小于当前 y 的数。
 * 之后再继续处理更低位。
 *
 * ------------------------------------------------------------
 *
 * 时间复杂度：
 * - 检查一次 mask：O(n log n)（排序代价数组）
 * - 位数约 31 位
 * 总复杂度 O(31 * n log n)，可通过。
 */

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/*
 * 计算把 x 变成某个 y >= x 且 (y & mask) == mask 的最小代价 y - x
 */
static ll min_cost_to_cover(ll x, ll mask) {
    ll y = x;

    /*
     * 由于 power[i] <= 1e9, k <= 1e9，最终值不会超过约 2e9，
     * 这里扫到第 31 位已经足够；写成 0..31 更稳妥。
     */
    for (int b = 31; b >= 0; --b) {
        if (((mask >> b) & 1LL) && (((y >> b) & 1LL) == 0)) {
            y = ((y >> b) + 1LL) << b;
        }
    }
    return y - x;
}

/*
 * 检查候选 mask 是否可行：
 * 是否存在 m 个元素，其最小升级代价之和 <= k
 */
static int feasible(ll *power, int n, int m, ll k, ll mask, ll *costs) {
    for (int i = 0; i < n; ++i) {
        costs[i] = min_cost_to_cover(power[i], mask);
    }

    qsort(costs, n, sizeof(ll), cmp_ll);

    ll sum = 0;
    for (int i = 0; i < m; ++i) {
        sum += costs[i];
        if (sum > k) return 0;
    }
    return 1;
}

int main() {
    int n, m;
    ll k;

    if (scanf("%d %lld %d", &n, &k, &m) != 3) {
        return 0;
    }

    ll *power = (ll *)malloc(sizeof(ll) * n);
    ll *costs = (ll *)malloc(sizeof(ll) * n);
    if (!power || !costs) {
        free(power);
        free(costs);
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%lld", &power[i]);
    }

    ll ans = 0;

    /*
     * 从高位到低位贪心尝试设 1
     */
    for (int b = 31; b >= 0; --b) {
        ll candidate = ans | (1LL << b);
        if (feasible(power, n, m, k, candidate, costs)) {
            ans = candidate;
        }
    }

    printf("%lld\n", ans);

    free(power);
    free(costs);
    return 0;
}

