#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 题意：
 * 从两个数组中总共选出 k 个数字，保持各自原有相对顺序不变，
 * 使得最终拼接出的长度为 k 的序列字典序最大。
 *
 * 核心思路：
 * 1) 枚举从 nums1 中取 x 个，那么从 nums2 中取 k-x 个。
 * 2) 对每个数组，利用“单调栈”思想求长度固定的最大子序列。
 * 3) 将两个最大子序列按“字典序最优”方式合并。
 * 4) 在所有方案中取全局最优。
 */

/*
 * 比较 a[i...] 与 b[j...] 的字典序大小。
 * 返回值：
 * > 0 表示 a[i...] > b[j...]
 * < 0 表示 a[i...] < b[j...]
 * = 0 表示相等
 */
static int compareSuffix(int* a, int lenA, int i, int* b, int lenB, int j) {
    while (i < lenA && j < lenB) {
        if (a[i] != b[j]) {
            return a[i] - b[j];
        }
        i++;
        j++;
    }

    /* 如果前缀都相同，则更长的后缀字典序更大 */
    return (lenA - i) - (lenB - j);
}

/*
 * 从 nums 中选出长度为 k 的字典序最大子序列。
 * 使用“可弹出若干元素”的贪心栈。
 *
 * 例如：nums = [3,4,6,5], k = 2
 * 删除总数 = 4 - 2 = 2
 * 尽量让前面的数更大。
 */
static int* maxSubsequence(int* nums, int size, int k) {
    int* stack = (int*)malloc(sizeof(int) * (k > 0 ? k : 1));
    int top = 0;
    int drop = size - k;   /* 允许丢弃的元素个数 */

    for (int i = 0; i < size; i++) {
        while (top > 0 && drop > 0 && stack[top - 1] < nums[i]) {
            top--;
            drop--;
        }
        if (top < k) {
            stack[top++] = nums[i];
        } else {
            /* 栈已满，只能丢弃当前元素 */
            drop--;
        }
    }

    return stack;
}

/*
 * 按照字典序最优原则，合并两个子序列。
 * 每一步都从“当前剩余部分更大”的那个序列取一个元素。
 */
static int* mergeSequence(int* a, int lenA, int* b, int lenB) {
    int total = lenA + lenB;
    int* merged = (int*)malloc(sizeof(int) * total);
    int i = 0, j = 0, p = 0;

    while (i < lenA || j < lenB) {
        if (compareSuffix(a, lenA, i, b, lenB, j) > 0) {
            merged[p++] = a[i++];
        } else {
            merged[p++] = b[j++];
        }
    }

    return merged;
}

/*
 * 比较两个等长数组的字典序。
 * 返回值：
 * > 0 表示 a > b
 * < 0 表示 a < b
 * = 0 表示相等
 */
static int compareArray(int* a, int* b, int len) {
    for (int i = 0; i < len; i++) {
        if (a[i] != b[i]) {
            return a[i] - b[i];
        }
    }
    return 0;
}

/*
 * 主函数：返回长度为 k 的最大观测序列。
 * 调用者负责释放返回数组。
 */
int* maxObservationSequence(int* stream1, int m, int* stream2, int n, int k, int* returnSize) {
    *returnSize = k;

    int* best = (int*)malloc(sizeof(int) * k);
    int hasBest = 0;

    /*
     * 枚举从 stream1 中取 x 个。
     * 则必须满足：
     * 0 <= x <= m
     * 0 <= k-x <= n
     */
    int start = (k - n > 0) ? (k - n) : 0;
    int end = (k < m) ? k : m;

    for (int x = start; x <= end; x++) {
        int y = k - x;

        int* sub1 = maxSubsequence(stream1, m, x);
        int* sub2 = maxSubsequence(stream2, n, y);
        int* candidate = mergeSequence(sub1, x, sub2, y);

        if (!hasBest || compareArray(candidate, best, k) > 0) {
            memcpy(best, candidate, sizeof(int) * k);
            hasBest = 1;
        }

        free(sub1);
        free(sub2);
        free(candidate);
    }

    return best;
}

/*
 * 下面给出一个简单的测试主函数。
 * 在线评测时如果不需要 main，可以删除。
 */
int main() {
    int nums1[] = {3, 4, 6, 5};
    int nums2[] = {9, 1, 2, 5, 8, 3};
    int k = 5;
    int returnSize = 0;

    int* ans = maxObservationSequence(nums1, 4, nums2, 6, k, &returnSize);

    printf("[");
    for (int i = 0; i < returnSize; i++) {
        if (i > 0) printf(",");
        printf("%d", ans[i]);
    }
    printf("]\n");

    free(ans);
    return 0;
}

