#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定仅包含 ()[]{} 的字符串，求最长的“合法括号连续子串”长度。

核心思路（栈，O(n)）：
- 栈中存“尚未匹配的位置下标”。
- 初始压入一个哨兵 -1，表示最近一个非法位置之前的边界。
- 遍历每个字符：
  1) 如果是左括号，直接压栈其下标。
  2) 如果是右括号：
     - 若栈顶对应的是匹配的左括号，则弹出栈顶；
       此时当前合法区间长度 = i - 栈新的栈顶下标。
     - 否则，当前右括号无法匹配，它会成为新的“断点”，压栈其下标。

为什么对多种括号也成立？
- 一旦出现类型不匹配，例如栈顶是 '['，当前却来了 ')'
  那么以当前字符结尾的任何跨过这个位置的子串都不可能是合法串。
  因此把当前下标压入栈，作为新的分界线即可。

时间复杂度：O(n)
空间复杂度：O(n)
*/

/* 判断是否为左括号 */
int is_open(char c) {
    return c == '(' || c == '[' || c == '{';
}

/* 判断左右括号是否匹配 */
int is_match(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

int main() {
    int capacity = 1024;
    int n = 0;
    char *s = (char *)malloc((size_t)capacity * sizeof(char));
    if (s == NULL) return 0;

    /*
    读取一整行字符串；支持空串。
    输入保证只有括号字符，这里遇到换行或 EOF 结束。
    */
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n' && ch != '\r') {
        if (n + 1 >= capacity) {
            capacity <<= 1;
            char *tmp = (char *)realloc(s, (size_t)capacity * sizeof(char));
            if (tmp == NULL) {
                free(s);
                return 0;
            }
            s = tmp;
        }
        s[n++] = (char)ch;
    }
    s[n] = '\0';

    /* 空串直接输出 0 */
    if (n == 0) {
        printf("0\n");
        free(s);
        return 0;
    }

    /* 栈中存下标 */
    int *stack = (int *)malloc((size_t)(n + 1) * sizeof(int));
    if (stack == NULL) {
        free(s);
        return 0;
    }

    int top = 0;
    stack[top] = -1;   /* 哨兵：最近一个非法位置之前的边界 */
    int ans = 0;

    for (int i = 0; i < n; ++i) {
        if (is_open(s[i])) {
            /* 左括号直接入栈 */
            stack[++top] = i;
        } else {
            /* 右括号：尝试与栈顶左括号匹配 */
            if (top > 0 && is_open(s[stack[top]]) && is_match(s[stack[top]], s[i])) {
                /* 匹配成功，弹出左括号位置 */
                --top;

                /*
                此时 stack[top] 是当前合法区间左边最近的“断点”位置，
                所以以 i 结尾的最长合法子串长度为 i - stack[top]
                */
                int len = i - stack[top];
                if (len > ans) ans = len;
            } else {
                /*
                匹配失败：
                当前右括号本身成为新的断点，压栈其下标。
                */
                stack[++top] = i;
            }
        }
    }

    printf("%d\n", ans);

    free(stack);
    free(s);
    return 0;
}

