#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
 * 影子档案栈 - 参考实现（C语言）
 *
 * 核心思路：
 * 1. 每次 push 的元素按“进入时间”分配一个递增位置 pos（1..N）。
 * 2. 用线段树维护当前仍然存在的元素信息。
 * 3. 每个线段树节点维护：
 *    - topPos : 该区间内仍存活元素中，位置最大的那个（即最靠近栈顶）
 *    - maxVal : 该区间内的最大值
 *    - maxPos : 在最大值 maxVal 中，位置最大的那个（题意要求：若最大值有多个，删离栈顶最近的）
 *
 * 这样就能支持：
 * - top    -> 查询全局 topPos
 * - pop    -> 删除全局 topPos
 * - peekMax-> 查询根节点 maxVal
 * - popMax -> 删除根节点 maxPos
 *
 * 单次操作复杂度 O(log Q)，总复杂度 O(Q log Q)
 */

#define MAXQ 200000
#define NEG_INF (LLONG_MIN / 4)

typedef long long ll;

typedef struct {
    int type;
    ll x;
} Operation;

typedef struct {
    ll maxVal;   // 区间最大值；若区间无元素，则为 NEG_INF
    int maxPos;  // 对应最大值中位置最大的那个
    int topPos;  // 区间内仍存活元素中位置最大的那个
} Node;

static Operation ops[MAXQ + 5];
static ll valueAtPos[MAXQ + 5];   // 每个 push 位置对应的值
static Node seg[MAXQ * 4 + 5];

/*
 * 合并左右儿子信息
 */
Node mergeNode(Node L, Node R) {
    Node res;

    // topPos：取更靠右（位置更大）的存活元素
    res.topPos = (R.topPos > 0) ? R.topPos : L.topPos;

    // maxVal/maxPos：取更大值；若相等，取位置更大的（更靠近栈顶）
    if (L.maxVal > R.maxVal) {
        res.maxVal = L.maxVal;
        res.maxPos = L.maxPos;
    } else if (L.maxVal < R.maxVal) {
        res.maxVal = R.maxVal;
        res.maxPos = R.maxPos;
    } else {
        // 最大值相同
        res.maxVal = L.maxVal;
        res.maxPos = (L.maxPos > R.maxPos) ? L.maxPos : R.maxPos;
    }

    return res;
}

/*
 * 建树：初始全部为空
 */
void build(int idx, int l, int r) {
    seg[idx].maxVal = NEG_INF;
    seg[idx].maxPos = 0;
    seg[idx].topPos = 0;

    if (l == r) return;
    int mid = (l + r) >> 1;
    build(idx << 1, l, mid);
    build(idx << 1 | 1, mid + 1, r);
}

/*
 * 在位置 pos 处放入一个值 val（表示 push）
 */
void activate(int idx, int l, int r, int pos, ll val) {
    if (l == r) {
        seg[idx].maxVal = val;
        seg[idx].maxPos = pos;
        seg[idx].topPos = pos;
        return;
    }

    int mid = (l + r) >> 1;
    if (pos <= mid) activate(idx << 1, l, mid, pos, val);
    else activate(idx << 1 | 1, mid + 1, r, pos, val);

    seg[idx] = mergeNode(seg[idx << 1], seg[idx << 1 | 1]);
}

/*
 * 删除位置 pos 的元素（表示 pop 或 popMax）
 */
void deactivate(int idx, int l, int r, int pos) {
    if (l == r) {
        seg[idx].maxVal = NEG_INF;
        seg[idx].maxPos = 0;
        seg[idx].topPos = 0;
        return;
    }

    int mid = (l + r) >> 1;
    if (pos <= mid) deactivate(idx << 1, l, mid, pos);
    else deactivate(idx << 1 | 1, mid + 1, r, pos);

    seg[idx] = mergeNode(seg[idx << 1], seg[idx << 1 | 1]);
}

int main() {
    int Q;
    if (scanf("%d", &Q) != 1) return 0;

    int pushCount = 0;
    for (int i = 1; i <= Q; i++) {
        scanf("%d", &ops[i].type);
        if (ops[i].type == 1) {
            scanf("%lld", &ops[i].x);
            pushCount++;
            valueAtPos[pushCount] = ops[i].x;
        }
    }

    // 线段树大小按 push 总次数建立即可
    if (pushCount == 0) {
        // 题目保证查询时非空；若没有 push，则说明没有输出操作
        return 0;
    }

    build(1, 1, pushCount);

    int currentPushPos = 0; // 已处理到的 push 编号

    for (int i = 1; i <= Q; i++) {
        int type = ops[i].type;

        if (type == 1) {
            // push
            currentPushPos++;
            activate(1, 1, pushCount, currentPushPos, ops[i].x);
        } else if (type == 2) {
            // pop：删除并输出栈顶
            int pos = seg[1].topPos;
            ll val = valueAtPos[pos];
            printf("%lld\n", val);
            deactivate(1, 1, pushCount, pos);
        } else if (type == 3) {
            // top：输出栈顶但不删除
            int pos = seg[1].topPos;
            printf("%lld\n", valueAtPos[pos]);
        } else if (type == 4) {
            // peek max：输出当前最大值
            printf("%lld\n", seg[1].maxVal);
        } else if (type == 5) {
            // pop max：删除并输出最大值；若有多个，删最靠近栈顶的
            int pos = seg[1].maxPos;
            ll val = seg[1].maxVal;
            printf("%lld\n", val);
            deactivate(1, 1, pushCount, pos);
        }
    }

    return 0;
}

