#include <stdio.h>
#include <string.h>

/*
题目思路：
- 用两个队列分别保存 Alpha 和 Beta 阵营议员的下标。
- 下标越小，表示越早轮到他行动。
- 每次分别取出两个队首：
    - 谁的下标更小，说明谁先行动。
    - 先行动的人会取消对方当前这名议员的资格。
    - 同时，这个先行动的人会进入下一轮，因此把他的下标加上 n 后重新入队。
- 当某一个队列为空时，另一方获胜。

为什么下标加 n？
- 因为整个过程是按轮次循环的。
- 例如原本在位置 2 的议员，如果这一轮行动完还能继续保留资格，
  那么下一次他出现的位置就可以看成是 2 + n，表示下一轮中的相对顺序。

时间复杂度：O(n)
空间复杂度：O(n)
*/

#define MAXN 20005

int main() {
    char council[10005];
    if (scanf("%10000s", council) != 1) {
        return 0;
    }

    int n = (int)strlen(council);

    /*
    使用数组模拟两个普通队列。
    qa 存 Alpha 议员的下标
    qb 存 Beta 议员的下标
    */
    int qa[MAXN], qb[MAXN];
    int ha = 0, ta = 0;  // Alpha 队列头尾
    int hb = 0, tb = 0;  // Beta 队列头尾

    // 初始化：把各阵营议员下标分别入队
    for (int i = 0; i < n; i++) {
        if (council[i] == 'A') {
            qa[ta++] = i;
        } else {
            qb[tb++] = i;
        }
    }

    // 模拟过程，直到一方队列为空
    while (ha < ta && hb < tb) {
        int a = qa[ha++];
        int b = qb[hb++];

        if (a < b) {
            // Alpha 议员先行动，取消这个 Beta 议员资格
            // 自己进入下一轮，因此下标加 n 后重新入队
            qa[ta++] = a + n;
        } else {
            // Beta 议员先行动，取消这个 Alpha 议员资格
            qb[tb++] = b + n;
        }
    }

    if (ha < ta) {
        printf("Alpha\n");
    } else {
        printf("Beta\n");
    }

    return 0;
}

