#include <stdio.h>
#include <stdlib.h>

/*
 * 设计思路：
 *
 * 由于时间戳严格递增，因此所有记录进入队列的顺序也是递增的。
 * 对于 query(timestamp)，我们只需要保留区间 [timestamp - 299, timestamp]
 * 内的时间戳，把更早的时间戳从队头弹出即可。
 *
 * 这样：
 * 1. record(timestamp)：把 timestamp 入队
 * 2. query(timestamp)：不断弹出队头中 < timestamp - 299 的元素
 *    此时队列中剩余元素个数就是答案
 *
 * 每个时间戳最多入队一次、出队一次，因此总时间复杂度为 O(n)，
 * 单次操作均摊 O(1)。
 */

/* 链式队列结点 */
typedef struct Node {
    int timestamp;
    struct Node* next;
} Node;

/* 统计器结构体 */
typedef struct GateCounter {
    Node* front;   // 队头
    Node* rear;    // 队尾
    int size;      // 当前队列元素个数
} GateCounter;

/* 创建统计器 */
GateCounter* gateCounterCreate() {
    GateCounter* obj = (GateCounter*)malloc(sizeof(GateCounter));
    obj->front = NULL;
    obj->rear = NULL;
    obj->size = 0;
    return obj;
}

/* 入队：记录一名乘客通过 */
void gateCounterRecord(GateCounter* obj, int timestamp) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->timestamp = timestamp;
    node->next = NULL;

    if (obj->rear == NULL) {
        // 队列为空
        obj->front = node;
        obj->rear = node;
    } else {
        obj->rear->next = node;
        obj->rear = node;
    }

    obj->size++;
}

/*
 * 查询最近 300 秒内的客流量
 * 有效区间为 [timestamp - 299, timestamp]
 */
int gateCounterQuery(GateCounter* obj, int timestamp) {
    int lowerBound = timestamp - 299;

    // 删除所有不在窗口内的旧记录
    while (obj->front != NULL && obj->front->timestamp < lowerBound) {
        Node* temp = obj->front;
        obj->front = obj->front->next;
        free(temp);
        obj->size--;
    }

    // 如果队列被删空，rear 也要置空
    if (obj->front == NULL) {
        obj->rear = NULL;
    }

    return obj->size;
}

/* 释放统计器 */
void gateCounterFree(GateCounter* obj) {
    Node* cur = obj->front;
    while (cur != NULL) {
        Node* temp = cur;
        cur = cur->next;
        free(temp);
    }
    free(obj);
}

