#include <stdio.h>
#include <stdlib.h>

/*
 * 题意：
 * 选一个非空递增下标序列，使相邻下标差在 [L, R] 内，最大化所选元素和。
 *
 * 状态设计：
 * dp[i] = 以 i 结尾的合法跃迁链最大总能量
 *
 * 转移：
 * dp[i] = a[i] + max(0, max(dp[j]))
 * 其中 j 满足 i - R <= j <= i - L
 *
 * 解释：
 * - 可以从 i 直接开始一条新链，此时贡献是 a[i]，对应 max(0, ...) 里的 0
 * - 或者接在某个合法前驱 j 后面
 *
 * 难点：
 * 对每个 i，需要求区间 [i-R, i-L] 中 dp 的最大值。
 * 这是一个滑动窗口最大值问题，可用单调队列 O(n) 解决。
 *
 * 单调队列维护规则：
 * - 队列中存下标 j
 * - 对应 dp[j] 从队头到队尾单调递减
 * - 当 i 增加时：
 *   1) 新进入窗口的候选下标是 add = i - L
 *   2) 过期下标是 < i - R 的位置，需要从队头弹出
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(n)
 */

int main(void) {
    int n, L, R;
    if (scanf("%d %d %d", &n, &L, &R) != 3) {
        return 0;
    }

    long long *a = (long long *)malloc(sizeof(long long) * n);
    long long *dp = (long long *)malloc(sizeof(long long) * n);
    int *deque = (int *)malloc(sizeof(int) * n);  // 单调队列，存下标

    if (!a || !dp || !deque) {
        free(a);
        free(dp);
        free(deque);
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%lld", &a[i]);
    }

    int head = 0, tail = 0; // 队列区间为 [head, tail)
    long long ans = -(1LL << 60);

    for (int i = 0; i < n; ++i) {
        // 1. 将新进入合法前驱窗口的下标 add = i - L 加入单调队列
        int add = i - L;
        if (add >= 0) {
            // 维持队列对应 dp 值单调递减
            // 若 dp[deque[tail-1]] <= dp[add]，则尾部元素不可能再成为更优答案
            while (head < tail && dp[deque[tail - 1]] <= dp[add]) {
                --tail;
            }
            deque[tail++] = add;
        }

        // 2. 移除已经离开窗口左边界的下标
        // 合法范围为 [i - R, i - L]
        // 所以所有 < i - R 的下标都必须弹出
        while (head < tail && deque[head] < i - R) {
            ++head;
        }

        // 3. 取窗口中的最大 dp 值进行转移
        long long bestPrev = 0;  // 允许从当前点重新开始一条新链
        if (head < tail && dp[deque[head]] > 0) {
            bestPrev = dp[deque[head]];
        }

        dp[i] = a[i] + bestPrev;

        if (dp[i] > ans) {
            ans = dp[i];
        }
    }

    printf("%lld\n", ans);

    free(a);
    free(dp);
    free(deque);
    return 0;
}

