#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 题解思路：
 *
 * 这是经典“反向消除 + 队列传播”的问题。
 *
 * 正向构造很难，因为前面的喷码可能会被后面的喷码覆盖。
 *
 * 因此我们反过来想：
 * 如果一个长度为 m 的窗口 [i, i+m-1]，其中所有字符都已经和 seal 对应匹配，
 * 那么这个窗口可以被看作“最后一次喷码”的位置。
 * 如果我们把这个窗口对应的字符全部“擦除”为已完成状态，
 * 就可能让其它窗口也变得可行。
 *
 * 做法类似拓扑排序：
 * 1. 对每个窗口 i，统计其中与 seal 不匹配的位置数 badCount[i]。
 * 2. 若 badCount[i] == 0，则该窗口立刻可被处理，入队。
 * 3. 每次从队列取出一个窗口，把它覆盖到的、尚未删除的字符位置标记为 deleted。
 * 4. 一个字符位置被删除后，它会影响所有覆盖它的窗口：
 *    若该位置原本是这些窗口中的“不匹配点”，则 badCount 减 1；
 *    一旦某窗口 badCount 变为 0，就入队。
 * 5. 最终若所有字符都被删除，说明存在方案；
 *    由于我们做的是逆过程，所以答案要反转输出。
 *
 * 复杂度：
 * - 共有 O(n) 个窗口，每个字符最多影响 O(m) 个窗口
 * - 总复杂度 O((n-m+1)*m)，在 n <= 1000 时完全可行
 */

int main() {
    char seal[1005], finalStr[1005];
    if (scanf("%1000s", seal) != 1) return 0;
    if (scanf("%1000s", finalStr) != 1) return 0;

    int m = (int)strlen(seal);
    int n = (int)strlen(finalStr);
    int w = n - m + 1;  // 可选窗口数量

    // 特判：理论上不会出现 m > n，因为题目保证了
    if (m > n) {
        printf("0\n");
        return 0;
    }

    // badCount[i]：窗口 i 中，当前仍然要求匹配但与 seal 不同的位置数量
    int *badCount = (int *)malloc(sizeof(int) * w);

    // inQueue[i]：窗口是否已入队过，避免重复入队
    int *inQueue = (int *)calloc(w, sizeof(int));

    // deleted[pos]：该位置是否已经在逆向过程中被“擦除”
    int *deleted = (int *)calloc(n, sizeof(int));

    // 队列，存放当前可处理的窗口起点
    int *queue = (int *)malloc(sizeof(int) * w);
    int head = 0, tail = 0;

    // answer 存放逆向处理顺序，最后需要反转
    int *answer = (int *)malloc(sizeof(int) * w);
    int ansSize = 0;

    // 初始化每个窗口的 badCount
    for (int i = 0; i < w; i++) {
        int bad = 0;
        for (int j = 0; j < m; j++) {
            if (finalStr[i + j] != seal[j]) {
                bad++;
            }
        }
        badCount[i] = bad;
        if (bad == 0) {
            queue[tail++] = i;
            inQueue[i] = 1;
        }
    }

    // BFS / 拓扑式传播
    while (head < tail) {
        int start = queue[head++];
        answer[ansSize++] = start;

        // 将窗口 [start, start+m-1] 内尚未删除的位置全部删除
        for (int pos = start; pos < start + m; pos++) {
            if (deleted[pos]) continue;
            deleted[pos] = 1;

            // 所有覆盖 pos 的窗口起点范围：
            // left <= pos <= left + m - 1
            // 即 left in [pos-m+1, pos]
            int leftMin = pos - m + 1;
            if (leftMin < 0) leftMin = 0;
            int leftMax = pos;
            if (leftMax > n - m) leftMax = n - m;

            for (int left = leftMin; left <= leftMax; left++) {
                int offset = pos - left;  // 对应 seal[offset]

                // 只有当这个位置原本是不匹配点时，删除它才会让 badCount 减 1
                if (finalStr[pos] != seal[offset]) {
                    badCount[left]--;
                    if (badCount[left] == 0 && !inQueue[left]) {
                        queue[tail++] = left;
                        inQueue[left] = 1;
                    }
                }
            }
        }
    }

    // 检查是否所有字符都被删除（即是否可以完整逆向还原）
    for (int i = 0; i < n; i++) {
        if (!deleted[i]) {
            printf("0\n");
            free(badCount);
            free(inQueue);
            free(deleted);
            free(queue);
            free(answer);
            return 0;
        }
    }

    // 按正向执行顺序输出：逆向顺序的反转
    printf("%d\n", ansSize);
    for (int i = ansSize - 1; i >= 0; i--) {
        printf("%d", answer[i]);
        if (i > 0) printf(" ");
    }
    printf("\n");

    free(badCount);
    free(inQueue);
    free(deleted);
    free(queue);
    free(answer);
    return 0;
}

