#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定一个环形数组 nums，长度为 n。
对于每个起点 i（0 <= i < n），考虑长度为 k 的环形窗口：
nums[i], nums[i+1], ..., nums[i+k-1]（下标对 n 取模）
求每个窗口的波动值 = 最大值 - 最小值。

核心思路：
1. 环形窗口可以通过“数组复制一遍”转化为线性问题。
   设 ext 长度为 n + k - 1，ext[i] = nums[i % n]
   这样从 ext 的每个位置 i（0 <= i < n）出发的长度为 k 的连续子数组，
   就对应原环上的一个窗口。

2. 对 ext 做长度为 k 的滑动窗口，同时维护：
   - 一个单调递减队列：队头始终是当前窗口最大值下标
   - 一个单调递增队列：队头始终是当前窗口最小值下标

3. 当窗口右端点为 r，左端点为 l = r - k + 1 时：
   - 弹出队头中所有 < l 的过期下标
   - 当前窗口最大值 = ext[maxDeque[head]]
   - 当前窗口最小值 = ext[minDeque[head]]
   - 波动值 = 最大值 - 最小值

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }

    long long *nums = (long long *)malloc(sizeof(long long) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &nums[i]);
    }

    // 扩展数组长度：只需要覆盖所有以 [0, n-1] 为起点、长度为 k 的窗口
    int m = n + k - 1;
    long long *ext = (long long *)malloc(sizeof(long long) * m);
    for (int i = 0; i < m; i++) {
        ext[i] = nums[i % n];
    }

    // 单调队列中存的是下标
    int *maxDeque = (int *)malloc(sizeof(int) * m);
    int *minDeque = (int *)malloc(sizeof(int) * m);
    int maxHead = 0, maxTail = 0; // [maxHead, maxTail)
    int minHead = 0, minTail = 0; // [minHead, minTail)

    long long *ans = (long long *)malloc(sizeof(long long) * n);
    int ansCount = 0;

    for (int r = 0; r < m; r++) {
        // 维护最大值单调队列（递减）
        while (maxHead < maxTail && ext[maxDeque[maxTail - 1]] <= ext[r]) {
            maxTail--;
        }
        maxDeque[maxTail++] = r;

        // 维护最小值单调队列（递增）
        while (minHead < minTail && ext[minDeque[minTail - 1]] >= ext[r]) {
            minTail--;
        }
        minDeque[minTail++] = r;

        // 当窗口长度达到 k 时，开始统计答案
        if (r >= k - 1) {
            int l = r - k + 1;

            // 弹出已经离开窗口的下标
            while (maxHead < maxTail && maxDeque[maxHead] < l) {
                maxHead++;
            }
            while (minHead < minTail && minDeque[minHead] < l) {
                minHead++;
            }

            // 只需要前 n 个起点对应的窗口答案
            if (l < n) {
                long long maxVal = ext[maxDeque[maxHead]];
                long long minVal = ext[minDeque[minHead]];
                ans[ansCount++] = maxVal - minVal;
            }
        }
    }

    // 输出答案
    for (int i = 0; i < ansCount; i++) {
        if (i > 0) printf(" ");
        printf("%lld", ans[i]);
    }
    printf("\n");

    free(nums);
    free(ext);
    free(maxDeque);
    free(minDeque);
    free(ans);

    return 0;
}

