核心思路（反向 + 队列）：

正向从全 '?' 构造 target 不容易判断“下一步盖哪里”。
反过来思考：
- 从 target 出发，尝试把某个长度为 m 的窗口“擦除”为全 '*'。
- 若一个窗口中，所有还没被擦除的位置都与 stamp 对应字符相同，
  那么这个窗口就可以被整体擦掉。
- 一旦某些位置被擦掉，它们会让别的窗口中“不匹配”的字符数量减少，
  可能使别的窗口也变得可擦。

这正是一个典型的“状态传播”过程，使用队列维护刚被擦掉的位置。

具体做法：
1. 对每个窗口 i（0 <= i <= n-m）：
   - 统计该窗口中与 stamp 不匹配的位置个数 todo[i]
   - 若 todo[i] == 0，说明该窗口当前就可擦，先记录该窗口，
     并把其覆盖到的所有位置加入队列（表示这些位置变成已擦除）
2. 队列中每弹出一个已擦除位置 pos：
   - 所有覆盖 pos 的窗口都可能因此变得“更接近可擦”
   - 对这些窗口，如果 pos 原本是该窗口中的一个不匹配点，
     则 todo[window]--
   - 若 todo[window] 变成 0，则该窗口可擦，将其加入答案，
     并把该窗口里所有尚未擦除的位置入队
3. 最终若所有位置都被擦除，则反转记录的窗口顺序，得到正向盖章顺序；
   否则无解。

时间复杂度：O((n-m+1) * m)
在 n <= 1000 范围内完全可行。
*/

int main() {
    char stamp[1005], target[1005];
    if (scanf("%1000s", stamp) != 1) return 0;
    if (scanf("%1000s", target) != 1) return 0;

    int m = (int)strlen(stamp);
    int n = (int)strlen(target);
    int wcnt = n - m + 1;  // 窗口数量

    // todo[i]：窗口 i 中当前还有多少个“必须匹配但尚未被擦除且不匹配”的位置
    int *todo = (int *)malloc(sizeof(int) * wcnt);

    // usedWindow[i]：窗口 i 是否已经被加入答案（避免重复处理）
    int *usedWindow = (int *)calloc(wcnt, sizeof(int));

    // donePos[p]：位置 p 是否已经被擦除
    int *donePos = (int *)calloc(n, sizeof(int));

    // queue：存储刚刚被擦除的位置，进行 BFS 传播
    int *queue = (int *)malloc(sizeof(int) * n);
    int ql = 0, qr = 0;

    // ans：反向擦除时记录的窗口起点，最后需要反转
    int *ans = (int *)malloc(sizeof(int) * (10 * n + 5));
    int ansSize = 0;

    // 初始化每个窗口的不匹配数量
    for (int i = 0; i < wcnt; i++) {
        todo[i] = 0;
        for (int j = 0; j < m; j++) {
            if (target[i + j] != stamp[j]) {
                todo[i]++;
            }
        }
    }

    // 先把一开始就可擦的窗口处理掉
    for (int i = 0; i < wcnt; i++) {
        if (todo[i] == 0) {
            usedWindow[i] = 1;
            ans[ansSize++] = i;
            for (int j = 0; j < m; j++) {
                int pos = i + j;
                if (!donePos[pos]) {
                    donePos[pos] = 1;
                    queue[qr++] = pos;
                }
            }
        }
    }

    // BFS：已擦除位置会影响覆盖它的所有窗口
    while (ql < qr) {
        int pos = queue[ql++];

        // 所有可能覆盖 pos 的窗口起点范围：
        // start <= pos <= start + m - 1
        // => pos - m + 1 <= start <= pos
        int left = pos - m + 1;
        if (left < 0) left = 0;
        int right = pos;
        if (right > n - m) right = n - m;

        for (int start = left; start <= right; start++) {
            if (usedWindow[start]) continue;

            int j = pos - start; // pos 对应窗口中的第 j 位
            // 若这个位置原本是该窗口中的一个不匹配点，
            // 那么它现在被擦除了，相当于少了一个障碍
            if (target[pos] != stamp[j]) {
                todo[start]--;
                if (todo[start] == 0) {
                    usedWindow[start] = 1;
                    ans[ansSize++] = start;
                    for (int k = 0; k < m; k++) {
                        int p = start + k;
                        if (!donePos[p]) {
                            donePos[p] = 1;
                            queue[qr++] = p;
                        }
                    }
                }
            }
        }
    }

    // 检查是否所有位置都已擦除
    for (int i = 0; i < n; i++) {
        if (!donePos[i]) {
            printf("0\n");
            free(todo);
            free(usedWindow);
            free(donePos);
            free(queue);
            free(ans);
            return 0;
        }
    }

    // 题目要求输出正向操作顺序，因此反转答案
    // 由于题目保证可行答案不超过 10*n，这里顺带检查一下
    if (ansSize > 10 * n) {
        printf("0\n");
        free(todo);
        free(usedWindow);
        free(donePos);
        free(queue);
        free(ans);
        return 0;
    }

    printf("%d\n", ansSize);
    for (int i = ansSize - 1; i >= 0; i--) {
        printf("%d", ans[i]);
        if (i != 0) printf(" ");
    }
    if (ansSize > 0) printf("\n");

    free(todo);
    free(usedWindow);
    free(donePos);
    free(queue);
    free(ans);
    return 0;
}

