#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
题意：
给定一个 n x m 的 01 字符矩阵，所有 '1' 构成一个上下左右连通区域，
并给出其中一个黑点 (x, y)。
要求求出包围所有 '1' 的最小轴对齐矩形面积。

核心思路：
由于所有 '1' 连成一片，因此：
1. 在 [0, x] 中，存在一个“最靠上”的含 '1' 的行 top；
2. 在 [x, n-1] 中，存在一个“最靠下”的含 '1' 的行 bottom；
3. 在 [0, y] 中，存在一个“最靠左”的含 '1' 的列 left；
4. 在 [y, m-1] 中，存在一个“最靠右”的含 '1' 的列 right。

并且“某一行是否含有 1”、“某一列是否含有 1”都具有可二分的单调边界性质，
可以分别通过二分搜索找到 top / bottom / left / right。

时间复杂度：
- 检查一行是否有 '1'：O(m)
- 检查一列是否有 '1'：O(n)
- 二分 4 次，总复杂度约为 O(m log n + n log m)

注意：
输入规模可达 2000 x 2000，使用 long long 计算面积更稳妥。
*/

/* 判断第 row 行是否存在 '1' */
static int row_has_one(char **grid, int row, int m) {
    for (int j = 0; j < m; ++j) {
        if (grid[row][j] == '1') {
            return 1;
        }
    }
    return 0;
}

/* 判断第 col 列是否存在 '1' */
static int col_has_one(char **grid, int n, int col) {
    for (int i = 0; i < n; ++i) {
        if (grid[i][col] == '1') {
            return 1;
        }
    }
    return 0;
}

/*
寻找区间 [low, high) 内第一个“含有 1 的行”
用于寻找 top。
*/
static int find_first_row_with_one(char **grid, int m, int low, int high) {
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (row_has_one(grid, mid, m)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

/*
寻找区间 [low, high) 内第一个“不含 1 的行”
最终 bottom = 返回值 - 1
用于寻找 bottom。
*/
static int find_first_row_without_one_after_black(char **grid, int m, int low, int high) {
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (row_has_one(grid, mid, m)) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

/*
寻找区间 [low, high) 内第一个“含有 1 的列”
用于寻找 left。
*/
static int find_first_col_with_one(char **grid, int n, int low, int high) {
    while (low < high) {
        int mid = low + (high - low) / 2;
