#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    int *a;
    int n;
    ll k;
} Input;

// 计算最大公约数
static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

// 计算最小公倍数，若超过 limit 则直接返回 limit + 1（用于剪枝防溢出）
static ll lcm_limit(ll a, ll b, ll limit) {
    ll g = gcdll(a, b);
    a /= g;
    if (a > limit / b) return limit + 1;
    return a * b;
}

// 升序排序用比较函数
static int cmp_int(const void *p1, const void *p2) {
    int x = *(const int *)p1;
    int y = *(const int *)p2;
    return (x > y) - (x < y);
}

/*
 * 预处理数组：
 * 如果存在 x, y 且 y % x == 0，那么 y 生成的所有数都已经包含在 x 的倍数中，y 可以删除。
 * 这样能显著减少后续子集枚举规模。
 * 返回保留下来的元素个数。
 */
static int simplify(int *base, int n) {
    qsort(base, n, sizeof(int), cmp_int);

    int *tmp = (int *)malloc(sizeof(int) * n);
    int m = 0;

    for (int i = 0; i < n; ++i) {
        int redundant = 0;
        for (int j = 0; j < m; ++j) {
            if (base[i] % tmp[j] == 0) {
                redundant = 1;
                break;
            }
        }
        if (!redundant) tmp[m++] = base[i];
    }

    for (int i = 0; i < m; ++i) base[i] = tmp[i];
    free(tmp);
    return m;
}

/*
 * 统计 <= x 的、能被 base 中至少一个元素整除的正整数个数。
 * 使用容斥原理：
 * count(x) = sum(x/lcm(singletons)) - sum(x/lcm(pairs)) + sum(x/lcm(triples)) - ...
 *
 * 因为 n <= 15，子集总数最多 2^15，配合二分查找可以接受。
 */
static ll count_leq(ll x, int *base, int n) {
    ll ans = 0;
    int total = 1 << n;

    for (int mask = 1; mask < total; ++mask) {
        ll lcm = 1;
        int bits = 0;
        int valid = 1;

        for (int i = 0; i < n; ++i) {
            if ((mask >> i) & 1) {
                ++bits;
                lcm = lcm_limit(lcm, base[i], x);
                if (lcm > x) {
                    valid = 0;
                    break;
                }
            }
        }

        if (!valid) continue;

        ll add = x / lcm;
        if (bits & 1) ans += add;
        else ans -= add;
    }

    return ans;
}

/*
 * 主函数：返回第 k 小的去重后元素。
 *
 * 思路：
 * 1. 先删除冗余基数（比如 6 可被 3 覆盖）。
 * 2. 对答案做二分：设 f(mid) = <= mid 的合法数个数。
 * 3. 找到最小的 mid 使得 f(mid) >= k。
 */
long long kthSmallestPeriodicValue(int *base, int baseSize, long long k) {
    baseSize = simplify(base, baseSize);

    ll left = 1;
    ll right = (ll)base[0] * k; // 最坏情况下最小基数自己单独生成第 k 个值

    while (left < right) {
        ll mid = left + (right - left) / 2;
        if (count_leq(mid, base, baseSize) >= k) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
}

/*
 * 以下给出一个简单的本地测试入口。
 * 在线评测时可按平台要求改写输入输出部分，只保留核心函数：
 *     long long kthSmallestPeriodicValue(int *base, int baseSize, long long k)
 */
int main() {
    int base1[] = {3, 6, 9};
    long long k1 = 3;
    printf("%lld\n", kthSmallestPeriodicValue(base1, 3, k1)); // 9

    int base2[] = {5, 2};
    long long k2 = 7;
    printf("%lld\n", kthSmallestPeriodicValue(base2, 2, k2)); // 12

    return 0;
}

