#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007

/*
 * 题意：
 * 选择数组 a，使得：
 * 1) a[i] + b[i] = nums[i]
 * 2) a 单调不降
 * 3) b 单调不升 => nums[i] - a[i] 单调不升
 * 4) L[i] <= a[i] <= R[i]
 *
 * 设 dp[i][x] 表示处理到第 i 位，且 a[i] = x 的方案数。
 *
 * 转移：从上一位 a[i-1] = y 转移到当前 a[i] = x，必须满足：
 *   y <= x                              (a 单调不降)
 *   nums[i-1] - y >= nums[i] - x        (b 单调不升)
 * 第二个条件可化为：
 *   y <= x + nums[i-1] - nums[i]
 *
 * 因此：
 *   y <= min(x, x + nums[i-1] - nums[i])
 *
 * 若令：
 *   upper = min(x, x + nums[i-1] - nums[i])
 * 则：
 *   dp[i][x] = sum(dp[i-1][y]), 其中 0 <= y <= upper
 *
 * 再结合区间约束：x 必须满足
 *   L[i] <= x <= R[i]
 *   且 x <= nums[i]（因为 b[i] 要非负）
 *
 * 使用前缀和可将每层转移优化到 O(max(nums))。
 *
 * 总复杂度：O(n * V)
 * 其中 V = max(nums[i], R[i])，在本题约束下 <= 3000。
 */
int countBoundedMonotonicPairs(int* nums, int numsSize, int** limits, int limitsSize, int* limitsColSize) {
    (void)limitsSize;     // 避免未使用警告
    (void)limitsColSize;  // 避免未使用警告

    int n = numsSize;
    int maxV = 0;
    for (int i = 0; i < n; ++i) {
        if (nums[i] > maxV) maxV = nums[i];
        if (limits[i][1] > maxV) maxV = limits[i][1];
    }

    // 滚动数组：prev 表示上一层 dp，curr 表示当前层 dp
    int* prev = (int*)calloc(maxV + 1, sizeof(int));
    int* curr = (int*)calloc(maxV + 1, sizeof(int));
    int* prefix = (int*)calloc(maxV + 1, sizeof(int));

    if (!prev || !curr || !prefix) {
        free(prev);
        free(curr);
        free(prefix);
        return 0;
    }

    // 初始化第 0 位
    // a[0] 需要满足：L[0] <= a[0] <= R[0] 且 a[0] <= nums[0]
    int left0 = limits[0][0];
    int right0 = limits[0][1];
    if (right0 > nums[0]) right0 = nums[0];

    for (int x = left0; x <= right0; ++x) {
        prev[x] = 1;
    }

    // 逐位转移
    for (int i = 1; i < n; ++i) {
        // 清空当前层
        memset(curr, 0, (maxV + 1) * sizeof(int));

        // 计算上一层的前缀和：prefix[v] = sum(prev[0..v])
        prefix[0] = prev[0];
        for (int v = 1; v <= maxV; ++v) {
            prefix[v] = prefix[v - 1] + prev[v];
            if (prefix[v] >= MOD) prefix[v] -= MOD;
        }

        int left = limits[i][0];
        int right = limits[i][1];
        if (right > nums[i]) right = nums[i];

        // 枚举当前 a[i] = x
        for (int x = left; x <= right; ++x) {
            int upper1 = x;
            int upper2 = x + nums[i - 1] - nums[i];
            int upper = upper1 < upper2 ? upper1 : upper2;

            if (upper < 0) {
                curr[x] = 0;
            } else {
                if (upper > maxV) upper = maxV;
                curr[x] = prefix[upper];
            }
        }

        // 滚动
        int* tmp = prev;
        prev = curr;
        curr = tmp;
    }

    // 汇总最后一层答案
    long long ans = 0;
    for (int x = 0; x <= maxV; ++x) {
        ans += prev[x];
        if (ans >= MOD) ans -= MOD;
    }

    free(prev);
    free(curr);
    free(prefix);

    return (int)ans;
}

/*
 * 以下为一个简单的本地测试示例。
 * 在线评测平台通常只需要提交上面的函数即可。
 */
int main() {
    // 示例 1
    int nums[] = {2, 3, 2};
    int numsSize = sizeof(nums) / sizeof(nums[0]);

    int row0[] = {0, 1};
    int row1[] = {1, 2};
    int row2[] = {1, 2};
    int* limits[] = {row0, row1, row2};
    int limitsColSize[] = {2, 2, 2};

    int ans = countBoundedMonotonicPairs(nums, numsSize, limits, numsSize, limitsColSize);
    printf("%d\n", ans);  // 输出 4

    return 0;
}

