#include <stdio.h>
#include <stdlib.h>

/*
题意分析：
给定两个数组 nums1 和 nums2，可以选择至多两个互不重叠的区间进行交换。
交换某些区间后：
- 若想最大化 nums1 的和，则每交换一个位置 i，nums1 的总和变化量为 nums2[i] - nums1[i]
  因此问题转化为：
  在 diff[i] = nums2[i] - nums1[i] 中，选至多两个互不重叠子数组，使它们的元素和最大。
- 同理，若想最大化 nums2 的和，则在 diff2[i] = nums1[i] - nums2[i] 中做同样的事。

最终答案：
max( sum(nums1) + bestGain(diff), sum(nums2) + bestGain(diff2) )

其中 bestGain(diff) 表示“至多两个互不重叠子数组最大和”，且允许一个都不选，所以结果至少为 0。

核心做法：
1. 用 Kadane 算法求：
   - prefix[i]：在区间 [0..i] 中，最多选一个子数组时的最大和
   - suffix[i]：在区间 [i..n-1] 中，最多选一个子数组时的最大和
2. 那么：
   - 选一个子数组：max(prefix[i])
   - 选两个互不重叠子数组：prefix[i] + suffix[i+1]
3. 取最大值，并与 0 比较（表示不交换）。

时间复杂度：O(n)
空间复杂度：O(n)
*/

static long long maxll(long long a, long long b) {
    return a > b ? a : b;
}

/*
计算一个差分数组 diff 中：
“至多两个互不重叠子数组”的最大和。
允许不选任何子数组，因此返回值 >= 0。
*/
long long bestGainWithAtMostTwoSegments(int* diff, int n) {
    long long* prefix = (long long*)malloc(sizeof(long long) * n);
    long long* suffix = (long long*)malloc(sizeof(long long) * n);

    // prefix[i]：在 [0..i] 中选至多一个子数组的最大和
    long long cur = diff[0];
    prefix[0] = cur > 0 ? cur : 0;
    for (int i = 1; i < n; ++i) {
        // Kadane：以 i 结尾的最大子数组和
        cur = maxll((long long)diff[i], cur + diff[i]);
        // prefix 记录前缀范围内的最优单段和，同时允许“不选”，因此与 0 比较
        prefix[i] = maxll(prefix[i - 1], cur);
        if (prefix[i] < 0) prefix[i] = 0;
    }

    // suffix[i]：在 [i..n-1] 中选至多一个子数组的最大和
    cur = diff[n - 1];
    suffix[n - 1] = cur > 0 ? cur : 0;
    for (int i = n - 2; i >= 0; --i) {
        // 从右往左做 Kadane
        cur = maxll((long long)diff[i], cur + diff[i]);
        suffix[i] = maxll(suffix[i + 1], cur);
        if (suffix[i] < 0) suffix[i] = 0;
    }

    // 答案可以是：
    // 1) 不选：0
    // 2) 只选一段：prefix[n-1]
    // 3) 选两段：prefix[i] + suffix[i+1]
    long long ans = prefix[n - 1];
    if (ans < 0) ans = 0;

    for (int i = 0; i + 1 < n; ++i) {
        long long two = prefix[i] + suffix[i + 1];
        if (two > ans) ans = two;
    }

    free(prefix);
    free(suffix);
    return ans;
}

long long maximumScoreAfterDoubleSplice(int* nums1, int nums1Size, int* nums2, int nums2Size) {
    int n = nums1Size;

    long long sum1 = 0, sum2 = 0;
    int* diff1 = (int*)malloc(sizeof(int) * n); // nums2 - nums1，用于提升 nums1
    int* diff2 = (int*)malloc(sizeof(int) * n); // nums1 - nums2，用于提升 nums2

    for (int i = 0; i < n; ++i) {
        sum1 += nums1[i];
        sum2 += nums2[i];
        diff1[i] = nums2[i] - nums1[i];
        diff2[i] = nums1[i] - nums2[i];
    }

    long long gain1 = bestGainWithAtMostTwoSegments(diff1, n);
    long long gain2 = bestGainWithAtMostTwoSegments(diff2, n);

    long long ans1 = sum1 + gain1;
    long long ans2 = sum2 + gain2;
    long long ans = ans1 > ans2 ? ans1 : ans2;

    free(diff1);
    free(diff2);
    return ans;
}

/*
下面给出一个简单的主函数用于本地测试。
在线评测时如平台已提供函数入口，可只保留上述核心函数。
*/
int main() {
    {
        int nums1[] = {1, 10, 1, 10, 1};
        int nums2[] = {10, 1, 10, 1, 10};
        int n = 5;
        printf("%lld\n", maximumScoreAfterDoubleSplice(nums1, n, nums2, n)); // 41
    }

    {
        int nums1[] = {60, 60, 60};
        int nums2[] = {10, 90, 10};
        int n = 3;
        printf("%lld\n", maximumScoreAfterDoubleSplice(nums1, n, nums2, n)); // 210
    }

    {
        int nums1[] = {7, 11, 13};
        int nums2[] = {1, 1, 1};
        int n = 3;
        printf("%lld\n", maximumScoreAfterDoubleSplice(nums1, n, nums2, n)); // 31
    }

    return 0;
}

