#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
核心思路：
1. need 的长度最多只有 4，因此可以用一个二进制 mask 表示哪些 need 已经被覆盖。
2. 对于 need 的任意非空子集，预处理它们的最小公倍数 lcm。
   如果把某个 base[i] 增加到该 lcm 的某个倍数，那么它就能同时覆盖这个子集中的所有需求。
3. 对每个 base[i]：
   - 枚举 need 的所有非空子集 mask
   - 计算把 base[i] 增加到 >= base[i] 的最小的 lcm(mask) 的倍数所需的代价
   - 该代价表示“使用当前元素来覆盖 mask 对应的一组需求”的最优代价
4. 然后做状态压缩 DP：
   dp[s] = 覆盖状态 s 的最小代价
   依次处理每个 base[i]，尝试让它覆盖一个子集 t，从而转移到 s | t。

复杂度：
- need.length <= 4，因此子集最多 15 个
- 总复杂度约为 O(base.length * 2^m * 2^m)，这里 m <= 4，完全可行
*/

typedef long long ll;

static ll gcd_ll(ll a, ll b) {
    while (b != 0) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static ll lcm_ll(ll a, ll b) {
    return a / gcd_ll(a, b) * b;
}

/*
函数说明：
base: 输入数组 base
n: base 长度
need: 输入数组 need
m: need 长度
返回最少操作次数
*/
long long minIncrementCover(int* base, int n, int* need, int m) {
    int totalMask = 1 << m;

    /* 预处理每个子集的 LCM */
    ll subsetLCM[16];
    subsetLCM[0] = 1;
    for (int mask = 1; mask < totalMask; ++mask) {
        ll cur = 1;
        for (int j = 0; j < m; ++j) {
            if (mask & (1 << j)) {
                cur = lcm_ll(cur, (ll)need[j]);
            }
        }
        subsetLCM[mask] = cur;
    }

    /*
    dp[s]：处理到当前为止的一些 base 元素后，覆盖状态为 s 的最小代价
    初始化：dp[0] = 0，其余为无穷大
    */
    const ll INF = (ll)4e18;
    ll dp[16], ndp[16];
    for (int s = 0; s < totalMask; ++s) dp[s] = INF;
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
