            ll x = base[i];
            ll r = x % l;
            if (r == 0) cost[mask] = 0;
            else cost[mask] = l - r;
        }

        /* 状态转移：当前元素选择覆盖某个子集 mask */
        for (int s = 0; s < totalMask; ++s) {
            if (dp[s] == INF) continue;
            for (int mask = 1; mask < totalMask; ++mask) {
                int ns = s | mask;
                ll cand = dp[s] + cost[mask];
                if (cand < ndp[ns]) ndp[ns] = cand;
            }
        }

        for (int s = 0; s < totalMask; ++s) dp[s] = ndp[s];
    }

    return dp[totalMask - 1];
}

