#include <stdio.h>
#include <stdlib.h>

/*
题意：
给定数组 a，统计所有满足：
  a[l] <= a[k] 对任意 l <= k <= r 成立
的子数组 [l..r]。
并输出：
1) 这样的子数组总个数
2) 这些子数组长度之和

核心思路：
对于每个起点 i，能够作为合法右端点的最远位置，
取决于“右侧第一个严格小于 a[i] 的位置”。

设 nextLess(i) = i 右边第一个满足 a[pos] < a[i] 的位置；
如果不存在，则 nextLess(i) = n。

那么以 i 为左端点的所有合法区间右端点 r 满足：
  i <= r < nextLess(i)
所以合法区间个数为：
  len = nextLess(i) - i

这些区间的长度分别是：
  1, 2, 3, ..., len
长度和为：
  len * (len + 1) / 2

因此问题转化为：
高效求出每个位置右侧第一个严格更小元素的位置。

使用单调栈：
- 栈中存下标，且对应的 a 值保持“非降”（递增允许相等）。
- 当扫描到 a[i] 时，如果 a[i] < a[stack[top]]，
  说明 i 就是栈顶元素右侧第一个严格更小的位置，持续弹栈。
- 相等时不能弹，因为相等不会破坏“a[l] 是最小值之一”的条件。

时间复杂度：O(n)
空间复杂度：O(n)
*/

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *a = (int *)malloc((size_t)n * sizeof(int));
    int *stack = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL || stack == NULL) {
        free(a);
        free(stack);
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }

    long long totalCount = 0;   // 前缀支配区间总个数
    long long totalLength = 0;  // 前缀支配区间长度总和

    int top = -1;

    for (int i = 0; i < n; ++i) {
        /*
        当前元素 a[i] 作为“更小值”出现：
        对所有栈顶位置 idx，若 a[i] < a[idx]，
        则 i 就是 idx 右侧第一个严格更小的位置。
        */
        while (top >= 0 && a[i] < a[stack[top]]) {
            int idx = stack[top--];
            long long len = (long long)i - idx;
            totalCount += len;
            totalLength += len * (len + 1) / 2;
        }

        // 当前下标入栈，维持值的非降单调性
        stack[++top] = i;
    }

    /*
    栈中剩余元素右侧都不存在严格更小值，
    因此 nextLess = n。
    */
    while (top >= 0) {
        int idx = stack[top--];
        long long len = (long long)n - idx;
        totalCount += len;
        totalLength += len * (len + 1) / 2;
    }

    printf("%lld %lld\n", totalCount, totalLength);

    free(a);
    free(stack);
    return 0;
}

