#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

/*
 * 分阶段发布的最小峰值成本
 *
 * 核心思路：
 * 设 dp[i] 表示“用当前考虑的阶段数，完成前 i+1 个任务（下标 0..i）”的最小成本。
 *
 * 对于第一阶段：
 *   dp[i] = max(risk[0..i])
 *
 * 对于后续阶段，若朴素转移：
 *   ndp[i] = min(dp_prev[k-1] + max(risk[k..i]))   (day-1 <= k <= i)
 * 直接做是 O(d * n^2)，在 n=2e5 时不可行。
 *
 * 这里使用“单调栈优化”的经典做法，将每一层转移优化到 O(n)。
 * 总复杂度 O(d * n)，空间复杂度 O(n)。
 */

#define INF ((long long)4e18)

static inline long long minll(long long a, long long b) {
    return a < b ? a : b;
}

int main(void) {
    int n, d;
    if (scanf("%d %d", &n, &d) != 2) {
        return 0;
    }

    int *risk = (int *)malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        scanf("%d", &risk[i]);
    }

    /* 若阶段数多于任务数，则无解 */
    if (d > n) {
        printf("-1\n");
        free(risk);
        return 0;
    }

    long long *dp = (long long *)malloc((size_t)n * sizeof(long long));
    long long *ndp = (long long *)malloc((size_t)n * sizeof(long long));
    int *stack = (int *)malloc((size_t)n * sizeof(int));

    /* 初始化：只用 1 个阶段完成前 i+1 个任务，成本就是前缀最大值 */
    int mx = 0;
    for (int i = 0; i < n; ++i) {
        if (risk[i] > mx) mx = risk[i];
        dp[i] = mx;
    }

    /* day 表示当前是第几个阶段（从 2 开始） */
    for (int day = 2; day <= d; ++day) {
        /* 对于前 day-2 个位置，不可能分成 day 个非空阶段 */
        for (int i = 0; i < day - 1; ++i) {
            ndp[i] = INF;
        }

        int top = 0; /* 单调递减栈，按 risk 值维护索引 */

        /* i 至少要从 day-1 开始，保证前 i+1 个任务能分成 day 段 */
        for (int i = day - 1; i < n; ++i) {
            /*
             * 基本转移：最后一段只放 risk[i]
             * 即前 i 个任务用 day-1 段，最后第 day 段是 [i..i]
             */
            ndp[i] = dp[i - 1] + (long long)risk[i];

            /*
             * 若栈顶的风险值 <= 当前 risk[i]，
             * 说明把那些位置对应方案的“最后一段最大值”提升到 risk[i] 后，
             * 可能得到更优值。
             */
            while (top > 0 && risk[stack[top - 1]] <= risk[i]) {
                int idx = stack[--top];
                ndp[i] = minll(ndp[i], ndp[idx] + (long long)risk[i] - risk[idx]);
            }

            /*
             * 如果栈中还有元素，说明其 risk 严格大于当前 risk[i]。
             * 当前 i 可以继承那个位置已经算出的更优结构。
             */
            if (top > 0) {
                ndp[i] = minll(ndp[i], ndp[stack[top - 1]]);
            }

            stack[top++] = i;
        }

        /* 交换 dp 与 ndp */
        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    printf("%lld\n", dp[n - 1]);

    free(risk);
    free(dp);
    free(ndp);
    free(stack);
    return 0;
}

