#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 将链表中表示的二进制数转换为十进制整数。
 *
 * 思路：
 * 从头到尾遍历链表。
 * 假设当前已经得到的数为 result，读入下一位 bit 后：
 * 新结果 = result * 2 + bit
 *
 * 例如：
 * [1, 0, 1]
 * result = 0
 * 读 1 -> 0*2+1 = 1
 * 读 0 -> 1*2+0 = 2
 * 读 1 -> 2*2+1 = 5
 */
int getDecimalValue(struct ListNode* head) {
    int result = 0;
    struct ListNode* current = head;

    while (current != NULL) {
        result = result * 2 + current->val;
        current = current->next;
    }

    return result;
}

/* 以下为测试代码，提交到在线评测时通常只需保留上面的函数 */

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 构造示例链表: [1, 0, 1]
    struct ListNode* head = createNode(1);
    head->next = createNode(0);
    head->next->next = createNode(1);

    printf("%d\n", getDecimalValue(head));  // 输出 5

    freeList(head);
    return 0;
}

