// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 将链表中按顺序存储的二进制位转换为十进制整数。
 * 头结点是最高位。
 *
 * 思路：
 * 从头到尾遍历链表。
 * 每读到一个新二进制位，相当于当前结果左移一位（乘 2），
 * 然后再加上当前结点的值。
 *
 * 例如：1 -> 0 -> 1
 * 初始 result = 0
 * 读 1: result = 0 * 2 + 1 = 1
 * 读 0: result = 1 * 2 + 0 = 2
 * 读 1: result = 2 * 2 + 1 = 5
 */
int getDecimalValue(struct ListNode* head) {
    int result = 0;
    struct ListNode* cur = head;

    while (cur != NULL) {
        result = result * 2 + cur->val;
        cur = cur->next;
    }

    return result;
}

/*
