#include <stdio.h>
#include <stdlib.h>

// 定义单链表节点
typedef struct ListNode {
    int val;
    struct ListNode *next;
} ListNode;

// 创建新节点
ListNode* createNode(int val) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 在链表尾部插入节点
void appendNode(ListNode** head, ListNode** tail, int val) {
    ListNode* node = createNode(val);
    if (*head == NULL) {
        *head = node;
        *tail = node;
    } else {
        (*tail)->next = node;
        *tail = node;
    }
}

// 按题意处理链表：保留 M 个，删除 N 个，循环执行
ListNode* keepMDeleteN(ListNode* head, int M, int N) {
    // 如果链表为空，直接返回
    if (head == NULL) {
        return NULL;
    }

    // 如果 M 为 0，说明一个都不保留，整条链表都删除
    if (M == 0) {
        ListNode* cur = head;
        while (cur != NULL) {
            ListNode* tmp = cur;
            cur = cur->next;
            free(tmp);
        }
        return NULL;
    }

    ListNode* cur = head;

    while (cur != NULL) {
        // 1. 保留当前开始的 M 个节点
        // cur 最终应停在这一段保留部分的最后一个节点
        for (int i = 1; i < M && cur != NULL; i++) {
            cur = cur->next;
        }

        // 如果已经到链表末尾，处理结束
        if (cur == NULL) {
            break;
        }

        // 2. 删除接下来的 N 个节点
        ListNode* del = cur->next;
        for (int i = 0; i < N && del != NULL; i++) {
            ListNode* tmp = del;
            del = del->next;
            free(tmp);
        }

        // 3. 将保留段尾部连接到删除段之后的节点
        cur->next = del;

        // 4. 继续处理下一轮
        cur = del;
    }

    return head;
}

// 输出链表
void printList(ListNode* head) {
    ListNode* cur = head;
    int first = 1;
    while (cur != NULL) {
        if (!first) {
            printf(" ");
        }
        printf("%d", cur->val);
        first = 0;
        cur = cur->next;
    }
    printf("\n");
}

// 释放整条链表内存
void freeList(ListNode* head) {
    ListNode* cur = head;
    while (cur != NULL) {
        ListNode* tmp = cur;
        cur = cur->next;
        free(tmp);
    }
}

int main() {
    int L;
    scanf("%d", &L);

    ListNode* head = NULL;
    ListNode* tail = NULL;

    for (int i = 0; i < L; i++) {
        int x;
        scanf("%d", &x);
        appendNode(&head, &tail, x);
    }

    int M, N;
    scanf("%d %d", &M, &N);

    head = keepMDeleteN(head, M, N);
    printList(head);
    freeList(head);

    return 0;
}

