#include <stdio.h>
#include <stdlib.h>

// 单链表节点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 创建新节点
static struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    if (node == NULL) {
        return NULL;
    }
    node->val = val;
    node->next = NULL;
    return node;
}

/*
 * 功能：
 * 给定一个按非递减顺序排列的链表，统计每段连续相同元素的个数，
 * 并把这些“个数”按顺序组成一个新链表返回。
 *
 * 例如：
 * 1 -> 1 -> 2 -> 2 -> 2 -> 5
 * 返回：
 * 2 -> 3 -> 1
 */
struct ListNode* countSegments(struct ListNode* head) {
    // 空链表直接返回空
    if (head == NULL) {
        return NULL;
    }

    // 虚拟头节点，方便统一处理结果链表的插入
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    struct ListNode* cur = head;

    while (cur != NULL) {
        int currentValue = cur->val;
        int count = 0;

        // 统计当前这一段连续相同数字的长度
        while (cur != NULL && cur->val == currentValue) {
            count++;
            cur = cur->next;
        }

        // 将统计结果作为新节点接到结果链表末尾
        struct ListNode* newNode = createNode(count);
        if (newNode == NULL) {
            // 若内存分配失败，释放已经创建的结果链表，避免内存泄漏
            struct ListNode* p = dummy.next;
            while (p != NULL) {
                struct ListNode* temp = p;
                p = p->next;
                free(temp);
            }
            return NULL;
        }

        tail->next = newNode;
        tail = newNode;
    }

    return dummy.next;
}

