#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 按顺序将链表中的结点两两配对比较，统计 Left 和 Right 的得分，
 * 最后返回胜者："Left"、"Right" 或 "Tie"。
 *
 * 说明：
 * 1. 题目保证链表长度为偶数，因此每次都可以安全地取两个结点。
 * 2. 返回的是字符串常量，无需调用者释放。
 */
char* duelWinner(struct ListNode* head) {
    int leftScore = 0;
    int rightScore = 0;

    struct ListNode* cur = head;

    // 每次处理一对相邻结点
    while (cur != NULL && cur->next != NULL) {
        int first = cur->val;
        int second = cur->next->val;

        if (first > second) {
            leftScore++;
        } else if (second > first) {
            rightScore++;
        }
        // 相等时无人得分

        // 跳到下一对
        cur = cur->next->next;
    }

    if (leftScore > rightScore) {
        return "Left";
    } else if (rightScore > leftScore) {
        return "Right";
    } else {
        return "Tie";
    }
}

/*
 * 下面给出一个简单的测试用例（非必须部分）。
 * 在实际评测环境中，通常只提交上面的函数即可。
 */

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 示例：5 -> 2 -> 3 -> 8 -> 7 -> 7 -> 9 -> 1
    struct ListNode* head = createNode(5);
    head->next = createNode(2);
    head->next->next = createNode(3);
    head->next->next->next = createNode(8);
    head->next->next->next->next = createNode(7);
    head->next->next->next->next->next = createNode(7);
    head->next->next->next->next->next->next = createNode(9);
    head->next->next->next->next->next->next->next = createNode(1);

    printf("%s\n", duelWinner(head));  // 预期输出：Left

    freeList(head);
    return 0;
}

