#include <limits.h>
#include <stdlib.h>

/**
 * Definition for singly-linked list.
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 判断链表是否为非递减
 * 只要存在前一个值大于后一个值，就不是非递减。
 */
static int isNonDecreasing(struct ListNode* head) {
    struct ListNode* cur = head;
    while (cur != NULL && cur->next != NULL) {
        if (cur->val > cur->next->val) {
            return 0;
        }
        cur = cur->next;
    }
    return 1;
}

/*
 * 返回使链表变为非递减所需的最少操作次数。
 *
 * 题目规则已经固定了每一步如何操作：
 * 1. 找到相邻结点中和最小的一对
 * 2. 若有多对，取最靠左的一对
 * 3. 合并为一个新值（两者之和）
 *
 * 因此我们只需要按规则不断模拟，直到链表非递减即可。
 */
int minimumPairMerges(struct ListNode* head) {
    int operations = 0;

    /* 长度为 0 或 1 的链表本身就是非递减 */
    if (head == NULL || head->next == NULL) {
        return 0;
    }

    /* 不断重复合并，直到链表非递减 */
    while (!isNonDecreasing(head)) {
        struct ListNode* prev = NULL;          // 当前 pair 的前驱结点
        struct ListNode* cur = head;           // pair 的第一个结点

        struct ListNode* bestPrev = NULL;      // 最优 pair 的前驱
        struct ListNode* bestFirst = head;     // 最优 pair 的第一个结点
        int minSum = INT_MAX;

        /*
         * 扫描所有相邻结点对，找到“和最小”的那一对。
         * 因为只有在 sum < minSum 时更新，所以遇到相等时不会更新，
         * 自然保留了最靠左的那一对。
         */
        while (cur != NULL && cur->next != NULL) {
            int sum = cur->val + cur->next->val;
            if (sum < minSum) {
                minSum = sum;
                bestPrev = prev;
                bestFirst = cur;
            }
            prev = cur;
            cur = cur->next;
        }

        /*
         * 合并 bestFirst 和 bestFirst->next
         * 合并方式：
         * - 第一个结点值改为两者之和
         * - 删除第二个结点
         */
        struct ListNode* second = bestFirst->next;
        bestFirst->val += second->val;
        bestFirst->next = second->next;
        free(second);

        /*
         * 这里 head 不需要修改：
         * 即使合并的是头结点和第二个结点，头结点本身仍然保留。
         */

        operations++;
    }

    return operations;
}

