#include <stdio.h>
#include <stdlib.h>

// 定义链表结点
typedef struct ListNode {
    int val;
    struct ListNode *next;
} ListNode;

// 创建新结点
ListNode* createNode(int val) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 在链表尾部插入结点
void appendNode(ListNode** head, int val) {
    ListNode* node = createNode(val);
    if (*head == NULL) {
        *head = node;
        return;
    }
    ListNode* cur = *head;
    while (cur->next != NULL) {
        cur = cur->next;
    }
    cur->next = node;
}

// 按规则处理链表：保留 m 个，删除 n 个，循环执行
ListNode* trimList(ListNode* head, int m, int n) {
    // 如果链表为空，直接返回
    if (head == NULL) {
        return NULL;
    }

    // 如果 m == 0，表示一个也不保留，整条链表都应删除
    if (m == 0) {
        ListNode* cur = head;
        while (cur != NULL) {
            ListNode* tmp = cur;
            cur = cur->next;
            free(tmp);
        }
        return NULL;
    }

    ListNode* cur = head;

    while (cur != NULL) {
        // 1. 保留当前开始的 m 个结点
        // cur 最终停在这一段需要保留的最后一个结点上
        for (int i = 1; i < m && cur != NULL; i++) {
            cur = cur->next;
        }

        // 如果已经到达链表末尾，则处理结束
        if (cur == NULL) {
            break;
        }

        // 2. 从 cur->next 开始删除 n 个结点
        ListNode* del = cur->next;
        for (int i = 0; i < n && del != NULL; i++) {
            ListNode* tmp = del;
            del = del->next;
            free(tmp);
        }

        // 3. 将保留段的最后一个结点连接到删除段之后的结点
        cur->next = del;

        // 4. 继续从后续结点开始重复操作
        cur = del;
    }

    return head;
}

// 输出链表
void printList(ListNode* head) {
    if (head == NULL) {
        printf("empty\n");
        return;
    }

    ListNode* cur = head;
    while (cur != NULL) {
        printf("%d", cur->val);
        if (cur->next != NULL) {
            printf(" ");
        }
        cur = cur->next;
    }
    printf("\n");
}

// 释放整条链表
void freeList(ListNode* head) {
    while (head != NULL) {
        ListNode* tmp = head;
        head = head->next;
        free(tmp);
    }
}

int main() {
    int len;
    scanf("%d", &len);

    ListNode* head = NULL;
    for (int i = 0; i < len; i++) {
        int x;
        scanf("%d", &x);
        appendNode(&head, x);
    }

    int m, n;
    scanf("%d %d", &m, &n);

    head = trimList(head, m, n);
    printList(head);
    freeList(head);

    return 0;
}

