#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 删除链表中所有值等于 x 的结点
 * 返回删除后的新头结点
 */
struct ListNode* deleteTarget(struct ListNode* head, int x) {
    // 创建一个虚拟头结点，方便处理头结点需要被删除的情况
    struct ListNode dummy;
    dummy.next = head;

    // cur 指向“当前结点的前一个结点”
    struct ListNode* cur = &dummy;

    while (cur->next != NULL) {
        // 如果下一个结点需要删除
        if (cur->next->val == x) {
            struct ListNode* toDelete = cur->next;
            cur->next = toDelete->next;  // 跳过该结点
            free(toDelete);              // 释放内存
        } else {
            // 否则继续向后移动
            cur = cur->next;
        }
    }

    return dummy.next;
}

