    MyLinkedSet* obj = (MyLinkedSet*)malloc(sizeof(MyLinkedSet));
    obj->head = (Node*)malloc(sizeof(Node));
    obj->head->next = NULL;
    return obj;
}

/*
 * 判断 key 是否存在于集合中
 */
bool myLinkedSetContains(MyLinkedSet* obj, int key) {
    Node* cur = obj->head->next;
    while (cur != NULL) {
        if (cur->key == key) {
            return true;
        }
        cur = cur->next;
    }
    return false;
}

/*
 * 向集合中添加 key
 * 如果 key 已经存在，则不重复插入
 */
