 */
void myLinkedSetRemove(MyLinkedSet* obj, int key) {
    Node* prev = obj->head;
    Node* cur = obj->head->next;

    while (cur != NULL) {
        if (cur->key == key) {
            prev->next = cur->next;
            free(cur);
            return;
        }
        prev = cur;
        cur = cur->next;
    }
}

/*
 * 释放整个集合占用的内存
 */
void myLinkedSetFree(MyLinkedSet* obj) {
    Node* cur = obj->head;
    while (cur != NULL) {
        Node* temp = cur;
        cur = cur->next;
        free(temp);
    }
    free(obj);
}

