#include <limits.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 判断链表是否为非递减
static int isNonDecreasing(struct ListNode* head) {
    struct ListNode* cur = head;
    while (cur != NULL && cur->next != NULL) {
        if (cur->val > cur->next->val) {
            return 0;  // 不是非递减
        }
        cur = cur->next;
    }
    return 1;  // 是非递减
}

int minMergeOperations(struct ListNode* head) {
    int operations = 0;

    // 当链表还不是非递减时，不断执行合并操作
    while (!isNonDecreasing(head)) {
        struct ListNode* cur = head;
        struct ListNode* prev = NULL;

        // 记录“和值最小且最靠左”的那一对相邻结点
        struct ListNode* bestPrev = NULL;   // 最优 pair 的前一个结点
        struct ListNode* bestFirst = NULL;  // 最优 pair 的第一个结点
        int minSum = INT_MAX;

        // 扫描所有相邻结点对
        while (cur != NULL && cur->next != NULL) {
            int sum = cur->val + cur->next->val;

            // 只有在 sum 更小时才更新
            // 如果相等则不更新，这样天然保留“最靠左”的那一对
            if (sum < minSum) {
                minSum = sum;
                bestPrev = prev;
                bestFirst = cur;
            }

            prev = cur;
            cur = cur->next;
        }

        // 合并 bestFirst 和 bestFirst->next
        struct ListNode* second = bestFirst->next;
        bestFirst->val = bestFirst->val + second->val;
        bestFirst->next = second->next;

        // 释放被删除的结点
        free(second);

        operations++;
    }

    return operations;
}

