#include <stdio.h>
#include <stdlib.h>

/*
 * 单链表结点定义
 */
typedef struct Node {
    int val;
    struct Node *next;
} Node;

/*
 * 创建新结点
 */
Node* createNode(int val) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->val = val;
    node->next = NULL;
    return node;
}

/*
 * 尾插法建立链表
 */
Node* buildList(int len) {
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < len; i++) {
        int x;
        scanf("%d", &x);
        Node *node = createNode(x);
        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }
    return head;
}

/*
 * 按题意处理链表：保留 m 个，删除 n 个，循环执行
 */
Node* keepMDeleteN(Node *head, int m, int n) {
    /*
     * 如果链表为空，直接返回
     */
    if (head == NULL) return NULL;

    /*
     * m == 0 表示每轮都不保留，整条链表都会被删除
     */
    if (m == 0) {
        Node *cur = head;
        while (cur != NULL) {
            Node *tmp = cur;
            cur = cur->next;
            free(tmp);
        }
        return NULL;
    }

    /*
     * n == 0 表示不删除任何结点，原链表直接返回
     */
    if (n == 0) return head;

    Node *cur = head;

    while (cur != NULL) {
        /*
         * 1. 保留 m 个结点
         * cur 最终应停在这一段保留区间的最后一个结点上
         */
        for (int i = 1; i < m && cur != NULL; i++) {
            cur = cur->next;
        }

        /*
         * 如果保留过程中已经到链表末尾，则处理结束
         */
        if (cur == NULL) break;

        /*
         * 2. 从 cur->next 开始删除 n 个结点
         */
        Node *toDelete = cur->next;
        for (int i = 0; i < n && toDelete != NULL; i++) {
            Node *tmp = toDelete;
            toDelete = toDelete->next;
            free(tmp);
        }

        /*
         * 3. 将保留段尾部与删除后的剩余部分连接
         */
        cur->next = toDelete;

        /*
         * 4. 继续从下一段开始处理
         */
        cur = toDelete;
    }

    return head;
}

/*
 * 输出链表
 */
void printList(Node *head) {
    if (head == NULL) {
        printf("NULL\n");
        return;
    }

    Node *cur = head;
    while (cur != NULL) {
        printf("%d", cur->val);
        if (cur->next != NULL) printf(" ");
        cur = cur->next;
    }
    printf("\n");
}

/*
 * 释放链表内存
 */
void freeList(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        Node *tmp = cur;
        cur = cur->next;
        free(tmp);
    }
}

int main() {
    int len, m, n;
    scanf("%d %d %d", &len, &m, &n);

    Node *head = buildList(len);
    head = keepMDeleteN(head, m, n);
    printList(head);
    freeList(head);

    return 0;
}

