#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 返回两条单链表的第一个公共结点；如果不相交则返回 NULL。
 *
 * 解题思路：双指针法
 * 1. 定义两个指针 pA 和 pB，分别从 headA 和 headB 出发。
 * 2. 每次都向后移动一个结点。
 * 3. 当某个指针走到链表末尾时，就跳到另一条链表的头部继续走。
 * 4. 如果两链表相交，两个指针最终会在第一个公共结点相遇。
 * 5. 如果不相交，两个指针最终都会变成 NULL，此时循环结束。
 *
 * 时间复杂度：O(m + n)
 * 空间复杂度：O(1)
 */
struct ListNode *getFirstCommonNode(struct ListNode *headA, struct ListNode *headB) {
    struct ListNode *pA = headA;
    struct ListNode *pB = headB;

    // 当两个指针相等时，可能是公共结点，也可能都是 NULL
    while (pA != pB) {
        // pA 走完 A 链表后，转到 B 链表头继续走
        if (pA == NULL) {
            pA = headB;
        } else {
            pA = pA->next;
        }

        // pB 走完 B 链表后，转到 A 链表头继续走
        if (pB == NULL) {
            pB = headA;
        } else {
            pB = pB->next;
        }
    }

    return pA;
}

/*
 * 下面代码仅用于本地测试，提交到题目平台时通常只需保留上面的函数。
 */

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

int main() {
    /*
     * 构造如下相交链表：
     * A: 1 -> 3 -> 5 -> 7 -> 9
     * B: 2 ------^
     *            |
     *            5 -> 7 -> 9
     */

    // 公共部分
    struct ListNode *c1 = createNode(5);
    struct ListNode *c2 = createNode(7);
    struct ListNode *c3 = createNode(9);
    c1->next = c2;
    c2->next = c3;

    // 链表 A 独有部分
    struct ListNode *a1 = createNode(1);
    struct ListNode *a2 = createNode(3);
    a1->next = a2;
    a2->next = c1;

    // 链表 B 独有部分
    struct ListNode *b1 = createNode(2);
    b1->next = c1;

    struct ListNode *ans = getFirstCommonNode(a1, b1);

    if (ans != NULL) {
        printf("第一个公共结点的值为: %d\n", ans->val);
    } else {
        printf("两条链表没有公共结点\n");
    }

    return 0;
}

