#include <stdbool.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
思路：
1. 先遍历链表，统计链表长度 n。
2. 申请一个长度为 n 的数组，把链表中的值依次存进去。
3. 使用双指针从数组两端向中间比较：
   - 如果有任意一对不相等，返回 false。
   - 全部相等，返回 true。

时间复杂度：O(n)
空间复杂度：O(n)

这是简单难度下非常直观、易于理解的做法。
*/
bool isMirrorList(struct ListNode* head) {
    int n = 0;
    struct ListNode* cur = head;

    // 第一次遍历：统计结点个数
    while (cur != NULL) {
        n++;
        cur = cur->next;
    }

    // 申请数组保存链表中的值
    int* arr = (int*)malloc(sizeof(int) * n);
    if (arr == NULL) {
        // 内存申请失败时，保守返回 false
        return false;
    }

    // 第二次遍历：把链表值存入数组
    cur = head;
    int i = 0;
    while (cur != NULL) {
        arr[i++] = cur->val;
        cur = cur->next;
    }

    // 双指针判断是否为回文序列
    int left = 0;
    int right = n - 1;
    while (left < right) {
        if (arr[left] != arr[right]) {
            free(arr);
            return false;
        }
        left++;
        right--;
    }

    free(arr);
    return true;
}

