#include <stdbool.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 反转链表，返回反转后的头结点
static struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode* prev = NULL;
    struct ListNode* cur = head;

    while (cur != NULL) {
        struct ListNode* nextNode = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nextNode;
    }

    return prev;
}

bool isSymmetricList(struct ListNode* head) {
    // 空链表或只有一个结点，一定对称
    if (head == NULL || head->next == NULL) {
        return true;
    }

    // 1. 使用快慢指针找到链表中点
    struct ListNode* slow = head;
    struct ListNode* fast = head;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }

    // 2. 如果链表长度为奇数，slow 目前在中间结点，需要跳过它
    if (fast != NULL) {
        slow = slow->next;
    }

    // 3. 反转后半部分链表
    struct ListNode* secondHalf = reverseList(slow);

    // 4. 从前半部分和反转后的后半部分同时开始比较
    struct ListNode* p1 = head;
    struct ListNode* p2 = secondHalf;

    while (p2 != NULL) {
        if (p1->val != p2->val) {
            return false;
        }
        p1 = p1->next;
        p2 = p2->next;
    }

    return true;
}

