#include <stdlib.h>

// 双向链表结点定义
struct Node {
    int val;
    struct Node* prev;
    struct Node* next;
};

/*
 * 功能：将双向链表中的值按从前到后的顺序复制到数组中
 * 参数：
 *   head       - 双向链表头结点
 *   returnSize - 返回数组长度
 * 返回：
 *   动态分配的整型数组指针；若链表为空，返回 NULL
 */
int* listToArray(struct Node* head, int* returnSize) {
    // 判空：如果链表为空，数组长度为 0，返回 NULL
    if (head == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 第一次遍历：统计链表长度
    int count = 0;
    struct Node* cur = head;
    while (cur != NULL) {
        count++;
        cur = cur->next;
    }

    // 记录返回数组长度
    *returnSize = count;

    // 为结果数组分配空间
    int* arr = (int*)malloc(sizeof(int) * count);
    if (arr == NULL) {
        // 内存分配失败时，按空结果处理
        *returnSize = 0;
        return NULL;
    }

    // 第二次遍历：将链表中的值依次写入数组
    cur = head;
    int index = 0;
    while (cur != NULL) {
        arr[index++] = cur->val;
        cur = cur->next;
    }

    return arr;
}

