#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

// 创建新结点
Node* createNode(int val) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->val = val;
    node->next = NULL;
    return node;
}

// 在链表尾部插入结点
void appendNode(Node **head, Node **tail, int val) {
    Node *node = createNode(val);
    if (*head == NULL) {
        *head = node;
        *tail = node;
    } else {
        (*tail)->next = node;
        *tail = node;
    }
}

// 按规则整理链表：保留 m 个，删除 k 个，循环进行
Node* processList(Node *head, int m, int k) {
    // 如果链表为空，直接返回
    if (head == NULL) {
        return NULL;
    }

    // 如果 m == 0，表示一个也不保留，结果为空链表
    if (m == 0) {
        Node *cur = head;
        while (cur != NULL) {
            Node *tmp = cur;
            cur = cur->next;
            free(tmp);
        }
        return NULL;
    }

    Node *cur = head;
    Node *prev = NULL;

    while (cur != NULL) {
        // 1. 保留 m 个结点
        for (int i = 0; i < m && cur != NULL; i++) {
            prev = cur;
            cur = cur->next;
        }

        // 如果已经走到链表末尾，结束
        if (cur == NULL) {
            break;
        }

        // 2. 删除接下来的 k 个结点
        Node *toDelete = cur;
        for (int i = 0; i < k && cur != NULL; i++) {
            Node *tmp = cur;
            cur = cur->next;
            free(tmp);
        }

        // 将保留段的末尾与后续未删除部分连接起来
        prev->next = cur;
    }

    return head;
}

// 输出链表
void printList(Node *head) {
    if (head == NULL) {
        printf("empty\n");
        return;
    }

    Node *cur = head;
    int first = 1;
    while (cur != NULL) {
        if (!first) {
            printf(" ");
        }
        printf("%d", cur->val);
        first = 0;
        cur = cur->next;
    }
    printf("\n");
}

// 释放链表内存
void freeList(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        Node *tmp = cur;
        cur = cur->next;
        free(tmp);
    }
}

int main() {
    int n, m, k;
    scanf("%d %d %d", &n, &m, &k);

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        appendNode(&head, &tail, x);
    }

    head = processList(head, m, k);
    printList(head);
    freeList(head);

    return 0;
}

