#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 返回两个无环单链表的第一个公共结点；如果不存在公共结点，返回 NULL。
 *
 * 思路：双指针法
 * 1. 指针 pA 从 headA 出发，pB 从 headB 出发。
 * 2. 当 pA 走到链表末尾时，让它跳到 headB 继续走。
 *    当 pB 走到链表末尾时，让它跳到 headA 继续走。
 * 3. 如果两个链表相交，那么两个指针最终会在第一个公共结点相遇。
 * 4. 如果不相交，那么两个指针最终都会变成 NULL，循环结束。
 *
 * 时间复杂度：O(m + n)
 * 空间复杂度：O(1)
 */
struct ListNode *getMergeNode(struct ListNode *headA, struct ListNode *headB) {
    struct ListNode *pA = headA;
    struct ListNode *pB = headB;

    // 当两个指针相等时，可能是公共结点，也可能同为 NULL
    while (pA != pB) {
        pA = (pA == NULL) ? headB : pA->next;
        pB = (pB == NULL) ? headA : pB->next;
    }

    return pA;
}

/* =========================
   以下为测试辅助代码（提交到只要求函数的平台时可删除）
   ========================= */

// 创建新结点
