    struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 打印结果
void printResult(struct ListNode *node) {
    if (node == NULL) {
        printf("NULL\n");
    } else {
        printf("%d\n", node->val);
    }
}

int main() {
    /*
     * 构造示例：
     * A: 1 -> 3 -> 7 -> 8 -> 10
     * B: 2 ------^ 
     */

    // 公共部分
    struct ListNode *c1 = createNode(8);
    struct ListNode *c2 = createNode(10);
    c1->next = c2;

    // 链表 A
    struct ListNode *a1 = createNode(1);
    struct ListNode *a2 = createNode(3);
    struct ListNode *a3 = createNode(7);
    a1->next = a2;
    a2->next = a3;
    a3->next = c1;

    // 链表 B
    struct ListNode *b1 = createNode(2);
    b1->next = c1;

    struct ListNode *ans = getMergeNode(a1, b1);
    printResult(ans);  // 输出 8

    return 0;
}

