#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：反转单链表，并返回新的头结点
 * 思路：使用三个指针进行迭代反转
 * prev：当前结点反转后应该指向的前一个结点
 * curr：当前正在处理的结点
 * nextNode：提前保存 curr 的下一个结点，防止链表断开
 */
struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode *prev = NULL;
    struct ListNode *curr = head;

    while (curr != NULL) {
        // 先保存下一个结点
        struct ListNode *nextNode = curr->next;

        // 反转当前结点的指针方向
        curr->next = prev;

        // prev 和 curr 同时向前推进
        prev = curr;
        curr = nextNode;
    }

    // prev 最终会指向反转后的头结点
    return prev;
}

/******************** 以下为辅助测试代码，可根据OJ要求删除 ********************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int arr[], int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* tail = head;

    for (int i = 1; i < size; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return head;
}

// 打印链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        if (head->next != NULL) {
            printf(",");
        }
        head = head->next;
    }
    printf("]\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);

    printf("原链表: ");
    printList(head);

    head = reverseList(head);

    printf("反转后: ");
    printList(head);

    freeList(head);
    return 0;
}

