#include <stdbool.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 反转链表，返回反转后的新头结点
static struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode* prev = NULL;
    struct ListNode* curr = head;

    while (curr != NULL) {
        struct ListNode* nextNode = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextNode;
    }

    return prev;
}

bool isSymmetricList(struct ListNode* head) {
    // 空链表或只有一个结点时，一定对称
    if (head == NULL || head->next == NULL) {
        return true;
    }

    // 使用快慢指针找到链表中点
    struct ListNode* slow = head;
    struct ListNode* fast = head;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }

    // 如果 fast != NULL，说明链表长度为奇数
    // 此时 slow 正好在中间结点，应跳过中间结点
    if (fast != NULL) {
        slow = slow->next;
    }

    // 反转后半段链表
    struct ListNode* secondHalf = reverseList(slow);
    struct ListNode* p1 = head;
    struct ListNode* p2 = secondHalf;

    // 逐个比较前半段和反转后的后半段
    while (p2 != NULL) {
        if (p1->val != p2->val) {
            return false;
        }
        p1 = p1->next;
        p2 = p2->next;
    }

    return true;
}

