#include <stdio.h>
#include <stdlib.h>

// 单链表节点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 按顺序将链表节点两两分组比较：
 * - 每组第一个节点属于 A 队
 * - 每组第二个节点属于 B 队
 * - 值更大的队伍得 1 分
 * 最后返回胜者："A"、"B" 或 "Draw"
 */
char* findWinner(struct ListNode* head) {
    int scoreA = 0;
    int scoreB = 0;

    // 每次处理两个相邻节点
    while (head != NULL && head->next != NULL) {
        int a = head->val;         // A 队节点值
        int b = head->next->val;   // B 队节点值

        if (a > b) {
            scoreA++;
        } else if (a < b) {
            scoreB++;
        }
        // 如果相等，则本轮无人得分

        // 跳到下一组
        head = head->next->next;
    }

    if (scoreA > scoreB) {
        return "A";
    } else if (scoreA < scoreB) {
        return "B";
    } else {
        return "Draw";
    }
}

/****************************
 * 以下为本地测试辅助代码
 ****************************/

// 创建新节点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int arr[], int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* cur = head;

    for (int i = 1; i < size; i++) {
        cur->next = createNode(arr[i]);
        cur = cur->next;
    }

    return head;
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {9, 3, 8, 2, 5, 6};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);

    printf("%s\n", findWinner(head));  // 预期输出: A

    freeList(head);
    return 0;
}

