#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

/*
 * 功能：
 * 给定一个按非递减顺序排列的链表，统计每一段连续相同数字的出现次数，
 * 并把这些次数按顺序组成一个新链表返回。
 *
 * 例如：
 * 1 -> 1 -> 2 -> 2 -> 2 -> 5
 * 返回：
 * 2 -> 3 -> 1
 */
struct ListNode* frequenciesOfRuns(struct ListNode* head) {
    // 空链表直接返回空
    if (head == NULL) {
        return NULL;
    }

    // 使用哑结点方便构造结果链表
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    struct ListNode* cur = head;

    while (cur != NULL) {
        int currentValue = cur->val; // 当前这一段的值
        int count = 0;               // 当前值连续出现次数

        // 统计这一段连续相同值的长度
        while (cur != NULL && cur->val == currentValue) {
            count++;
            cur = cur->next;
        }

        // 将统计结果作为新结点接到结果链表末尾
        tail->next = createNode(count);
        tail = tail->next;
    }

    return dummy.next;
}

/********************
 * 以下为辅助测试代码，可根据需要保留或删除
 ********************/

// 尾插法构建链表
struct ListNode* buildList(int arr[], int n) {
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    for (int i = 0; i < n; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return dummy.next;
}

// 打印链表
void printList(struct ListNode* head) {
    struct ListNode* cur = head;
    while (cur != NULL) {
        printf("%d", cur->val);
        if (cur->next != NULL) {
            printf(" -> ");
        }
        cur = cur->next;
    }
    printf("\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 示例：1 -> 1 -> 2 -> 2 -> 2 -> 5
    int arr[] = {1, 1, 2, 2, 2, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = buildList(arr, n);
    struct ListNode* result = frequenciesOfRuns(head);

    // 输出结果：2 -> 3 -> 1
    printList(result);

    // 释放内存
    freeList(head);
    freeList(result);

    return 0;
}

