#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 功能：删除有序链表中的重复结点，只保留每个值的第一个结点
 * 返回：处理后的链表头结点
 */
struct ListNode* compressSortedList(struct ListNode* head) {
    // 空链表或只有一个结点时，直接返回
    if (head == NULL || head->next == NULL) {
        return head;
    }

    struct ListNode* cur = head;

    // 因为链表有序，所以重复元素一定相邻
    while (cur != NULL && cur->next != NULL) {
        if (cur->val == cur->next->val) {
            // 找到重复结点，删除 cur->next
            struct ListNode* temp = cur->next;
            cur->next = cur->next->next;
            free(temp);
        } else {
            // 当前值和下一个值不同，继续向后移动
            cur = cur->next;
        }
    }

    return head;
}

/***********************
 * 以下为辅助测试代码
 ***********************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int arr[], int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* tail = head;

    for (int i = 1; i < size; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return head;
}

// 打印链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        if (head->next != NULL) {
            printf(",");
        }
        head = head->next;
    }
    printf("]\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 示例：head = [1,1,2,3,3]
    int arr[] = {1, 1, 2, 3, 3};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);

    printf("原链表: ");
    printList(head);

    head = compressSortedList(head);

    printf("去重后: ");
    printList(head);

    freeList(head);
    return 0;
}

