#include <stdio.h>
#include <stdlib.h>

// 双向链表结点定义
struct DoublyNode {
    int val;
    struct DoublyNode* prev;
    struct DoublyNode* next;
};

/*
 * 功能：将双向链表中的元素按从头到尾的顺序拷贝到数组中
 * 参数：
 *   head       - 双向链表头结点
 *   returnSize - 输出参数，用于返回数组长度
 * 返回：
 *   动态分配的整型数组；如果链表为空，返回 NULL
 */
int* listToArray(struct DoublyNode* head, int* returnSize) {
    // 判空保护
    if (returnSize == NULL) {
        return NULL;
    }

    // 如果链表为空，长度为 0，返回 NULL
    if (head == NULL) {
        *returnSize = 0;
        return NULL;
    }

    // 第一次遍历：统计链表长度
    int count = 0;
    struct DoublyNode* cur = head;
    while (cur != NULL) {
        count++;
        cur = cur->next;
    }

    // 记录返回数组长度
    *returnSize = count;

    // 为数组申请空间
    int* arr = (int*)malloc(sizeof(int) * count);
    if (arr == NULL) {
        // 内存申请失败时，通常将长度置 0 并返回 NULL
        *returnSize = 0;
        return NULL;
    }

    // 第二次遍历：将链表值复制到数组中
    cur = head;
    int i = 0;
    while (cur != NULL) {
        arr[i++] = cur->val;
        cur = cur->next;
    }

    return arr;
}

/*
 * 下面是一个简单的本地测试示例。
 * 在线判题时通常只需要提交上面的函数即可。
 */

// 创建新结点
struct DoublyNode* createNode(int val) {
    struct DoublyNode* node = (struct DoublyNode*)malloc(sizeof(struct DoublyNode));
    node->val = val;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

int main() {
    // 构造链表：1 <-> 3 <-> 5 <-> 7
    struct DoublyNode* n1 = createNode(1);
    struct DoublyNode* n2 = createNode(3);
    struct DoublyNode* n3 = createNode(5);
    struct DoublyNode* n4 = createNode(7);

    n1->next = n2;
    n2->prev = n1;
    n2->next = n3;
    n3->prev = n2;
    n3->next = n4;
    n4->prev = n3;

    int size = 0;
    int* arr = listToArray(n1, &size);

    // 输出结果
    printf("size = %d\n", size);
    printf("[");
    for (int i = 0; i < size; i++) {
        printf("%d", arr[i]);
        if (i < size - 1) {
            printf(", ");
        }
    }
    printf("]\n");

    // 释放数组内存
    free(arr);

    // 释放链表内存
    free(n1);
    free(n2);
    free(n3);
    free(n4);

    return 0;
}

