#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 功能：返回链表后半段的起始结点
 * 规则：
 * 1. 若链表长度为奇数，返回正中间结点
 * 2. 若链表长度为偶数，返回两个中间结点中靠后的那个
 *
 * 思路：快慢指针
 * - slow 每次走 1 步
 * - fast 每次走 2 步
 * 当 fast 到达链表末尾时，slow 恰好在目标位置
 */
struct ListNode* secondHalfStart(struct ListNode* head) {
    struct ListNode *slow = head;
    struct ListNode *fast = head;

    // fast 每次前进两步，slow 每次前进一步
    // 当 fast 不能继续前进两步时，slow 就在中间位置
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }

    return slow;
}

/******************** 以下为测试代码，可根据评测平台要求删除 ********************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int arr[], int n) {
    if (n == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* cur = head;

    for (int i = 1; i < n; i++) {
        cur->next = createNode(arr[i]);
        cur = cur->next;
    }

    return head;
}

// 输出从某个结点开始的链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        if (head->next != NULL) {
            printf(",");
        }
        head = head->next;
    }
    printf("]\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr1[] = {1, 2, 3, 4, 5};
    struct ListNode* list1 = createList(arr1, 5);
    struct ListNode* ans1 = secondHalfStart(list1);
    printList(ans1);  // 预期输出: [3,4,5]
    freeList(list1);

    int arr2[] = {10, 20, 30, 40, 50, 60};
    struct ListNode* list2 = createList(arr2, 6);
    struct ListNode* ans2 = secondHalfStart(list2);
    printList(ans2);  // 预期输出: [40,50,60]
    freeList(list2);

    return 0;
}

