#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：
 * 将链表中表示的二进制数转换为十进制整数并返回。
 *
 * 思路：
 * 从头结点开始遍历链表，当前结果记为 result。
 * 每读取一个新二进制位 x，相当于：
 *   result = result * 2 + x
 * 也可以写成位运算形式：
 *   result = (result << 1) | x
 */
int getDecimalValue(struct ListNode* head) {
    int result = 0;
    struct ListNode* cur = head;

    while (cur != NULL) {
        result = (result << 1) | cur->val;
        cur = cur->next;
    }

    return result;
}

/************ 以下为测试代码，可根据需要保留或删除 ************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 构造示例链表：[1,0,1]
    struct ListNode* head = createNode(1);
    head->next = createNode(0);
    head->next->next = createNode(1);

    int ans = getDecimalValue(head);
    printf("%d\n", ans);  // 输出 5

    freeList(head);
    return 0;
}

