#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 删除链表中所有值等于 x 的结点
 * 返回删除后的新头结点
 */
struct ListNode* deleteTarget(struct ListNode* head, int x) {
    // 创建虚拟头结点，方便处理头结点被删除的情况
    struct ListNode dummy;
    dummy.next = head;

    // cur 始终指向“当前待检查结点”的前一个结点
    struct ListNode *cur = &dummy;

    while (cur->next != NULL) {
        if (cur->next->val == x) {
            // 找到需要删除的结点
            struct ListNode *toDelete = cur->next;
            cur->next = toDelete->next;  // 跳过该结点
            free(toDelete);              // 释放内存
        } else {
            // 当前结点不需要删除，继续向后移动
            cur = cur->next;
        }
    }

    return dummy.next;
}

/******************** 以下为辅助测试代码，可根据平台要求保留或删除 ********************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 尾插法创建链表
struct ListNode* buildList(int arr[], int n) {
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    for (int i = 0; i < n; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return dummy.next;
}

// 打印链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        if (head->next != NULL) {
            printf(",");
        }
        head = head->next;
    }
    printf("]\n");
}

// 释放整个链表
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {1, 2, 3, 2, 4};
    int n = sizeof(arr) / sizeof(arr[0]);
    int x = 2;

    struct ListNode* head = buildList(arr, n);

    printf("原链表: ");
    printList(head);

    head = deleteTarget(head, x);

    printf("删除后: ");
    printList(head);

    freeList(head);
    return 0;
}

