#include <stdbool.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 函数功能：判断链表中是否存在环
 * 返回值：
 *   true  - 存在环
 *   false - 不存在环
 *
 * 解题思路：快慢指针（Floyd 判圈算法）
 * 1. slow 每次走 1 步，fast 每次走 2 步
 * 2. 如果链表有环，fast 和 slow 迟早会相遇
 * 3. 如果链表无环，fast 或 fast->next 会先到达 NULL
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
bool hasCycle(struct ListNode *head) {
    // 空链表或只有一个结点且没有自环，不可能形成普通环
    if (head == NULL || head->next == NULL) {
        return false;
    }

    struct ListNode *slow = head;
    struct ListNode *fast = head;

    // fast 每次走两步，因此需要判断 fast 和 fast->next 是否为空
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;           // 慢指针走一步
        fast = fast->next->next;     // 快指针走两步

        // 如果相遇，说明存在环
        if (slow == fast) {
            return true;
        }
