#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/**
 * 单链表节点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/**
 * 题意：
 * 只保留值出现在 nums 中的节点。
 * 若若干保留节点在原链表中位置连续，则构成一个连续片段。
 * 返回所有片段长度平方和。
 *
 * 思路：
 * 1. 用一个布尔数组/标记表记录哪些值在 nums 中。
 * 2. 遍历链表，统计当前连续片段长度 len。
 *    - 若当前节点值在 nums 中：len++
 *    - 否则：说明一个片段结束，将 len^2 加入答案，并清零 len
 * 3. 遍历结束后，若 len > 0，再补一次 len^2。
 *
 * 由于题目给出值范围 0 <= val < 1e5，可以直接开数组标记。
 * 时间复杂度：O(n + numsSize)
 * 空间复杂度：O(MAXV)
 */
long long componentScore(struct ListNode* head, int* nums, int numsSize) {
    const int MAXV = 100000;
    bool *exist = (bool *)calloc(MAXV, sizeof(bool));
    if (exist == NULL) {
        return -1; // 内存分配失败时返回 -1（实际竞赛环境一般不会发生）
    }

    // 标记 nums 中出现的值
    for (int i = 0; i < numsSize; i++) {
        exist[nums[i]] = true;
    }

    long long ans = 0;
    long long len = 0;
    struct ListNode* cur = head;

    while (cur != NULL) {
        if (exist[cur->val]) {
            // 当前节点属于保留集合，延长当前片段
            len++;
        } else {
            // 当前片段结束，结算平方和
            if (len > 0) {
                ans += len * len;
                len = 0;
            }
        }
        cur = cur->next;
    }

    // 若链表结束时仍有未结算片段，补上
    if (len > 0) {
        ans += len * len;
    }

    free(exist);
    return ans;
}

