#include <stdio.h>
#include <stdlib.h>

// 单链表节点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
题意：
将链表每连续 3 个节点 a -> b -> c 重排为 c -> a -> b。
若最后不足 3 个节点，则保持原顺序。

例如：
1 -> 2 -> 3 -> 4 -> 5 -> 6
变为：
3 -> 1 -> 2 -> 6 -> 4 -> 5

思路：
1. 使用哑节点 dummy，方便处理头节点被修改的情况。
2. 每次检查当前位置开始是否至少有 3 个节点。
3. 若有 3 个节点 first, second, third：
   原结构：prev -> first -> second -> third -> nextGroup
   调整为：prev -> third -> first -> second -> nextGroup
4. 更新 prev 到当前这一组重排后的最后一个节点 second，继续处理下一组。
5. 若不足 3 个节点，结束。

时间复杂度：O(n)
空间复杂度：O(1)
*/
struct ListNode* rearrangeTriples(struct ListNode* head) {
    // 创建哑节点，统一处理头节点变化
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    // prev 指向每一组处理前的前驱节点
    struct ListNode *prev = &dummy;

    while (prev->next != NULL) {
        // 尝试取出当前组的 3 个节点
        struct ListNode *first = prev->next;
        if (first == NULL) {
            break;
        }

        struct ListNode *second = first->next;
        if (second == NULL) {
            break; // 不足 3 个
        }

        struct ListNode *third = second->next;
        if (third == NULL) {
            break; // 不足 3 个
        }

        // 记录下一组起点
        struct ListNode *nextGroup = third->next;

        // 重排：a -> b -> c 变为 c -> a -> b
        prev->next = third;
        third->next = first;
        first->next = second;
        second->next = nextGroup;

        // 更新 prev，进入下一组
        prev = second;
    }

    return dummy.next;
}

/**************** 以下为辅助测试代码，可根据平台要求删除 ****************/

// 创建新节点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int* arr, int size) {
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    for (int i = 0; i < size; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return dummy.next;
}

// 打印链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        head = head->next;
        if (head != NULL) {
            printf(",");
        }
    }
    printf("]\n");
}

// 释放链表
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);
    printf("重排前: ");
    printList(head);

    head = rearrangeTriples(head);
    printf("重排后: ");
    printList(head);

    freeList(head);
    return 0;
}

