#include <stdlib.h>

// 节点定义
struct Node {
    int val;
    struct Node *next;
};

/**
 * 向循环有序单链表中插入一个值，插入后仍保持循环有序。
 *
 * 参数：
 *   head      - 循环链表中的任意一个节点，可能为 NULL
 *   insertVal - 待插入的值
 *
 * 返回：
 *   插入后的链表中原来的 head；若原链表为空，则返回新建节点
 */
struct Node* insert(struct Node* head, int insertVal) {
    // 情况1：空链表，创建一个自环节点即可
    if (head == NULL) {
        struct Node* node = (struct Node*)malloc(sizeof(struct Node));
        node->val = insertVal;
        node->next = node;
        return node;
    }

    struct Node* cur = head;

    while (1) {
        struct Node* nxt = cur->next;

        // 情况2：正常升序区间，insertVal 落在 [cur->val, nxt->val] 之间
        // 例如：1 -> 3，此时插入 2
        if (cur->val <= insertVal && insertVal <= nxt->val) {
            break;
        }

        // 情况3：遇到“最大值 -> 最小值”的断点
        // 例如：4 -> 1
        // 如果 insertVal >= 最大值，或者 insertVal <= 最小值，都应插在这里
        if (cur->val > nxt->val) {
            if (insertVal >= cur->val || insertVal <= nxt->val) {
                break;
            }
        }

        cur = cur->next;

        // 情况4：绕了一整圈仍未找到合适位置
        // 说明链表所有值都相同，或者 insertVal 可插在任意等价位置
        if (cur == head) {
            break;
        }
    }

    // 在 cur 和 cur->next 之间插入新节点
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->val = insertVal;
    node->next = cur->next;
    cur->next = node;

    return head;
}

