#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 功能：将链表中第 start 到第 end 个结点原地翻转，并返回新链表头结点
 * 思路：
 * 1. 使用哑结点 dummy，方便处理 start == 1 的情况。
 * 2. 先让 pre 指向待翻转区间前一个结点。
 * 3. 再通过“头插法”在区间内原地翻转：
 *    每次把 curr 后面的一个结点摘下来，插到 pre 后面。
 * 4. 最终返回 dummy.next。
 *
 * 例如：1 -> 2 -> 3 -> 4 -> 5, start=2, end=4
 * pre 指向 1，curr 指向 2
 * 第一次调整后：1 -> 3 -> 2 -> 4 -> 5
 * 第二次调整后：1 -> 4 -> 3 -> 2 -> 5
 */
struct ListNode* reverseRange(struct ListNode* head, int start, int end) {
    // 如果链表为空，或者翻转区间长度为 1，直接返回
    if (head == NULL || start == end) {
        return head;
    }

    // 创建哑结点，统一处理头结点参与翻转的情况
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    // pre 最终要走到待翻转区间前一个结点
    struct ListNode *pre = &dummy;
    for (int i = 1; i < start; i++) {
        pre = pre->next;
    }

    // curr 指向待翻转区间的第一个结点
    struct ListNode *curr = pre->next;

    // 进行 end-start 次头插操作
    for (int i = 0; i < end - start; i++) {
        // nextNode 是 curr 后面要被摘出来插到前面的结点
        struct ListNode *nextNode = curr->next;

        // 从原位置摘除 nextNode
        curr->next = nextNode->next;

        // 把 nextNode 插入到 pre 后面
        nextNode->next = pre->next;
        pre->next = nextNode;
    }

    return dummy.next;
}

/********************* 以下为辅助测试代码，可按需保留或删除 *********************/

// 创建新结点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* buildList(int arr[], int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* tail = head;

    for (int i = 1; i < size; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return head;
}

// 打印链表
void printList(struct ListNode* head) {
    struct ListNode* p = head;
    printf("[");
    while (p != NULL) {
        printf("%d", p->val);
        if (p->next != NULL) {
            printf(",");
        }
        p = p->next;
    }
    printf("]\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = buildList(arr, size);

    int start = 2, end = 4;
    head = reverseRange(head, start, end);

    printList(head);  // 期望输出: [1,4,3,2,5]

    freeList(head);
    return 0;
}

