#include <stdbool.h>
#include <stdlib.h>

/**
 * Definition for singly-linked list.
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/**
 * Definition for a binary tree node.
 */
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

/**
 * 判断：从当前树节点 root 出发，是否存在一条向下路径，
 * 能够完整匹配链表 head。
 *
 * 匹配规则：
 * - 链表走到 NULL，说明已经全部匹配成功，返回 true。
 * - 树节点走到 NULL，但链表还没结束，返回 false。
 * - 当前值不同，返回 false。
 * - 当前值相同，则继续尝试匹配左子树或右子树。
 */
bool matchFrom(struct TreeNode* root, struct ListNode* head) {
    if (head == NULL) {
        return true;    // 链表已经全部匹配完
    }
    if (root == NULL) {
        return false;   // 树路径提前结束
    }
    if (root->val != head->val) {
        return false;   // 当前节点值不匹配
    }

    // 当前节点匹配，继续向下匹配链表的下一个节点
    return matchFrom(root->left, head->next) || matchFrom(root->right, head->next);
}

/**
 * 遍历整棵树，把每个节点都当作“起点”尝试一次。
 * 如果该节点可以作为合法起点，则计数 +1。
 */
int countMatchingStarts(struct ListNode* head, struct TreeNode* root) {
    if (root == NULL) {
        return 0;
    }

    int count = 0;

    // 当前节点作为起点是否可行
    if (matchFrom(root, head)) {
        count = 1;
    }

    // 继续统计左子树和右子树中的起点数量
    count += countMatchingStarts(head, root->left);
    count += countMatchingStarts(head, root->right);

    return count;
}

