#include <stdlib.h>
#include <limits.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 返回一个长度为 2 的数组：
 * ans[0] = 任意两个转折点之间的最小距离
 * ans[1] = 任意两个转折点之间的最大距离
 * 若转折点不足两个，则返回 [-1, -1]
 *
 * 思路：
 * 1. 使用三个指针 prev, curr, next 同时扫描链表。
 * 2. 对于每个中间结点 curr，判断它是否为转折点：
 *      - curr->val > prev->val 且 curr->val > next->val
 *      - curr->val < prev->val 且 curr->val < next->val
 * 3. 如果是转折点：
 *      - 记录第一个转折点位置 firstPos
 *      - 记录上一个转折点位置 lastPos
 *      - 用当前位置与 lastPos 更新最小距离
 * 4. 最大距离只需要最后一个转折点位置 - 第一个转折点位置。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
int* turningPointDistances(struct ListNode* head, int* returnSize) {
    int* ans = (int*)malloc(sizeof(int) * 2);
    *returnSize = 2;
    ans[0] = -1;
    ans[1] = -1;

    // 少于 3 个结点，不可能存在转折点
    if (head == NULL || head->next == NULL || head->next->next == NULL) {
        return ans;
    }

    struct ListNode* prev = head;
    struct ListNode* curr = head->next;
    struct ListNode* next = curr->next;

    int index = 2;              // curr 的下标（题目要求从 1 开始）
    int firstPos = -1;          // 第一个转折点位置
    int lastPos = -1;           // 上一个转折点位置
    int minDist = INT_MAX;      // 最小距离
    int count = 0;              // 转折点数量

    while (next != NULL) {
        int isPeak = (curr->val > prev->val && curr->val > next->val);
        int isValley = (curr->val < prev->val && curr->val < next->val);

        if (isPeak || isValley) {
            count++;

            if (firstPos == -1) {
                // 第一次发现转折点
                firstPos = index;
            } else {
                // 与上一个转折点比较，更新最小距离
                if (index - lastPos < minDist) {
                    minDist = index - lastPos;
                }
            }

            // 无论是否为第一个，都更新 lastPos
            lastPos = index;
        }

        // 三指针整体后移
        prev = curr;
        curr = next;
        next = next->next;
        index++;
    }

    // 转折点不足两个
    if (count < 2) {
        ans[0] = -1;
        ans[1] = -1;
        return ans;
    }

    ans[0] = minDist;
    ans[1] = lastPos - firstPos;
    return ans;
}

