#include <stdio.h>
#include <stdlib.h>

// 单链表节点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 功能：切分链表，截取从 head 开始的前 size 个节点，
 *      返回剩余部分的头结点。
 * 说明：
 *   - 如果剩余节点不足 size 个，则直接切断并返回 NULL。
 *   - 该函数会修改链表指针。
 */
static struct ListNode* split(struct ListNode* head, int size) {
    if (head == NULL) {
        return NULL;
    }

    // 向后走 size - 1 步，找到这一段的最后一个节点
    for (int i = 1; i < size && head->next != NULL; ++i) {
        head = head->next;
    }

    // second 为下一段的起点
    struct ListNode* second = head->next;
    head->next = NULL;  // 断开当前这一段
    return second;
}

/*
 * 功能：合并两个有序链表 l1 和 l2，结果接到 tail 后面。
 * 返回值：合并完成后链表的最后一个节点（新的 tail）
 */
static struct ListNode* merge(struct ListNode* l1, struct ListNode* l2, struct ListNode* tail) {
    struct ListNode* cur = tail;

    // 归并两个有序链表
    while (l1 != NULL && l2 != NULL) {
        if (l1->val <= l2->val) {
            cur->next = l1;
            l1 = l1->next;
        } else {
            cur->next = l2;
            l2 = l2->next;
        }
        cur = cur->next;
    }

    // 接上剩余部分
    if (l1 != NULL) {
        cur->next = l1;
    } else {
        cur->next = l2;
    }

    // 将 cur 移动到合并后链表的末尾，便于下一次拼接
    while (cur->next != NULL) {
        cur = cur->next;
    }

    return cur;
}

/*
 * 功能：将单链表按非递减顺序重排并返回新头结点
 * 算法：自底向上的链表归并排序
 * 时间复杂度：O(n log n)
 * 空间复杂度：O(1) 额外空间
 */
struct ListNode* reorderListAscending(struct ListNode* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    // 1. 先统计链表长度
    int n = 0;
    struct ListNode* p = head;
    while (p != NULL) {
        ++n;
        p = p->next;
    }

    // 哑节点，便于处理头结点变化
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    // 2. 每轮归并的段长度 step = 1, 2, 4, 8 ...
    for (int step = 1; step < n; step <<= 1) {
        struct ListNode* cur = dummy.next;
        struct ListNode* tail = &dummy;

        while (cur != NULL) {
            // 左半段起点
            struct ListNode* left = cur;
            // 右半段起点
            struct ListNode* right = split(left, step);
            // 下一轮待处理起点
            cur = split(right, step);

            // 合并 left 和 right，接到 tail 后面
            tail = merge(left, right, tail);
        }
    }

    return dummy.next;
}

/*
