提交到在线评测系统时，如果平台已经提供链表构造与输出逻辑，可不保留 main。
*/

// 创建新节点
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 根据数组创建链表
struct ListNode* createList(int* arr, int size) {
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    for (int i = 0; i < size; ++i) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return dummy.next;
}

// 打印链表
void printList(struct ListNode* head) {
    printf("[");
    while (head != NULL) {
        printf("%d", head->val);
        head = head->next;
        if (head != NULL) {
            printf(",");
        }
    }
    printf("]\n");
}

// 释放链表内存
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int arr[] = {4, 2, 1, 3};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);
    head = reorderListAscending(head);

    printList(head);  // 期望输出: [1,2,3,4]
    freeList(head);

    return 0;
}

