#include <stdio.h>
#include <stdlib.h>

// 单链表节点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 功能：将链表中每两个相邻节点交换位置
 * 要求：不能修改节点值，只能调整指针
 * 返回：交换后的新头节点
 */
struct ListNode* rearrangePairs(struct ListNode* head) {
    // 虚拟头节点，方便统一处理头节点被交换的情况
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    // prev 指向当前待交换这一对节点之前的那个节点
    struct ListNode *prev = &dummy;

    // 当剩余节点不少于 2 个时，继续交换
    while (prev->next != NULL && prev->next->next != NULL) {
        // first 和 second 是当前要交换的两个节点
        struct ListNode *first = prev->next;
        struct ListNode *second = first->next;

        // 执行交换：
        // prev -> first -> second -> nextPart
        // 变为
        // prev -> second -> first -> nextPart
        first->next = second->next;
        second->next = first;
        prev->next = second;

        // prev 向后移动到交换后的第二个节点（即 first）
        // 准备处理下一组
        prev = first;
    }

    return dummy.next;
}

