    node->next = NULL;
    return node;
}

// 由数组创建链表
struct ListNode* createList(int arr[], int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* cur = head;
    for (int i = 1; i < size; i++) {
        cur->next = createNode(arr[i]);
        cur = cur->next;
    }
    return head;
}

