#include <stddef.h>

struct Node {
    int val;
    struct Node *next;   // 同一个子链表中的下一个节点
    struct Node *down;   // 下一层子链表的头节点
    struct Node *link;   // 需要填充的同层后继指针
};

/*
 * 题意说明：
 * - 第 0 层只有 head。
 * - 当前层通过 link 指针从左到右遍历。
 * - 对于当前层的每个节点 cur，cur->down 指向一条下一层的子链表，
 *   这条子链表内部通过 next 串联。
 * - 下一层的整体顺序，就是把当前层所有节点的 down 子链表按从左到右依次拼接。
 * - 需要把这些下一层节点的 link 指针连接起来。
 *
 * 做法：
 * - 用 level_head 表示当前层最左节点。
 * - 扫描当前层时，收集所有 down 子链表中的节点，按出现顺序串到下一层的 link 链上。
 * - 由于当前层本身已经能通过 link 遍历，因此整个过程只用到有限几个指针，满足 O(1) 额外空间。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
struct Node* connect(struct Node* head) {
    if (head == NULL) {
        return NULL;
    }

    // 第 0 层只有头节点本身
    Node *level_head = head;

    while (level_head != NULL) {
        // next_level_head：下一层最左节点
        // prev：下一层已经连接好的链表尾节点
        struct Node *next_level_head = NULL;
        struct Node *prev = NULL;

        // 遍历当前层，当前层节点之间通过 link 串联
        struct Node *cur = level_head;
        while (cur != NULL) {
            // cur->down 指向下一层的一条子链表，子链表内部通过 next 遍历
            struct Node *child = cur->down;
            while (child != NULL) {
                // 记录下一层的头节点
                if (next_level_head == NULL) {
                    next_level_head = child;
                }

                // 把 child 接到下一层 link 链的尾部
                if (prev != NULL) {
                    prev->link = child;
                }
                prev = child;

                child = child->next;
            }

            cur = cur->link;
        }

        // 下一层最后一个节点的 link 应为 NULL
        if (prev != NULL) {
            prev->link = NULL;
        }

        // 进入下一层继续处理
        level_head = next_level_head;
    }

    return head;
}

