#include <stdio.h>
#include <stdlib.h>

/*
 * 设计思路：
 * 1. 使用双向链表 + 头尾哨兵节点，简化边界处理。
 * 2. 维护当前链表长度 size。
 * 3. get / addAtIndex / deleteAtIndex 时，可根据 index 靠近头还是尾，
 *    决定从前往后还是从后往前遍历，提升效率。
 * 4. reverse() 通过交换每个节点的 next 和 prev 指针，最后再交换 head 和 tail。
 */

typedef struct Node {
    int val;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct {
    Node *head;   // 头哨兵
    Node *tail;   // 尾哨兵
    int size;     // 当前有效节点数
} MyLinkedList;

/* 创建一个新节点 */
static Node* createNode(int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->val = val;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

/* 初始化链表 */
MyLinkedList* myLinkedListCreate() {
    MyLinkedList *obj = (MyLinkedList *)malloc(sizeof(MyLinkedList));

    obj->head = createNode(0);  // 哨兵节点，值无实际意义
    obj->tail = createNode(0);

    obj->head->next = obj->tail;
    obj->tail->prev = obj->head;
    obj->head->prev = NULL;
    obj->tail->next = NULL;

    obj->size = 0;
    return obj;
}

/*
 * 获取第 index 个有效节点的指针
 * 若 index 非法，返回 NULL
 */
static Node* getNode(MyLinkedList* obj, int index) {
    if (index < 0 || index >= obj->size) {
        return NULL;
    }

    Node *cur;
    int i;

    /* 如果 index 靠近前半段，从头开始找 */
    if (index < obj->size / 2) {
        cur = obj->head->next;
        for (i = 0; i < index; i++) {
            cur = cur->next;
        }
    } else {
        /* 否则从尾开始找 */
        cur = obj->tail->prev;
        for (i = obj->size - 1; i > index; i--) {
            cur = cur->prev;
        }
    }

    return cur;
}

/* 查询值 */
int myLinkedListGet(MyLinkedList* obj, int index) {
    Node *node = getNode(obj, index);
    return node == NULL ? -1 : node->val;
}

/*
 * 在指定节点 before 之前插入新节点
 * 这是一个底层辅助函数
 */
static void insertBefore(Node *before, Node *newNode) {
    Node *pre = before->prev;

    pre->next = newNode;
    newNode->prev = pre;
    newNode->next = before;
    before->prev = newNode;
}

/* 头插 */
void myLinkedListAddAtHead(MyLinkedList* obj, int val) {
    Node *newNode = createNode(val);
    insertBefore(obj->head->next, newNode);
    obj->size++;
}

/* 尾插 */
void myLinkedListAddAtTail(MyLinkedList* obj, int val) {
    Node *newNode = createNode(val);
    insertBefore(obj->tail, newNode);
    obj->size++;
}

/* 按下标插入 */
void myLinkedListAddAtIndex(MyLinkedList* obj, int index, int val) {
    if (index < 0 || index > obj->size) {
        return;
    }

    Node *newNode = createNode(val);

    if (index == obj->size) {
        /* 插入到尾部 */
        insertBefore(obj->tail, newNode);
    } else {
        /* 插入到 index 位置之前 */
        Node *target = getNode(obj, index);
        insertBefore(target, newNode);
    }

    obj->size++;
}

/* 删除指定节点 */
static void removeNode(Node *node) {
    Node *pre = node->prev;
    Node *nxt = node->next;

    pre->next = nxt;
    nxt->prev = pre;
    free(node);
}

/* 按下标删除 */
void myLinkedListDeleteAtIndex(MyLinkedList* obj, int index) {
    Node *target = getNode(obj, index);
    if (target == NULL) {
        return;
    }

    removeNode(target);
    obj->size--;
}

/*
 * 原地反转整个链表
 * 包括哨兵节点在内，统一交换 prev 和 next
 * 最后交换 head 和 tail 指针
 */
void myLinkedListReverse(MyLinkedList* obj) {
    Node *cur = obj->head;
    Node *temp = NULL;

    /*
     * 原链表结构：head <-> ... <-> tail
     * 交换每个节点的 prev 和 next 后，链表方向整体反过来
     */
    while (cur != NULL) {
        temp = cur->next;
        cur->next = cur->prev;
        cur->prev = temp;
        cur = temp;
    }

    /* 交换头尾哨兵指针 */
    temp = obj->head;
    obj->head = obj->tail;
    obj->tail = temp;
}

/* 释放链表 */
void myLinkedListFree(MyLinkedList* obj) {
    Node *cur = obj->head;
    while (cur != NULL) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
    free(obj);
}

/*
 * 以下 main 函数仅用于本地调试，提交到题目平台时可按平台要求删除。
 */
/*
int main() {
    MyLinkedList *list = myLinkedListCreate();

    myLinkedListAddAtHead(list, 1);      // 1
    myLinkedListAddAtTail(list, 3);      // 1 3
    myLinkedListAddAtIndex(list, 1, 2);  // 1 2 3
    printf("%d\n", myLinkedListGet(list, 1)); // 2

    myLinkedListReverse(list);           // 3 2 1
    printf("%d\n", myLinkedListGet(list, 1)); // 2

    myLinkedListDeleteAtIndex(list, 1);  // 3 1
    printf("%d\n", myLinkedListGet(list, 1)); // 1

    myLinkedListFree(list);
    return 0;
}
*/

