#include <stdlib.h>

/**
 * 单链表结点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/**
 * 将链表按要求切分为 k 个连续片段。
 *
 * 返回：长度为 k 的数组，每个元素是一个片段的头结点。
 * 说明：
 * 1. 片段长度尽量均匀，任意两个片段长度差不超过 1；
 * 2. 靠前的片段长度 >= 靠后的片段长度；
 * 3. 若链表长度 < k，则后面若干片段为 NULL。
 */
struct ListNode** divideListBalanced(struct ListNode* head, int k, int* returnSize) {
    // 返回数组大小固定为 k
    *returnSize = k;

    // 为结果数组分配空间，并初始化为 NULL
    struct ListNode** ans = (struct ListNode**)calloc(k, sizeof(struct ListNode*));
    if (ans == NULL) {
        return NULL;
    }

    // 第一步：统计链表总长度 n
    int n = 0;
    struct ListNode* cur = head;
    while (cur != NULL) {
        n++;
        cur = cur->next;
    }

    // 第二步：计算每段的基础长度和需要多分配 1 个节点的段数
    int baseSize = n / k;   // 每段至少有 baseSize 个节点
    int extra = n % k;      // 前 extra 段各多 1 个节点

    // 第三步：依次切分链表
    cur = head;
    for (int i = 0; i < k; i++) {
        // 当前片段的头结点
        ans[i] = cur;

        // 当前片段应有的长度
        int partSize = baseSize + (i < extra ? 1 : 0);

        // 如果当前片段为空，直接进入下一段
        if (cur == NULL) {
            continue;
        }

        // 走到当前片段的最后一个节点
        // 由于 cur 已经指向第 1 个节点，所以只需再走 partSize - 1 步
        for (int j = 1; j < partSize; j++) {
            cur = cur->next;
        }

        // 断开当前片段与后续链表的连接
        struct ListNode* nextPart = cur->next;
        cur->next = NULL;

        // cur 移动到下一片段的开头
        cur = nextPart;
    }

    return ans;
}

