#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/*
 * 单链表结点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * Selector 结构体：只保存链表头指针
 * 不预先统计长度，从而支持“长度未知”的场景
 */
typedef struct {
    struct ListNode *head;
} Selector;

/*
 * 创建对象
 */
Selector* selectorCreate(struct ListNode* head) {
    Selector* obj = (Selector*)malloc(sizeof(Selector));
    obj->head = head;

    /*
     * 初始化随机种子。
     * 为避免多次创建对象时重复播种，这里只初始化一次。
     */
    static int seeded = 0;
    if (!seeded) {
        srand((unsigned int)time(NULL));
        seeded = 1;
    }

    return obj;
}

/*
 * 等概率随机返回一个结点值
 *
 * 核心思想：蓄水池抽样（Reservoir Sampling）
 *
 * 遍历到第 i 个结点时，以 1/i 的概率选择当前结点替换答案。
 * 最终每个结点被保留到最后的概率都相同，为 1/n。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
int selectorPick(Selector* obj) {
    struct ListNode* cur = obj->head;
    int ans = 0;
    int count = 0;

    while (cur != NULL) {
        count++;

        /*
         * rand() % count 的结果范围是 [0, count-1]
         * 当结果为 0 时，用当前结点更新答案
         * 即当前结点以 1/count 的概率被选中
         */
        if (rand() % count == 0) {
            ans = cur->val;
        }

        cur = cur->next;
    }

    return ans;
}

/*
 * 释放对象
 * 注意：这里只释放 Selector 本身，不释放链表结点
 */
void selectorFree(Selector* obj) {
    free(obj);
}

/*
 * =========================
 * 以下是本地测试辅助代码（提交时可保留）
 * =========================
 */

/* 创建新结点 */
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

/* 释放链表 */
void freeList(struct ListNode* head) {
    while (head) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    /* 构造链表：10 -> 20 -> 30 */
    struct ListNode* head = createNode(10);
    head->next = createNode(20);
    head->next->next = createNode(30);

    Selector* obj = selectorCreate(head);

    /* 多次调用，观察返回值是否分布较随机 */
    for (int i = 0; i < 10; i++) {
        printf("%d\n", selectorPick(obj));
    }

    selectorFree(obj);
    freeList(head);
    return 0;
}

