#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 删除有序链表中所有重复值对应的结点，
 * 仅保留原链表中出现次数恰好为 1 的结点。
 *
 * 思路：
 * 1. 由于链表有序，相同值一定连续出现。
 * 2. 使用哑结点 dummy，方便处理头结点被删除的情况。
 * 3. 使用 prev 指向“结果链表的最后一个确定保留的结点”。
 * 4. 使用 cur 扫描链表：
 *    - 若 cur 后面存在相同值，说明当前值是重复段；
 *      跳过这一整段，并让 prev->next 连接到重复段之后。
 *    - 否则，cur 是唯一值，prev 和 cur 同步向前移动。
 */
struct ListNode* deleteAllDuplicates(struct ListNode* head) {
    // 创建哑结点，统一处理头结点删除问题
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    struct ListNode *prev = &dummy;  // 指向已确认保留部分的尾部
    struct ListNode *cur = head;     // 当前扫描指针

    while (cur != NULL) {
        int duplicated = 0;

        // 检查当前值是否形成重复段
        while (cur->next != NULL && cur->val == cur->next->val) {
            duplicated = 1;
            cur = cur->next;
        }

        if (duplicated) {
            // cur 当前停在重复段的最后一个结点
            // 跳过整个重复段
            prev->next = cur->next;
        } else {
            // 当前结点值唯一，保留
            prev = prev->next;
        }

        // 继续处理下一个位置
        cur = cur->next;
    }

    return dummy.next;
}

