#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * 题意：
 * 设计一个固定容量的“最近激活任务表”。
 * - query(taskId): 如果存在则返回 priority，并把该任务移动到“最近激活”位置；不存在返回 -1
 * - activate(taskId, priority):
 *      - 存在则更新 priority，并移动到“最近激活”位置
 *      - 不存在则插入
 *      - 若超出容量，淘汰“最久未激活”的任务
 *
 * 要求：平均 O(1)
 *
 * 经典解法：哈希表 + 双向链表
 * - 双向链表：维护访问顺序
 *      头部(head后) = 最近激活
 *      尾部(tail前) = 最久未激活
 * - 哈希表：taskId -> 对应链表节点，支持 O(1) 平均查找
 */

/* ========================= 双向链表节点定义 ========================= */
typedef struct Node {
    int taskId;
    int priority;
    struct Node* prev;
    struct Node* next;
} Node;

/* ========================= 哈希表链地址节点定义 ========================= */
typedef struct HashEntry {
    int key;
    Node* node;                 // 指向双向链表中的节点
    struct HashEntry* next;
} HashEntry;

/* ========================= 主结构定义 ========================= */
typedef struct {
    int capacity;               // 容量
    int size;                   // 当前任务数

    Node* head;                 // 双向链表伪头
    Node* tail;                 // 双向链表伪尾

    int hashSize;               // 哈希桶数量
    HashEntry** table;          // 哈希表桶数组
} RecentTaskList;

/* ========================= 工具函数：创建链表节点 ========================= */
static Node* createNode(int taskId, int priority) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->taskId = taskId;
    node->priority = priority;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

/* ========================= 工具函数：哈希函数 ========================= */
static int hashFunc(RecentTaskList* obj, int key) {
    return key % obj->hashSize;
}

/* ========================= 双向链表操作 ========================= */

/* 将节点插入到头部之后，表示“最近激活” */
static void addToFront(RecentTaskList* obj, Node* node) {
    node->next = obj->head->next;
    node->prev = obj->head;
    obj->head->next->prev = node;
    obj->head->next = node;
}

/* 从链表中移除某个节点 */
static void removeNode(Node* node) {
    node->prev->next = node->next;
    node->next->prev = node->prev;
}

/* 将已有节点移动到头部，表示最近被访问/激活 */
static void moveToFront(RecentTaskList* obj, Node* node) {
    removeNode(node);
    addToFront(obj, node);
}

/* 删除尾部前一个节点，即“最久未激活”的节点 */
static Node* removeLeastRecent(RecentTaskList* obj) {
    if (obj->tail->prev == obj->head) {
        return NULL;
    }
    Node* node = obj->tail->prev;
    removeNode(node);
    return node;
}

/* ========================= 哈希表操作 ========================= */

/* 查找 key 对应的链表节点，存在则返回 Node*，否则返回 NULL */
static Node* hashGet(RecentTaskList* obj, int key) {
    int idx = hashFunc(obj, key);
    HashEntry* cur = obj->table[idx];
    while (cur) {
        if (cur->key == key) {
            return cur->node;
        }
        cur = cur->next;
    }
    return NULL;
}

/* 插入或更新 key -> node */
static void hashPut(RecentTaskList* obj, int key, Node* node) {
    int idx = hashFunc(obj, key);
    HashEntry* cur = obj->table[idx];

    while (cur) {
        if (cur->key == key) {
            cur->node = node;
            return;
        }
        cur = cur->next;
    }

    HashEntry* entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->key = key;
    entry->node = node;
    entry->next = obj->table[idx];
    obj->table[idx] = entry;
}

/* 删除 key */
static void hashRemove(RecentTaskList* obj, int key) {
    int idx = hashFunc(obj, key);
    HashEntry* cur = obj->table[idx];
    HashEntry* prev = NULL;

    while (cur) {
        if (cur->key == key) {
            if (prev) {
                prev->next = cur->next;
            } else {
                obj->table[idx] = cur->next;
            }
            free(cur);
            return;
        }
        prev = cur;
        cur = cur->next;
    }
}

/* ========================= 接口实现 ========================= */

RecentTaskList* recentTaskListCreate(int capacity) {
    RecentTaskList* obj = (RecentTaskList*)malloc(sizeof(RecentTaskList));
    obj->capacity = capacity;
    obj->size = 0;

    /*
     * 哈希桶数量可以取一个稍大的质数/固定值。
     * 在本题约束下，8192 足以保证较好的平均性能。
     */
    obj->hashSize = 8192;
    obj->table = (HashEntry**)calloc(obj->hashSize, sizeof(HashEntry*));

    /* 创建双向链表伪头伪尾 */
    obj->head = createNode(-1, -1);
    obj->tail = createNode(-1, -1);
    obj->head->next = obj->tail;
    obj->tail->prev = obj->head;

    return obj;
}

int recentTaskListQuery(RecentTaskList* obj, int taskId) {
    Node* node = hashGet(obj, taskId);
    if (node == NULL) {
        return -1;
    }

    /* 查询成功后，视为最近激活 */
    moveToFront(obj, node);
    return node->priority;
}

void recentTaskListActivate(RecentTaskList* obj, int taskId, int priority) {
    Node* node = hashGet(obj, taskId);

    if (node != NULL) {
        /* 已存在：更新优先级，并移动到头部 */
        node->priority = priority;
        moveToFront(obj, node);
        return;
    }

    /* 不存在：创建新节点，插入头部 */
    Node* newNode = createNode(taskId, priority);
    addToFront(obj, newNode);
    hashPut(obj, taskId, newNode);
    obj->size++;

    /* 若超容量，删除尾部最久未激活的节点 */
    if (obj->size > obj->capacity) {
        Node* removed = removeLeastRecent(obj);
        if (removed != NULL) {
            hashRemove(obj, removed->taskId);
            free(removed);
            obj->size--;
        }
    }
}

void recentTaskListFree(RecentTaskList* obj) {
    if (obj == NULL) {
        return;
    }

    /* 释放双向链表所有节点 */
    Node* curNode = obj->head;
    while (curNode) {
        Node* nextNode = curNode->next;
        free(curNode);
        curNode = nextNode;
    }

    /* 释放哈希表链地址节点 */
    for (int i = 0; i < obj->hashSize; ++i) {
        HashEntry* cur = obj->table[i];
        while (cur) {
            HashEntry* next = cur->next;
            free(cur);
            cur = next;
        }
    }

    free(obj->table);
    free(obj);
}

/*
 * 复杂度分析：
 * - recentTaskListQuery: O(1) 平均
 * - recentTaskListActivate: O(1) 平均
 * - 空间复杂度: O(capacity + hashSize)
 *
 * 说明：
 * 1. 双向链表负责维护“最近激活”顺序
 * 2. 哈希表负责 O(1) 平均定位 taskId 对应节点
 * 3. 伪头伪尾使插入、删除逻辑统一，减少边界判断
 */

