#include <stdio.h>
#include <stdlib.h>

/*
 * 多项式链表结点定义
 */
struct PolyNode {
    int coef;               // 系数
    int exp;                // 指数
    struct PolyNode* next;  // 指向下一项
};

/*
 * 创建新结点
 */
static struct PolyNode* createNode(int coef, int exp) {
    struct PolyNode* node = (struct PolyNode*)malloc(sizeof(struct PolyNode));
    if (node == NULL) {
        // 在多数在线评测环境中，可以直接返回 NULL；
        // 这里简单处理，调用者应保证内存足够。
        return NULL;
    }
    node->coef = coef;
    node->exp = exp;
    node->next = NULL;
    return node;
}

/*
 * 将一个结点追加到结果链表尾部
 */
static void appendNode(struct PolyNode** tail, int coef, int exp) {
    struct PolyNode* node = createNode(coef, exp);
    if (node == NULL) {
        return;
    }
    (*tail)->next = node;
    *tail = node;
}

/*
 * 功能：计算两个按指数递减排列的稀疏多项式之和
 * 返回：结果链表头结点
 *
 * 思路：
 * 1. 使用两个指针分别遍历 poly1 和 poly2。
 * 2. 如果某一边的指数更大，则该项直接加入结果。
 * 3. 如果指数相同，则系数相加：
 *    - 若和不为 0，则加入结果
 *    - 若和为 0，则跳过
 * 4. 最后把未处理完的剩余结点依次加入结果。
 */
struct PolyNode* addPolynomials(struct PolyNode* poly1, struct PolyNode* poly2) {
    // 哑结点，便于统一处理头结点插入逻辑
    struct PolyNode dummy;
    dummy.next = NULL;
    struct PolyNode* tail = &dummy;

    struct PolyNode* p = poly1;
    struct PolyNode* q = poly2;

    while (p != NULL && q != NULL) {
        if (p->exp > q->exp) {
            // p 的指数更大，直接加入结果
            appendNode(&tail, p->coef, p->exp);
            p = p->next;
        } else if (p->exp < q->exp) {
            // q 的指数更大，直接加入结果
            appendNode(&tail, q->coef, q->exp);
            q = q->next;
        } else {
            // 指数相同，合并系数
            int sum = p->coef + q->coef;
            if (sum != 0) {
                appendNode(&tail, sum, p->exp);
            }
            p = p->next;
            q = q->next;
        }
    }

    // 处理剩余项
    while (p != NULL) {
        appendNode(&tail, p->coef, p->exp);
        p = p->next;
    }

    while (q != NULL) {
        appendNode(&tail, q->coef, q->exp);
        q = q->next;
    }

    return dummy.next;
}

/* =========================
 * 以下为测试辅助代码（非必须）
 * 在提交到只要求函数实现的平台时，可删除 main。
 * =========================
 */

/*
 * 根据二维数组创建多项式链表
 * arr[i][0] = coef, arr[i][1] = exp
 */
struct PolyNode* buildPolynomial(int arr[][2], int n) {
    struct PolyNode dummy;
    dummy.next = NULL;
    struct PolyNode* tail = &dummy;

    for (int i = 0; i < n; i++) {
        appendNode(&tail, arr[i][0], arr[i][1]);
    }

    return dummy.next;
}

/*
 * 打印多项式链表
 */
void printPolynomial(struct PolyNode* head) {
    if (head == NULL) {
        printf("NULL\n");
        return;
    }

    while (head != NULL) {
        printf("(%d,%d)", head->coef, head->exp);
        if (head->next != NULL) {
            printf(" -> ");
        }
        head = head->next;
    }
    printf("\n");
}

/*
 * 释放链表内存
 */
void freePolynomial(struct PolyNode* head) {
    while (head != NULL) {
        struct PolyNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // 示例：
    // poly1 = (5,4) -> (2,2) -> (3,0)
    // poly2 = (3,5) -> (-5,4) -> (7,1)
    int a[][2] = {{5, 4}, {2, 2}, {3, 0}};
    int b[][2] = {{3, 5}, {-5, 4}, {7, 1}};

    struct PolyNode* poly1 = buildPolynomial(a, 3);
    struct PolyNode* poly2 = buildPolynomial(b, 3);

    struct PolyNode* result = addPolynomials(poly1, poly2);

    printPolynomial(result);

    // 释放内存
    freePolynomial(poly1);
    freePolynomial(poly2);
    freePolynomial(result);

    return 0;
}

