#include <stdio.h>
#include <stdlib.h>

/*
 * 单链表结点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 计算链表稳定化所需的轮数
 *
 * 核心思路：
 * 1. 先把链表值提取到数组中，方便随机访问。
 * 2. 使用单调栈，栈中保存下标，并维护每个位置“会在第几轮被删除”。
 * 3. 对于当前值 nums[i]：
 *    - 不断弹出所有 <= nums[i] 的元素，因为它们无法作为当前元素左侧更大的“压制者”。
 *    - 在弹出的过程中，当前元素的删除轮数要继承这些元素中最大的删除轮数。
 *    - 如果栈最终为空，说明左边没有比它更大的元素，它永远不会被删除，dp[i] = 0。
 *    - 如果栈不为空，说明左边存在第一个更大的元素，那么当前元素会在 maxPopped + 1 轮被删除。
 * 4. 所有 dp[i] 的最大值就是答案。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(n)
 */
int stepsToStableList(struct ListNode* head) {
    if (head == NULL) return 0;

    /* 第一步：统计链表长度 */
    int n = 0;
    struct ListNode *cur = head;
    while (cur != NULL) {
        n++;
        cur = cur->next;
    }

    /* 第二步：提取链表值到数组 */
    int *nums = (int *)malloc(sizeof(int) * n);
    int idx = 0;
    cur = head;
    while (cur != NULL) {
        nums[idx++] = cur->val;
        cur = cur->next;
    }

    /* dp[i]：第 i 个元素会在第几轮被删除；0 表示不会被删除 */
    int *dp = (int *)calloc(n, sizeof(int));

    /* 单调栈：保存下标，保持对应值严格递减 */
    int *stack = (int *)malloc(sizeof(int) * n);
    int top = -1;

    int ans = 0;

    for (int i = 0; i < n; i++) {
        int mx = 0;

        /*
         * 弹出所有 <= nums[i] 的位置。
         * 这些位置不会成为 i 左侧最近的更大值，
         * 但它们的删除轮数可能会影响 i 的删除时间。
         */
        while (top >= 0 && nums[stack[top]] <= nums[i]) {
            if (dp[stack[top]] > mx) {
                mx = dp[stack[top]];
            }
            top--;
        }

        if (top == -1) {
            /* 左边没有更大的元素，当前元素不会被删除 */
            dp[i] = 0;
        } else {
            /*
             * 左边仍有更大的元素存在，当前元素一定会被删除。
             * 但必须等到前面那些“挡路”的较小/相等元素处理完，
             * 所以是 mx + 1。
             */
            dp[i] = mx + 1;
        }

        if (dp[i] > ans) {
            ans = dp[i];
        }

        stack[++top] = i;
    }

    free(nums);
    free(dp);
    free(stack);

    return ans;
}

/* ===================== 以下为演示用的完整输入输出代码 ===================== */

/* 创建新结点 */
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

/* 根据数组构建链表 */
struct ListNode* buildList(int *arr, int n) {
    if (n == 0) return NULL;

    struct ListNode *head = createNode(arr[0]);
    struct ListNode *tail = head;

    for (int i = 1; i < n; i++) {
        tail->next = createNode(arr[i]);
        tail = tail->next;
    }

    return head;
}

/* 释放链表内存 */
void freeList(struct ListNode* head) {
    while (head != NULL) {
        struct ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    /*
     * 输入格式：
     * 第一行一个整数 n
     * 第二行 n 个整数，表示链表中的结点值
     *
     * 示例：
     * 11
     * 5 3 4 4 7 3 6 11 8 5 11
     */
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *arr = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    struct ListNode *head = buildList(arr, n);
    int result = stepsToStableList(head);
    printf("%d\n", result);

    free(arr);
    freeList(head);
    return 0;
}

