#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

// 创建新结点
static struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

// 反转链表
static struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode* prev = NULL;
    struct ListNode* curr = head;

    while (curr != NULL) {
        struct ListNode* nextNode = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextNode;
    }

    return prev;
}

/*
 * 函数功能：
 * 将链表表示的数字转换为：原值 * 3 + 1
 * 返回结果链表的头结点（高位在前）
 *
 * 思路：
 * 1. 由于高位在前，不方便直接处理进位，因此先反转链表。
 * 2. 从最低位开始做运算：当前位 = 当前数字 * 3 + carry。
 * 3. 注意“+1”只应加在整体数字上一次，因此可以把初始 carry 设为 1。
 * 4. 处理完整个链表后，如果仍有进位，则继续补结点。
 * 5. 最后再将链表反转回来。
 */
struct ListNode* transformNumber(struct ListNode* head) {
    // 先反转，便于从最低位开始处理
    head = reverseList(head);

    struct ListNode* curr = head;
    struct ListNode* prev = NULL;

    // 初始 carry = 1，相当于最后统一实现“*3 + 1”中的 +1
    int carry = 1;

    while (curr != NULL) {
        int value = curr->val * 3 + carry;
        curr->val = value % 10;
        carry = value / 10;

        prev = curr;
        curr = curr->next;
    }

    // 如果最高位处理后还有进位，则继续追加结点
    while (carry > 0) {
        prev->next = createNode(carry % 10);
        prev = prev->next;
        carry /= 10;
    }

    // 再次反转，恢复为高位在前
    return reverseList(head);
}

