#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 删除链表的中心检查点：下标为 floor(n / 2) 的结点（0-based）
 *
 * 思路：快慢指针
 * 1. 如果链表只有一个结点，删除后返回 NULL。
 * 2. 使用 fast 每次走两步，slow 每次走一步。
 * 3. 当 fast 到达末尾时，slow 正好停在要删除的结点上。
 * 4. 用 prev 记录 slow 的前一个结点，便于完成删除。
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
struct ListNode* removeCenterCheckpoint(struct ListNode* head) {
    // 只有一个结点，删除后链表为空
    if (head == NULL) {
        return NULL;
    }
    if (head->next == NULL) {
        free(head);
        return NULL;
    }

    struct ListNode *slow = head;
    struct ListNode *fast = head;
    struct ListNode *prev = NULL;

    // fast 每次走两步，slow 每次走一步
    while (fast != NULL && fast->next != NULL) {
        prev = slow;
        slow = slow->next;
        fast = fast->next->next;
    }

    // 此时 slow 指向下标 floor(n / 2) 的结点，prev 是其前驱
    prev->next = slow->next;
    free(slow);

    return head;
}

