 * 返回：动态申请的二维数组
 * returnSize：返回矩阵行数 m
 * returnColumnSizes：返回每一行的列数，均为 n
 */
int** fillCounterClockwiseMatrix(int m, int n, struct ListNode* head,
                                 int* returnSize, int** returnColumnSizes) {
    int i;

    /* 设置返回的行数 */
    *returnSize = m;

    /* 分配每行列数数组 */
    *returnColumnSizes = (int*)malloc(sizeof(int) * m);
    for (i = 0; i < m; i++) {
        (*returnColumnSizes)[i] = n;
    }

    /* 分配矩阵空间，并初始化为 -1 */
    int** matrix = (int**)malloc(sizeof(int*) * m);
    for (i = 0; i < m; i++) {
        matrix[i] = (int*)malloc(sizeof(int) * n);
        for (int j = 0; j < n; j++) {
            matrix[i][j] = -1;
        }
    }

    /* 四个边界，表示当前尚未填充区域 */
    int top = 0;
    int bottom = m - 1;
    int left = 0;
    int right = n - 1;

    /*
     * 按层填充，顺序为：
     * 1. 右边界从上到下
     * 2. 下边界从右到左
     * 3. 左边界从下到上
     * 4. 上边界从左到右
     *
     * 这正对应：从右上角开始，初始向下，整体逆时针环绕
     */
    while (head != NULL && top <= bottom && left <= right) {
        /* 1. 向下填充右边界 */
        for (i = top; i <= bottom && head != NULL; i++) {
            matrix[i][right] = head->val;
            head = head->next;
        }
        right--;

        /* 2. 向左填充下边界 */
        for (i = right; i >= left && head != NULL && top <= bottom; i--) {
            matrix[bottom][i] = head->val;
            head = head->next;
        }
        bottom--;

        /* 3. 向上填充左边界 */
        for (i = bottom; i >= top && head != NULL && left <= right; i--) {
            matrix[i][left] = head->val;
            head = head->next;
        }
        left++;

        /* 4. 向右填充上边界 */
        for (i = left; i <= right && head != NULL && top <= bottom; i++) {
            matrix[top][i] = head->val;
            head = head->next;
        }
        top++;
    }

    return matrix;
}

/*
 * --------------------------
 * 以下为本地测试辅助代码（提交到题库时通常可省略 main）
 * --------------------------
 */

/* 创建新结点 */
struct ListNode* createNode(int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;
    return node;
}

/* 根据数组创建链表 */
struct ListNode* createList(int* arr, int size) {
    if (size == 0) return NULL;

    struct ListNode* head = createNode(arr[0]);
    struct ListNode* cur = head;
    for (int i = 1; i < size; i++) {
        cur->next = createNode(arr[i]);
        cur = cur->next;
    }
    return head;
}

/* 打印矩阵 */
void printMatrix(int** matrix, int rows, int* colSizes) {
    for (int i = 0; i < rows; i++) {
        printf("[");
        for (int j = 0; j < colSizes[i]; j++) {
            printf("%d", matrix[i][j]);
            if (j + 1 < colSizes[i]) printf(", ");
        }
        printf("]\n");
    }
}

/* 释放链表 */
void freeList(struct ListNode* head) {
    while (head) {
        struct ListNode* tmp = head;
        head = head->next;
        free(tmp);
    }
}

/* 释放矩阵 */
void freeMatrix(int** matrix, int rows, int* colSizes) {
    (void)colSizes; /* 避免未使用警告 */
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main() {
    int m = 3, n = 4;
    int arr[] = {1, 2, 3, 4, 5, 6, 7, 8};
    int size = sizeof(arr) / sizeof(arr[0]);

    struct ListNode* head = createList(arr, size);

    int returnSize;
    int* returnColumnSizes;
    int** matrix = fillCounterClockwiseMatrix(m, n, head, &returnSize, &returnColumnSizes);

    printMatrix(matrix, returnSize, returnColumnSizes);

    freeList(head);
    freeMatrix(matrix, returnSize, returnColumnSizes);
    free(returnColumnSizes);

    return 0;
}

