#include <stdio.h>
#include <stdlib.h>

// 单链表结点定义
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 题意：
 * 找到链表中第 k 个结点 A，以及倒数第 k 个结点 B，
 * 将 A 和 B 之间（含端点）的整段子链表原地反转。
 *
 * 思路：
 * 1. 先利用“间隔指针”思想找到：
 *    - 第 k 个结点的位置 pos1 = k
 *    - 倒数第 k 个结点的位置 pos2 = n - k + 1
 *    同时得到链表长度 n。
 *
 *    做法：
 *    - fast 先走到第 k 个结点；
 *    - slow 从头开始；
 *    - 然后 fast 和 slow 一起往后走，直到 fast 到达尾结点；
 *      此时 slow 就停在倒数第 k 个结点。
 *
 * 2. 取 left = min(pos1, pos2), right = max(pos1, pos2)。
 *    如果 left == right，说明是同一个结点，直接返回。
 *
 * 3. 使用经典的“反转链表指定区间 [left, right]”方法：
 *    - 找到区间前一个结点 beforeLeft
 *    - 反转 [left, right] 这段链表
 *    - 重新接回前后部分
 *
 * 时间复杂度：O(n)
 * 空间复杂度：O(1)
 */
struct ListNode* reverseBetweenMirrorNodes(struct ListNode* head, int k) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    // ---------- 第一步：找到第 k 个结点和倒数第 k 个结点的位置 ----------
    struct ListNode *fast = head;
    int len = 1;

    // fast 走到第 k 个结点
    for (int i = 1; i < k; ++i) {
        fast = fast->next;
        ++len;
    }

    // 此时第 k 个结点位置为 pos1 = k
    int pos1 = k;

    // slow 从头开始，最终会停在倒数第 k 个结点
    struct ListNode *slow = head;

    // fast 和 slow 同时向后移动，直到 fast 到达尾结点
    while (fast->next != NULL) {
        fast = fast->next;
        slow = slow->next;
        ++len;
    }

    // slow 指向倒数第 k 个结点，其位置为 pos2 = len - k + 1
    int pos2 = len - k + 1;

    // 计算要反转的区间左右边界
    int left = pos1 < pos2 ? pos1 : pos2;
    int right = pos1 > pos2 ? pos1 : pos2;

    // 如果是同一个结点，无需反转
    if (left == right) {
        return head;
    }

    // ---------- 第二步：反转区间 [left, right] ----------
    struct ListNode dummy;
    dummy.val = 0;
    dummy.next = head;

    // beforeLeft 指向第 left 个结点之前的那个结点
    struct ListNode *beforeLeft = &dummy;
    for (int i = 1; i < left; ++i) {
        beforeLeft = beforeLeft->next;
    }

    // start 是待反转区间的第一个结点
    struct ListNode *start = beforeLeft->next;
    struct ListNode *cur = start;
    struct ListNode *prev = NULL;

    // 反转 right - left + 1 个结点
    for (int i = left; i <= right; ++i) {
        struct ListNode *nextNode = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nextNode;
    }

