#include <stdlib.h>

/*
 * 单链表结点定义
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/*
 * 为了实现“稳定归并”：
 * 1. 先按节点值 val 升序比较
 * 2. 若 val 相同，则按链表下标 idx 升序比较
 *
 * 堆中保存的是“某条链表当前头结点”以及其所属链表编号。
 */
struct HeapNode {
    struct ListNode *node;  // 当前节点
    int idx;                // 来自第 idx 条链表
};

/*
 * 比较函数：返回 1 表示 a 比 b 更小（优先级更高）
 * 规则：
 *   - val 更小者优先
 *   - val 相等时，idx 更小者优先
 */
static int lessNode(struct HeapNode a, struct HeapNode b) {
    if (a.node->val != b.node->val) {
        return a.node->val < b.node->val;
    }
    return a.idx < b.idx;
}

/*
 * 交换两个堆元素
 */
static void swapNode(struct HeapNode *a, struct HeapNode *b) {
    struct HeapNode tmp = *a;
    *a = *b;
    *b = tmp;
}

/*
 * 最小堆下沉操作
 */
static void heapifyDown(struct HeapNode *heap, int size, int pos) {
    while (1) {
        int smallest = pos;
        int left = pos * 2 + 1;
        int right = pos * 2 + 2;

        if (left < size && lessNode(heap[left], heap[smallest])) {
            smallest = left;
        }
        if (right < size && lessNode(heap[right], heap[smallest])) {
            smallest = right;
        }

        if (smallest == pos) {
            break;
        }

        swapNode(&heap[pos], &heap[smallest]);
        pos = smallest;
    }
}

/*
 * 最小堆上浮操作
 */
static void heapifyUp(struct HeapNode *heap, int pos) {
    while (pos > 0) {
        int parent = (pos - 1) / 2;
        if (lessNode(heap[pos], heap[parent])) {
            swapNode(&heap[pos], &heap[parent]);
            pos = parent;
        } else {
            break;
        }
    }
}

/*
 * 向堆中插入一个元素
 */
static void heapPush(struct HeapNode *heap, int *size, struct HeapNode x) {
    heap[*size] = x;
    (*size)++;
    heapifyUp(heap, (*size) - 1);
}

/*
 * 弹出堆顶最小元素
 */
static struct HeapNode heapPop(struct HeapNode *heap, int *size) {
    struct HeapNode top = heap[0];
    (*size)--;
    if (*size > 0) {
        heap[0] = heap[*size];
        heapifyDown(heap, *size, 0);
    }
    return top;
}

/*
 * 题目要求的函数：
 * 将 k 条有序链表稳定地原地归并为一条有序链表。
 *
 * 时间复杂度：O(N log k)
 * 空间复杂度：O(k)
 */
struct ListNode* mergeKListsStable(struct ListNode** lists, int listsSize) {
    if (listsSize == 0 || lists == NULL) {
        return NULL;
    }

    /*
     * 最多同时有 listsSize 个链表头在堆中，因此开一个大小为 listsSize 的最小堆。
     */
    struct HeapNode *heap = (struct HeapNode *)malloc(sizeof(struct HeapNode) * (listsSize > 0 ? listsSize : 1));
    int heapSize = 0;

    /*
     * 初始化：把每条非空链表的头结点放入堆中。
     */
    for (int i = 0; i < listsSize; ++i) {
        if (lists[i] != NULL) {
            struct HeapNode item;
            item.node = lists[i];
            item.idx = i;
            heapPush(heap, &heapSize, item);
        }
    }

    /*
     * dummy 仅作为辅助头结点，不属于“新建结果数据节点”。
     * 最终返回 dummy.next。
     */
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode *tail = &dummy;

    /*
     * 每次取出当前全局最小节点接到结果链表尾部；
     * 然后把该节点在原链表中的下一个节点继续放回堆中。
     */
    while (heapSize > 0) {
        struct HeapNode cur = heapPop(heap, &heapSize);
        struct ListNode *picked = cur.node;

        /*
         * 先记录后继，因为等会儿要把 picked 接到结果链表尾部。
         */
        struct ListNode *nextNode = picked->next;

        /*
         * 将 picked 原地拼接到答案链表末尾。
         */
        tail->next = picked;
        tail = picked;

        /*
         * 如果当前链表还有后继节点，将其重新加入堆中。
         * 注意：链表编号 idx 不变，用于相同值时的稳定性比较。
         */
        if (nextNode != NULL) {
            struct HeapNode item;
            item.node = nextNode;
            item.idx = cur.idx;
            heapPush(heap, &heapSize, item);
        }
    }

    /*
     * 结果链表收尾，避免残留旧 next 关系造成歧义。
     */
    if (tail != NULL) {
        tail->next = NULL;
    }

    free(heap);
    return dummy.next;
}

/*
 * 说明：
 *
 * 为什么该做法满足稳定性？
 * 1. 同一条链表内部：
 *    只有当前节点被弹出后，它的 next 才会入堆，
 *    因此同一链表内部节点顺序绝不会被打乱。
 *
 * 2. 不同链表之间相同 val 的处理：
 *    堆比较时，若 val 相等，则链表编号 idx 小的优先。
 *    因而题目要求的“下标更小的链表先出”能够保证。
 *
 * 为什么是 O(N log k)？
 * - 每个节点最多入堆一次、出堆一次；
 * - 每次堆操作复杂度 O(log k)；
 * - 总节点数为 N，因此总复杂度 O(N log k)。
 */

