#include <stdio.h>
#include <stdlib.h>

/**
 * Definition for singly-linked list.
 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/* =========================
 * 最小堆实现：按节点值排序
 * ========================= */
typedef struct {
    struct ListNode** data;
    int size;
    int capacity;
} MinHeap;

/* 交换堆中的两个元素 */
static void swapNode(struct ListNode** a, struct ListNode** b) {
    struct ListNode* t = *a;
    *a = *b;
    *b = t;
}

/* 创建最小堆 */
static MinHeap* createHeap(int capacity) {
    MinHeap* heap = (MinHeap*)malloc(sizeof(MinHeap));
    heap->data = (struct ListNode**)malloc(sizeof(struct ListNode*) * (capacity > 0 ? capacity : 1));
    heap->size = 0;
    heap->capacity = (capacity > 0 ? capacity : 1);
    return heap;
}

/* 上浮 */
static void heapifyUp(MinHeap* heap, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap->data[parent]->val <= heap->data[idx]->val) {
            break;
        }
        swapNode(&heap->data[parent], &heap->data[idx]);
        idx = parent;
    }
}

/* 下沉 */
static void heapifyDown(MinHeap* heap, int idx) {
    while (1) {
        int left = idx * 2 + 1;
        int right = idx * 2 + 2;
        int smallest = idx;

        if (left < heap->size && heap->data[left]->val < heap->data[smallest]->val) {
            smallest = left;
        }
        if (right < heap->size && heap->data[right]->val < heap->data[smallest]->val) {
            smallest = right;
        }

        if (smallest == idx) {
            break;
        }

        swapNode(&heap->data[idx], &heap->data[smallest]);
        idx = smallest;
    }
}

/* 插入节点到堆 */
static void heapPush(MinHeap* heap, struct ListNode* node) {
    if (node == NULL) return;

    if (heap->size == heap->capacity) {
        heap->capacity *= 2;
        heap->data = (struct ListNode**)realloc(heap->data, sizeof(struct ListNode*) * heap->capacity);
    }

    heap->data[heap->size] = node;
    heapifyUp(heap, heap->size);
    heap->size++;
}

/* 弹出堆顶最小节点 */
static struct ListNode* heapPop(MinHeap* heap) {
    if (heap->size == 0) return NULL;

    struct ListNode* top = heap->data[0];
    heap->size--;
    if (heap->size > 0) {
        heap->data[0] = heap->data[heap->size];
        heapifyDown(heap, 0);
    }
    return top;
}

/* 销毁堆 */
static void destroyHeap(MinHeap* heap) {
    if (!heap) return;
    free(heap->data);
    free(heap);
}

/*
 * 核心函数：
 * 1. 使用最小堆做 k 路归并，保证每次取到当前最小值节点。
 * 2. 由于整体输出有序，因此相同值一定会连续弹出。
 * 3. 统计每一段相同值的出现次数：
 *      - 若次数 == 1，则把该节点接入答案链表
 *      - 若次数 > 1，则整段全部丢弃
 *
 * 时间复杂度：O(N log k)
 * 空间复杂度：O(k)
 * 其中 N 是所有链表节点总数。
 */
struct ListNode* mergeKListsKeepUnique(struct ListNode** lists, int listsSize) {
    if (listsSize == 0) return NULL;

    MinHeap* heap = createHeap(listsSize);

    /* 将每条链表的头节点加入堆 */
    for (int i = 0; i < listsSize; i++) {
        if (lists[i] != NULL) {
            heapPush(heap, lists[i]);
        }
    }

    /* 哑节点，便于构造结果链表 */
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode* tail = &dummy;

    while (heap->size > 0) {
        /* 取出当前最小值，作为一个值段的开始 */
        struct ListNode* first = heapPop(heap);
        int currentValue = first->val;
        int count = 1;

        /* 保存该节点的后继，后面要放回堆 */
        struct ListNode* nextNode = first->next;
        first->next = NULL;  /* 先断开，避免后续拼接产生混乱 */
        if (nextNode != NULL) {
            heapPush(heap, nextNode);
        }

        /* 记录当前值段中的第一个节点。
         * 只有当 count 最终仍为 1 时，才会把它接入答案。 */
        struct ListNode* uniqueCandidate = first;

        /* 持续取出所有与 currentValue 相同的节点 */
        while (heap->size > 0 && heap->data[0]->val == currentValue) {
            struct ListNode* node = heapPop(heap);
            count++;

            nextNode = node->next;
            node->next = NULL;
            if (nextNode != NULL) {
                heapPush(heap, nextNode);
            }

            /* 这里不需要保存这些重复节点，因为最终会全部丢弃 */
        }

        /* 仅当该值在全局中只出现 1 次时，保留这个节点 */
        if (count == 1) {
            tail->next = uniqueCandidate;
            tail = uniqueCandidate;
        }
        /* 否则该值出现多次，整段丢弃，不接入结果链表 */
    }

    tail->next = NULL;
    destroyHeap(heap);
    return dummy.next;
}

