typedef struct {
    struct ListNode** data;
    int size;
    int capacity;
} MinHeap;

/* 交换堆中的两个元素 */
static void swapNode(struct ListNode** a, struct ListNode** b) {
    struct ListNode* t = *a;
    *a = *b;
    *b = t;
}

/* 创建最小堆 */
static MinHeap* createHeap(int capacity) {
    MinHeap* heap = (MinHeap*)malloc(sizeof(MinHeap));
    heap->data = (struct ListNode**)malloc(sizeof(struct ListNode*) * (capacity > 0 ? capacity : 1));
    heap->size = 0;
    heap->capacity = (capacity > 0 ? capacity : 1);
    return heap;
}

/* 上浮 */
static void heapifyUp(MinHeap* heap, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap->data[parent]->val <= heap->data[idx]->val) {
            break;
        }
        swapNode(&heap->data[parent], &heap->data[idx]);
        idx = parent;
    }
}

/* 下沉 */
static void heapifyDown(MinHeap* heap, int idx) {
    while (1) {
        int left = idx * 2 + 1;
        int right = idx * 2 + 2;
        int smallest = idx;

        if (left < heap->size && heap->data[left]->val < heap->data[smallest]->val) {
            smallest = left;
        }
        if (right < heap->size && heap->data[right]->val < heap->data[smallest]->val) {
            smallest = right;
        }

        if (smallest == idx) {
            break;
        }

        swapNode(&heap->data[idx], &heap->data[smallest]);
        idx = smallest;
    }
}

/* 插入节点到堆 */
static void heapPush(MinHeap* heap, struct ListNode* node) {
    if (node == NULL) return;

    if (heap->size == heap->capacity) {
        heap->capacity *= 2;
        heap->data = (struct ListNode**)realloc(heap->data, sizeof(struct ListNode*) * heap->capacity);
    }

    heap->data[heap->size] = node;
    heapifyUp(heap, heap->size);
    heap->size++;
}

/* 弹出堆顶最小节点 */
static struct ListNode* heapPop(MinHeap* heap) {
    if (heap->size == 0) return NULL;

    struct ListNode* top = heap->data[0];
    heap->size--;
    if (heap->size > 0) {
        heap->data[0] = heap->data[heap->size];
        heapifyDown(heap, 0);
    }
    return top;
}

