#include <stdio.h>

/*
 * 题意：
 * 统计满足 i < j 且 nums[i] != nums[j] 的下标对数量。
 *
 * 思路：
 * 1. 使用“哈希表”统计每个数字出现的次数。
 *    由于题目保证 1 <= nums[i] <= 1000，
 *    这里可以直接用大小为 1001 的数组来模拟哈希表。
 *
 * 2. 总下标对数量为：n * (n - 1) / 2。
 *
 * 3. 对于每个出现次数为 c 的数字，
 *    它会产生 c * (c - 1) / 2 个“值相同”的下标对。
 *
 * 4. 用总下标对数量减去所有“值相同”的下标对数量，
 *    就得到“值不同”的下标对数量。
 *
 * 时间复杂度：O(n + V)，其中 V = 1000
 * 空间复杂度：O(V)
 */
long long countUnequalPairs(int* nums, int numsSize) {
    // 用数组模拟哈希表，freq[x] 表示数字 x 出现的次数
    int freq[1001] = {0};

    // 统计每个数字的出现次数
    for (int i = 0; i < numsSize; i++) {
        freq[nums[i]]++;
    }

    // 计算总下标对数量
    long long totalPairs = (long long)numsSize * (numsSize - 1) / 2;

    // 计算值相同的下标对数量
    long long equalPairs = 0;
    for (int x = 1; x <= 1000; x++) {
        if (freq[x] >= 2) {
            equalPairs += (long long)freq[x] * (freq[x] - 1) / 2;
        }
    }

    // 值不同的下标对 = 总下标对 - 值相同的下标对
    return totalPairs - equalPairs;
}

/*
 * 以下 main 函数仅用于本地测试，提交到在线评测系统时
 * 如果平台不需要 main，可以删除。
 */
int main() {
    int nums1[] = {4, 4, 2, 4, 3};
    int size1 = sizeof(nums1) / sizeof(nums1[0]);
    printf("%lld\n", countUnequalPairs(nums1, size1)); // 7

    int nums2[] = {1, 1, 1, 1};
    int size2 = sizeof(nums2) / sizeof(nums2[0]);
    printf("%lld\n", countUnequalPairs(nums2, size2)); // 0

    return 0;
}

