#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ------------------------------
// 简单哈希集合实现（拉链法）
// ------------------------------

#define HASH_SIZE 2003  // 取一个较小的质数，足够应对本题数据

typedef struct Node {
    int key;
    struct Node* next;
} Node;

// 哈希表：每个位置存一个链表头指针
Node* hashTable[HASH_SIZE];

// 哈希函数
int hashFunc(int key) {
    return key % HASH_SIZE;
}

// 向哈希集合中插入一个值
void insert(int key) {
    int index = hashFunc(key);

    // 如果已经存在，则不用重复插入
    Node* cur = hashTable[index];
    while (cur != NULL) {
        if (cur->key == key) {
            return;
        }
        cur = cur->next;
    }

    // 头插法插入新节点
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->next = hashTable[index];
    hashTable[index] = node;
}

// 判断某个值是否存在于哈希集合中
int contains(int key) {
    int index = hashFunc(key);
    Node* cur = hashTable[index];

    while (cur != NULL) {
        if (cur->key == key) {
            return 1;
        }
        cur = cur->next;
    }
    return 0;
}

// 释放哈希表内存
void freeHashTable() {
    for (int i = 0; i < HASH_SIZE; i++) {
        Node* cur = hashTable[i];
        while (cur != NULL) {
            Node* temp = cur;
            cur = cur->next;
            free(temp);
        }
        hashTable[i] = NULL;
    }
}

int main() {
    int n;
    scanf("%d", &n);

    // 初始化哈希表
    memset(hashTable, 0, sizeof(hashTable));

    // 读入数组并存入哈希集合
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        insert(x);
    }

    int start;
    scanf("%d", &start);

    // 只要当前值存在，就不断翻倍
    while (contains(start)) {
        start *= 2;
    }

    printf("%d\n", start);

    // 释放内存
    freeHashTable();
    return 0;
}

